function normalizeSubscriptionStatusFromStripe(status: string): 'active' | 'pending' | 'delinquent' | 'canceled' {
  const normalized = sanitizeString(status, 50).toLowerCase();
  if (normalized === 'active' || normalized === 'trialing') return 'active';
  if (normalized === 'past_due' || normalized === 'unpaid') return 'delinquent';
  if (normalized === 'canceled' || normalized === 'incomplete_expired') return 'canceled';
  return 'pending';
}

async function updateClinicSubscriptionStatus(params: {
  clinicId?: string | null;
  userId?: string | null;
  email?: string | null;
  status: 'active' | 'pending' | 'delinquent' | 'canceled';
}) {
  const safeClinicId = sanitizeString(params.clinicId, 120);
  const safeUserId = sanitizeString(params.userId, 120);
  const safeEmail = sanitizeEmail(params.email);

  if (safeClinicId) {
    const { error } = await supabase
      .from('users')
      .update({ subscription_status: params.status })
      .eq('clinic_id', safeClinicId)
      .in('role', ['director', 'coordinator', 'supervisor', 'therapist', 'receptionist', 'biller']);
    if (error) {
      console.error('[Stripe Webhook] Falha ao atualizar status por clínica:', {
        clinicId: safeClinicId,
        status: params.status,
        message: error.message
      });
    }
  }

  if (safeUserId) {
    const { error } = await supabase
      .from('users')
      .update({ subscription_status: params.status })
      .eq('id', safeUserId);
    if (error) {
      console.error('[Stripe Webhook] Falha ao atualizar status por userId:', {
        userId: safeUserId,
        status: params.status,
        message: error.message
      });
    }
  } else if (!safeClinicId && safeEmail) {
    const { error } = await supabase
      .from('users')
      .update({ subscription_status: params.status })
      .eq('email', safeEmail);
    if (error) {
      console.error('[Stripe Webhook] Falha ao atualizar status por email:', {
        email: safeEmail,
        status: params.status,
        message: error.message
      });
    }
  }
}

function resolveActivePatientPriceId(): string {
  return sanitizeString(process.env.STRIPE_ACTIVE_PATIENT_PRICE_ID || '', 120);
}

function resolveActivePatientPlanLookupKeys(): string[] {
  return Array.from(
    new Set(
      [
        ACTIVE_PATIENT_BILLING_LOOKUP_KEY,
        ...sanitizeString(process.env.STRIPE_ACTIVE_PATIENT_LOOKUP_KEY || '', 500)
          .split(',')
          .map((item) => sanitizeString(item, 160)),
        ...sanitizeString(process.env.STRIPE_ACTIVE_PATIENT_LOOKUP_KEYS || '', 1000)
          .split(',')
          .map((item) => sanitizeString(item, 160))
      ].filter(Boolean)
    )
  );
}

function resolveBillingPlanPriceIds(): string[] {
  return Array.from(
    new Set(
      sanitizeString(process.env.STRIPE_BILLING_PLAN_PRICE_IDS || process.env.STRIPE_CLINIC_PLAN_PRICE_IDS || '', 2000)
        .split(',')
        .map((item) => sanitizeString(item, 120))
        .filter(Boolean)
    )
  );
}

function resolveSalesContactUrl(): string {
  const configuredNumber = normalizePublicSalesWhatsappNumber(
    process.env.VITE_SALES_WHATSAPP_NUMBER
  );
  const whatsappNumber = configuredNumber.length >= 10
    ? configuredNumber
    : PUBLIC_SALES_WHATSAPP_NUMBER;
  return `https://wa.me/${whatsappNumber}`;
}

const DEFAULT_SALES_NOTIFICATION_EMAIL = 'appverto1@gmail.com';

function resolveSalesNotificationEmail(): string {
  return sanitizeEmail(process.env.SALES_NOTIFICATION_EMAIL) || DEFAULT_SALES_NOTIFICATION_EMAIL;
}

function resolveActivePatientEnterpriseThreshold(): number {
  const raw = Number(
    process.env.ACTIVE_PATIENT_ENTERPRISE_THRESHOLD ||
    process.env.BILLING_ENTERPRISE_PATIENT_THRESHOLD ||
    50
  );
  return Number.isFinite(raw) && raw > 0 ? Math.floor(raw) : 50;
}

function resolveVertoPatientPricingTiers() {
  const raw = sanitizeString(process.env.VERTO_PATIENT_PRICING_TIERS || process.env.PATIENT_BASED_BILLING_TIERS || '', 2000);
  if (!raw) return DEFAULT_VERTO_PATIENT_PRICING_TIERS;
  const parsed = raw
    .split(',')
    .map((entry) => {
      const [limitRaw, priceRaw] = entry.split(':');
      const patientLimit = Math.floor(Number(limitRaw));
      const fixedMonthlyPriceCents = Math.round(Number(priceRaw));
      return { patientLimit, fixedMonthlyPriceCents };
    })
    .filter((tier) => Number.isFinite(tier.patientLimit) && tier.patientLimit > 0 && Number.isFinite(tier.fixedMonthlyPriceCents) && tier.fixedMonthlyPriceCents > 0);
  return parsed.length > 0 ? parsed : DEFAULT_VERTO_PATIENT_PRICING_TIERS;
}

function resolvePatientBasedBillingEnabled(): boolean {
  return isVertoPatientBasedBillingEnabled(
    process.env.PATIENT_BASED_BILLING_ENABLED ||
      process.env.VERTO_PATIENT_BASED_BILLING_ENABLED ||
      ''
  );
}

function resolveBillingPlanSnapshotTtlMs(): number {
  const minutes = Number(
    process.env.BILLING_PLAN_SNAPSHOT_TTL_MINUTES ||
    process.env.STRIPE_PLAN_CACHE_TTL_MINUTES ||
    10
  );
  const safeMinutes = Number.isFinite(minutes) && minutes > 0 ? minutes : 10;
  return Math.floor(safeMinutes * 60 * 1000);
}

function normalizeActivePatientQuantity(value: unknown): number | null {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || !Number.isInteger(parsed) || parsed < 1) return null;
  return Math.min(100000, parsed);
}

const BILLABLE_ACTIVE_PATIENT_STATUSES = new Set([
  'active',
  'ativo',
  'atendimento_ativo',
  'em_tratamento'
]);

function isBillableActivePatientStatus(value: unknown): boolean {
  const normalized = sanitizeString(value, 80).toLowerCase();
  return BILLABLE_ACTIVE_PATIENT_STATUSES.has(normalized);
}

function findPlanTierForActivePatients(
  plans: SafeStripeBillingPlan[],
  activePatients: number,
  enterpriseThreshold = resolveActivePatientEnterpriseThreshold()
): { plan: SafeStripeBillingPlan | null; tier: SafeStripeBillingTier | null; limit: number | null; enterpriseRequired: boolean } {
  const safeQuantity = Math.max(1, Math.floor(Number(activePatients) || 1));
  for (const plan of plans) {
    if (!plan?.selfService || plan.isCustom) continue;
    const threshold = Number(plan.enterpriseThreshold || enterpriseThreshold || 50);
    for (const tier of plan.tiers || []) {
      const tierFrom = Number(tier.from || 1);
      const tierTo = typeof tier.to === 'number' ? tier.to : null;
      const matchesLowerBound = safeQuantity >= tierFrom;
      const matchesUpperBound = tierTo === null || safeQuantity <= tierTo;
      if (matchesLowerBound && matchesUpperBound) {
        const limit = tierTo || threshold || null;
        return {
          plan,
          tier,
          limit,
          enterpriseRequired: Boolean(limit && threshold && limit > threshold)
        };
      }
    }
    if (typeof plan.maxPatients === 'number' && safeQuantity <= plan.maxPatients) {
      return {
        plan,
        tier: null,
        limit: plan.maxPatients,
        enterpriseRequired: Boolean(threshold && plan.maxPatients > threshold)
      };
    }
  }
  return {
    plan: null,
    tier: null,
    limit: null,
    enterpriseRequired: safeQuantity > enterpriseThreshold
  };
}

async function readClinicActivePatientBillingState(clinicId: string): Promise<{
  currentActivePatientLimit: number | null;
  currentActivePatientCount: number | null;
  pendingBillingQuantity: number | null;
  pendingEffectiveDate: string | null;
  pendingBillingStatus: string | null;
  stripeSubscriptionId: string | null;
  stripeSubscriptionItemId: string | null;
  stripePriceId: string | null;
  subscriptionStatus: string | null;
}> {
  const safeClinicId = sanitizeString(clinicId, 120);
  const empty = {
    currentActivePatientLimit: null,
    currentActivePatientCount: null,
    pendingBillingQuantity: null,
    pendingEffectiveDate: null,
    pendingBillingStatus: null,
    stripeSubscriptionId: null,
    stripeSubscriptionItemId: null,
    stripePriceId: null,
    subscriptionStatus: null
  };
  if (!isUuid(safeClinicId)) return empty;

  const run = (selectColumns: string) =>
    supabase
      .from('clinics')
      .select(selectColumns)
      .eq('id', safeClinicId)
      .maybeSingle();

  let result = await run([
    'id',
    'subscription_status',
    'stripe_subscription_id',
    'stripe_subscription_item_id',
    'stripe_price_id',
    'active_patient_count',
    'current_active_patient_limit',
    'current_active_patient_count',
    'pending_billing_quantity',
    'pending_effective_date',
    'pending_billing_status'
  ].join(','));
  if (result.error && extractMissingColumnName(result.error)) {
    result = await run('id,subscription_status,stripe_subscription_id,stripe_subscription_item_id,stripe_price_id,active_patient_count');
  }
  if (result.error || !result.data) return empty;
  const row: any = result.data;
  const pendingStatus = sanitizeString(row.pending_billing_status, 80) || null;
  return {
    currentActivePatientLimit: normalizeActivePatientQuantity(row.current_active_patient_limit),
    currentActivePatientCount: typeof row.current_active_patient_count === 'number'
      ? Math.max(0, Math.floor(row.current_active_patient_count))
      : typeof row.active_patient_count === 'number'
        ? Math.max(0, Math.floor(row.active_patient_count))
        : null,
    pendingBillingQuantity: normalizeActivePatientQuantity(row.pending_billing_quantity),
    pendingEffectiveDate: sanitizeString(row.pending_effective_date, 80) || null,
    pendingBillingStatus: pendingStatus,
    stripeSubscriptionId: sanitizeString(row.stripe_subscription_id, 200) || null,
    stripeSubscriptionItemId: sanitizeString(row.stripe_subscription_item_id, 200) || null,
    stripePriceId: sanitizeString(row.stripe_price_id, 200) || null,
    subscriptionStatus: sanitizeString(row.subscription_status, 80) || null
  };
}

async function resolveClinicActivePatientLimit(params: {
  clinicId: string;
  activePatientCount: number;
  requiredActivePatientCount?: number;
  billingState?: Awaited<ReturnType<typeof readClinicActivePatientBillingState>>;
}): Promise<{
  currentLimit: number | null;
  requiredLimit: number | null;
  enterpriseRequired: boolean;
  requiredTierLabel: string | null;
  plansSource: string;
}> {
  const activePatientCount = Math.max(0, Math.floor(Number(params.activePatientCount) || 0));
  const requiredActivePatientCount = Math.max(
    1,
    Math.floor(Number(params.requiredActivePatientCount || params.activePatientCount || 1))
  );
  const billingState = params.billingState || await readClinicActivePatientBillingState(params.clinicId);
  const confirmedPendingLimit =
    billingState.pendingBillingStatus === 'confirmed_next_cycle' && billingState.pendingBillingQuantity
      ? billingState.pendingBillingQuantity
      : null;
  let currentLimit = confirmedPendingLimit || billingState.currentActivePatientLimit || null;
  const enterpriseThreshold = resolveActivePatientEnterpriseThreshold();
  let plans: SafeStripeBillingPlan[] = [];
  let plansSource = 'not_loaded';
  try {
    const loaded = await loadBillingPlansFromSnapshots({ allowSync: true });
    plans = loaded.plans || [];
    plansSource = loaded.source;
  } catch (error: any) {
    console.warn('[Billing Limits] Falha ao carregar planos para validar limite de pacientes ativos.', {
      clinicId: sanitizeString(params.clinicId, 120),
      message: sanitizeString(error?.message || String(error), 240)
    });
  }

  if (!currentLimit && plans.length > 0) {
    const currentTier = findPlanTierForActivePatients(plans, Math.max(1, activePatientCount || 1), enterpriseThreshold);
    currentLimit = currentTier.limit;
  }

  const requiredTier = plans.length > 0
    ? findPlanTierForActivePatients(plans, requiredActivePatientCount, enterpriseThreshold)
    : {
        tier: null,
        limit: requiredActivePatientCount > enterpriseThreshold ? null : requiredActivePatientCount,
        enterpriseRequired: requiredActivePatientCount > enterpriseThreshold
      };
  const requiredLimit = requiredTier.limit;
  const requiredTierLabel =
    sanitizeString(requiredTier.tier?.displayLabel, 120) ||
    (requiredLimit ? `até ${requiredLimit} pacientes ativos` : null);

  return {
    currentLimit,
    requiredLimit,
    enterpriseRequired: requiredTier.enterpriseRequired || requiredActivePatientCount > enterpriseThreshold || !requiredLimit,
    requiredTierLabel,
    plansSource
  };
}

function billingUpgradeRequiredPayload(params: {
  currentLimit: number;
  currentActivePatients: number;
  requiredActivePatients: number;
  requiredLimit: number | null;
  requiredTierLabel?: string | null;
  enterpriseRequired?: boolean;
}) {
  const currentLimit = Math.max(0, Math.floor(params.currentLimit || 0));
  const requiredLimit = params.requiredLimit ? Math.max(0, Math.floor(params.requiredLimit)) : null;
  const requiredTier = params.enterpriseRequired
    ? 'plano personalizado'
    : sanitizeString(params.requiredTierLabel, 120) || (requiredLimit ? `até ${requiredLimit} pacientes ativos` : 'nova faixa');
  const message = params.enterpriseRequired
    ? `Seu plano atual cobre até ${currentLimit} pacientes ativos. Para ativar este paciente, solicite uma proposta personalizada.`
    : `Seu plano atual cobre até ${currentLimit} pacientes ativos. Para ativar este paciente, atualize para a faixa ${requiredTier}.`;
  return {
    success: false,
    code: 'BILLING_UPGRADE_REQUIRED',
    error: message,
    message,
    details: {
      currentLimit,
      currentActivePatients: Math.max(0, Math.floor(params.currentActivePatients || 0)),
      requiredActivePatients: Math.max(1, Math.floor(params.requiredActivePatients || 1)),
      requiredLimit,
      requiredTierLabel: requiredTier,
      enterpriseRequired: Boolean(params.enterpriseRequired),
      salesContactUrl: params.enterpriseRequired ? resolveSalesContactUrl() : null,
      policy: {
        requiresExplicitConfirmation: true,
        effectiveTiming: 'next_billing_cycle',
        prorationBehavior: 'none'
      }
    }
  };
}

function sendBillingUpgradeRequired(res: any, payload: ReturnType<typeof billingUpgradeRequiredPayload>) {
  return res.status(402).json(payload);
}

async function isPatientCurrentlyBillableActive(params: {
  patientId?: string | null;
  clinicId?: string | null;
}): Promise<boolean> {
  const patientId = sanitizeString(params.patientId, 120);
  const clinicId = sanitizeString(params.clinicId, 120);
  if (!isUuid(patientId)) return false;
  let query = supabase
    .from('patients')
    .select('id, clinic_id, status, is_active, deleted_at, archived_at')
    .eq('id', patientId);
  if (isUuid(clinicId)) query = query.eq('clinic_id', clinicId);
  const result = await query.maybeSingle();
  if (result.error && extractMissingColumnName(result.error) === 'archived_at') {
    let fallbackQuery = supabase
      .from('patients')
      .select('id, clinic_id, status, is_active, deleted_at')
      .eq('id', patientId);
    if (isUuid(clinicId)) fallbackQuery = fallbackQuery.eq('clinic_id', clinicId);
    const fallback = await fallbackQuery.maybeSingle();
    if (fallback.error || !fallback.data) return false;
    return fallback.data.is_active === true && !fallback.data.deleted_at && isBillableActivePatientStatus(fallback.data.status);
  }
  if (result.error || !result.data) return false;
  return (
    result.data.is_active === true &&
    !result.data.deleted_at &&
    !result.data.archived_at &&
    isBillableActivePatientStatus(result.data.status)
  );
}

async function legacyAssertCanActivateBillablePatient(params: {
  clinicId?: string | null;
  patientId?: string | null;
  targetStatus?: string | null;
  actorUserId?: string | null;
  trigger: string;
}): Promise<{ ok: true } | { ok: false; payload: ReturnType<typeof billingUpgradeRequiredPayload> }> {
  const clinicId = sanitizeString(params.clinicId, 120);
  if (!isUuid(clinicId) || !isBillableActivePatientStatus(params.targetStatus)) return { ok: true };
  const demoState = await fetchClinicDemoState(clinicId);
  if (demoState.isDemo) return { ok: true };

  const currentActivePatients = await getBillableActivePatientCount({ supabase, clinicId });
  const alreadyBillable = await isPatientCurrentlyBillableActive({ patientId: params.patientId, clinicId });
  const requiredActivePatients = alreadyBillable ? currentActivePatients : currentActivePatients + 1;
  const billingState = await readClinicActivePatientBillingState(clinicId);
  const limitResolution = await resolveClinicActivePatientLimit({
    clinicId,
    activePatientCount: currentActivePatients,
    requiredActivePatientCount: requiredActivePatients,
    billingState
  });
  const currentLimit = limitResolution.currentLimit;
  if (!currentLimit || requiredActivePatients <= currentLimit) {
    await patchTableSafely('clinics', { column: 'id', value: clinicId }, {
      current_active_patient_count: currentActivePatients,
      active_patient_count: currentActivePatients,
      updated_at: new Date().toISOString()
    });
    return { ok: true };
  }

  const patientBasedBillingEnabled = resolvePatientBasedBillingEnabled();
  const requiredBillingQuantity = patientBasedBillingEnabled
    ? requiredActivePatients
    : limitResolution.requiredLimit;
  const requiredTierLabel = patientBasedBillingEnabled
    ? `${requiredActivePatients} pacientes ativos`
    : limitResolution.requiredTierLabel;

  console.info('[Billing Limits] ativacao de paciente exige upgrade confirmado.', {
    clinicId,
    patientId: sanitizeString(params.patientId, 120) || null,
    actorUserId: sanitizeString(params.actorUserId, 120) || null,
    trigger: sanitizeString(params.trigger, 80),
    currentActivePatients,
    requiredActivePatients,
    currentLimit,
    requiredLimit: requiredBillingQuantity,
    enterpriseRequired: limitResolution.enterpriseRequired,
    plansSource: limitResolution.plansSource
  });

  return {
    ok: false,
    payload: billingUpgradeRequiredPayload({
      currentLimit,
      currentActivePatients,
      requiredActivePatients,
      requiredLimit: requiredBillingQuantity,
      requiredTierLabel,
      enterpriseRequired: limitResolution.enterpriseRequired
    })
  };
}

async function assertCanActivateBillablePatient(params: {
  clinicId?: string | null;
  patientId?: string | null;
  targetStatus?: string | null;
  actorUserId?: string | null;
  trigger: string;
}): Promise<{ ok: true } | { ok: false; payload: ReturnType<typeof billingUpgradeRequiredPayload> }> {
  // Patient activation must never wait for an operator to authorize a pricing
  // change. The post-mutation queue mirrors the canonical count in Stripe.
  void params;
  return { ok: true };
}

function withEnterpriseThreshold<T extends { enterpriseThreshold?: number | null }>(plan: T, fallbackThreshold: number): T & { enterpriseThreshold: number } {
  const planThreshold = Number(plan.enterpriseThreshold || 0);
  return {
    ...plan,
    enterpriseThreshold: Number.isFinite(planThreshold) && planThreshold > 0 ? Math.floor(planThreshold) : fallbackThreshold
  };
}

function isMissingStripeConfigError(error: any): boolean {
  const message = sanitizeString(error?.message || String(error || ''), 500).toLowerCase();
  return message.includes('stripe_secret_key') || message.includes('stripe secret key');
}

const BILLING_PLAN_SNAPSHOT_COLUMNS = [
  'id',
  'stripe_product_id',
  'stripe_price_id',
  'lookup_key',
  'plan_key',
  'name',
  'description',
  'currency',
  'interval',
  'interval_count',
  'billing_scheme',
  'tiers_mode',
  'usage_type',
  'active',
  'self_service',
  'enterprise_threshold',
  'tiers_json',
  'metadata_json',
  'last_synced_at',
  'stripe_created_at',
  'stripe_updated_at',
  'created_at',
  'updated_at'
].join(', ');

type BillingPlanSnapshotRow = {
  id?: string | null;
  stripe_product_id: string;
  stripe_price_id: string;
  lookup_key?: string | null;
  plan_key?: string | null;
  name: string;
  description?: string | null;
  currency: string;
  interval?: string | null;
  interval_count?: number | null;
  billing_scheme?: string | null;
  tiers_mode?: string | null;
  usage_type?: string | null;
  active?: boolean | null;
  self_service?: boolean | null;
  enterprise_threshold?: number | null;
  tiers_json?: unknown;
  metadata_json?: unknown;
  last_synced_at?: string | null;
  stripe_created_at?: string | null;
  stripe_updated_at?: string | null;
  created_at?: string | null;
  updated_at?: string | null;
};

function billingMoneyLabel(amountCents: number | null | undefined, currency = 'brl'): string | null {
  if (typeof amountCents !== 'number' || !Number.isFinite(amountCents)) return null;
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: sanitizeString(currency, 10).toUpperCase() || 'BRL'
  }).format(amountCents / 100);
}

function billingTierDisplayLabel(tier: SafeStripeBillingTier): string {
  const from = Math.max(1, Number(tier.from || 1));
  const to = tier.to === null || tier.upTo === null ? null : Number(tier.to || tier.upTo || 0);
  return to ? `${from} a ${to} pacientes ativos` : `Acima de ${Math.max(0, from - 1)} pacientes ativos`;
}

function enrichBillingPlanForUi(plan: SafeStripeBillingPlan): SafeStripeBillingPlan {
  const tiers = Array.isArray(plan.tiers)
    ? plan.tiers.map((tier) => {
        const flat = typeof tier.flatAmountCents === 'number' ? tier.flatAmountCents : null;
        const unit = typeof tier.unitAmountCents === 'number' ? tier.unitAmountCents : null;
        const primaryAmount = flat !== null ? flat : unit;
        return {
          ...tier,
          displayLabel: billingTierDisplayLabel(tier),
          displayPrice: flat !== null
            ? `${billingMoneyLabel(flat, plan.currency)}/mês`
            : unit !== null
              ? `${billingMoneyLabel(unit, plan.currency)} por paciente/mês`
              : null
        };
      })
    : [];
  return { ...plan, tiers };
}

function billingPlanToSnapshotPayload(plan: SafeStripeBillingPlan, nowIso: string): BillingPlanSnapshotRow {
  return {
    stripe_product_id: sanitizeString(plan.productId, 120),
    stripe_price_id: sanitizeString(plan.priceId, 120),
    lookup_key: sanitizeString(plan.lookupKey || '', 160) || null,
    plan_key: sanitizeString(plan.planKey || '', 160) || null,
    name: sanitizeString(plan.name, 180) || 'Plano Verto',
    description: sanitizeString(plan.description || '', 500) || null,
    currency: sanitizeString(plan.currency, 20).toLowerCase() || 'brl',
    interval: sanitizeString(plan.interval || '', 40) || null,
    interval_count: Number.isFinite(Number(plan.intervalCount)) ? Number(plan.intervalCount) : null,
    billing_scheme: sanitizeString(plan.billingScheme || '', 40) || null,
    tiers_mode: sanitizeString(plan.tiersMode || '', 40) || null,
    usage_type: sanitizeString(plan.usageType || '', 40) || null,
    active: plan.active === true,
    self_service: plan.selfService !== false && !plan.isCustom,
    enterprise_threshold: Number.isFinite(Number(plan.enterpriseThreshold || 0)) && Number(plan.enterpriseThreshold) > 0
      ? Math.floor(Number(plan.enterpriseThreshold))
      : null,
    tiers_json: Array.isArray(plan.tiers) ? plan.tiers : [],
    metadata_json: plan.metadata || {},
    last_synced_at: nowIso,
    stripe_created_at: sanitizeString(plan.stripeCreatedAt || '', 80) || null,
    stripe_updated_at: sanitizeString(plan.stripeUpdatedAt || '', 80) || null,
    updated_at: nowIso
  };
}

function billingPlanFromSnapshot(row: BillingPlanSnapshotRow, fallbackEnterpriseThreshold: number): SafeStripeBillingPlan {
  const metadata = row.metadata_json && typeof row.metadata_json === 'object'
    ? row.metadata_json as Record<string, string>
    : {};
  const tiers = Array.isArray(row.tiers_json) ? row.tiers_json as SafeStripeBillingTier[] : [];
  const maxTier = tiers
    .map((tier) => (tier.to === null || tier.upTo === null ? null : Number(tier.to || tier.upTo || 0)))
    .filter((value): value is number => Number.isFinite(value) && value > 0)
    .reduce<number | null>((max, value) => (max === null || value > max ? value : max), null);
  const enterpriseThreshold =
    Number.isFinite(Number(row.enterprise_threshold || 0)) && Number(row.enterprise_threshold) > 0
      ? Math.floor(Number(row.enterprise_threshold))
      : fallbackEnterpriseThreshold;
  const billingScheme = sanitizeString(row.billing_scheme || '', 40) || 'per_unit';
  const selfService = row.self_service !== false;
  const isCustom = selfService === false;
  return enrichBillingPlanForUi({
    productId: sanitizeString(row.stripe_product_id, 120),
    priceId: sanitizeString(row.stripe_price_id, 120),
    lookupKey: sanitizeString(row.lookup_key || '', 160) || null,
    planKey: sanitizeString(row.plan_key || '', 160) || null,
    name: sanitizeString(row.name, 180) || 'Plano Verto',
    description: sanitizeString(row.description || '', 500) || null,
    currency: sanitizeString(row.currency, 20).toLowerCase() || 'brl',
    interval: sanitizeString(row.interval || '', 40) || null,
    intervalCount: Number.isFinite(Number(row.interval_count)) ? Number(row.interval_count) : null,
    billingScheme,
    tiersMode: sanitizeString(row.tiers_mode || '', 40) || null,
    usageType: sanitizeString(row.usage_type || '', 40) || null,
    unitAmountCents: null,
    unitAmountDecimal: null,
    tiers,
    active: row.active !== false,
    metadata,
    patientLimit: maxTier,
    minPatients: tiers[0]?.from || null,
    maxPatients: maxTier,
    pricingModel: tiers.length > 0 ? 'tiered_active_patients' : 'per_patient',
    usesActivePatientQuantity: billingScheme === 'tiered' || selfService,
    isCustom,
    enterpriseThreshold,
    selfService,
    stripeCreatedAt: sanitizeString(row.stripe_created_at || '', 80) || null,
    stripeUpdatedAt: sanitizeString(row.stripe_updated_at || '', 80) || null
  });
}

async function readActiveBillingPlanSnapshots(): Promise<BillingPlanSnapshotRow[]> {
  const { data, error } = await supabase
    .from('billing_plan_snapshots')
    .select(BILLING_PLAN_SNAPSHOT_COLUMNS)
    .eq('active', true)
    .order('last_synced_at', { ascending: false });
  if (error) throw error;
  return Array.isArray(data) ? data as BillingPlanSnapshotRow[] : [];
}

function snapshotsAreFresh(rows: BillingPlanSnapshotRow[]): boolean {
  if (!rows.length) return false;
  const ttlMs = resolveBillingPlanSnapshotTtlMs();
  const newest = rows
    .map((row) => new Date(String(row.last_synced_at || 0)).getTime())
    .filter((time) => Number.isFinite(time))
    .sort((a, b) => b - a)[0] || 0;
  return newest > 0 && Date.now() - newest <= ttlMs;
}

type StripePlanSyncResult = {
  pricesFound: number;
  activePrices: number;
  matchedVertoPrices: number;
  snapshotsCreated: number;
  snapshotsUpdated: number;
  snapshotsDeactivated: number;
  currentActivePriceId: string | null;
  tierCount: number;
  plans: SafeStripeBillingPlan[];
};

async function syncStripeBillingPlanSnapshots(reason = 'manual'): Promise<StripePlanSyncResult> {
  const stripe = getStripe();
  const enterpriseThreshold = resolveActivePatientEnterpriseThreshold();
  const activePatientPriceId = resolveActivePatientPriceId();
  const plans = (await listStripeActivePatientBillingPlans({
    stripe,
    activePatientPriceId,
    allowedPriceIds: resolveBillingPlanPriceIds()
  })).map((plan) => enrichBillingPlanForUi(withEnterpriseThreshold(plan, enterpriseThreshold)));
  const nowIso = new Date().toISOString();

  const { data: existingRows, error: existingError } = await supabase
    .from('billing_plan_snapshots')
    .select('id, stripe_price_id, active')
    .order('created_at', { ascending: true });
  if (existingError) throw existingError;
  const existingByPriceId = new Map<string, any>(
    (Array.isArray(existingRows) ? existingRows : []).map((row: any) => [sanitizeString(row.stripe_price_id, 120), row])
  );

  let snapshotsCreated = 0;
  let snapshotsUpdated = 0;
  const activePriceIds = new Set<string>();
  for (const plan of plans) {
    const payload = billingPlanToSnapshotPayload(plan, nowIso);
    activePriceIds.add(payload.stripe_price_id);
    const existed = existingByPriceId.has(payload.stripe_price_id);
    const { error: upsertError } = await supabase
      .from('billing_plan_snapshots')
      .upsert(payload, { onConflict: 'stripe_price_id' });
    if (upsertError) throw upsertError;
    if (existed) snapshotsUpdated += 1;
    else snapshotsCreated += 1;
  }

  let snapshotsDeactivated = 0;
  for (const row of Array.isArray(existingRows) ? existingRows : []) {
    const priceId = sanitizeString((row as any).stripe_price_id, 120);
    if (!priceId || activePriceIds.has(priceId) || (row as any).active === false) continue;
    const { error: deactivateError } = await supabase
      .from('billing_plan_snapshots')
      .update({ active: false, last_synced_at: nowIso, updated_at: nowIso })
      .eq('stripe_price_id', priceId);
    if (deactivateError) throw deactivateError;
    snapshotsDeactivated += 1;
  }

  const currentActivePriceId = activePatientPriceId || plans.find((plan) => plan.selfService && !plan.isCustom)?.priceId || null;
  const result = {
    pricesFound: plans.length,
    activePrices: plans.filter((plan) => plan.active).length,
    matchedVertoPrices: plans.length,
    snapshotsCreated,
    snapshotsUpdated,
    snapshotsDeactivated,
    currentActivePriceId,
    tierCount: plans.reduce((total, plan) => total + (plan.tiers?.length || 0), 0),
    plans
  };
  console.info('[Stripe Plan Sync] diagnostics:', {
    reason,
    ...result,
    plans: undefined,
    lookupKeys: resolveActivePatientPlanLookupKeys()
  });
  return result;
}

async function loadBillingPlansFromSnapshots(params: { allowSync?: boolean; forceSync?: boolean } = {}): Promise<{
  plans: SafeStripeBillingPlan[];
  source: 'snapshot' | 'stripe_sync' | 'stale_snapshot';
  sync?: StripePlanSyncResult | null;
}> {
  const enterpriseThreshold = resolveActivePatientEnterpriseThreshold();
  let snapshots = await readActiveBillingPlanSnapshots();
  let source: 'snapshot' | 'stripe_sync' | 'stale_snapshot' = snapshotsAreFresh(snapshots) ? 'snapshot' : 'stale_snapshot';
  let sync: StripePlanSyncResult | null = null;

  if ((params.forceSync || (!snapshots.length || !snapshotsAreFresh(snapshots))) && params.allowSync !== false) {
    try {
      sync = await syncStripeBillingPlanSnapshots(params.forceSync ? 'force' : 'cache_miss_or_stale');
      snapshots = await readActiveBillingPlanSnapshots();
      source = 'stripe_sync';
    } catch (syncError: any) {
      if (!snapshots.length) throw syncError;
      console.warn('[Stripe Plan Sync] usando snapshot antigo como fallback:', {
        message: sanitizeString(syncError?.message || String(syncError), 240)
      });
      source = 'stale_snapshot';
    }
  }

  const plans = snapshots
    .map((row) => billingPlanFromSnapshot(row, enterpriseThreshold))
    .sort((a, b) => {
      if (a.isCustom !== b.isCustom) return a.isCustom ? 1 : -1;
      const aLimit = a.maxPatients ?? Number.MAX_SAFE_INTEGER;
      const bLimit = b.maxPatients ?? Number.MAX_SAFE_INTEGER;
      if (aLimit !== bLimit) return aLimit - bLimit;
      return a.name.localeCompare(b.name, 'pt-BR');
    });
  return { plans, source, sync };
}

const ACTIVE_PATIENT_BILLING_MODEL = 'active_patients';
const CLINIC_ACCESS_ACTIVE_STATUSES = new Set(['active', 'trial_active', 'trialing', 'demo', 'demo_sandbox']);
const CLINIC_MEMBER_BILLING_READY_SYNC_STATUSES = new Set(['synced', 'within_current_limit']);
const CLINIC_MEMBER_HARD_BLOCK_STATUSES = new Set([
  'blocked',
  'canceled',
  'cancelled',
  'incomplete_expired',
  'checkout_abandoned'
]);
const CLINIC_MEMBER_GRACE_STATUSES = new Set(['past_due', 'unpaid', 'delinquent']);
const CLINIC_ACCESS_BLOCKED_STATUSES = new Set([
  '',
  'pending',
  'plan_required',
  'payment_required',
  'subscription_pending',
  'incomplete',
  'incomplete_expired',
  'past_due',
  'unpaid',
  'delinquent',
  'blocked',
  'canceled',
  'cancelled',
  'checkout_abandoned'
]);

function normalizeClinicAccessStatus(value: any): string {
  return sanitizeString(value, 60).toLowerCase();
}

function roleRequiresClinicBillingAccess(role: any): boolean {
  return ['director', 'coordinator', 'supervisor', 'therapist', 'receptionist', 'biller', 'admin'].includes(
    sanitizeString(role, 40).toLowerCase()
  );
}

async function resolveClinicManagedMemberDashboardAccess(clinicIdValue: unknown, clinicRow: any): Promise<boolean> {
  const clinicId = sanitizeString(clinicIdValue, 120);
  if (!isUuid(clinicId)) return false;

  const subscriptionStatus = normalizeClinicAccessStatus(clinicRow?.subscription_status);
  const billingModel = sanitizeString(clinicRow?.billing_model, 60).toLowerCase();
  const billingSyncStatus = sanitizeString(clinicRow?.billing_sync_status, 80).toLowerCase();

  // Explicit terminal states always win. A stale sync marker or entitlement
  // snapshot must never reopen a cancelled/blocked clinic for an invited member.
  if (CLINIC_MEMBER_HARD_BLOCK_STATUSES.has(subscriptionStatus)) return false;

  // Stripe payment failures intentionally grant a short grace period. The old
  // onboarding gate ignored stripe_access_block_at and blocked invited staff
  // immediately, before the clinic itself was actually blocked.
  if (CLINIC_MEMBER_GRACE_STATUSES.has(subscriptionStatus)) {
    const accessBlockAtRaw = sanitizeString(clinicRow?.stripe_access_block_at, 80);
    const accessBlockAt = accessBlockAtRaw ? new Date(accessBlockAtRaw).getTime() : Number.NaN;
    if (Number.isFinite(accessBlockAt)) return accessBlockAt > Date.now();
  }

  // A collaborator never owns the clinic checkout. Once the membership is active,
  // access follows the clinic's commercial state instead of the collaborator's
  // individual profile. Healthy states stay on the fast path with no extra read.
  if (
    !subscriptionStatus ||
    CLINIC_ACCESS_ACTIVE_STATUSES.has(subscriptionStatus) ||
    billingModel === 'demo' ||
    billingModel === 'demo_sandbox'
  ) {
    return true;
  }

  // Some older clinics persisted the paid state on the owner profile before the
  // clinic mirror was fully reconciled. Only ambiguous states pay this one extra
  // read, and only the three commercial columns required for the decision are read.
  const ownerUserId = sanitizeString(clinicRow?.owner_user_id || clinicRow?.created_by, 120);
  if (isUuid(ownerUserId)) {
    let ownerAccessColumns = ['subscription_status', 'billing_model', 'stripe_access_block_at'];
    let ownerResult: any = { data: null, error: null };
    for (let attempt = 0; attempt < 3; attempt += 1) {
      ownerResult = await supabase
        .from('users')
        .select(ownerAccessColumns.join(','))
        .eq('id', ownerUserId)
        .maybeSingle();
      if (!ownerResult.error) break;
      const missingColumn = extractMissingColumnName(ownerResult.error);
      if (!missingColumn || !ownerAccessColumns.includes(missingColumn) || ownerAccessColumns.length <= 1) break;
      ownerAccessColumns = ownerAccessColumns.filter((column) => column !== missingColumn);
    }

    if (!ownerResult.error && ownerResult.data) {
      const ownerStatus = normalizeClinicAccessStatus(ownerResult.data?.subscription_status);
      const ownerBillingModel = sanitizeString(ownerResult.data?.billing_model, 60).toLowerCase();
      if (CLINIC_MEMBER_HARD_BLOCK_STATUSES.has(ownerStatus)) return false;
      if (CLINIC_MEMBER_GRACE_STATUSES.has(ownerStatus)) {
        const ownerBlockAtRaw = sanitizeString(ownerResult.data?.stripe_access_block_at, 80);
        const ownerBlockAt = ownerBlockAtRaw ? new Date(ownerBlockAtRaw).getTime() : Number.NaN;
        if (Number.isFinite(ownerBlockAt)) return ownerBlockAt > Date.now();
      }
      if (
        CLINIC_ACCESS_ACTIVE_STATUSES.has(ownerStatus) ||
        ownerBillingModel === 'demo' ||
        ownerBillingModel === 'demo_sandbox'
      ) {
        return true;
      }
    }
  }

  // Backward-compatible active-patient billing marker. It is never allowed to
  // override cancellation or an expired payment grace period evaluated above.
  if (
    CLINIC_MEMBER_BILLING_READY_SYNC_STATUSES.has(billingSyncStatus) &&
    !CLINIC_MEMBER_GRACE_STATUSES.has(subscriptionStatus)
  ) {
    return true;
  }

  // Contract entitlements are a valid positive signal for modular paid/trial/grace
  // organizations. legacy_full is intentionally not used as billing evidence: it
  // exists to preserve module visibility for old clinics, not to prove payment.
  if (CLINIC_ACCESS_BLOCKED_STATUSES.has(subscriptionStatus)) {
    try {
      const { data, error } = await supabase.rpc('get_organization_module_access_v1', {
        p_organization_id: clinicId,
      });
      if (error) return false;
      const mode = sanitizeString((data as any)?.mode, 30).toLowerCase();
      const modules = Array.isArray((data as any)?.modules) ? (data as any).modules : [];
      if (mode === 'contract' && modules.some((item: any) => isOrganizationModuleKey(sanitizeString(item, 80)))) {
        return true;
      }
    } catch {
      return false;
    }
  }

  // Unknown commercial states fail closed. A future Stripe/status value must be
  // added deliberately instead of silently granting access to the whole clinic.
  return false;
}

function hasActiveClinicBillingAccess(user: any): boolean {
  const role = sanitizeString(user?.role, 40).toLowerCase();
  if (!roleRequiresClinicBillingAccess(role)) return true;
  const onboardingContext = compactOnboardingContextForSession(user?.onboardingContext);
  if (
    onboardingContext?.requiresPayment === false &&
    onboardingContext?.clinic?.id &&
    ['invited_professional', 'clinic_member'].includes(onboardingContext.onboardingMode)
  ) {
    return onboardingContext.canAccessDashboard !== false;
  }
  if (user?.isDemoUser === true || user?.is_demo_user === true) return true;
  const billingModel = sanitizeString(user?.billingModel || user?.billing_model, 60).toLowerCase();
  if (billingModel === 'demo' || billingModel === 'demo_sandbox') return true;
  const status = normalizeClinicAccessStatus(user?.subscriptionStatus || user?.subscription_status);
  if (CLINIC_ACCESS_ACTIVE_STATUSES.has(status)) return true;
  if (CLINIC_ACCESS_BLOCKED_STATUSES.has(status)) return false;
  return false;
}

function isBillingOnboardingAllowedPath(pathname: any): boolean {
  const path = sanitizeString(pathname, 240).toLowerCase();
  return (
    path === '/api/auth/me' ||
    path === '/api/onboarding/context' ||
    path === '/api/auth/logout' ||
    path === '/api/workspaces' ||
    path === '/api/workspaces/select' ||
    path === '/api/access-contexts/select' ||
    path === '/api/clinic/accept-invite' ||
    path === '/api/supabase-config' ||
    path.startsWith('/api/profile/') ||
    path.startsWith('/api/stripe/') ||
    path.startsWith('/api/billing/') ||
    path.startsWith('/api/config')
  );
}

function isClinicInvitationAcceptancePath(pathname: any): boolean {
  return sanitizeString(pathname, 240).toLowerCase() === '/api/clinic/accept-invite';
}

function isAccessContextSelectionAllowedPath(pathname: any): boolean {
  const path = sanitizeString(pathname, 240).toLowerCase();
  return (
    path === '/api/auth/me' ||
    path === '/api/auth/logout' ||
    path === '/api/onboarding/context' ||
    path === '/api/workspaces' ||
    path === '/api/workspaces/select' ||
    path === '/api/access-contexts/select' ||
    path === '/api/clinic/accept-invite' ||
    path === '/api/supabase-config'
  );
}

function billingAccessBlockedPayload(user: any) {
  const status = normalizeClinicAccessStatus(user?.subscriptionStatus || user?.subscription_status) || 'payment_required';
  return {
    error: 'SUBSCRIPTION_REQUIRED',
    message: 'Escolha um plano e ative a assinatura para acessar o painel completo.',
    onboardingState:
      status === 'plan_required'
        ? 'PLAN_REQUIRED'
        : status === 'subscription_pending' || status === 'pending'
          ? 'SUBSCRIPTION_PENDING'
          : status === 'past_due' || status === 'unpaid' || status === 'delinquent'
            ? 'PAST_DUE'
            : status === 'blocked'
              ? 'BLOCKED'
              : 'PAYMENT_REQUIRED',
    subscriptionStatus: status
  };
}
const DEMO_SANDBOX_BILLING_MODEL = 'demo';
const DEMO_SANDBOX_TEMPLATE_NAME = 'Clinica Demo Verto';
const DEMO_PLAYGROUND_NAME = 'Playground Demo Verto';
const DEMO_SANDBOX_SEED_VERSION = '2026-06-demo-v1';
const DEMO_PRESENTATION_CLINIC_ID = uuidFromStableString('verto:presentation-demo-clinic');
const DEMO_PLAYGROUND_CLINIC_ID = uuidFromStableString('verto:playground-demo-clinic');
const DEMO_SHARED_USER_EMAIL = 'coordenador.teste@verto.com';

function legacyQueueActivePatientSync(clinicId: string | null | undefined, trigger: string) {
  const safeClinicId = sanitizeString(clinicId, 120);
  const activePatientPriceId = resolveActivePatientPriceId();
  if (!safeClinicId || !activePatientPriceId) return;

  try {
    void (async () => {
      const demoState = await fetchClinicDemoState(safeClinicId);
      if (demoState.isDemo) {
        console.log('[Stripe Sync] Clinica demo sem cobranca real. Sync em fila ignorado.', { clinicId: safeClinicId });
        return;
      }
      const stripe = getStripe();
      await syncClinicActivePatientAddonQuantity({
        supabase,
        stripe,
        clinicId: safeClinicId,
        trigger,
        activePatientPriceId,
        logger: console
      });
    })().catch((error: any) => {
      console.error('[CRITICAL] Falha ao sincronizar adicional de pacientes ativos (não bloqueante).', {
        clinicId: safeClinicId,
        trigger,
        message: error?.message || String(error)
      });
    });
  } catch (error: any) {
    console.error('[CRITICAL] Stripe indisponível para sincronização de pacientes ativos.', {
      clinicId: safeClinicId,
      trigger,
      message: error?.message || String(error)
    });
  }
}

type ActivePatientSyncQueueResult = {
  queued: boolean;
  activePatientCount: number;
  queueVersion: number | null;
  growthMilestone: number | null;
};

type ActivePatientSyncQueueJob = {
  clinic_id: string;
  desired_active_patient_count: number;
  queue_version: number;
  attempts: number;
  trigger: string;
};

function isActivePatientSyncQueueUnavailable(error: any): boolean {
  const message = sanitizeString(`${error?.message || ''} ${error?.details || ''} ${error?.hint || ''}`, 600).toLowerCase();
  return (
    isMissingRelationError(error) ||
    message.includes('enqueue_active_patient_billing_sync') ||
    message.includes('active_patient_billing_sync_queue') ||
    message.includes('clinic_growth_milestones')
  );
}

function activePatientSyncIdempotencyKey(clinicId: string, queueVersion: number, quantity: number): string {
  return crypto
    .createHash('sha256')
    .update(`active-patient-sync:${clinicId}:${queueVersion}:${quantity}`)
    .digest('hex');
}

let activePatientSyncDrainInFlight = false;

async function completeActivePatientSyncJob(params: {
  clinicId: string;
  lockToken: string;
  queueVersion: number;
  activePatientCount: number;
}) {
  const { error } = await supabase.rpc('complete_active_patient_billing_sync_job', {
    p_clinic_id: params.clinicId,
    p_lock_token: params.lockToken,
    p_queue_version: params.queueVersion,
    p_synced_active_patient_count: params.activePatientCount
  });
  if (error) throw error;
}

async function failActivePatientSyncJob(params: {
  clinicId: string;
  lockToken: string;
  queueVersion: number;
  errorMessage: string;
}) {
  const { error } = await supabase.rpc('fail_active_patient_billing_sync_job', {
    p_clinic_id: params.clinicId,
    p_lock_token: params.lockToken,
    p_queue_version: params.queueVersion,
    p_error: sanitizeString(params.errorMessage, 1000) || 'active_patient_sync_failed'
  });
  if (error) throw error;
}

async function drainActivePatientSyncQueue(trigger: string): Promise<void> {
  if (activePatientSyncDrainInFlight) return;
  const activePatientPriceId = resolveActivePatientPriceId();
  activePatientSyncDrainInFlight = true;
  const lockToken = crypto.randomUUID();

  try {
    const { data, error } = await supabase.rpc('claim_active_patient_billing_sync_jobs', {
      p_lock_token: lockToken,
      p_limit: 20
    });
    if (error) {
      if (isActivePatientSyncQueueUnavailable(error)) return;
      throw error;
    }

    for (const rawJob of (data || []) as ActivePatientSyncQueueJob[]) {
      const job: ActivePatientSyncQueueJob = {
        clinic_id: sanitizeString(rawJob?.clinic_id, 120),
        desired_active_patient_count: Math.max(0, Math.floor(Number(rawJob?.desired_active_patient_count || 0))),
        queue_version: Math.max(1, Math.floor(Number(rawJob?.queue_version || 1))),
        attempts: Math.max(0, Math.floor(Number(rawJob?.attempts || 0))),
        trigger: sanitizeString(rawJob?.trigger, 100) || 'patient_lifecycle'
      };
      if (!isUuid(job.clinic_id)) continue;

      try {
        const liveCount = await getBillableActivePatientCount({ supabase, clinicId: job.clinic_id });
        if (liveCount !== job.desired_active_patient_count) {
          await queueActivePatientSync(job.clinic_id, 'worker_count_reconciliation');
          await completeActivePatientSyncJob({
            clinicId: job.clinic_id,
            lockToken,
            queueVersion: job.queue_version,
            activePatientCount: job.desired_active_patient_count
          });
          continue;
        }

        const syncResult = await syncClinicActivePatientAddonQuantity({
          supabase,
          stripe: getStripe(),
          clinicId: job.clinic_id,
          trigger: `queue:${sanitizeString(trigger, 40)}:${job.trigger}`,
          activePatientPriceId,
          requestedBillingQuantity: job.desired_active_patient_count,
          idempotencyKey: activePatientSyncIdempotencyKey(job.clinic_id, job.queue_version, job.desired_active_patient_count),
          logger: console
        });
        const terminalReason = ['demo_billing_disabled'].includes(sanitizeString(syncResult.reason, 80));
        if (!syncResult.success || (!syncResult.synced && !terminalReason)) {
          await failActivePatientSyncJob({
            clinicId: job.clinic_id,
            lockToken,
            queueVersion: job.queue_version,
            errorMessage: syncResult.reason || 'stripe_active_patient_sync_pending'
          });
          continue;
        }
        await completeActivePatientSyncJob({
          clinicId: job.clinic_id,
          lockToken,
          queueVersion: job.queue_version,
          activePatientCount: syncResult.activePatients
        });
      } catch (error: any) {
        try {
          await failActivePatientSyncJob({
            clinicId: job.clinic_id,
            lockToken,
            queueVersion: job.queue_version,
            errorMessage: error?.message || String(error)
          });
        } catch (queueError: any) {
          console.error('[ActivePatientSync] retry persistence failed', {
            clinicId: job.clinic_id,
            trigger,
            message: sanitizeString(queueError?.message || String(queueError), 240)
          });
        }
      }
    }
  } catch (error: any) {
    console.error('[ActivePatientSync] queue drain failed', {
      trigger,
      message: sanitizeString(error?.message || String(error), 240)
    });
  } finally {
    activePatientSyncDrainInFlight = false;
  }
}

async function queueActivePatientSync(
  clinicId: string | null | undefined,
  trigger: string,
  options: { previousActivePatientCount?: number | null } = {}
): Promise<ActivePatientSyncQueueResult> {
  const safeClinicId = sanitizeString(clinicId, 120);
  if (!isUuid(safeClinicId)) {
    return { queued: false, activePatientCount: 0, queueVersion: null, growthMilestone: null };
  }

  try {
    const demoState = await fetchClinicDemoState(safeClinicId);
    if (demoState.isDemo) {
      return { queued: false, activePatientCount: 0, queueVersion: null, growthMilestone: null };
    }
    const activePatientCount = await getBillableActivePatientCount({ supabase, clinicId: safeClinicId });
    const { data, error } = await supabase.rpc('enqueue_active_patient_billing_sync', {
      p_clinic_id: safeClinicId,
      p_desired_active_patient_count: activePatientCount,
      p_trigger: sanitizeString(trigger, 100) || 'patient_lifecycle',
      p_previous_active_patient_count:
        typeof options.previousActivePatientCount === 'number' && options.previousActivePatientCount >= 0
          ? Math.floor(options.previousActivePatientCount)
          : null
    });
    if (error) {
      if (isActivePatientSyncQueueUnavailable(error)) {
        console.warn('[ActivePatientSync] persistent queue unavailable', { clinicId: safeClinicId, trigger: sanitizeString(trigger, 100) });
        return { queued: false, activePatientCount, queueVersion: null, growthMilestone: null };
      }
      throw error;
    }

    const row = Array.isArray(data) ? data[0] : data;
    const result: ActivePatientSyncQueueResult = {
      queued: row?.queued !== false,
      activePatientCount,
      queueVersion: Number.isFinite(Number(row?.queue_version)) ? Number(row.queue_version) : null,
      growthMilestone: Number.isFinite(Number(row?.growth_milestone)) ? Number(row.growth_milestone) : null
    };
    void drainActivePatientSyncQueue('patient_lifecycle_enqueue');
    return result;
  } catch (error: any) {
    console.error('[ActivePatientSync] queue enqueue failed', {
      clinicId: safeClinicId,
      trigger: sanitizeString(trigger, 100),
      message: sanitizeString(error?.message || String(error), 240)
    });
    return { queued: false, activePatientCount: 0, queueVersion: null, growthMilestone: null };
  }
}

async function enqueueDueCapacityContractBillingSync(trigger: string): Promise<number> {
  const safeTrigger = sanitizeString(trigger, 100) || 'scheduled_capacity_grace';
  try {
    const result = await supabase.rpc('enqueue_due_capacity_contract_billing_sync', {
      p_trigger: safeTrigger
    });
    if (result.error) {
      const message = sanitizeString(
        `${result.error?.message || ''} ${result.error?.details || ''} ${result.error?.hint || ''}`,
        600,
      ).toLowerCase();
      const unavailable =
        ['PGRST202', '42883', '42P01'].includes(sanitizeString(result.error?.code, 40).toUpperCase())
        || message.includes('enqueue_due_capacity_contract_billing_sync')
        || message.includes('organization_billing_contracts');
      if (unavailable) return 0;
      throw result.error;
    }
    return Math.max(0, Number(result.data || 0));
  } catch (error: any) {
    console.error('[ActivePatientSync] capacity grace enqueue failed', {
      trigger: safeTrigger,
      message: sanitizeString(error?.message || String(error), 240)
    });
    return 0;
  }
}

async function reconcileActivePatientSyncQueue(trigger: string): Promise<number> {
  try {
    const safeTrigger = sanitizeString(trigger, 100) || 'scheduled_reconciliation';
    const { data, error } = await supabase.rpc('reconcile_active_patient_billing_sync_queue', {
      p_trigger: safeTrigger
    });
    if (error) {
      if (isActivePatientSyncQueueUnavailable(error)) return 0;
      throw error;
    }
    const capacityGraceQueued = await enqueueDueCapacityContractBillingSync(
      `${safeTrigger}:capacity_grace`,
    );
    await drainActivePatientSyncQueue(trigger);
    return Math.max(0, Number(data || 0)) + capacityGraceQueued;
  } catch (error: any) {
    console.error('[ActivePatientSync] reconciliation failed', {
      trigger,
      message: sanitizeString(error?.message || String(error), 240)
    });
    return 0;
  }
}

