async function loadSalesPricingCatalog(
  catalogVersionId?: string | null,
  options: { includeDraft?: boolean } = {},
): Promise<SalesPricingCatalogSnapshot & { metadata: Record<string, any> }> {
  let versionQuery = supabase
    .from("sales_pricing_catalog_versions")
    .select(SALES_PRICING_CATALOG_VERSION_SELECT);
  if (catalogVersionId) versionQuery = versionQuery.eq("id", catalogVersionId);
  else versionQuery = versionQuery.eq("status", "active");
  if (!options.includeDraft) {
    versionQuery = versionQuery.in("status", ["active", "archived"]);
  }
  const { data: version, error: versionError } = await versionQuery
    .order("version", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (versionError) throw salesProfitabilityPolicySchemaError(versionError);
  if (!version) {
    const error = new Error("PRICING_CATALOG_VERSION_NOT_FOUND");
    (error as any).code = "PRICING_CATALOG_VERSION_NOT_FOUND";
    throw error;
  }
  const versionId = sanitizeString(version.id, 120);
  const [itemsResult, tiersResult, costsResult] = await Promise.all([
    supabase
      .from("sales_pricing_catalog_items")
      .select(SALES_PRICING_CATALOG_ITEM_SELECT)
      .eq("catalog_version_id", versionId)
      .order("sort_order", { ascending: true }),
    supabase
      .from("sales_pricing_catalog_tiers")
      .select(SALES_PRICING_CATALOG_TIER_SELECT)
      .eq("catalog_version_id", versionId)
      .order("sort_order", { ascending: true }),
    supabase
      .from("sales_pricing_item_cost_models")
      .select(SALES_PRICING_COST_MODEL_SELECT)
      .eq("catalog_version_id", versionId)
      .order("version", { ascending: false }),
  ]);
  const batchError = [itemsResult, tiersResult, costsResult].find(
    (result: any) => result.error,
  )?.error;
  if (batchError) throw batchError;
  const tiersByItem = new Map<string, SalesPricingCatalogTier[]>();
  for (const row of tiersResult.data || []) {
    const tier = mapSalesPricingTier(row);
    const existing = tiersByItem.get(tier.itemId) || [];
    existing.push(tier);
    tiersByItem.set(tier.itemId, existing);
  }
  const costByItem = new Map<string, SalesPricingCostModel>();
  for (const row of costsResult.data || []) {
    const itemId = sanitizeString(row?.catalog_item_id, 120);
    if (!costByItem.has(itemId)) {
      costByItem.set(itemId, mapSalesPricingCostModel(row));
    }
  }
  const items: SalesPricingCatalogItem[] = (itemsResult.data || []).map(
    (row: any) => {
      const itemId = sanitizeString(row?.id, 120);
      const itemKey = sanitizeString(row?.item_key, 80);
      const mappedCost = costByItem.get(itemId) || null;
      return {
        id: itemId,
        itemKey,
        publicName: sanitizeString(row?.public_name, 120),
        internalName: sanitizeString(row?.internal_name, 160),
        description: sanitizeString(row?.public_description, 4000),
        pricingMode: sanitizeString(row?.pricing_mode, 40) as any,
        billingInterval: sanitizeString(row?.billing_interval, 30) as any,
        unitName: sanitizeString(row?.unit_name, 80),
        includedQuantity: nullableSalesNumber(row?.included_quantity),
        maximumQuantity: nullableSalesNumber(row?.maximum_quantity),
        recurringAmountCents: nullableSalesNumber(
          row?.recurring_amount_cents,
        ),
        oneTimeAmountCents: nullableSalesNumber(row?.one_time_amount_cents),
        sortOrder: Number(row?.sort_order || 0),
        isRequired: row?.is_required === true,
        isPublic: row?.is_public === true,
        isActive: row?.is_active === true,
        compatibleBasePackages: Array.isArray(
          row?.compatible_base_packages,
        )
          ? row.compatible_base_packages.map((value: any) =>
              sanitizeString(value, 80)
            ).filter(Boolean)
          : [],
        metadata:
          row?.metadata && typeof row.metadata === "object"
            ? row.metadata
            : {},
        tiers: tiersByItem.get(itemId) || [],
        costModel: mappedCost,
      };
    },
  );
  return {
    id: versionId,
    version: Number(version.version || 0),
    name: sanitizeString(version.name, 120),
    status: sanitizeString(version.status, 20) as any,
    effectiveAt: String(version.effective_at || ""),
    allocationSettings:
      version.allocation_settings
      && typeof version.allocation_settings === "object"
        ? version.allocation_settings
        : {},
    modularCostSettings:
      version.modular_cost_settings
      && typeof version.modular_cost_settings === "object"
        ? version.modular_cost_settings
        : null as any,
    customCapacityPolicy: validateCustomCapacityPolicy(
      version.custom_capacity_policy,
    )
      ? version.custom_capacity_policy
      : null,
    hasVersionedCustomCapacityPolicy: validateCustomCapacityPolicy(
      version.custom_capacity_policy,
    ),
    profitabilityPolicy: validateSalesProfitabilityPolicy(
      version.profitability_policy,
    )
      ? version.profitability_policy
      : null,
    hasVersionedProfitabilityPolicy: validateSalesProfitabilityPolicy(
      version.profitability_policy,
    ),
    items,
    metadata: {
      adminNotes: sanitizeString(version.admin_notes, 2000) || null,
      createdBy: sanitizeString(version.created_by, 120) || null,
      createdAt: version.created_at || null,
      publishedBy: sanitizeString(version.published_by, 120) || null,
      publishedAt: version.published_at || null,
      archivedAt: version.archived_at || null,
    },
  };
}

const SALES_MODULAR_DRIVER_KEYS = new Set<SalesModularDriverKey>(
  SALES_MODULAR_DRIVER_DEFINITIONS.map((definition) => definition.key),
);

function normalizeSalesModularDriverOverrides(
  raw: unknown,
): SalesModularDriverOverrides {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const normalized: SalesModularDriverOverrides = {};
  for (const [rawItemKey, rawDrivers] of Object.entries(raw).slice(0, 50)) {
    const itemKey = sanitizeString(rawItemKey, 80);
    if (!itemKey || !rawDrivers || typeof rawDrivers !== "object" || Array.isArray(rawDrivers)) {
      continue;
    }
    const drivers: Partial<Record<SalesModularDriverKey, SalesModularDriverValue>> = {};
    for (const [rawDriverKey, rawDatum] of Object.entries(rawDrivers).slice(0, 50)) {
      const driverKey = sanitizeString(rawDriverKey, 80) as SalesModularDriverKey;
      if (!SALES_MODULAR_DRIVER_KEYS.has(driverKey) || !rawDatum || typeof rawDatum !== "object" || Array.isArray(rawDatum)) {
        continue;
      }
      const datum = rawDatum as Record<string, any>;
      drivers[driverKey] = {
        value: datum.value === null || datum.value === ""
          ? null
          : Number(datum.value),
        source: sanitizeString(datum.source, 30) as SimulationValueSource,
        sourceDetail: sanitizeString(datum.sourceDetail, 500),
        effectiveAt: sanitizeString(datum.effectiveAt, 80),
        version: Number(datum.version),
      };
    }
    normalized[itemKey] = drivers;
  }
  return normalized;
}

function normalizeSalesModularProposalRequest(
  raw: unknown,
): SalesModularProposalInput {
  const source =
    raw && typeof raw === "object" ? raw as Record<string, any> : {};
  const lines = Array.isArray(source.lines)
    ? source.lines.slice(0, 50).map((line: any) => ({
        itemKey: sanitizeString(line?.itemKey, 80),
        tierId: sanitizeString(line?.tierId, 120) || null,
        quantity: Number(line?.quantity),
        itemDiscountBasisPoints: Number(
          line?.itemDiscountBasisPoints || 0,
        ),
        customRecurringAmountCents:
          line?.customRecurringAmountCents === null
          || line?.customRecurringAmountCents === undefined
            ? null
            : Number(line.customRecurringAmountCents),
        customOneTimeAmountCents:
          line?.customOneTimeAmountCents === null
          || line?.customOneTimeAmountCents === undefined
            ? null
            : Number(line.customOneTimeAmountCents),
        pricingEditMode:
          ["per_patient", "monthly_total"].includes(
            sanitizeString(line?.pricingEditMode, 30),
          )
            ? sanitizeString(line.pricingEditMode, 30) as
              "per_patient" | "monthly_total"
            : undefined,
        proposedPricePerPatientCents:
          line?.proposedPricePerPatientCents === null
          || line?.proposedPricePerPatientCents === undefined
            ? null
            : Number(line.proposedPricePerPatientCents),
        offerDiscount:
          line?.offerDiscount && typeof line.offerDiscount === "object"
            ? {
                type: sanitizeString(line.offerDiscount.type, 30),
                percentageBasisPoints:
                  line.offerDiscount.percentageBasisPoints == null
                    ? undefined
                    : Number(line.offerDiscount.percentageBasisPoints),
                amountOffCents:
                  line.offerDiscount.amountOffCents == null
                    ? undefined
                    : Number(line.offerDiscount.amountOffCents),
                startsAt: sanitizeString(line.offerDiscount.startsAt, 80),
                endsAt:
                  sanitizeString(line.offerDiscount.endsAt, 80) || null,
                durationCount:
                  line.offerDiscount.durationCount == null
                    ? undefined
                    : Number(line.offerDiscount.durationCount),
                durationUnit: sanitizeString(
                  line.offerDiscount.durationUnit,
                  30,
                ),
                priceBeforeDiscountCents: Number(
                  line.offerDiscount.priceBeforeDiscountCents,
                ),
                discountedPriceCents: Number(
                  line.offerDiscount.discountedPriceCents,
                ),
                priceAfterExpirationCents: Number(
                  line.offerDiscount.priceAfterExpirationCents,
                ),
                reason: sanitizeString(line.offerDiscount.reason, 300),
                internalNotes:
                  sanitizeString(line.offerDiscount.internalNotes, 1000)
                    || undefined,
                status: sanitizeString(line.offerDiscount.status, 30),
              } as OfferItemDiscount
            : null,
      }))
    : [];
  const basePackageSelectionMode = sanitizeString(
    source.basePackageSelectionMode || "automatic",
    20,
  );
  return {
    commercialPricingMode:
      sanitizeString(source.commercialPricingMode, 40) ===
      "manual_module_prices"
        ? "manual_module_prices"
        : "catalog",
    commercialCapacityBasis:
      sanitizeString(source.commercialCapacityBasis, 40) === "current_patients"
        ? "current_patients"
        : "projected_demand",
    exactPerPatientBilling: source.exactPerPatientBilling === true,
    // Snapshots anteriores à Fundação não possuem estes campos. Para não
    // recalcular propostas históricas com uma cobrança nova, ausência significa
    // Fundação manual zero. A interface atual envia automatic_target de forma
    // explícita em cenários novos e em duplicações modernizadas.
    platformFoundationPricingMode:
      sanitizeString(source.platformFoundationPricingMode, 40) ===
      "automatic_target"
        ? "automatic_target"
        : "manual",
    platformFoundationMonthlyAmountCents:
      source.platformFoundationMonthlyAmountCents === null
      || source.platformFoundationMonthlyAmountCents === undefined
      || source.platformFoundationMonthlyAmountCents === ""
        ? sanitizeString(source.platformFoundationPricingMode, 40) ===
            "automatic_target"
          ? null
          : 0
        : Number(source.platformFoundationMonthlyAmountCents),
    patientQuantity: Number(source.patientQuantity),
    expectedPatientQuantity12Months: Number(
      source.expectedPatientQuantity12Months,
    ),
    basePackageTierId: sanitizeString(source.basePackageTierId, 120),
    basePackageSelectionMode:
      basePackageSelectionMode === "manual" ? "manual" : "automatic",
    customBasePackageLimit:
      source.customBasePackageLimit === null
      || source.customBasePackageLimit === undefined
      || source.customBasePackageLimit === ""
        ? null
        : Number(source.customBasePackageLimit),
    customCapacityBlocks:
      source.customCapacityBlocks === null
      || source.customCapacityBlocks === undefined
      || source.customCapacityBlocks === ""
        ? null
        : Number(source.customCapacityBlocks),
    customCapacitySelectionMode:
      sanitizeString(source.customCapacitySelectionMode, 20) === "manual"
        ? "manual"
        : "automatic",
    lines,
    globalDiscountBasisPoints: Number(
      source.globalDiscountBasisPoints || 0,
    ),
    discountDurationMonths: Number(source.discountDurationMonths || 0),
    offerValidityDays: Number(source.offerValidityDays || 14),
    trialDays: [0, 7, 14, 30].includes(Number(source.trialDays || 0))
      ? Number(source.trialDays || 0) as 0 | 7 | 14 | 30
      : Number(source.trialDays || 0) as 0 | 7 | 14 | 30,
    onboardingInstallments: Number(source.onboardingInstallments || 1),
    usageProfile: "intensive" as SalesUsageProfile,
    driverOverrides: {},
    internalNotes: sanitizeString(source.internalNotes, 2000),
    publicNotes: sanitizeString(source.publicNotes, 1500),
    offerStartsAt: sanitizeString(source.offerStartsAt, 80),
    discountStackingJustification: sanitizeString(
      source.discountStackingJustification,
      1500,
    ),
  };
}

function salesModularResultMatches(
  stored: any,
  recalculated: ReturnType<typeof calculateSalesModularProposal>,
) {
  const nullableNumberMatches = (
    storedValue: unknown,
    recalculatedValue: number | null | undefined,
  ) => {
    if (recalculatedValue === null || recalculatedValue === undefined) {
      return storedValue === null || storedValue === undefined;
    }
    return Number.isFinite(Number(storedValue))
      && Number(storedValue) === recalculatedValue;
  };
  if (
    !stored
    || typeof stored !== "object"
    || sanitizeString(stored.modelVersion, 80) !== recalculated.modelVersion
    || sanitizeString(stored.catalogVersionId, 120)
      !== recalculated.catalogVersionId
    || Number(stored.promotionalRecurringRevenueCents)
      !== recalculated.promotionalRecurringRevenueCents
    || Number(stored.postPromotionRecurringRevenueCents)
      !== recalculated.postPromotionRecurringRevenueCents
    || Number(stored.oneTimeRevenueCents) !== recalculated.oneTimeRevenueCents
    || !nullableNumberMatches(
      stored.breakEvenRecurringRevenueCents,
      recalculated.breakEvenRecurringRevenueCents,
    )
    || !nullableNumberMatches(
      stored.targetRecurringRevenueCents,
      recalculated.targetRecurringRevenueCents,
    )
    || !nullableNumberMatches(
      stored.targetEbitdaMarginBasisPoints,
      recalculated.targetEbitdaMarginBasisPoints,
    )
    || !nullableNumberMatches(
      stored.targetGapCents,
      recalculated.targetGapCents,
    )
    || !nullableNumberMatches(
      stored.targetGapAnnualCents,
      recalculated.targetGapAnnualCents,
    )
    || !nullableNumberMatches(
      stored.markupOnEbitdaCostBasisPoints,
      recalculated.markupOnEbitdaCostBasisPoints,
    )
    || !nullableNumberMatches(
      stored.markupMultiplier,
      recalculated.markupMultiplier,
    )
    || sanitizeString(stored.rating, 40) !== recalculated.rating
    || Boolean(stored.requiresJustification)
      !== recalculated.requiresJustification
    || stored.basePackage?.limitQuantity
      !== recalculated.basePackage.limitQuantity
    || stored.basePackage?.includedStorageMb
      !== recalculated.basePackage.includedStorageMb
    || Number(stored.platformFoundation?.schemaVersion)
      !== recalculated.platformFoundation.schemaVersion
    || sanitizeString(stored.platformFoundation?.itemKey, 80)
      !== recalculated.platformFoundation.itemKey
    || sanitizeString(stored.platformFoundation?.publicName, 120)
      !== recalculated.platformFoundation.publicName
    || sanitizeString(stored.platformFoundation?.pricingMode, 40)
      !== recalculated.platformFoundation.pricingMode
    || Number(stored.platformFoundation?.recurringAmountCents)
      !== recalculated.platformFoundation.recurringAmountCents
    || !nullableNumberMatches(
      stored.platformFoundation?.recommendedRecurringAmountCents,
      recalculated.platformFoundation.recommendedRecurringAmountCents,
    )
    || !nullableNumberMatches(
      stored.platformFoundation?.targetTotalRecurringRevenueCents,
      recalculated.platformFoundation.targetTotalRecurringRevenueCents,
    )
    || !nullableNumberMatches(
      stored.platformFoundation?.moduleRecurringRevenueCents,
      recalculated.platformFoundation.moduleRecurringRevenueCents,
    )
    || !nullableNumberMatches(
      stored.platformFoundation?.sharedCostCents,
      recalculated.platformFoundation.sharedCostCents,
    )
    || !nullableNumberMatches(
      stored.platformFoundation?.fixedPaymentFeeCents,
      recalculated.platformFoundation.fixedPaymentFeeCents,
    )
    || Boolean(stored.platformFoundation?.automaticAmountAvailable)
      !== recalculated.platformFoundation.automaticAmountAvailable
    || (
      recalculated.commercialPricing.enabled
      && (
        stored.commercialPricing?.enabled !== true
        || Number(
          stored.commercialPricing?.contractedCapacityPatients,
        ) !== recalculated.commercialPricing.contractedCapacityPatients
        || Number(
          stored.commercialPricing?.totalProposedPricePerPatientCents,
        ) !== Number(
          recalculated.commercialPricing.totalProposedPricePerPatientCents,
        )
        || Number(stored.commercialPricing?.nextBlockPriceCents)
          !== Number(recalculated.commercialPricing.nextBlockPriceCents)
        || !salesCapacityBlockPhasesMatch(
          stored.commercialPricing?.capacityBlockPhases,
          recalculated.commercialPricing.capacityBlockPhases,
        )
      )
    )
    || Boolean(stored.economics) !== Boolean(recalculated.economics)
    || (
      recalculated.economics
      && (
        stored.economics?.canSend !== recalculated.economics.canSend
        || Number(stored.economics?.promotional?.marginBasisPoints)
          !== Number(recalculated.economics.promotional.marginBasisPoints)
        || Number(stored.economics?.postPromotion?.marginBasisPoints)
          !== Number(recalculated.economics.postPromotion.marginBasisPoints)
      )
    )
    || !Array.isArray(stored.lines)
    || stored.lines.length !== recalculated.lines.length
  ) {
    return false;
  }
  const storedByLine = new Map(
    stored.lines.map((line: any) => [
      `${sanitizeString(line.itemKey, 80)}:${sanitizeString(line.tierId, 120) || "item"}`,
      line,
    ]),
  );
  return recalculated.lines.every((line) => {
    const storedLine = storedByLine.get(
      `${line.itemKey}:${line.tierId || "item"}`,
    );
    return Boolean(
      storedLine
      && Number(storedLine.grossRecurringRevenueCents)
        === line.grossRecurringRevenueCents
      && Number(storedLine.promotionalRecurringRevenueCents)
        === line.promotionalRecurringRevenueCents
      && Number(storedLine.postPromotionRecurringRevenueCents)
        === line.postPromotionRecurringRevenueCents
      && Number(storedLine.oneTimeRevenueCents)
        === line.oneTimeRevenueCents
      && (
        !recalculated.commercialPricing.enabled
        || (
          Number(
            storedLine.commercialPricing?.proposedPricePerPatientCents,
          ) === Number(
            line.commercialPricing.proposedPricePerPatientCents,
          )
          && Number(
            storedLine.commercialPricing?.derivedMonthlyRevenueCents,
          ) === Number(
            line.commercialPricing.derivedMonthlyRevenueCents,
          )
        )
      )
      && Number(storedLine.promotional?.ebitdaCents)
        === Number(line.promotional.ebitdaCents)
      && Number(storedLine.promotional?.netIncomeCents)
        === Number(line.promotional.netIncomeCents),
    );
  });
}

function expectedSalesCommercialApprovalCodes(
  result: ReturnType<typeof calculateSalesModularProposal>,
  type: SalesCommercialExceptionType,
): string[] {
  const review = classifySalesProposalReview(result);
  return Array.from(new Set([
    ...review.commercialAlertCodes,
    ...(type === "strategic_showcase"
      ? ["STRATEGIC_SHOWCASE_CONDITION"]
      : []),
  ])).sort();
}

function salesCommercialApprovalPolicyHash(
  result: ReturnType<typeof calculateSalesModularProposal>,
): string {
  return stableHashPayload(result.economics?.policy ?? null);
}

function hashSalesCommercialApprovalResult(
  result: ReturnType<typeof calculateSalesModularProposal>,
  approvedCodes: string[],
  includePolicyHash = true,
): string {
  const approvalResult = buildSalesCommercialApprovalResult(
    result,
    approvedCodes,
  );
  return includePolicyHash
    ? stableHashPayload(
        buildSalesCommercialApprovalHashInput(result, approvedCodes),
      )
    : stableHashPayload(approvalResult);
}

function buildSalesCommercialExceptionApproval(input: {
  result: ReturnType<typeof calculateSalesModularProposal>;
  actorUserId: string;
  actorRole: unknown;
  mfaVerified: boolean;
  explicitConfirmation: boolean;
  justification: string;
  type: unknown;
  approvedAt: string;
}): {
  approval: SalesCommercialExceptionApprovalSnapshot | null;
  error: string | null;
} {
  const validationError = validateSalesCommercialExceptionActor({
    role: input.actorRole,
    mfaVerified: input.mfaVerified,
    explicitConfirmation: input.explicitConfirmation,
    justification: input.justification,
    type: input.type,
  });
  if (validationError) return { approval: null, error: validationError };
  const type = input.type as SalesCommercialExceptionType;
  const review = classifySalesProposalReview(input.result);
  const technicalBlockingCodes = filterSalesCurrentOperatingTechnicalBlockers(
    review.technicalBlockingCodes,
  );
  if (technicalBlockingCodes.length > 0) {
    return { approval: null, error: "PROPOSAL_TECHNICAL_BLOCKED" };
  }
  if (!review.requiresCommercialApproval && type !== "strategic_showcase") {
    return { approval: null, error: "COMMERCIAL_EXCEPTION_NOT_REQUIRED" };
  }
  const approvedCodes = expectedSalesCommercialApprovalCodes(
    input.result,
    type,
  );
  const approvedResult = buildSalesCommercialApprovalResult(
    input.result,
    approvedCodes,
  );
  return {
    approval: {
      schemaVersion: 1,
      status: "approved",
      type,
      explicitConfirmation: true,
      approvedCodes,
      promotionalMarginBasisPoints:
        approvedResult.promotionalMarginBasisPoints,
      postPromotionMarginBasisPoints:
        approvedResult.postPromotionMarginBasisPoints,
      moduleMargins: approvedResult.moduleMargins,
      capacityMarginBasisPoints: approvedResult.capacityMarginBasisPoints,
      monthlyPriceCents: approvedResult.monthlyPriceCents,
      pricePerPatientCents: approvedResult.pricePerPatientCents,
      contractedCapacityPatients:
        approvedResult.contractedCapacityPatients,
      approvedBy: input.actorUserId,
      approvedAt: input.approvedAt,
      policyVersion: {
        catalogVersion: approvedResult.catalogVersion,
        schemaVersion: approvedResult.policySchemaVersion,
      },
      policyHash: salesCommercialApprovalPolicyHash(input.result),
      justification: input.justification.trim(),
      resultHash: hashSalesCommercialApprovalResult(
        input.result,
        approvedCodes,
      ),
    },
    error: null,
  };
}

function salesCommercialExceptionApprovalMatches(
  result: ReturnType<typeof calculateSalesModularProposal>,
  rawApproval: any,
): boolean {
  if (
    !rawApproval
    || rawApproval.schemaVersion !== 1
    || rawApproval.status !== "approved"
    || rawApproval.explicitConfirmation !== true
    || !SALES_COMMERCIAL_EXCEPTION_TYPES.includes(rawApproval.type)
    || !isUuid(sanitizeString(rawApproval.approvedBy, 120))
    || sanitizeString(rawApproval.justification, 1500).trim().length < 20
    || !Number.isFinite(Date.parse(sanitizeString(rawApproval.approvedAt, 80)))
    || !Array.isArray(rawApproval.approvedCodes)
    || !/^[a-f0-9]{64}$/.test(String(rawApproval.resultHash || ""))
    || (
      rawApproval.policyHash !== undefined
      && !/^[a-f0-9]{64}$/.test(String(rawApproval.policyHash || ""))
    )
  ) {
    return false;
  }
  const expectedCodes = expectedSalesCommercialApprovalCodes(
    result,
    rawApproval.type,
  );
  const storedCodes = Array.from(
    new Set(
      rawApproval.approvedCodes
        .map((code: unknown) => sanitizeString(code, 160))
        .filter(Boolean),
    ),
  ).sort();
  if (
    expectedCodes.length !== storedCodes.length
    || expectedCodes.some((code, index) => code !== storedCodes[index])
  ) {
    return false;
  }
  const approvedResult = buildSalesCommercialApprovalResult(
    result,
    expectedCodes,
  );
  const storedFinancialApproval = {
    promotionalMarginBasisPoints:
      rawApproval.promotionalMarginBasisPoints ?? null,
    postPromotionMarginBasisPoints:
      rawApproval.postPromotionMarginBasisPoints ?? null,
    moduleMargins: Array.isArray(rawApproval.moduleMargins)
      ? rawApproval.moduleMargins
      : [],
    capacityMarginBasisPoints:
      rawApproval.capacityMarginBasisPoints ?? null,
    monthlyPriceCents: Number(rawApproval.monthlyPriceCents),
    pricePerPatientCents: rawApproval.pricePerPatientCents ?? null,
    contractedCapacityPatients:
      rawApproval.contractedCapacityPatients ?? null,
  };
  const expectedFinancialApproval = {
    promotionalMarginBasisPoints:
      approvedResult.promotionalMarginBasisPoints,
    postPromotionMarginBasisPoints:
      approvedResult.postPromotionMarginBasisPoints,
    moduleMargins: approvedResult.moduleMargins,
    capacityMarginBasisPoints:
      approvedResult.capacityMarginBasisPoints,
    monthlyPriceCents: approvedResult.monthlyPriceCents,
    pricePerPatientCents: approvedResult.pricePerPatientCents,
    contractedCapacityPatients:
      approvedResult.contractedCapacityPatients,
  };
  const hasPolicyHash = typeof rawApproval.policyHash === "string";
  if (
    hasPolicyHash
    && sanitizeString(rawApproval.policyHash, 64) !==
      salesCommercialApprovalPolicyHash(result)
  ) {
    return false;
  }
  return (
    rawApproval.policyVersion?.catalogVersion ===
      approvedResult.catalogVersion
    && rawApproval.policyVersion?.schemaVersion ===
      approvedResult.policySchemaVersion
    && stableHashPayload(storedFinancialApproval) ===
      stableHashPayload(expectedFinancialApproval)
    && sanitizeString(rawApproval.resultHash, 64) ===
      hashSalesCommercialApprovalResult(
        result,
        expectedCodes,
        hasPolicyHash,
      )
  );
}

function isCustomCouponDurationMonths(value: unknown): value is number {
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed >= 1 && parsed <= 36;
}

function isSalesOfferStripeReady(offer: any, stripeConfig: ReturnType<
  typeof resolveSalesStripeConfiguration
>): boolean {
  if (!stripeConfig.enabled || !stripeConfig.basePriceId) return false;
  const discountType = sanitizeString(offer?.discount_type, 20);
  if (discountType !== "coupon") return true;
  if (sanitizeString(offer?.stripe_coupon_id, 240)) return true;
  const duration = Number(offer?.discount_duration_months || 0) || null;
  return stripeConfig.readyForDuration(duration);
}

function buildSalesOfferPublicUrl(req: any, token: string): string {
  const configuredBase = sanitizeString(
    process.env.VERTO_APP_BASE_URL,
    500,
  ).replace(/\/+$/, "");
  const origin = configuredBase || `${req.protocol}://${req.get("host")}`;
  return `${origin}/oferta/${encodeURIComponent(token)}`;
}

function salesOfferPublicStatusAllowed(status: unknown): boolean {
  return [
    "ready",
    "sent",
    "opened",
    "checkout_created",
    "payment_pending",
  ].includes(sanitizeString(status, 40).toLowerCase());
}

async function readOptionalScalarColumn(params: {
  table: 'users' | 'clinics';
  match: { column: string; value: string };
  column: string;
}): Promise<string | null> {
  try {
    const { data, error } = await supabase
      .from(params.table)
      .select(`${params.column}`)
      .eq(params.match.column, params.match.value)
      .maybeSingle();
    if (error) return null;
    const value = sanitizeString((data as any)?.[params.column], 200);
    return value || null;
  } catch {
    return null;
  }
}

async function patchTableSafely(
  table: 'users' | 'clinics' | 'patients',
  matcher: { column: string; value: string },
  patch: Record<string, any>
): Promise<void> {
  let safePatch: Record<string, any> = cleanObject(patch);
  while (Object.keys(safePatch).length > 0) {
    const { error } = await supabase
      .from(table)
      .update(safePatch)
      .eq(matcher.column, matcher.value);
    if (!error) return;
    const missingColumn = extractMissingColumnName(error);
    if (!missingColumn || !(missingColumn in safePatch)) return;
    delete safePatch[missingColumn];
  }
}

async function persistStripeCustomerReference(params: {
  customerId: string;
  email?: string | null;
  userId?: string | null;
  clinicId?: string | null;
}) {
  const customerId = sanitizeString(params.customerId, 200);
  if (!customerId) return;
  const userId = sanitizeString(params.userId, 120);
  const clinicId = sanitizeString(params.clinicId, 120);
  const safeEmail = sanitizeEmail(params.email);

  if (userId) {
    await patchTableSafely('users', { column: 'id', value: userId }, {
      stripe_customer_id: customerId,
      stripe_customer_email: safeEmail || undefined,
      updated_at: new Date().toISOString()
    });
  }
  if (safeEmail) {
    await patchTableSafely('users', { column: 'email', value: safeEmail }, {
      stripe_customer_id: customerId,
      stripe_customer_email: safeEmail,
      updated_at: new Date().toISOString()
    });
  }
  if (clinicId) {
    await patchTableSafely('clinics', { column: 'id', value: clinicId }, {
      stripe_customer_id: customerId,
      stripe_customer_email: safeEmail || undefined,
      updated_at: new Date().toISOString()
    });
  }
}

async function persistStripeSubscriptionReference(params: {
  subscriptionId?: string | null;
  subscriptionItemId?: string | null;
  customerId?: string | null;
  priceId?: string | null;
  activePatientCount?: number | null;
  activePatientLimit?: number | null;
  billingSyncStatus?: string | null;
  billingSyncError?: string | null;
  email?: string | null;
  userId?: string | null;
  clinicId?: string | null;
  status?: string | null;
}) {
  const subscriptionId = sanitizeString(params.subscriptionId, 200);
  const subscriptionItemId = sanitizeString(params.subscriptionItemId, 200);
  const customerId = sanitizeString(params.customerId, 200);
  const priceId = sanitizeString(params.priceId, 200);
  const userId = sanitizeString(params.userId, 120);
  const clinicId = sanitizeString(params.clinicId, 120);
  const safeEmail = sanitizeEmail(params.email);
  const status = normalizeSubscriptionStatusFromStripe(sanitizeString(params.status, 80));
  const activePatientLimit = normalizeActivePatientQuantity(params.activePatientLimit);
  const activePatientCount = typeof params.activePatientCount === 'number'
    ? Math.max(0, Math.floor(params.activePatientCount))
    : undefined;
  const patch = cleanObject({
    stripe_subscription_id: subscriptionId || undefined,
    stripe_subscription_item_id: subscriptionItemId || undefined,
    stripe_customer_id: customerId || undefined,
    stripe_customer_email: safeEmail || undefined,
    stripe_price_id: priceId || undefined,
    subscription_status: status,
    billing_model: ACTIVE_PATIENT_BILLING_MODEL,
    active_patient_count: activePatientCount,
    current_active_patient_count: activePatientCount,
    current_active_patient_limit: activePatientLimit || undefined,
    billing_sync_status: sanitizeString(params.billingSyncStatus, 80) || undefined,
    billing_sync_error: sanitizeString(params.billingSyncError, 500) || undefined,
    last_billing_sync_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  });

  if (clinicId) {
    await patchTableSafely('clinics', { column: 'id', value: clinicId }, patch);
  }
  if (userId) {
    await patchTableSafely('users', { column: 'id', value: userId }, patch);
  } else if (safeEmail) {
    await patchTableSafely('users', { column: 'email', value: safeEmail }, patch);
  }
}

async function reserveStripeWebhookEvent(event: Stripe.Event): Promise<boolean> {
  const eventId = sanitizeString(event?.id, 200);
  const eventType = sanitizeString(event?.type, 120);
  if (!eventId || !eventType) {
    throw new Error('STRIPE_WEBHOOK_EVENT_ID_INVALID');
  }

  const now = new Date().toISOString();
  const { error } = await supabase
    .from('stripe_webhook_events')
    .insert([{
      id: eventId,
      event_type: eventType,
      status: 'processing',
      metadata: {},
      processed_at: now,
      updated_at: now,
      attempt_count: 1
    }]);
  if (!error) return true;

  const code = sanitizeString((error as any)?.code, 20);
  const message = sanitizeString((error as any)?.message || '', 300).toLowerCase();
  if (code !== '23505' && !message.includes('duplicate')) {
    throw error;
  }

  const { data: existing, error: existingError } = await supabase
    .from('stripe_webhook_events')
    .select('id,status,processed_at,attempt_count')
    .eq('id', eventId)
    .maybeSingle();
  if (existingError || !existing) {
    throw existingError || new Error('STRIPE_WEBHOOK_RESERVATION_NOT_FOUND');
  }
  if (sanitizeString(existing.status, 40) === 'processed') return false;

  const staleBefore = new Date(Date.now() - 5 * 60 * 1000).toISOString();
  const canRetry =
    sanitizeString(existing.status, 40) === 'failed' ||
    (sanitizeString(existing.status, 40) === 'processing' &&
      sanitizeString(existing.processed_at, 80) < staleBefore);
  if (!canRetry) return false;

  let retryQuery = supabase
    .from('stripe_webhook_events')
    .update({
      status: 'processing',
      processed_at: now,
      updated_at: now,
      last_error_code: null,
      attempt_count: Math.max(1, Number(existing.attempt_count || 1)) + 1
    })
    .eq('id', eventId)
    .eq('status', sanitizeString(existing.status, 40));
  if (sanitizeString(existing.status, 40) === 'processing') {
    retryQuery = retryQuery.lt('processed_at', staleBefore);
  }
  const { data: retried, error: retryError } = await retryQuery.select('id');
  if (retryError) throw retryError;
  return Array.isArray(retried) && retried.length === 1;
}

async function markStripeWebhookEventStatus(
  event: Stripe.Event,
  status: 'processed' | 'failed',
  errorCode?: string | null
): Promise<void> {
  const eventId = sanitizeString(event?.id, 200);
  if (!eventId) return;
  try {
    const now = new Date().toISOString();
    const { error } = await supabase
      .from('stripe_webhook_events')
      .update({
        status,
        processed_at: now,
        updated_at: now,
        last_error_code: status === 'failed' ? sanitizeString(errorCode, 120) || 'PROCESSING_FAILED' : null
      })
      .eq('id', eventId);
    if (error) throw error;
  } catch (statusError: any) {
    console.error('[Stripe Webhook] Falha ao persistir status do evento.', {
      eventType: sanitizeString(event?.type, 120),
      message: sanitizeString(statusError?.message || String(statusError), 200)
    });
  }
}

async function markClinicPaymentFailed(params: {
  clinicId?: string | null;
  userId?: string | null;
  email?: string | null;
  invoiceId?: string | null;
}) {
  const clinicId = sanitizeString(params.clinicId, 120);
  const userId = sanitizeString(params.userId, 120);
  const email = sanitizeEmail(params.email);
  const failedAt = new Date().toISOString();
  const result = await supabase.rpc('apply_billing_payment_failure_v1', {
    p_clinic_id: isUuid(clinicId) ? clinicId : null,
    p_user_id: isUuid(userId) ? userId : null,
    p_email: email || null,
    p_invoice_id: sanitizeString(params.invoiceId, 200) || null,
    p_failed_at: failedAt,
  });
  if (result.error) {
    const message = String(result.error?.message || result.error?.details || '');
    if (/apply_billing_payment_failure_v1|42883|function .* does not exist|schema cache/i.test(message)) {
      throw new Error('BILLING_GRACE_MIGRATION_REQUIRED');
    }
    throw result.error;
  }
  return result.data || null;
}

async function clearClinicPaymentFailure(params: {
  clinicId?: string | null;
  userId?: string | null;
  email?: string | null;
}) {
  const payload = {
    subscription_status: 'active',
    stripe_payment_failed_at: null,
    stripe_access_block_at: null,
    stripe_last_failed_invoice_id: null,
    updated_at: new Date().toISOString()
  };
  const clinicId = sanitizeString(params.clinicId, 120);
  const userId = sanitizeString(params.userId, 120);
  const email = sanitizeEmail(params.email);

  if (clinicId) await patchTableSafely('clinics', { column: 'id', value: clinicId }, payload);
  if (userId) await patchTableSafely('users', { column: 'id', value: userId }, payload);
  if (!userId && email) await patchTableSafely('users', { column: 'email', value: email }, payload);
}

async function resolvePersistedStripeCustomerId(params: {
  userId?: string | null;
  clinicId?: string | null;
  email?: string | null;
}): Promise<string | null> {
  const userId = sanitizeString(params.userId, 120);
  const clinicId = sanitizeString(params.clinicId, 120);
  const email = sanitizeEmail(params.email);

  if (userId) {
    const byUserId = await readOptionalScalarColumn({
      table: 'users',
      match: { column: 'id', value: userId },
      column: 'stripe_customer_id'
    });
    if (byUserId) return byUserId;
  }
  if (clinicId) {
    const byClinicId = await readOptionalScalarColumn({
      table: 'clinics',
      match: { column: 'id', value: clinicId },
      column: 'stripe_customer_id'
    });
    if (byClinicId) return byClinicId;
  }
  if (email) {
    const byEmail = await readOptionalScalarColumn({
      table: 'users',
      match: { column: 'email', value: email },
      column: 'stripe_customer_id'
    });
    if (byEmail) return byEmail;
  }
  return null;
}

function normalizeProtocolKey(input?: string | null): string {
  return sanitizeString(input || '', 180)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function identifyVertoProtocolCandidate(input?: string | null): { canonicalKey: string; canonicalName: string; confidence: number } {
  const key = normalizeProtocolKey(input);
  if (/\bafls\b|assessment functional living skills|functional living skills/.test(key)) {
    return { canonicalKey: 'afls-social-participation-adult', canonicalName: 'AFLS - Habilidades de Participação Social', confidence: 0.94 };
  }
  if (/\bvb\s*mapp\s*2\b|\bvbmapp\s*2\b|\bvb\s*mapp\s*nivel\s*2\b|\bvb\s*mapp\s*level\s*2\b|\b18\s*a\s*30\b|\b18\s*30\b/.test(key)) {
    return { canonicalKey: 'vb-mapp-level-2', canonicalName: 'VB-MAPP - Nivel 2', confidence: 0.92 };
  }
  if (/\bvb\s*mapp\s*3\b|\bvbmapp\s*3\b|\bvb\s*mapp\s*nivel\s*3\b|\bvb\s*mapp\s*level\s*3\b|\b30\s*a\s*48\b|\b30\s*48\b/.test(key)) {
    return { canonicalKey: 'vb-mapp-level-3', canonicalName: 'VB-MAPP - Nivel 3', confidence: 0.92 };
  }
  if (/\bvb\s*mapp\b|\bvbmapp\b|verbal behavior milestones/.test(key)) {
    return { canonicalKey: 'vb-mapp-level-1', canonicalName: 'VB-MAPP - Nivel 1', confidence: 0.9 };
  }
  if (/\bablls\b|\bablls r\b|basic language learning skills/.test(key)) {
    return { canonicalKey: 'ablls-r', canonicalName: 'ABLLS-R', confidence: 0.86 };
  }
  if (/\bvineland\b/.test(key)) {
    return { canonicalKey: 'vineland', canonicalName: 'Vineland', confidence: 0.82 };
  }
  return { canonicalKey: 'manual-review', canonicalName: 'Analise manual necessaria', confidence: 0.35 };
}

function normalizeApprovedProtocolKey(input?: string | null): string {
  const rawKey = sanitizeString(input, 180);
  const key = normalizeProtocolKey(rawKey);
  if (!key) return '';
  if (
    key === 'afls' ||
    key === 'afls social participation' ||
    key === 'afls social participation adult' ||
    key === 'afls community' ||
    key.includes('habilidades de participacao social') ||
    key.includes('functional living skills')
  ) {
    return 'afls-social-participation-adult';
  }
  const looksLikeVbMapp = /\bvb\s*mapp\b|\bvbmapp/.test(key);
  if (looksLikeVbMapp) {
    if (/\b(level|nivel)\s*3\b|\bvbmapp\s*3\b|\b30\s*a\s*48\b|\b30\s*48\b|\b3\b/.test(key)) {
      return 'vb-mapp-level-3';
    }
    if (/\b(level|nivel)\s*2\b|\bvbmapp\s*2\b|\b18\s*a\s*30\b|\b18\s*30\b|\b2\b/.test(key)) {
      return 'vb-mapp-level-2';
    }
    return 'vb-mapp-level-1';
  }
  return rawKey;
}

