function sanitizeTextField(value: unknown, maxLength = 5000): string {
  return escapeHtml(sanitizeString(value, maxLength));
}

function approximateBodySizeBytes(body: any): number {
  try {
    return Buffer.byteLength(JSON.stringify(body || {}), 'utf8');
  } catch {
    return 0;
  }
}

function enforcePayloadLimit(req: any, res: any, maxBytes: number, label: string): boolean {
  const contentLength = Number(req.headers?.['content-length'] || 0);
  if (Number.isFinite(contentLength) && contentLength > maxBytes) {
    res.status(413).json({ error: `${label} excede o limite permitido.` });
    return false;
  }

  const actualBytes = approximateBodySizeBytes(req.body);
  if (actualBytes > maxBytes) {
    res.status(413).json({ error: `${label} excede o limite permitido.` });
    return false;
  }
  return true;
}

const DANGEROUS_OBJECT_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function parseStoredJsonObject(input: any): Record<string, any> {
  if (!input) return {};
  if (typeof input === 'object' && !Array.isArray(input)) return input;
  if (typeof input !== 'string') return {};

  try {
    const parsed = JSON.parse(input);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function readPatientAuthorizationTissGuide(row: any) {
  const syncMetadata = parseStoredJsonObject(row?.sync_metadata || row?.syncMetadata);
  const guide = parseStoredJsonObject(syncMetadata.tissGuide || syncMetadata.tiss_guide);
  const requester = parseStoredJsonObject(guide.requester);
  const operatorGuideNumber = sanitizeString(
    guide.operatorGuideNumber || guide.operator_guide_number || row?.guide_number || row?.guideNumber,
    120
  ) || null;

  return {
    schemaVersion: Number(guide.schemaVersion || guide.schema_version) === 1 ? 1 : null,
    providerGuideNumber: sanitizeString(guide.providerGuideNumber || guide.provider_guide_number, 120) || null,
    operatorGuideNumber,
    requestDate: sanitizeIsoDateOnly(guide.requestDate || guide.request_date),
    consultationType: sanitizeString(guide.consultationType || guide.consultation_type, 4) || null,
    executantParticipationDegree: sanitizeString(
      guide.executantParticipationDegree || guide.executant_participation_degree,
      4
    ) || null,
    requester: {
      name: sanitizeString(requester.name, 180) || null,
      councilType: sanitizeString(requester.councilType || requester.council_type, 40) || null,
      councilNumber: sanitizeString(requester.councilNumber || requester.council_number, 80) || null,
      councilState: sanitizeString(requester.councilState || requester.council_state, 8) || null,
      cboCode: sanitizeString(requester.cboCode || requester.cbo_code, 40) || null,
      source: sanitizeString(requester.source, 40) || null
    }
  };
}

function sanitizeClinicalPayload(input: any, depth = 0): any {
  if (depth > 8) return null;
  if (input === null || input === undefined) return null;

  if (typeof input === 'string') {
    return sanitizeTextField(input, 4000);
  }
  if (typeof input === 'number' || typeof input === 'boolean') {
    return input;
  }
  if (Array.isArray(input)) {
    return input.slice(0, 200).map((item) => sanitizeClinicalPayload(item, depth + 1));
  }
  if (typeof input !== 'object') return null;

  const safe: Record<string, any> = {};
  const entries = Object.entries(input).slice(0, 300);
  for (const [rawKey, value] of entries) {
    const key = sanitizeString(rawKey, 120);
    if (!key || DANGEROUS_OBJECT_KEYS.has(key)) continue;
    if (
      (key === 'content' || key === 'dataUrl') &&
      typeof value === 'string' &&
      /^data:(application\/pdf|application\/vnd\.openxmlformats-officedocument\.spreadsheetml\.sheet|application\/vnd\.ms-excel);base64,[a-z0-9+/=\s]+$/i.test(value) &&
      value.length <= 14_000_000
    ) {
      safe[key] = sanitizeString(value, 14_000_000);
      continue;
    }
    if (
      key === 'dataUrl' &&
      typeof value === 'string' &&
      /^data:image\/(png|jpeg|jpg|webp);base64,[a-z0-9+/=\s]+$/i.test(value) &&
      value.length <= 8_000_000
    ) {
      safe[key] = sanitizeString(value, 8_000_000);
      continue;
    }
    safe[key] = sanitizeClinicalPayload(value, depth + 1);
  }
  return safe;
}

const PATIENT_FINANCIAL_PAYLOAD_KEYS = new Set([
  'financialPlans',
  'monthlyTreatmentValue',
  'monthlyFee',
  'billingDueDay',
  'billingMethod',
  'paymentMethod',
  'payerType',
  'billingMode',
  'payerId',
  'payerNameSnapshot',
  'insurancePlanName',
  'authorizationCode',
  'authorizationValidUntil',
  'sessionsQuantity',
  'quantityPeriod',
  'amountCents',
  'copaymentAmount',
  'copaymentAmountCents',
  'packageValidUntil',
  'baseAmount',
  'additionalAmount',
  'specialtyAmount',
  'specialtyValues',
  'dreMetrics'
]);

const PATIENT_GENERIC_PAYER_PAYLOAD_KEYS = new Set([
  'insurancePayerId','insurance_payer_id','convenioPayerId','convenio_payer_id',
  'insuranceType','insurance_type','convenioTipo','insuranceName','insurance_name','convenioNome',
]);

const PATIENT_INSURANCE_PAYLOAD_KEYS = new Set([
  'insuranceCardNumber','insurance_card_number','cardNumber','convenioCarteirinha',
  'insuranceCardValidUntil','insurance_card_valid_until','convenioCarteirinhaValidade',
  'insurancePlanCategory','insurance_plan_category','convenioPlanoCategoria',
  'insuranceHolderName','insurance_holder_name','convenioTitularNome',
  'insuranceHolderCpf','insurance_holder_cpf','convenioTitularCpf',
  'insuranceHolderRelationship','insurance_holder_relationship','convenioTitularRelacao',
  'insuranceEligibilityNotes','eligibilityNotes','eligibility_notes','convenioElegibilidadeObs',
]);

function redactPatientPayloadKeys(input: any, keys: ReadonlySet<string>): any {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return input;
  const redacted: Record<string, any> = { ...input };
  for (const key of keys) delete redacted[key];
  for (const nestedKey of ['anamnese', 'anamnesisData']) {
    const nested = redacted[nestedKey];
    if (!nested || typeof nested !== 'object' || Array.isArray(nested)) continue;
    const safeNested = { ...nested };
    for (const key of keys) delete safeNested[key];
    redacted[nestedKey] = safeNested;
  }
  return redacted;
}

function redactPatientFinancialPlanTissOperationalFields(input: any): any {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return input;
  const redactPlans = (value: any) => {
    if (!Array.isArray(value)) return value;
    return value.map((rawPlan: any) => {
      if (!rawPlan || typeof rawPlan !== 'object' || Array.isArray(rawPlan)) return rawPlan;
      const plan = { ...rawPlan };
      for (const key of [
        'insurancePlanName','insurance_plan_name',
        'authorizationCode','authorization_code',
        'authorizationValidUntil','authorization_valid_until',
        'insuranceCardNumber','insurance_card_number',
        'insuranceCardHolder','insurance_card_holder',
        'insuranceCardValidUntil','insurance_card_valid_until',
      ]) {
        delete plan[key];
      }
      return plan;
    });
  };
  const redacted: Record<string, any> = { ...input };
  if (Object.prototype.hasOwnProperty.call(redacted, 'financialPlans')) {
    redacted.financialPlans = redactPlans(redacted.financialPlans);
  }
  if (Object.prototype.hasOwnProperty.call(redacted, 'financial_plans')) {
    redacted.financial_plans = redactPlans(redacted.financial_plans);
  }
  return redacted;
}

function redactPatientFinancialPayload(input: any, user: any): any {
  if (canAccessClinicFinance(user)) return input;
  return redactPatientPayloadKeys(input, PATIENT_FINANCIAL_PAYLOAD_KEYS);
}

function redactPatientRecordPayloadForCapabilities(
  input: any,
  user: any,
  capabilities?: ReadonlySet<CapabilityKey> | null,
): any {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return input;
  // Portal do próprio paciente mantém o comportamento histórico. Atores da clínica
  // são filtrados pela membership efetiva, inclusive overrides ALLOW/DENY.
  if (!capabilities) return redactPatientFinancialPayload(input, user);

  let redacted = input;
  const canViewPatientFinancialPlan = capabilities.has('patient.demographics.edit');
  const canViewFinance = capabilities.has('finance.payments.view');
  const canViewTissInsurance = capabilities.has('patient.insurance.view');
  if (!canViewPatientFinancialPlan) {
    redacted = redactPatientPayloadKeys(redacted, PATIENT_FINANCIAL_PAYLOAD_KEYS);
  }
  if (!canViewFinance && !canViewTissInsurance) {
    redacted = redactPatientPayloadKeys(redacted, PATIENT_GENERIC_PAYER_PAYLOAD_KEYS);
  }
  if (!canViewTissInsurance) {
    redacted = redactPatientPayloadKeys(redacted, PATIENT_INSURANCE_PAYLOAD_KEYS);
    redacted = redactPatientFinancialPlanTissOperationalFields(redacted);
  }
  return redacted;
}

function isAllowedScreenshotDataUrl(value: unknown): value is string {
  return typeof value === 'string'
    && /^data:image\/(png|jpeg|jpg|webp);base64,[a-z0-9+/=\s]+$/i.test(value)
    && value.length <= 8_000_000;
}

function buildScreenshotEvidenceSummary(params: {
  totalPages?: number | null;
  coverageMaxPage?: number | null;
  applicableAgeGroup?: string | null;
  ageMin?: number | null;
  ageMax?: number | null;
  screenshots: Array<{ pageNumber: number; prompt?: string | null }>;
}): string {
  const pages = params.screenshots.map((shot) => shot.pageNumber).filter((page) => Number.isFinite(page));
  const hasAgeRange = Number.isFinite(Number(params.ageMin));
  const ageLabel = hasAgeRange
    ? `${Number(params.ageMin)} ate ${Number.isFinite(Number(params.ageMax)) ? Number(params.ageMax) : '+'} anos`
    : params.applicableAgeGroup === 'child'
    ? 'Criancas'
    : params.applicableAgeGroup === 'teen'
      ? 'Adolescentes'
      : params.applicableAgeGroup === 'adult'
        ? 'Adultos'
        : 'Todas as idades';
  return [
    `Modo de validacao: screenshots enviados pelo cliente`,
    `Faixa etaria declarada: ${ageLabel}`,
    params.totalPages ? `Paginas totais declaradas: ${params.totalPages}` : null,
    params.coverageMaxPage ? `Janela de amostragem: 1 ate ${params.coverageMaxPage}` : null,
    `Capturas recebidas: ${pages.length}`,
    pages.length ? `Paginas conferidas: ${pages.join(', ')}` : 'Paginas conferidas: nenhuma',
    'Arquivo bruto nao foi aberto. A revisao deve ocorrer pelas miniaturas e pela correspondencia com o protocolo canonico.'
  ].filter(Boolean).join('\n');
}

function getTrustedMediaHosts(): Set<string> {
  const hosts = new Set<string>();
  const envHosts = sanitizeString(process.env.TRUSTED_MEDIA_HOSTS || '', 2000)
    .split(',')
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean);

  for (const host of envHosts) hosts.add(host);

  try {
    if (process.env.SUPABASE_URL) {
      hosts.add(new URL(process.env.SUPABASE_URL).hostname.toLowerCase());
    }
  } catch {
    // no-op
  }

  hosts.add('localhost');
  hosts.add('127.0.0.1');
  return hosts;
}

const trustedMediaHosts = getTrustedMediaHosts();
const SAFE_IMAGE_DATA_URL_PATTERN = /^data:image\/(png|jpeg|jpg|webp);base64,[a-z0-9+/=\s]+$/i;
const SAFE_PDF_DATA_URL_PATTERN = /^data:application\/pdf;base64,[a-z0-9+/=\s]+$/i;

function isTrustedRemoteMediaUrl(rawUrl: string): boolean {
  try {
    const parsed = new URL(rawUrl);
    const protocol = parsed.protocol.toLowerCase();
    if (protocol !== 'https:' && protocol !== 'http:') return false;
    if (protocol === 'http:' && parsed.hostname !== 'localhost' && parsed.hostname !== '127.0.0.1') {
      return false;
    }

    const host = parsed.hostname.toLowerCase();
    if (trustedMediaHosts.has(host)) return true;
    if (host.endsWith('.supabase.co')) return true;
    return false;
  } catch {
    return false;
  }
}

function sanitizeUrl(value: unknown): string | null {
  const url = typeof value === 'string' ? value.trim() : '';
  if (!url) return null;
  if (url.startsWith('http://') || url.startsWith('https://')) {
    const safe = sanitizeString(url, 4000);
    return isTrustedRemoteMediaUrl(safe) ? safe : null;
  }
  if (url.startsWith('data:image/')) {
    // Data URLs (logo/assinatura/foto) podem passar de 2k caracteres.
    // Mantemos limite de 1MB para evitar payloads abusivos.
    if (url.length > 1_000_000) return null;
    return SAFE_IMAGE_DATA_URL_PATTERN.test(url) ? url : null;
  }
  return null;
}

function sanitizeReceiptUrl(value: unknown): string | null {
  const url = (typeof value === 'string' ? value.trim() : '')
    .replace(/^data:application\/pdf;filename=[^;,]{1,180};base64,/i, 'data:application/pdf;base64,');
  if (!url) return null;
  if (url.startsWith('data:image/')) {
    if (url.length > 2_000_000) return null;
    return SAFE_IMAGE_DATA_URL_PATTERN.test(url) ? url : null;
  }
  if (url.startsWith('data:application/pdf')) {
    if (url.length > 2_000_000) return null;
    return SAFE_PDF_DATA_URL_PATTERN.test(url) ? url : null;
  }
  return sanitizeUrl(url);
}

function sanitizeSessionUrl(value: unknown): string | null {
  const raw = sanitizeString(value, 1500);
  if (!raw) return null;

  // Internal patient-photo proxy URLs are authenticated, stable view URLs.
  // Preserve them in the session instead of dropping them simply because they
  // are same-origin relative paths. Rebuild from the canonical storage path to
  // prevent arbitrary relative URLs from entering the session payload.
  if (
    raw.startsWith('/api/storage/patient-photos/view?') ||
    raw.startsWith('patient-photos/') ||
    raw.startsWith('onboarding/') ||
    raw.startsWith('patients/') ||
    raw.includes('/storage/v1/object/sign/patient-photos/')
  ) {
    const storagePath = extractPatientPhotosStoragePath(raw);
    if (storagePath) return buildPatientPhotoViewUrl(storagePath);
  }

  const url = sanitizeUrl(raw);
  if (!url) return null;
  // Never keep large data URLs inside session payload.
  if (url.startsWith('data:image/')) return null;
  return sanitizeString(url, 1500);
}

function sanitizeClinicBrandImageUrl(value: unknown): string | null {
  const storagePath = extractPatientPhotosStoragePath(value);
  if (storagePath) return buildPatientPhotoViewUrl(storagePath);
  const raw = sanitizeString(value, 4_000);
  if (isVertoInstitutionalAsset(raw)) return null;
  if (raw && raw.startsWith('/') && !raw.startsWith('//')) {
    return sanitizeString(raw, 1_500);
  }
  const url = sanitizeUrl(value);
  if (!url) return null;
  return url.startsWith('data:image/') ? url : sanitizeString(url, 1_500);
}

function extractPatientPhotosStoragePath(raw: unknown): string | null {
  const value = sanitizeString(raw, 1500);
  if (!value) return null;
  if (value.startsWith('patient-photos/')) {
    const pathPart = value.slice('patient-photos/'.length);
    return pathPart ? pathPart : null;
  }
  if (value.startsWith('/api/storage/patient-photos/view?')) {
    try {
      const params = new URLSearchParams(value.slice(value.indexOf('?') + 1));
      const proxyPath = params.get('path') || '';
      return proxyPath ? proxyPath : null;
    } catch {
      return null;
    }
  }
  if (value.startsWith('onboarding/')) return value;
  if (value.startsWith('patients/')) return value;
  if (!value.includes('://') && value.includes('/') && !value.startsWith('data:')) return value;
  const marker = '/storage/v1/object/sign/patient-photos/';
  if (value.includes(marker)) {
    const encodedPath = value.split(marker)[1]?.split('?')[0] || '';
    if (!encodedPath) return null;
    try {
      return decodeURIComponent(encodedPath);
    } catch {
      return encodedPath;
    }
  }
  return null;
}

function buildPatientPhotoViewUrl(storagePath: unknown): string | null {
  const path = extractPatientPhotosStoragePath(storagePath);
  if (!path) return null;
  return `/api/storage/patient-photos/view?path=${encodeURIComponent(path)}`;
}

const PROFESSIONAL_PROFILE_PHOTO_ACCESS_TTL_SECONDS = 15 * 60;
const PROFESSIONAL_PROFILE_PHOTO_ACCESS_MAX_FUTURE_SECONDS = 20 * 60;

function isProfessionalProfileOnboardingPath(objectPath: unknown, expectedOwnerUserId?: unknown): boolean {
  const parts = sanitizeString(objectPath, 1500).split('/').filter(Boolean);
  if (parts[0] !== 'onboarding' || !isUuid(parts[1])) return false;
  const expectedOwner = sanitizeString(expectedOwnerUserId, 120);
  if (expectedOwner && parts[1] !== expectedOwner) return false;
  const assetPath = parts.slice(2).join('/').toLowerCase();
  return (
    assetPath.startsWith('profile-') ||
    assetPath.startsWith('perfil-') ||
    assetPath.startsWith('profile/')
  );
}

function professionalProfilePhotoAccessSignature(params: {
  clinicId: string;
  ownerUserId: string;
  storagePath: string;
  expiresAt: number;
}): string {
  const secret = sanitizeString(process.env.SESSION_SECRET, 1000);
  if (!secret) return '';
  return crypto
    .createHmac('sha256', secret)
    .update(`professional-profile-photo:${params.clinicId}:${params.ownerUserId}:${params.expiresAt}:${params.storagePath}`)
    .digest('hex');
}

function buildProfessionalProfilePhotoViewUrl(
  storagePath: unknown,
  clinicIdInput: unknown,
  ownerUserIdInput: unknown,
): string | null {
  const storagePathValue = extractPatientPhotosStoragePath(storagePath);
  const clinicId = sanitizeString(clinicIdInput, 120);
  const ownerUserId = sanitizeString(ownerUserIdInput, 120);
  if (!storagePathValue || !isUuid(clinicId) || !isUuid(ownerUserId)) {
    return buildPatientPhotoViewUrl(storagePathValue);
  }
  const pathParts = storagePathValue.split('/').filter(Boolean);
  const accessObjectPath =
    pathParts[0] === 'demo' && pathParts[1] === clinicId
      ? pathParts.slice(2).join('/')
      : storagePathValue;
  if (!isProfessionalProfileOnboardingPath(accessObjectPath, ownerUserId)) {
    return buildPatientPhotoViewUrl(storagePathValue);
  }
  const expiresAt = Math.floor(Date.now() / 1000) + PROFESSIONAL_PROFILE_PHOTO_ACCESS_TTL_SECONDS;
  const signature = professionalProfilePhotoAccessSignature({
    clinicId,
    ownerUserId,
    storagePath: storagePathValue,
    expiresAt,
  });
  if (!signature) return buildPatientPhotoViewUrl(storagePathValue);
  const query = new URLSearchParams({
    path: storagePathValue,
    clinic_id: clinicId,
    owner_user_id: ownerUserId,
    expires_at: String(expiresAt),
    profile_signature: signature,
  });
  return `/api/storage/patient-photos/view?${query.toString()}`;
}

function verifyProfessionalProfilePhotoAccess(params: {
  clinicId: unknown;
  ownerUserId: unknown;
  storagePath: unknown;
  accessObjectPath: unknown;
  expiresAt: unknown;
  signature: unknown;
}): boolean {
  const clinicId = sanitizeString(params.clinicId, 120);
  const ownerUserId = sanitizeString(params.ownerUserId, 120);
  const storagePath = extractPatientPhotosStoragePath(params.storagePath);
  const accessObjectPath = sanitizeString(params.accessObjectPath, 1500);
  const signature = sanitizeString(params.signature, 128).toLowerCase();
  const expiresAt = Number(params.expiresAt);
  const nowSeconds = Math.floor(Date.now() / 1000);
  if (
    !isUuid(clinicId) ||
    !isUuid(ownerUserId) ||
    !storagePath ||
    !isProfessionalProfileOnboardingPath(accessObjectPath, ownerUserId) ||
    !Number.isInteger(expiresAt) ||
    expiresAt < nowSeconds ||
    expiresAt > nowSeconds + PROFESSIONAL_PROFILE_PHOTO_ACCESS_MAX_FUTURE_SECONDS ||
    !/^[a-f0-9]{64}$/.test(signature)
  ) {
    return false;
  }
  const expected = professionalProfilePhotoAccessSignature({
    clinicId,
    ownerUserId,
    storagePath,
    expiresAt,
  });
  if (!expected) return false;
  const providedBuffer = Buffer.from(signature, 'hex');
  const expectedBuffer = Buffer.from(expected, 'hex');
  return providedBuffer.length === expectedBuffer.length && crypto.timingSafeEqual(providedBuffer, expectedBuffer);
}

function enrichPatientPhotoHistoryRow(row: any): any {
  if (!row || typeof row !== 'object') return row;
  const metadata = row?.metadata && typeof row.metadata === 'object' ? row.metadata : {};
  const attachments = [
    ...(Array.isArray(row?.attachments) ? row.attachments : []),
    ...(Array.isArray(row?.files) ? row.files : []),
    ...(Array.isArray(row?.photos) ? row.photos : []),
    ...(Array.isArray(metadata?.attachments) ? metadata.attachments : []),
    ...(Array.isArray(metadata?.files) ? metadata.files : []),
    ...(Array.isArray(metadata?.photos) ? metadata.photos : [])
  ].filter((item) => item && typeof item === 'object');
  const candidates = [
    row?.image_path,
    row?.imagePath,
    row?.storage_path,
    row?.storagePath,
    row?.photo_path,
    row?.photoPath,
    row?.path,
    row?.image,
    row?.image_url,
    row?.imageUrl,
    row?.photo,
    row?.photo_url,
    row?.photoUrl,
    row?.url,
    metadata?.image_path,
    metadata?.imagePath,
    metadata?.storage_path,
    metadata?.storagePath,
    metadata?.photo_path,
    metadata?.photoPath,
    metadata?.path,
    metadata?.image,
    metadata?.image_url,
    metadata?.imageUrl,
    metadata?.photo,
    metadata?.photo_url,
    metadata?.photoUrl,
    metadata?.url,
    ...attachments.flatMap((item: any) => [
      item?.image_path,
      item?.imagePath,
      item?.storage_path,
      item?.storagePath,
      item?.photo_path,
      item?.photoPath,
      item?.path,
      item?.image,
      item?.image_url,
      item?.imageUrl,
      item?.photo,
      item?.photo_url,
      item?.photoUrl,
      item?.url
    ])
  ];
  const storagePath = candidates.map(extractPatientPhotosStoragePath).find(Boolean);
  if (!storagePath) return row;
  const viewUrl = buildPatientPhotoViewUrl(storagePath);
  if (!viewUrl) return row;
  return {
    ...row,
    image: viewUrl,
    image_url: viewUrl,
    imageUrl: viewUrl,
    image_path: storagePath,
    imagePath: storagePath
  };
}

async function canAccessPatientPhotoReferencedByHistory(params: {
  objectPath: string;
  accessObjectPath: string;
  actorId: string;
  activeClinicId: string;
  role: string;
  req: any;
}): Promise<boolean> {
  const { objectPath, accessObjectPath, actorId, activeClinicId, role, req } = params;
  const possibleReferences = Array.from(new Set([
    objectPath,
    accessObjectPath,
    `patient-photos/${objectPath}`,
    `patient-photos/${accessObjectPath}`,
    buildPatientPhotoViewUrl(objectPath),
    buildPatientPhotoViewUrl(accessObjectPath)
  ].filter(Boolean).map((item) => sanitizeString(item, 1500)).filter(Boolean)));

  const matchingRows: any[] = [];
  if (possibleReferences.length > 0) {
    const { data: pathRows, error: pathError } = await supabase
      .from('history')
      .select('patient_id,patient_email')
      .in('image_path', possibleReferences)
      .eq('is_active', true)
      .is('deleted_at', null)
      .limit(10);
    if (!pathError && Array.isArray(pathRows)) matchingRows.push(...pathRows);

    const { data: imageRows, error: imageError } = await supabase
      .from('history')
      .select('patient_id,patient_email')
      .in('image', possibleReferences)
      .eq('is_active', true)
      .is('deleted_at', null)
      .limit(10);
    if (!imageError && Array.isArray(imageRows)) matchingRows.push(...imageRows);
  }

  if (role === 'patient') {
    const portalScope = await resolveCanonicalPatientPortalScope(req.session.user);
    if (!portalScope || portalScope.clinicId !== activeClinicId) return false;
    return matchingRows.some((row) =>
      sanitizeString(row?.patient_id, 120) === portalScope.patientId
    );
  }

  for (const row of matchingRows) {
    const rowPatientId = sanitizeString(row?.patient_id, 120);
    if (rowPatientId && await canAccessPatientInCurrentClinic(rowPatientId, req.session.user)) {
      return true;
    }
  }

  return false;
}

function normalizeCanonicalPatientName(value: unknown): string {
  return sanitizeString(value, 180).replace(/\s+/g, ' ').trim();
}

function patientNameWordCount(value: unknown): number {
  return normalizeCanonicalPatientName(value).split(/\s+/).filter(Boolean).length;
}

function shouldPreserveExistingPatientFullName(existingName: unknown, incomingName: unknown): boolean {
  const current = normalizeCanonicalPatientName(existingName);
  const incoming = normalizeCanonicalPatientName(incomingName);
  if (!incoming) return Boolean(current);
  if (!current) return false;
  if (current.toLocaleLowerCase('pt-BR') === incoming.toLocaleLowerCase('pt-BR')) return false;
  return patientNameWordCount(current) >= 2 && patientNameWordCount(incoming) <= 1;
}

function serializePatientMediaForClient(row: any) {
  if (!row || typeof row !== 'object') return row;
  const profilePicturePath =
    extractPatientPhotosStoragePath(row?.profile_picture_path) ||
    extractPatientPhotosStoragePath(row?.profilePicturePath) ||
    extractPatientPhotosStoragePath(row?.profile_picture) ||
    extractPatientPhotosStoragePath(row?.profilePicture);
  const profilePicture = profilePicturePath
    ? buildPatientPhotoViewUrl(profilePicturePath)
    : sanitizeSessionUrl(row?.profile_picture || row?.profilePicture);
  const portalProfilePicturePath =
    extractPatientPhotosStoragePath(row?.portal_profile_picture_path) ||
    extractPatientPhotosStoragePath(row?.portalProfilePicturePath) ||
    extractPatientPhotosStoragePath(row?.portal_profile_picture) ||
    extractPatientPhotosStoragePath(row?.portalProfilePicture);
  const portalProfilePicture = portalProfilePicturePath
    ? buildPatientPhotoViewUrl(portalProfilePicturePath)
    : sanitizeSessionUrl(row?.portal_profile_picture || row?.portalProfilePicture);
  return {
    ...row,
    profile_picture: profilePicture || row?.profile_picture || null,
    profilePicture: profilePicture || row?.profilePicture || null,
    profile_picture_path: profilePicturePath || row?.profile_picture_path || null,
    profilePicturePath: profilePicturePath || row?.profilePicturePath || null,
    portal_profile_picture: portalProfilePicture || row?.portal_profile_picture || null,
    portalProfilePicture: portalProfilePicture || row?.portalProfilePicture || null,
    portal_profile_picture_path: portalProfilePicturePath || row?.portal_profile_picture_path || null,
    portalProfilePicturePath: portalProfilePicturePath || row?.portalProfilePicturePath || null
  };
}

async function resolvePatientPhotoUrl(rawUrl: unknown, rawPath?: unknown): Promise<string | null> {
  const storagePath = extractPatientPhotosStoragePath(rawPath) || extractPatientPhotosStoragePath(rawUrl);
  if (storagePath) return buildPatientPhotoViewUrl(storagePath);
  return sanitizeSessionUrl(rawUrl);
}

function buildLegacyPortalPatientPhotoRepair(patient: any, user: any) {
  const patientId = sanitizeString(patient?.id, 120);
  if (!isUuid(patientId)) return null;

  const explicitPortalPath =
    extractPatientPhotosStoragePath(patient?.portal_profile_picture_path) ||
    extractPatientPhotosStoragePath(patient?.portalProfilePicturePath);
  if (explicitPortalPath) return null;

  const existingPortalUrl = sanitizeSessionUrl(
    patient?.portal_profile_picture || patient?.portalProfilePicture,
  );
  const pathFromExistingPortalUrl = extractPatientPhotosStoragePath(existingPortalUrl);
  if (existingPortalUrl && !pathFromExistingPortalUrl) return null;

  const legacyPath =
    pathFromExistingPortalUrl ||
    extractPatientPhotosStoragePath(user?.profilePicturePath) ||
    extractPatientPhotosStoragePath(user?.profile_picture_path) ||
    extractPatientPhotosStoragePath(user?.profilePicture) ||
    extractPatientPhotosStoragePath(user?.profile_picture);
  if (!legacyPath) return null;

  const parts = legacyPath.split('/').filter(Boolean);
  const ownerPatientId = parts[0] === 'demo' ? parts[2] : parts[0];
  if (sanitizeString(ownerPatientId, 120) !== patientId) return null;

  const portalProfilePicture = buildPatientPhotoViewUrl(legacyPath);
  if (!portalProfilePicture) return null;
  return { portalProfilePicture, portalProfilePicturePath: legacyPath };
}

async function resolveProfessionalProfilePhotoUrl(profile: any, user?: any): Promise<string | null> {
  const metadata = profile?.metadata && typeof profile.metadata === 'object' && !Array.isArray(profile.metadata)
    ? profile.metadata
    : {};
  const storagePath =
    extractPatientPhotosStoragePath(metadata?.profilePicturePath) ||
    extractPatientPhotosStoragePath(metadata?.profile_picture_path) ||
    extractPatientPhotosStoragePath(profile?.profile_photo_url) ||
    extractPatientPhotosStoragePath(user?.profile_picture_path) ||
    extractPatientPhotosStoragePath(user?.profile_picture);
  return resolvePatientPhotoUrl(profile?.profile_photo_url || user?.profile_picture, storagePath);
}

function scopeProfessionalProfilePhotoUrlForClinic(
  rawUrl: unknown,
  clinicId: unknown,
  ownerUserId: unknown,
): string | null {
  const storagePath = extractPatientPhotosStoragePath(rawUrl);
  if (!storagePath) return sanitizeSessionUrl(rawUrl);
  return buildProfessionalProfilePhotoViewUrl(storagePath, clinicId, ownerUserId);
}

type DetectedUploadMime =
  | 'image/png'
  | 'image/jpeg'
  | 'image/gif'
  | 'image/webp'
  | 'application/pdf'
  | 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  | 'text/html'
  | 'application/json';
type UploadContext = 'image-only' | 'image-or-pdf' | 'anamnesis-document';
type ProtocolScanStatus = 'clean' | 'blocked';

function normalizeMime(input?: string | null): string {
  const lower = sanitizeString(input, 120).toLowerCase().split(';')[0].trim();
  if (!lower) return '';
  if (lower === 'image/jpg') return 'image/jpeg';
  return lower;
}

function detectMimeByMagicBytes(buffer: Buffer): DetectedUploadMime | null {
  if (buffer.length >= 8) {
    const isPng =
      buffer[0] === 0x89 &&
      buffer[1] === 0x50 &&
      buffer[2] === 0x4e &&
      buffer[3] === 0x47 &&
      buffer[4] === 0x0d &&
      buffer[5] === 0x0a &&
      buffer[6] === 0x1a &&
      buffer[7] === 0x0a;
    if (isPng) return 'image/png';
  }

  if (buffer.length >= 3) {
    const isJpeg = buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff;
    if (isJpeg) return 'image/jpeg';
  }

  if (buffer.length >= 6) {
    const header = buffer.subarray(0, 6).toString('ascii');
    if (header === 'GIF87a' || header === 'GIF89a') return 'image/gif';
  }

  if (buffer.length >= 12) {
    const riff = buffer.subarray(0, 4).toString('ascii');
    const webp = buffer.subarray(8, 12).toString('ascii');
    if (riff === 'RIFF' && webp === 'WEBP') return 'image/webp';
  }

  if (buffer.length >= 4 && buffer[0] === 0x50 && buffer[1] === 0x4b && buffer[2] === 0x03 && buffer[3] === 0x04) {
    // DOCX is an OOXML ZIP package. We never trust the extension alone: the
    // archive must expose the canonical Word package entries and must not
    // contain a VBA project (DOCM/macro-enabled document).
    const zipMetadataProbe = buffer.toString('latin1');
    const hasContentTypes = zipMetadataProbe.includes('[Content_Types].xml');
    const hasRootRelationships = zipMetadataProbe.includes('_rels/.rels');
    const hasWordDocument = zipMetadataProbe.includes('word/document.xml');
    const hasMacroProject = /word\/vbaProject\.bin/i.test(zipMetadataProbe);
    if (hasContentTypes && hasRootRelationships && hasWordDocument && !hasMacroProject) {
      return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
    }
  }

  if (buffer.length >= 5) {
    const pdf = buffer.subarray(0, 5).toString('ascii');
    if (pdf === '%PDF-') return 'application/pdf';
  }

  // Suporte para ficha de anamnese em HTML (gerada no frontend e enviada em base64)
  // Apenas quando o conteúdo realmente parece um documento HTML válido.
  const textProbe = buffer.subarray(0, Math.min(buffer.length, 2048)).toString('utf8').trim().toLowerCase();
  if (textProbe.startsWith('<!doctype html') || textProbe.startsWith('<html') || textProbe.includes('<body')) {
    return 'text/html';
  }
  if (buffer.length >= 4) {
    const isUtf16Le = buffer[0] === 0xff && buffer[1] === 0xfe;
    const isUtf16Be = buffer[0] === 0xfe && buffer[1] === 0xff;
    if (isUtf16Le || isUtf16Be) {
      const utf16Probe = buffer.subarray(0, Math.min(buffer.length, 4096)).toString('utf16le').trim().toLowerCase();
      if (utf16Probe.startsWith('<!doctype html') || utf16Probe.startsWith('<html') || utf16Probe.includes('<body')) {
        return 'text/html';
      }
    }
  }

  if (textProbe.startsWith('{') || textProbe.startsWith('[')) {
    try {
      JSON.parse(textProbe);
      return 'application/json';
    } catch {
      // ignore invalid json probe
    }
  }

  return null;
}

function isStorageDuplicateObjectError(error: any): boolean {
  const status = Number(error?.statusCode || error?.status || 0);
  const code = sanitizeString(error?.code || error?.error, 80).toLowerCase();
  const message = sanitizeString(error?.message || String(error || ''), 300).toLowerCase();
  return (
    status === 409 ||
    code.includes('duplicate') ||
    code.includes('resourcealreadyexists') ||
    message.includes('already exists') ||
    message.includes('duplicate')
  );
}

function isAllowedDetectedMime(mime: DetectedUploadMime, context: UploadContext): boolean {
  if (context === 'image-only') {
    return mime.startsWith('image/');
  }
  if (context === 'anamnesis-document') {
    return mime === 'application/pdf' || mime === 'text/html' || mime === 'application/json' || mime.startsWith('image/');
  }
  return (
    mime.startsWith('image/') ||
    mime === 'application/pdf' ||
    mime === 'application/json' ||
    mime === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  );
}

function validateBinaryUpload(
  fileBuffer: Buffer,
  providedMime: string | null | undefined,
  context: UploadContext
): { ok: true; detectedMime: DetectedUploadMime } | { ok: false; error: string } {
  const detectedMime = detectMimeByMagicBytes(fileBuffer);
  if (!detectedMime) {
    return { ok: false, error: 'Tipo real do arquivo não reconhecido. Envie PDF, imagem válida ou DOCX sem macros.' };
  }

  if (!isAllowedDetectedMime(detectedMime, context)) {
    return { ok: false, error: 'Arquivo bloqueado pela política de mídia segura.' };
  }

  const normalizedProvidedMime = normalizeMime(providedMime);
  if (normalizedProvidedMime && normalizedProvidedMime !== 'application/octet-stream' && normalizedProvidedMime !== detectedMime) {
    return { ok: false, error: 'MIME informado divergente do tipo real (magic bytes).' };
  }

  return { ok: true, detectedMime };
}

function decodeSafeDataUrl(input: string): { buffer: Buffer; mime: string } | null {
  const match = String(input || '').match(/^data:([^;]+);base64,([a-z0-9+/=\s]+)$/i);
  if (!match) return null;
  try {
    const buffer = Buffer.from(match[2].replace(/\s/g, ''), 'base64');
    return buffer.length ? { buffer, mime: normalizeMime(match[1]) } : null;
  } catch {
    return null;
  }
}

function detectProtocolFileKind(buffer: Buffer): 'pdf' | 'xlsx' | 'xls' | 'unknown' {
  if (buffer.subarray(0, 5).toString('ascii') === '%PDF-') return 'pdf';
  if (buffer.length >= 4 && buffer[0] === 0x50 && buffer[1] === 0x4b && buffer[2] === 0x03 && buffer[3] === 0x04) return 'xlsx';
  if (buffer.length >= 8 && buffer[0] === 0xd0 && buffer[1] === 0xcf && buffer[2] === 0x11 && buffer[3] === 0xe0) return 'xls';
  return 'unknown';
}

function sanitizeSafePreviewText(input: string, maxLength = 4000): string {
  return sanitizeString(
    String(input || '')
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim(),
    maxLength
  );
}

function clampScore(value: number): number {
  return Math.max(0, Math.min(100, Math.round(value)));
}

function extractProtocolReadableText(buffer: Buffer, kind: 'pdf' | 'xlsx' | 'xls' | 'unknown'): string {
  if (kind !== 'pdf') return '';

  const rawText = buffer.subarray(0, Math.min(buffer.length, 1_800_000)).toString('latin1');
  const chunkCandidates = rawText
    .replace(/\\[rn]/g, '\n')
    .split(/(?:\r?\n|endstream|endobj|stream|obj|BT|ET)+/i)
    .map((chunk) => sanitizeSafePreviewText(
      chunk
        .replace(/\/[A-Za-z][A-Za-z0-9]+/g, ' ')
        .replace(/[()[\]{}<>]/g, ' ')
        .replace(/[^A-Za-zÀ-ÖØ-öø-ÿ0-9.,;:!?+\-_/ ]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim(),
      240
    ))
    .filter(Boolean);

  const filtered = chunkCandidates.filter((chunk) => {
    const alphaChars = (chunk.match(/[A-Za-zÀ-ÖØ-öø-ÿ]/g) || []).length;
    const digitChars = (chunk.match(/[0-9]/g) || []).length;
    const alphaRatio = alphaChars / Math.max(1, chunk.length);
    const noisyPdfInternals = /(catalog|pages|kids|mediabox|procset|font|resources|filter|length|device(rgb|gray)|xref|startxref)/i.test(chunk);
    const mostlyNumbers = digitChars > alphaChars * 1.6;
    return chunk.length >= 20 && alphaRatio >= 0.45 && !noisyPdfInternals && !mostlyNumbers;
  });

  const unique = Array.from(new Set(filtered));
  return sanitizeSafePreviewText(unique.slice(0, 12).join(' | '), 1800);
}

function analyzeProtocolStructure(text: string, kind: 'pdf' | 'xlsx' | 'xls' | 'unknown'): Record<string, any> {
  const normalizedText = sanitizeSafePreviewText(text, 4000).toLowerCase();
  const lines = text.split('|').map((line) => sanitizeSafePreviewText(line, 240)).filter(Boolean);
  const fieldDetectors = [
    { key: 'task', label: 'Tarefa', regex: /\btarefa\b|\bskill\b|\bitem\b/gi },
    { key: 'points', label: 'Pontos', regex: /\bpontos?\b|\bpontuacao\b|\bscore\b|\b0\s*-\s*[1-9]\b/gi },
    { key: 'name', label: 'Nome', regex: /\bnome da tarefa\b|\bnome\b|\btitle\b/gi },
    { key: 'objective', label: 'Objetivo', regex: /\bobjetivo\b|\bmeta\b|\bgoal\b/gi },
    { key: 'question', label: 'Pergunta', regex: /\bpergunta\b|\bquestao\b|\bprompt\b/gi },
    { key: 'example', label: 'Exemplo', regex: /\bexemplo\b|\bexample\b/gi },
    { key: 'criteria', label: 'Criterios', regex: /\bcriterios?\b|\bcrit[eé]rios?\b|\bmastery\b|\bscoring\b/gi },
    { key: 'comment', label: 'Comentario', regex: /\bcomentario\b|\bobservacao\b|\bnota\b/gi }
  ];

  const detectedFields = fieldDetectors
    .map((field) => ({
      ...field,
      hits: (normalizedText.match(field.regex) || []).length
    }))
    .filter((field) => field.hits > 0);

  const taskCodeMatches = normalizedText.match(/\b[a-z]{1,4}\d{1,3}(?:[.-]\d+)?\b/gi) || [];
  const scoringMatches = normalizedText.match(/\b[0-5]\s*(?:-|a)?\s*[0-5]\b/g) || [];
  const questionMarks = (text.match(/\?/g) || []).length;
  const lineCount = lines.length;
  const legibleChars = (text.match(/[A-Za-zÀ-ÖØ-öø-ÿ]/g) || []).length;
  const weirdChars = (text.match(/[^\x20-\x7EÀ-ÖØ-öø-ÿ]/g) || []).length;
  const gibberishPenalty = weirdChars > 0 ? Math.min(35, weirdChars / 3) : 0;

  const coverageRatio = detectedFields.length / fieldDetectors.length;
  const taskSignalScore = Math.min(100, (taskCodeMatches.length * 7) + (lineCount * 4) + (questionMarks * 3));
  const structureScore = clampScore((coverageRatio * 55) + (taskSignalScore * 0.45));
  const canonicalReadinessScore = clampScore(
    (coverageRatio * 70) +
    Math.min(20, taskCodeMatches.length * 3) +
    Math.min(10, scoringMatches.length * 2)
  );
  const legibilityScore = clampScore(
    (legibleChars >= 120 ? 72 : legibleChars >= 60 ? 54 : legibleChars >= 20 ? 30 : 12) - gibberishPenalty
  );
  const reliabilityScore = clampScore((legibilityScore * 0.4) + (structureScore * 0.35) + (canonicalReadinessScore * 0.25));

  const warnings: string[] = [];
  const strengths: string[] = [];

  if (!text) warnings.push('Nao foi possivel extrair texto clinico legivel sem abrir o arquivo bruto.');
  if (legibilityScore < 45) warnings.push('O conteudo extraido esta pouco legivel e pode ter vindo de PDF escaneado ou com texto embaralhado.');
  if (detectedFields.length < 3) warnings.push('A estrutura minima de protocolo nao apareceu com clareza na amostra segura.');
  if (taskCodeMatches.length === 0) warnings.push('Nao identifiquei codigos de tarefa de forma confiavel.');
  if (!detectedFields.some((field) => field.key === 'criteria')) warnings.push('Nao encontrei criterios de pontuacao de forma explicita.');
  if (!detectedFields.some((field) => field.key === 'objective')) warnings.push('Nao encontrei objetivos clinicos de forma explicita.');

  if (legibilityScore >= 65) strengths.push('A previa segura trouxe texto suficientemente legivel para triagem.');
  if (detectedFields.length >= 4) strengths.push('A estrutura basica de um protocolo clinico apareceu na amostra.');
  if (taskCodeMatches.length >= 3) strengths.push('Foram encontrados multiplos possiveis codigos de tarefa.');
  if (scoringMatches.length > 0 || detectedFields.some((field) => field.key === 'points')) strengths.push('Existem sinais de rubricacao/pontuacao no material.');

  const suggestedNextStep = reliabilityScore >= 75 && canonicalReadinessScore >= 60
    ? 'Pode seguir para vinculacao com protocolo canonico e montagem estruturada.'
    : reliabilityScore >= 50
      ? 'Revisar a previa segura e completar a montagem canonica antes de aprovar.'
      : 'Nao confiar na estrutura atual. Solicite nova fonte ou reconstrua a partir de tabela limpa.';

  return {
    detectedFields: detectedFields.map((field) => field.label),
    detectedFieldCoverage: {
      found: detectedFields.length,
      total: fieldDetectors.length
    },
    estimatedTaskCodes: taskCodeMatches.slice(0, 12),
    estimatedRows: lineCount,
    scores: {
      legibility: legibilityScore,
      structure: structureScore,
      canonicalReadiness: canonicalReadinessScore,
      reliability: reliabilityScore
    },
    strengths,
    warnings,
    suggestedNextStep
  };
}

function buildProtocolSafePreview(
  buffer: Buffer,
  kind: 'pdf' | 'xlsx' | 'xls' | 'unknown',
  fileName: string
): { text: string; structureReport: Record<string, any> } {
  const sizeKb = Math.max(1, Math.round(buffer.length / 1024));
  const readableText = extractProtocolReadableText(buffer, kind);
  const structureReport = analyzeProtocolStructure(readableText, kind);

  if (kind === 'pdf') {
    const canShowExcerpt = (structureReport.scores?.reliability || 0) >= 55 || (structureReport.detectedFields?.length || 0) >= 2;
    return {
      text: [
        `Arquivo: ${fileName}`,
        'Tipo detectado: PDF',
        `Tamanho: ${sizeKb} KB`,
        `Legibilidade: ${structureReport.scores?.legibility || 0}%`,
        `Estrutura clinica: ${structureReport.scores?.structure || 0}%`,
        `Prontidao canonica: ${structureReport.scores?.canonicalReadiness || 0}%`,
        `Confiabilidade da leitura segura: ${structureReport.scores?.reliability || 0}%`,
        structureReport.detectedFields?.length
          ? `Campos detectados: ${structureReport.detectedFields.join(', ')}`
          : 'Campos detectados: nenhum campo clinico reconhecido com seguranca.',
        readableText && canShowExcerpt
          ? `Trecho clinico seguro: ${sanitizeSafePreviewText(readableText, 1400)}`
          : 'Trecho clinico seguro: leitura textual insuficiente para confiar na estrutura. Use o PDF apenas como comprovante e monte a estrutura a partir de tabela limpa.',
        'Arquivo bruto permanece bloqueado para abertura/download.'
      ].join('\n'),
      structureReport
    };
  }
  if (kind === 'xlsx') {
    return {
      text: [
        `Arquivo: ${fileName}`,
        'Tipo detectado: Excel XLSX',
        `Tamanho: ${sizeKb} KB`,
        'Previa segura: planilha Office detectada. A estrutura tende a ser melhor, mas a leitura completa deve ocorrer em worker isolado.',
        'Arquivo bruto permanece bloqueado para abertura/download.'
      ].join('\n'),
      structureReport: {
        ...structureReport,
        warnings: [
          'A leitura estrutural detalhada de XLSX ainda nao roda neste scanner seguro.',
          ...(Array.isArray(structureReport.warnings) ? structureReport.warnings : [])
        ]
      }
    };
  }
  if (kind === 'xls') {
    return {
      text: [
        `Arquivo: ${fileName}`,
        'Tipo detectado: Excel XLS legado',
        `Tamanho: ${sizeKb} KB`,
        'Previa segura indisponivel: formato legado pode conter macros/OLE e exige sandbox dedicada.',
        'Arquivo bruto permanece bloqueado para abertura/download.'
      ].join('\n'),
      structureReport: {
        ...structureReport,
        warnings: [
          'Formato XLS legado requer analise externa mais restrita.',
          ...(Array.isArray(structureReport.warnings) ? structureReport.warnings : [])
        ]
      }
    };
  }
  return {
    text: [
      `Arquivo: ${fileName}`,
      'Tipo detectado: desconhecido',
      `Tamanho: ${sizeKb} KB`,
      'Previa segura indisponivel.',
      'Arquivo bruto permanece bloqueado para abertura/download.'
    ].join('\n'),
    structureReport: {
      ...structureReport,
      warnings: [
        'Nao foi possivel identificar o formato real do arquivo.',
        ...(Array.isArray(structureReport.warnings) ? structureReport.warnings : [])
      ]
    }
  };
}

function scanProtocolUpload(dataUrl: string, fileName: string, providedMime: string): {
  scanStatus: ProtocolScanStatus;
  quarantineStatus: 'review_ready' | 'blocked';
  safePreviewStatus: 'generated' | 'blocked';
  safePreviewText: string;
  scanReport: Record<string, any>;
} {
  const decoded = decodeSafeDataUrl(dataUrl);
  if (!decoded) {
    return {
      scanStatus: 'blocked',
      quarantineStatus: 'blocked',
      safePreviewStatus: 'blocked',
      safePreviewText: 'Arquivo bloqueado: conteudo base64 invalido.',
      scanReport: { engine: 'verto-basic-static-scan', blockedReason: 'invalid_data_url', flags: ['invalid_data_url'] }
    };
  }

  const kind = detectProtocolFileKind(decoded.buffer);
  const normalizedProvidedMime = normalizeMime(providedMime || decoded.mime);
  const flags: string[] = [];
  const lowerFileName = sanitizeString(fileName, 240).toLowerCase();
  const lowerPdfProbe = kind === 'pdf' ? decoded.buffer.toString('latin1').toLowerCase() : '';
  const pdfIndicators = [
    ['/javascript', 'pdf_javascript'],
    ['/js', 'pdf_js_action'],
    ['/openaction', 'pdf_open_action'],
    ['/aa', 'pdf_additional_action'],
    ['/launch', 'pdf_launch_action'],
    ['/embeddedfile', 'pdf_embedded_file'],
    ['/richmedia', 'pdf_rich_media'],
    ['/xfa', 'pdf_xfa_form']
  ];

  if (kind === 'unknown') flags.push('unknown_magic_bytes');
  if (kind === 'xls') flags.push('legacy_excel_ole_requires_external_sandbox');
  if (lowerFileName.endsWith('.xlsm') || lowerFileName.endsWith('.xltm')) flags.push('macro_enabled_excel_extension');
  if (kind === 'xlsx' && normalizedProvidedMime && !['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/octet-stream'].includes(normalizedProvidedMime)) {
    flags.push('provided_mime_mismatch');
  }
  if (kind === 'xls' && normalizedProvidedMime && !['application/vnd.ms-excel', 'application/octet-stream'].includes(normalizedProvidedMime)) {
    flags.push('provided_mime_mismatch');
  }
  if (kind === 'pdf' && normalizedProvidedMime && !['application/pdf', 'application/octet-stream'].includes(normalizedProvidedMime)) {
    flags.push('provided_mime_mismatch');
  }
  for (const [indicator, flag] of pdfIndicators) {
    if (lowerPdfProbe.includes(indicator)) flags.push(flag);
  }

  const blockedFlags = new Set([
    'unknown_magic_bytes',
    'legacy_excel_ole_requires_external_sandbox',
    'macro_enabled_excel_extension',
    'provided_mime_mismatch',
    'pdf_javascript',
    'pdf_js_action',
    'pdf_open_action',
    'pdf_additional_action',
    'pdf_launch_action',
    'pdf_embedded_file',
    'pdf_rich_media',
    'pdf_xfa_form'
  ]);
  const blocked = flags.some((flag) => blockedFlags.has(flag));
  const safePreview = buildProtocolSafePreview(decoded.buffer, kind, sanitizeString(fileName, 240) || 'protocolo');

  return {
    scanStatus: blocked ? 'blocked' : 'clean',
    quarantineStatus: blocked ? 'blocked' : 'review_ready',
    safePreviewStatus: blocked ? 'blocked' : 'generated',
    safePreviewText: safePreview.text,
    scanReport: {
      engine: 'verto-basic-static-scan',
      scannedAt: new Date().toISOString(),
      detectedKind: kind,
      detectedMime: decoded.mime,
      providedMime: normalizedProvidedMime || null,
      sizeBytes: decoded.buffer.length,
      flags,
      structure: safePreview.structureReport
    }
  };
}

async function readBoundedRawUpload(req: any, maxBytes: number): Promise<Buffer> {
  const chunks: Buffer[] = [];
  let total = 0;
  let exceeded = false;

  await new Promise<void>((resolve, reject) => {
    req.on('data', (chunk: Buffer) => {
      const bufferChunk = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      total += bufferChunk.length;
      if (total > maxBytes) {
        exceeded = true;
        return;
      }
      chunks.push(bufferChunk);
    });
    req.once('end', () => resolve());
    req.once('error', (error: any) => reject(error));
    req.once('aborted', () => reject(Object.assign(new Error('Upload interrompido antes de concluir.'), { code: 'UPLOAD_ABORTED' })));
  });

  if (exceeded) {
    throw Object.assign(new Error('O arquivo deve ter no máximo 10 MB.'), { code: 'UPLOAD_TOO_LARGE' });
  }

  return Buffer.concat(chunks);
}

function decodeUploadHeader(value: unknown, maxLength: number): string {
  const raw = sanitizeString(value, Math.max(maxLength * 3, maxLength));
  if (!raw) return '';
  try {
    return sanitizeString(decodeURIComponent(raw), maxLength);
  } catch {
    return sanitizeString(raw, maxLength);
  }
}

async function parseMultipartFormData(req: any): Promise<{
  fields: Record<string, string>;
  file: { fileName: string; contentType: string; buffer: Buffer } | null;
}> {
  const contentType = String(req.headers?.['content-type'] || '');
  const boundaryMatch = contentType.match(/boundary=(?:"([^"]+)"|([^;]+))/i);
  const boundary = boundaryMatch?.[1] || boundaryMatch?.[2];
  if (!boundary) {
    throw new Error('Boundary multipart ausente.');
  }

  const chunks: Buffer[] = [];
  let total = 0;
  await new Promise<void>((resolve, reject) => {
    req.on('data', (chunk: Buffer) => {
      total += chunk.length;
      if (total > 12 * 1024 * 1024) {
        reject(new Error('Payload multipart excede 12MB.'));
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve());
    req.on('error', (error: any) => reject(error));
  });

  const raw = Buffer.concat(chunks).toString('latin1');
  const boundaryToken = `--${boundary}`;
  const fields: Record<string, string> = {};
  let file: { fileName: string; contentType: string; buffer: Buffer } | null = null;

  for (const rawPart of raw.split(boundaryToken)) {
    const part = rawPart.trim();
    if (!part || part === '--') continue;

    const headerEndIndex = part.indexOf('\r\n\r\n');
    if (headerEndIndex <= 0) continue;

    const headersRaw = part.slice(0, headerEndIndex);
    let bodyRaw = part.slice(headerEndIndex + 4);
    bodyRaw = bodyRaw.replace(/\r\n$/, '');
    bodyRaw = bodyRaw.replace(/--$/, '');

    const contentDispositionLine =
      headersRaw
        .split('\r\n')
        .find((line) => line.toLowerCase().startsWith('content-disposition:')) || '';
    const contentTypeLine =
      headersRaw
        .split('\r\n')
        .find((line) => line.toLowerCase().startsWith('content-type:')) || '';

    const nameMatch = contentDispositionLine.match(/name="([^"]+)"/i);
    const fileNameMatch = contentDispositionLine.match(/filename="([^"]*)"/i);
    const fieldName = sanitizeString(nameMatch?.[1] || '', 120);
    if (!fieldName) continue;

    const bodyBuffer = Buffer.from(bodyRaw, 'latin1');
    if (fileNameMatch && bodyBuffer.length) {
      const uploadedName = sanitizeString(fileNameMatch[1] || 'arquivo.bin', 220) || 'arquivo.bin';
      const uploadedType = sanitizeString(
        contentTypeLine.replace(/^content-type:\s*/i, ''),
        120
      ) || 'application/octet-stream';
      file = {
        fileName: uploadedName,
        contentType: uploadedType,
        buffer: bodyBuffer
      };
      continue;
    }

    fields[fieldName] = Buffer.from(bodyRaw, 'latin1').toString('utf8');
  }

  return { fields, file };
}

function asSafeNumber(value: unknown, min = 0, max = Number.MAX_SAFE_INTEGER): number | null {
  if (typeof value !== 'number' && typeof value !== 'string') return null;
  const num = Number(value);
  if (!Number.isFinite(num)) return null;
  return Math.min(max, Math.max(min, num));
}

function parseBoundedListLimit(value: unknown, fallback = 50, max = 50): number {
  const parsed = asSafeNumber(value, 1, max);
  return Math.min(max, Math.max(1, parsed || fallback));
}

