const logPrefacturingReadPerformance = (label: string, stats: Record<string, any>) => {
  if (process.env.NODE_ENV === 'production') return;
  console.info('[PrefacturingRead]', cleanObject({
    label,
    mode: 'read-only',
    recompute: false,
    ...stats
  }));
};

