function cleanObject<T extends Record<string, any>>(input: T): Partial<T> {
  return Object.fromEntries(Object.entries(input).filter(([, v]) => v !== undefined)) as Partial<T>;
}

function parseJsonValueForRoute(value: any): any {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function normalizeJsonArrayForRoute(value: any, nestedKeys: string[] = []): any[] {
  if (Array.isArray(value)) return value;

  const parsed = parseJsonValueForRoute(value);
  if (Array.isArray(parsed)) return parsed;

  const source =
    parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      ? parsed
      : value && typeof value === 'object' && !Array.isArray(value)
        ? value
        : null;

  if (!source) return [];

  for (const key of nestedKeys) {
    const nested = source[key];
    if (Array.isArray(nested)) return nested;
    const parsedNested = parseJsonValueForRoute(nested);
    if (Array.isArray(parsedNested)) return parsedNested;
  }

  return [];
}

function normalizeProtocolArrayForRoute(value: any): any[] {
  return normalizeJsonArrayForRoute(value, ['protocols', 'items', 'data', 'value']).filter(Boolean);
}

function resolveProtocolSkillOriginForRoute(
  value: any,
  params: { protocolId: string; domainId: string; skillId: string }
): {
  protocolId: string;
  protocolTitle: string | null;
  domainId: string;
  domainName: string | null;
  skillId: string;
  skillName: string | null;
} | null {
  const protocol = normalizeProtocolArrayForRoute(value).find(
    (item: any) => sanitizeString(item?.id, 180) === params.protocolId
  );
  if (!protocol) return null;

  const domain = normalizeJsonArrayForRoute(protocol?.data, ['domains', 'items', 'data', 'value']).find(
    (item: any) => sanitizeString(item?.id, 180) === params.domainId
  );
  if (!domain) return null;

  const skill = normalizeJsonArrayForRoute(domain?.skills, ['skills', 'items', 'data', 'value']).find(
    (item: any) => sanitizeString(item?.id, 180) === params.skillId
  );
  if (!skill) return null;

  return {
    protocolId: sanitizeString(protocol.id, 180),
    protocolTitle: sanitizeString(protocol.title || protocol.name, 240) || null,
    domainId: sanitizeString(domain.id, 180),
    domainName: sanitizeString(domain.name || domain.title, 240) || null,
    skillId: sanitizeString(skill.id, 180),
    skillName: sanitizeString(skill.name || skill.title, 240) || null
  };
}

const ADULT_EFFORT_SEMANTICS_V2 = 'effort_min_0_max_100_v2';

function effortEmojiForPercent(value: number | null | undefined): string | null {
  if (value === null || value === undefined || !Number.isFinite(Number(value))) return null;
  const percent = Number(value);
  if (percent < 20) return '🙂';
  if (percent < 40) return '😌';
  if (percent < 60) return '😐';
  if (percent < 80) return '😕';
  return '😫';
}

function effortLabelForPercent(value: number | null | undefined): string | null {
  if (value === null || value === undefined || !Number.isFinite(Number(value))) return null;
  const percent = Number(value);
  if (percent < 20) return 'Muito leve';
  if (percent < 40) return 'Leve';
  if (percent < 60) return 'Moderado';
  if (percent < 80) return 'Difícil';
  return 'Muito difícil';
}

function isVbMappTask(taskLike: any): boolean {
  const candidates = [
    taskLike?.protocol_id,
    taskLike?.protocolId,
    taskLike?.protocol_title,
    taskLike?.protocolTitle,
    taskLike?.title,
    taskLike?.name
  ]
    .map((v) => sanitizeString(v, 180).toLowerCase())
    .filter(Boolean);
  return candidates.some((v) => /vb[\s-]?mapp/.test(v));
}

async function resolveVbMappMasteryCriterionByClinicId(clinicId: string | null | undefined): Promise<number> {
  const fallback = 5;
  const safeClinicId = sanitizeString(clinicId, 120);
  if (!safeClinicId) return fallback;
  try {
    const { data, error } = await supabase
      .from('clinics')
      .select('vbmapp_mastery_criterion')
      .eq('id', safeClinicId)
      .maybeSingle();
    if (error) {
      if (/vbmapp_mastery_criterion|relation "clinics"/i.test(String(error?.message || ''))) {
        return fallback;
      }
      return fallback;
    }
    const criterion = asSafeNumber((data as any)?.vbmapp_mastery_criterion, 1, 20);
    if (criterion === 10) return 10;
    return 5;
  } catch {
    return fallback;
  }
}

function ensureRole(role: unknown): role is AppRole {
  return typeof role === 'string' && (ALL_ROLES as string[]).includes(role);
}

function ensureClinicRole(role: unknown): role is ClinicRole {
  return typeof role === 'string' && (CLINIC_ROLES as string[]).includes(role);
}

function normalizeRequestedRole(role: unknown): AppRole {
  const safe = sanitizeString(role, 40).toLowerCase();
  if (safe === 'director' || safe === 'coordinator' || safe === 'supervisor' || safe === 'admin' || safe === 'therapist' || safe === 'receptionist' || safe === 'biller' || safe === 'patient' || safe === 'owner') {
    return safe as AppRole;
  }
  if (safe === 'professional') return 'coordinator';
  return 'therapist';
}

const OWNER_MFA_POLICY_VERSION = '2026-07-23-v1';

function hasVerifiedMfaSession(user: any): boolean {
  const verifiedAt = Date.parse(sanitizeString(user?.mfaVerifiedAt, 80));
  return user?.mfaVerified === true &&
    sanitizeString(user?.mfaMethod, 20).toLowerCase() === 'totp' &&
    Number.isFinite(verifiedAt);
}

function hasVerifiedOwnerMfaSession(user: any): boolean {
  const privilegedSession =
    sanitizeString(user?.role, 40).toLowerCase() === 'owner' ||
    user?.isPlatformAdmin === true;
  if (!privilegedSession) return true;
  return hasVerifiedMfaSession(user);
}

function requireRoles(...allowedRoles: AppRole[]) {
  const allowed = new Set<AppRole>(allowedRoles);
  return async (req: any, res: any, next: any) => {
    const role = req.session?.user?.role;
    if (!ensureRole(role)) {
      return res.status(403).json({ error: 'Acesso negado para este perfil.' });
    }

    let roleAllowed = allowed.has(role);
    // Transitional compatibility while legacy routes are migrated to capabilities:
    // Director is a strict superset of Coordinator, but only when the active
    // membership for the selected clinic is still valid on the server.
    if (!roleAllowed && role === 'director' && allowed.has('coordinator')) {
      try {
        roleAllowed = (await resolveEffectiveClinicRole(req.session?.user)) === 'director';
      } catch (error) {
        logRouteDbError('requireRoles.directorCompatibility', error, {
          clinicId: sanitizeString(currentClinicId(req.session?.user), 120),
          userId: sanitizeString(req.session?.user?.id, 120)
        });
        return res.status(503).json({
          error: 'CLINIC_MEMBERSHIP_ROLE_UNAVAILABLE',
          message: 'Não foi possível validar seu acesso nesta clínica agora.'
        });
      }
    }

    if (!roleAllowed) {
      return res.status(403).json({ error: 'Acesso negado para este perfil.' });
    }
    if (role === 'owner' && !hasVerifiedMfaSession(req.session?.user)) {
      return res.status(401).json({
        error: 'OWNER_MFA_REQUIRED',
        message: 'Confirme o Google Authenticator para acessar esta area.'
      });
    }
    return next();
  };
}

function getEncryptionKey(): Buffer | null {
  const raw = (process.env.DATA_ENCRYPTION_KEY || '').trim();
  if (!raw) {
    const sessionSecret = (process.env.SESSION_SECRET || '').trim();
    if (!sessionSecret) return null;
    return crypto.createHash('sha256').update(sessionSecret).digest();
  }

  if (/^[0-9a-fA-F]{64}$/.test(raw)) {
    return Buffer.from(raw, 'hex');
  }

  try {
    const decoded = Buffer.from(raw, 'base64');
    if (decoded.length === 32) return decoded;
  } catch {
    return null;
  }

  return null;
}

const encryptionKey = getEncryptionKey();

function encryptJsonPayload(payload: Record<string, any>): string | null {
  if (!encryptionKey) return null;
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ENCRYPTION_ALGO, encryptionKey, iv);
  const plaintext = Buffer.from(JSON.stringify(payload), 'utf8');
  const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return `${iv.toString('base64')}.${tag.toString('base64')}.${encrypted.toString('base64')}`;
}

function decryptJsonPayload(payload: string | null | undefined): Record<string, any> | null {
  if (!encryptionKey || !payload) return null;
  try {
    const [ivB64, tagB64, dataB64] = payload.split('.');
    if (!ivB64 || !tagB64 || !dataB64) return null;

    const iv = Buffer.from(ivB64, 'base64');
    const tag = Buffer.from(tagB64, 'base64');
    const encrypted = Buffer.from(dataB64, 'base64');

    const decipher = crypto.createDecipheriv(ENCRYPTION_ALGO, encryptionKey, iv);
    decipher.setAuthTag(tag);
    const decrypted = Buffer.concat([decipher.update(encrypted), decipher.final()]);
    return JSON.parse(decrypted.toString('utf8'));
  } catch (error: any) {
    console.error('[Encryption] Falha ao descriptografar payload clínico:', error?.message || String(error));
    return null;
  }
}

const MFA_STORED_SECRET_PREFIX = 'enc:v1:';

function isEncryptedStoredMfaSecret(value: unknown): boolean {
  return sanitizeString(value, 4000).startsWith(MFA_STORED_SECRET_PREFIX);
}

function resolveStoredMfaSecret(value: unknown): string {
  const stored = sanitizeString(value, 4000);
  if (!stored) return '';
  if (!stored.startsWith(MFA_STORED_SECRET_PREFIX)) {
    // Compatibilidade de leitura para segredos existentes. Depois de uma
    // validacao TOTP bem-sucedida, o mesmo segredo e gravado criptografado.
    return sanitizeString(stored, 512);
  }
  return sanitizeString(
    decryptJsonPayload(stored.slice(MFA_STORED_SECRET_PREFIX.length))?.secret,
    512,
  );
}

function encryptStoredMfaSecret(secret: unknown): string {
  const normalized = sanitizeString(secret, 512);
  if (!normalized) throw new Error('MFA_SECRET_INVALID');
  const encrypted = encryptJsonPayload({ secret: normalized });
  if (!encrypted) throw new Error('MFA_ENCRYPTION_UNAVAILABLE');
  return `${MFA_STORED_SECRET_PREFIX}${encrypted}`;
}

const AUTH_MFA_CHALLENGE_TTL_MS = 5 * 60 * 1000;
const AUTH_MFA_MAX_ATTEMPTS = 5;
const AUTH_MFA_CHALLENGE_SELECT =
  'id,challenge_hash,user_id,purpose,setup_secret_encrypted,attempts,max_attempts,expires_at,consumed_at,created_at';

function hashAuthMfaChallenge(challengeId: string): string {
  const secret = (process.env.SESSION_SECRET || '').trim();
  if (!secret) throw new Error('SESSION_SECRET_REQUIRED_FOR_MFA');
  return crypto.createHmac('sha256', secret).update(challengeId).digest('hex');
}

function constantTimeStringEquals(left: unknown, right: unknown): boolean {
  const leftBuffer = Buffer.from(String(left || ''), 'utf8');
  const rightBuffer = Buffer.from(String(right || ''), 'utf8');
  return leftBuffer.length === rightBuffer.length && crypto.timingSafeEqual(leftBuffer, rightBuffer);
}

function regenerateExpressSession(req: any): Promise<void> {
  return new Promise((resolve, reject) => {
    req.session.regenerate((error: any) => error ? reject(error) : resolve());
  });
}

function saveExpressSession(req: any): Promise<void> {
  return new Promise((resolve, reject) => {
    req.session.save((error: any) => error ? reject(error) : resolve());
  });
}

async function fetchMfaSecurityProfile(userId: string) {
  if (!supabase || !isUuid(userId)) {
    return { data: null, error: new Error('MFA_SECURITY_PROFILE_UNAVAILABLE') };
  }
  return await supabase
    .from('users')
    .select('id,role,two_factor_enabled,two_factor_secret')
    .eq('id', userId)
    .maybeSingle();
}

async function createAuthMfaChallenge(params: {
  req: any;
  userId: string;
  email: string;
  purpose: 'login' | 'setup';
  setupSecret?: string | null;
}) {
  const challengeId = crypto.randomBytes(32).toString('base64url');
  const challengeHash = hashAuthMfaChallenge(challengeId);
  const expiresAt = new Date(Date.now() + AUTH_MFA_CHALLENGE_TTL_MS).toISOString();
  let setupSecretEncrypted: string | null = null;
  let qrCodeUrl: string | null = null;

  if (params.purpose === 'setup') {
    const setupSecret = sanitizeString(params.setupSecret, 512) || generateSecret();
    setupSecretEncrypted = encryptJsonPayload({ secret: setupSecret });
    if (!setupSecretEncrypted) throw new Error('MFA_ENCRYPTION_UNAVAILABLE');
    const otpauth = generateURI({ issuer: 'Verto', label: params.email, secret: setupSecret });
    qrCodeUrl = await QRCode.toDataURL(otpauth);
  }

  const consumedAt = new Date().toISOString();
  const invalidateResult = await supabase
    .from('auth_mfa_challenges')
    .update({ consumed_at: consumedAt })
    .eq('user_id', params.userId)
    .is('consumed_at', null);
  if (invalidateResult.error) throw invalidateResult.error;

  const insertResult = await supabase
    .from('auth_mfa_challenges')
    .insert({
      challenge_hash: challengeHash,
      user_id: params.userId,
      purpose: params.purpose,
      setup_secret_encrypted: setupSecretEncrypted,
      attempts: 0,
      max_attempts: AUTH_MFA_MAX_ATTEMPTS,
      expires_at: expiresAt,
    })
    .select('id')
    .single();
  if (insertResult.error) throw insertResult.error;

  try {
    await regenerateExpressSession(params.req);
    params.req.session.mfaChallengeHash = challengeHash;
    params.req.session.mfaChallengeUserId = params.userId;
    params.req.session.mfaChallengeExpiresAt = expiresAt;
    await saveExpressSession(params.req);
  } catch (error) {
    await supabase
      .from('auth_mfa_challenges')
      .update({ consumed_at: new Date().toISOString() })
      .eq('challenge_hash', challengeHash)
      .is('consumed_at', null);
    throw error;
  }

  return {
    challengeId,
    expiresAt,
    purpose: params.purpose,
    qrCodeUrl,
  };
}

function pseudonymizeValue(value: string): string {
  const secret = (process.env.PSEUDONYMIZATION_KEY || process.env.SESSION_SECRET || '').trim();
  if (!secret) {
    throw new Error('PSEUDONYMIZATION_KEY (ou SESSION_SECRET em dev) deve estar definido.');
  }
  return crypto.createHmac('sha256', secret).update(value).digest('hex').slice(0, 24);
}

