  app.post('/api/auth/resend-confirmation', recoveryLimiter, async (req, res) => {
    try {
      const email = sanitizeEmail(req.body?.email);
      if (!email) return res.status(400).json({ error: 'E-mail inválido.' });
      const genericResponse = {
        success: true,
        message: 'Se este e-mail estiver cadastrado, você receberá instruções.'
      };

      const authUser = await findAuthUserByEmail(email);
      if (!authUser?.id) {
        await persistIdentityAuditLog({
          title: 'Reenvio de confirmação de e-mail solicitado',
          content: `Reenvio de confirmação solicitado para identificador não encontrado (${maskEmail(email)}).`,
          identifier: email,
          channel: 'email',
          request: req,
          status: 'not_found'
        });
        return res.json(genericResponse);
      }

      const { data: profile } = await supabase
        .from('users')
        .select('name, role')
        .eq('id', authUser.id)
        .maybeSingle();

      const activationLink =
        (await generateSupabaseActionLink({
          type: 'signup',
          email,
          redirectTo: getActivationRedirectUrl(profile?.role, email)
        })) || getActivationRedirectUrl(profile?.role, email);
      const activationEmail = buildActivationEmailTemplate({
        nome: sanitizeString(profile?.name || authUser.user_metadata?.full_name || email.split('@')[0], 180),
        link_ativacao: activationLink,
        perfil: resolveTemplateProfileByRole(profile?.role)
      });
      const emailSent = await sendTransactionalEmailSafe({
        to: email,
        subject: activationEmail.subject,
        html: activationEmail.html,
        context: 'resend_confirmation',
        from: resolveTemplateProfileByRole(profile?.role) === 'patient' ? OFFICIAL_FROM_NOREPLY : OFFICIAL_FROM_CONTACT,
        replyTo: OFFICIAL_TRANSACTIONAL_REPLY_TO,
        templateKind: resolveTemplateProfileByRole(profile?.role) === 'patient' ? 'welcome_patient' : 'welcome_professional',
        templateData: activationEmail.variables,
        metadata: {
          email: maskEmail(email),
          userId: authUser.id
        }
      });

      await persistIdentityAuditLog({
        title: 'Reenvio de confirmação de e-mail solicitado',
        content: `Reenvio de confirmação para ${maskEmail(email)} solicitado. E-mail oficial ${emailSent ? 'enviado' : 'com falha de envio'}.`,
        identifier: email,
        channel: 'email',
        userId: authUser.id,
        request: req,
        status: emailSent ? 'sent' : 'warning'
      });

      return res.json(genericResponse);
    } catch (error) {
      return res.json({
        success: true,
        message: 'Se este e-mail estiver cadastrado, você receberá instruções.'
      });
    }
  });

  app.post('/api/auth/patient-activation/password', authMfaLimiter, async (req, res) => {
    const token = sanitizeString(req.body?.token, 4096);
    const password = validateStrongPassword(req.body?.newPassword);
    if (!token || !password) {
      return res.status(400).json({
        success: false,
        error: 'PATIENT_ACTIVATION_INVALID',
        message: 'Link de ativação inválido ou senha fora da política de segurança.'
      });
    }

    let claims: PatientActivationTokenClaims | null = null;
    try {
      claims = verifyPatientActivationToken(token);
    } catch (error: any) {
      console.error('[Auth] patient activation signing unavailable:', {
        message: sanitizeString(error?.message || String(error), 180)
      });
      return res.status(503).json({
        success: false,
        error: 'PATIENT_ACTIVATION_UNAVAILABLE',
        message: 'A ativação está temporariamente indisponível. Tente novamente em alguns instantes.'
      });
    }

    if (!claims || !isUuid(claims.userId)) {
      return res.status(400).json({
        success: false,
        error: 'PATIENT_ACTIVATION_EXPIRED',
        message: 'Este link de ativação é inválido ou expirou. Solicite um novo link.'
      });
    }

    let leaseAcquired = false;
    const leaseKey = `patient-activate:${claims.userId}`;
    try {
      if (requiresDistributedRuntimeState()) {
        leaseAcquired = await tryAcquireDistributedJobLease({
          supabase,
          jobKey: leaseKey,
          ownerId: runtimeOwnerId,
          leaseSeconds: 30,
        });
        if (!leaseAcquired) {
          return res.status(409).json({
            success: false,
            error: 'PATIENT_ACTIVATION_IN_PROGRESS',
            message: 'Esta ativação já está sendo processada. Aguarde alguns instantes e tente novamente.'
          });
        }
      }

      const { data: authUserResult, error: authUserError } = await supabase.auth.admin.getUserById(claims.userId);
      const authUser = authUserResult?.user || null;
      if (authUserError || !authUser?.id) {
        return res.status(403).json({
          success: false,
          error: 'PATIENT_ACTIVATION_USER_NOT_FOUND',
          message: 'Não foi possível validar esta conta de paciente.'
        });
      }

      const profileResult = await fetchProfileWithSchemaFallback({
        supabase,
        userId: claims.userId,
        logger: console,
      });
      if (profileResult.error) throw profileResult.error;
      const profile = profileResult.data as any;
      const metadata: Record<string, any> = authUser.user_metadata && typeof authUser.user_metadata === 'object'
        ? { ...authUser.user_metadata }
        : {};
      if (!patientActivationIsPending(authUser, profile)) {
        return res.status(409).json({
          success: false,
          error: 'PATIENT_ACTIVATION_NOT_PENDING',
          message: 'Esta conta já foi ativada. Entre normalmente com seu e-mail e senha.'
        });
      }

      const metadataNonce = sanitizeString(metadata?.patient_activation_nonce, 200);
      const suppliedNonce = sanitizeString(claims.nonce, 200);
      const metadataNonceBuffer = Buffer.from(metadataNonce, 'utf8');
      const suppliedNonceBuffer = Buffer.from(suppliedNonce, 'utf8');
      const nonceMatches = Boolean(
        metadataNonce &&
        suppliedNonce &&
        metadataNonceBuffer.length === suppliedNonceBuffer.length &&
        crypto.timingSafeEqual(metadataNonceBuffer, suppliedNonceBuffer)
      );
      if (!nonceMatches) {
        return res.status(403).json({
          success: false,
          error: 'PATIENT_ACTIVATION_LINK_REPLACED',
          message: 'Este link foi substituído por um link de ativação mais recente. Abra o último e-mail recebido.'
        });
      }

      const email = sanitizeEmail(authUser.email);
      if (!email) {
        return res.status(403).json({
          success: false,
          error: 'PATIENT_ACTIVATION_EMAIL_MISSING',
          message: 'Não foi possível validar o e-mail desta conta.'
        });
      }

      delete metadata.patient_activation_nonce;
      await invalidateAllActiveSessions(claims.userId);
      const { error: updateAuthError } = await supabase.auth.admin.updateUserById(claims.userId, {
        password,
        email_confirm: true,
        user_metadata: {
          ...metadata,
          patient_activation_required: false,
          first_login_completed: true,
        },
      });
      if (updateAuthError) throw updateAuthError;
      await invalidateAllActiveSessions(claims.userId);

      const profileUpdate = await updateRowsWithSchemaFallback({
        tableName: 'users',
        payload: {
          status: 'active',
          first_login_completed: true,
          updated_at: new Date().toISOString(),
        },
        filters: [{ column: 'id', value: claims.userId }],
        context: 'patient-activation-password-profile',
      });
      if (!profileUpdate.success) throw profileUpdate.error;

      await persistIdentityAuditLog({
        title: 'Conta de paciente ativada por link seguro',
        content: `Paciente ${maskEmail(email)} definiu a senha e concluiu a ativação da identidade.`,
        identifier: email,
        channel: 'email',
        userId: claims.userId,
        request: req,
        status: 'success'
      });

      return res.json({
        success: true,
        loginEmail: email,
      });
    } catch (error: any) {
      console.error('[Auth] patient activation password failed:', {
        userId: sanitizeString(claims?.userId, 120),
        message: sanitizeString(error?.message || String(error), 240)
      });
      return res.status(500).json({
        success: false,
        error: 'PATIENT_ACTIVATION_FAILED',
        message: 'Não foi possível concluir a ativação agora. Tente novamente.'
      });
    } finally {
      if (leaseAcquired) {
        try {
          await releaseDistributedJobLease({
            supabase,
            jobKey: leaseKey,
            ownerId: runtimeOwnerId,
          });
        } catch (releaseError: any) {
          console.warn('[Auth] patient activation lease release failed:', {
            userId: sanitizeString(claims?.userId, 120),
            message: sanitizeString(releaseError?.message || String(releaseError), 180)
          });
        }
      }
    }
  });

  app.post('/api/auth/invitation/password', authMfaLimiter, async (req, res) => {
    const token = sanitizeString(req.body?.token, 4096);
    const password = validateStrongPassword(req.body?.newPassword);
    if (!token || !password) {
      return res.status(400).json({
        success: false,
        error: 'CLINIC_INVITATION_ACTIVATION_INVALID',
        message: 'Link de ativação inválido ou senha fora da política de segurança.'
      });
    }

    let claims: ReturnType<typeof verifyClinicInvitationActivationToken> = null;
    try {
      claims = verifyClinicInvitationActivationToken({
        token,
        signingSecret: clinicInvitationActivationSigningSecret(),
      });
    } catch (error: any) {
      console.error('[Auth] clinic invitation activation signing unavailable:', {
        message: sanitizeString(error?.message || String(error), 180)
      });
      return res.status(503).json({
        success: false,
        error: 'CLINIC_INVITATION_ACTIVATION_UNAVAILABLE',
        message: 'A ativação está temporariamente indisponível. Tente novamente em alguns instantes.'
      });
    }

    if (!claims || !isUuid(claims.invitationId) || !isUuid(claims.userId)) {
      return res.status(400).json({
        success: false,
        error: 'CLINIC_INVITATION_ACTIVATION_EXPIRED',
        message: 'Este link de ativação é inválido ou expirou. Solicite um novo convite.'
      });
    }

    let leaseAcquired = false;
    const leaseKey = `clinic-invite-activate:${claims.invitationId}`;
    try {
      if (requiresDistributedRuntimeState()) {
        leaseAcquired = await tryAcquireDistributedJobLease({
          supabase,
          jobKey: leaseKey,
          ownerId: runtimeOwnerId,
          leaseSeconds: 30,
        });
        if (!leaseAcquired) {
          return res.status(409).json({
            success: false,
            error: 'CLINIC_INVITATION_ACTIVATION_IN_PROGRESS',
            message: 'Esta ativação já está sendo processada. Aguarde alguns instantes e tente novamente.'
          });
        }
      }

      const { data: invitation, error: invitationError } = await supabase
        .from('invitations')
        .select('id,email,status')
        .eq('id', claims.invitationId)
        .limit(1)
        .maybeSingle();
      if (invitationError) throw invitationError;

      const invitationEmail = sanitizeEmail(invitation?.email);
      const invitationStatus = sanitizeString(invitation?.status, 40).toLowerCase();
      if (!invitation || !invitationEmail || invitationStatus !== 'pending') {
        return res.status(409).json({
          success: false,
          error: 'CLINIC_INVITATION_NOT_AVAILABLE',
          message: 'Este convite expirou, foi cancelado ou já foi utilizado.'
        });
      }

      const { data: authUserResult, error: authUserError } = await supabase.auth.admin.getUserById(claims.userId);
      const authUser = authUserResult?.user || null;
      if (authUserError || !authUser?.id) {
        return res.status(403).json({
          success: false,
          error: 'CLINIC_INVITATION_AUTH_USER_NOT_FOUND',
          message: 'Não foi possível validar a conta deste convite.'
        });
      }

      const authEmail = sanitizeEmail(authUser.email);
      const metadata: Record<string, any> = authUser.user_metadata && typeof authUser.user_metadata === 'object'
        ? { ...authUser.user_metadata }
        : {};
      const metadataInvitationId = sanitizeString(
        metadata?.invitation_id || metadata?.clinic_invitation_id,
        120
      );
      const metadataNonce = sanitizeString(metadata?.invitation_activation_nonce, 200);
      const suppliedNonce = sanitizeString(claims.nonce, 200);
      const metadataNonceBuffer = Buffer.from(metadataNonce, 'utf8');
      const suppliedNonceBuffer = Buffer.from(suppliedNonce, 'utf8');
      const nonceMatches = Boolean(
        metadataNonce &&
        suppliedNonce &&
        metadataNonceBuffer.length === suppliedNonceBuffer.length &&
        crypto.timingSafeEqual(metadataNonceBuffer, suppliedNonceBuffer)
      );

      if (
        authEmail !== invitationEmail ||
        metadataInvitationId !== claims.invitationId ||
        !nonceMatches
      ) {
        return res.status(403).json({
          success: false,
          error: 'CLINIC_INVITATION_ACTIVATION_MISMATCH',
          message: 'Este link não corresponde mais ao convite ativo. Solicite um novo convite.'
        });
      }

      delete metadata.invitation_activation_nonce;
      const { error: updateUserError } = await supabase.auth.admin.updateUserById(
        claims.userId,
        {
          password,
          email_confirm: true,
          user_metadata: metadata,
        }
      );
      if (updateUserError) throw updateUserError;

      await persistIdentityAuditLog({
        title: 'Senha definida por convite de clínica',
        content: `Conta ${maskEmail(invitationEmail)} confirmou o link seguro de convite e definiu a senha.`,
        identifier: invitationEmail,
        channel: 'email',
        userId: claims.userId,
        request: req,
        status: 'success'
      });

      return res.json({
        success: true,
        loginEmail: invitationEmail,
        invitationId: claims.invitationId,
      });
    } catch (error: any) {
      console.error('[Auth] clinic invitation password activation failed:', {
        invitationId: sanitizeString(claims?.invitationId, 120),
        message: sanitizeString(error?.message || String(error), 240)
      });
      return res.status(500).json({
        success: false,
        error: 'CLINIC_INVITATION_ACTIVATION_FAILED',
        message: 'Não foi possível concluir a ativação agora. Tente novamente.'
      });
    } finally {
      if (leaseAcquired) {
        try {
          await releaseDistributedJobLease({
            supabase,
            jobKey: leaseKey,
            ownerId: runtimeOwnerId,
          });
        } catch (releaseError: any) {
          console.warn('[Auth] clinic invitation activation lease release failed:', {
            invitationId: sanitizeString(claims?.invitationId, 120),
            message: sanitizeString(releaseError?.message || String(releaseError), 180)
          });
        }
      }
    }
  });

  app.post('/api/auth/activation/bootstrap', recoveryLimiter, async (req, res) => {
    const genericResponse = {
      success: true,
      message: 'Se esta conta estiver pendente, você receberá um novo link de ativação por e-mail.'
    };
    try {
      const email = sanitizeEmail(req.body?.email);
      if (!email) return res.json(genericResponse);

      const authUser = await findAuthUserByEmail(email);
      if (!authUser?.id) return res.json(genericResponse);
      const profileResult = await fetchProfileWithSchemaFallback({
        supabase,
        userId: authUser.id,
        logger: console,
      });
      if (profileResult.error) throw profileResult.error;
      const profile = profileResult.data as any;
      const authMetadata: Record<string, any> = (authUser as any)?.user_metadata && typeof (authUser as any).user_metadata === 'object'
        ? { ...(authUser as any).user_metadata }
        : {};
      const persistedRole = sanitizeString(
        profile?.role || authMetadata?.invited_role || authMetadata?.role,
        40
      );
      const templateProfile = resolveTemplateProfileByRole(persistedRole);
      const isAlreadyConfirmed = Boolean(
        (authUser as any)?.email_confirmed_at || (authUser as any)?.confirmed_at,
      );
      const pendingPatientActivation = patientActivationIsPending(authUser, profile);
      if (isAlreadyConfirmed && !pendingPatientActivation) return res.json(genericResponse);
      const metadataInvitationId = sanitizeString(
        authMetadata?.invitation_id || authMetadata?.clinic_invitation_id,
        120
      );
      let activationLink: string | null = null;

      if (pendingPatientActivation) {
        activationLink = await createPatientActivationLink(authUser);
      } else if (isUuid(metadataInvitationId)) {
        const { data: pendingInvitation, error: pendingInvitationError } = await supabase
          .from('invitations')
          .select('id,email,status')
          .eq('id', metadataInvitationId)
          .eq('status', 'pending')
          .limit(1)
          .maybeSingle();
        if (pendingInvitationError) throw pendingInvitationError;

        if (
          pendingInvitation?.id &&
          sanitizeEmail(pendingInvitation.email) === email
        ) {
          const invitationActivationNonce = crypto.randomBytes(32).toString('base64url');
          const { error: updateActivationNonceError } = await supabase.auth.admin.updateUserById(
            authUser.id,
            {
              user_metadata: {
                ...authMetadata,
                invitation_activation_nonce: invitationActivationNonce,
              }
            }
          );
          if (updateActivationNonceError) throw updateActivationNonceError;
          activationLink = getClinicInvitationActivationUrl({
            invitationId: pendingInvitation.id,
            userId: authUser.id,
            email,
            nonce: invitationActivationNonce,
          });
        }
      }

      if (!activationLink) {
        const activationLinkFromSignup = await generateSupabaseActionLink({
          type: 'signup',
          email,
          redirectTo: getActivationRedirectUrl(persistedRole, email),
        });
        activationLink =
          activationLinkFromSignup ||
          (await generateSupabaseActionLink({
            type: 'recovery',
            email,
            redirectTo: getActivationRedirectUrl(persistedRole, email),
          }));
      }

      if (activationLink) {
        const activationEmail = buildActivationEmailTemplate({
          nome: sanitizeString(
            profile?.name || (authUser as any)?.user_metadata?.full_name || email.split('@')[0],
            180
          ),
          link_ativacao: activationLink,
          perfil: templateProfile
        });
        const emailSent = await sendTransactionalEmailSafe({
          to: email,
          subject: activationEmail.subject,
          html: activationEmail.html,
          context: 'activation_bootstrap_resend',
          from: templateProfile === 'patient' ? OFFICIAL_FROM_NOREPLY : OFFICIAL_FROM_CONTACT,
          replyTo: OFFICIAL_TRANSACTIONAL_REPLY_TO,
          templateKind: templateProfile === 'patient' ? 'welcome_patient' : 'welcome_professional',
          templateData: activationEmail.variables,
          metadata: {
            userId: authUser.id,
            email: maskEmail(email)
          }
        });
        await persistIdentityAuditLog({
          title: 'Novo link de ativação solicitado',
          content: `Reenvio de ativação para ${maskEmail(email)} ${emailSent ? 'encaminhado' : 'não concluído'}.`,
          identifier: email,
          channel: 'email',
          userId: authUser.id,
          request: req,
          status: emailSent ? 'sent' : 'warning'
        });
      }

      return res.json(genericResponse);
    } catch (error: any) {
      console.warn('[Auth] activation bootstrap could not resend email:', {
        message: sanitizeString(error?.message || String(error), 180)
      });
      return res.json(genericResponse);
    }
  });

