  app.get('/api/clinic/anamnesis-template/defaults', checkAuth, requireClinicCapability('clinical.anamnesis.view'), async (_req: any, res) => {
    return res.json({ success: true, data: getDefaultAnamnesisTemplate() });
  });

  app.get('/api/clinic/anamnesis-templates', checkAuth, requireClinicCapability('clinical.anamnesis.view'), async (req: any, res) => {
    try {
      const clinicId = currentClinicId(req.session.user);
      const actorId = sanitizeString(req.session.user?.id, 120);
      if (!isUuid(clinicId) || !isUuid(actorId)) {
        return res.json({ success: true, data: [] });
      }

      const [globalResult, clinicResult, personalResult] = await Promise.all([
        supabase
          .from('anamnesis_templates')
          .select(ANAMNESIS_TEMPLATE_SELECT)
          .eq('scope', 'global')
          .eq('is_active', true)
          .order('updated_at', { ascending: false })
          .limit(20),
        supabase
          .from('anamnesis_templates')
          .select(ANAMNESIS_TEMPLATE_SELECT)
          .eq('scope', 'clinic')
          .eq('organization_id', clinicId)
          .eq('is_active', true)
          .order('updated_at', { ascending: false })
          .limit(10),
        supabase
          .from('anamnesis_templates')
          .select(ANAMNESIS_TEMPLATE_SELECT)
          .eq('scope', 'personal')
          .eq('owner_user_id', actorId)
          .eq('is_active', true)
          .order('updated_at', { ascending: false })
          .limit(15)
      ]);

      const firstError = globalResult.error || clinicResult.error || personalResult.error;
      if (firstError) {
        if (isMissingRelationError(firstError) || extractMissingColumnName(firstError)) {
          return res.status(503).json({
            success: false,
            error: 'PROFESSIONAL_PORTABLE_TEMPLATES_MIGRATION_REQUIRED',
            message: 'A estrutura de fichas profissionais portáteis precisa ser aplicada.'
          });
        }
        throw firstError;
      }

      const rows = [
        ...(personalResult.data || []),
        ...(clinicResult.data || []),
        ...(globalResult.data || [])
      ];
      const uniqueRows = Array.from(new Map(rows.map((row: any) => [sanitizeString(row?.id, 120), row])).values());

      return res.json({
        success: true,
        data: uniqueRows.map(mapAnamnesisTemplateRowForEditor),
        meta: {
          personalCount: (personalResult.data || []).length,
          clinicCount: (clinicResult.data || []).length,
          globalCount: (globalResult.data || []).length,
          personalLimit: 15,
          clinicLimit: 10,
          portablePersonalTemplates: true
        }
      });
    } catch (error) {
      return sendRouteDbError(res, '/api/clinic/anamnesis-templates [GET]', error, {
        clinicId: sanitizeString(currentClinicId(req.session.user), 120),
        requestId: requestIdForLogs(req)
      });
    }
  });

  app.post('/api/clinic/anamnesis-templates', checkAuth, requireClinicCapability('clinical.anamnesis.edit'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 96 * 1024, 'Ficha de anamnese')) return;
      const clinicId = currentClinicId(req.session.user);
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorRole = sanitizeString(req.effectiveClinicRole || req.session.user?.role, 40).toLowerCase();
      if (!isUuid(clinicId) || !isUuid(actorId)) {
        return res.status(400).json({ success: false, error: 'Identidade profissional ou clínica inválida.' });
      }

      const canManageClinicTemplates = ['director', 'coordinator'].includes(actorRole);
      const incomingTemplate = req.body?.template && typeof req.body.template === 'object' ? req.body.template : {};
      const requestedScope = sanitizeString(
        incomingTemplate?.templateScope || incomingTemplate?.scope || req.body?.templateScope || req.body?.scope,
        20
      ).toLowerCase();
      const templateScope = canManageClinicTemplates && requestedScope === 'clinic' ? 'clinic' : 'personal';
      const organizationId = templateScope === 'personal' ? actorId : clinicId;
      const ownerUserId = templateScope === 'personal' ? actorId : null;
      const visibility = templateScope === 'personal' ? 'private' : 'clinic';
      const maxActiveTemplates = templateScope === 'personal' ? 15 : 10;

      const templateId = sanitizeString(incomingTemplate?.selectedTemplateId || incomingTemplate?.id || req.body?.templateId, 120);
      const name = sanitizeString(incomingTemplate?.templateName || incomingTemplate?.name, 180);
      if (!name) {
        return res.status(400).json({ success: false, error: 'Informe um nome para a ficha.' });
      }

      let existingTemplate: any = null;
      if (isUuid(templateId)) {
        let existingTemplateQuery = supabase
          .from('anamnesis_templates')
          .select(ANAMNESIS_TEMPLATE_SELECT)
          .eq('id', templateId)
          .eq('scope', templateScope);
        existingTemplateQuery = templateScope === 'personal'
          ? existingTemplateQuery.eq('owner_user_id', actorId)
          : existingTemplateQuery.eq('organization_id', clinicId);
        const existingTemplateResult = await existingTemplateQuery.maybeSingle();
        if (existingTemplateResult.error) {
          if (isMissingRelationError(existingTemplateResult.error) || extractMissingColumnName(existingTemplateResult.error)) {
            return res.status(503).json({
              success: false,
              error: 'PROFESSIONAL_PORTABLE_TEMPLATES_MIGRATION_REQUIRED',
              message: 'A estrutura de fichas profissionais portáteis precisa ser aplicada.'
            });
          }
          throw existingTemplateResult.error;
        }
        existingTemplate = existingTemplateResult.data || null;
      }

      let activeCountQuery = supabase
        .from('anamnesis_templates')
        .select('id')
        .eq('scope', templateScope)
        .eq('is_active', true)
        .limit(maxActiveTemplates + 1);
      activeCountQuery = templateScope === 'personal'
        ? activeCountQuery.eq('owner_user_id', actorId)
        : activeCountQuery.eq('organization_id', clinicId);
      const activeCountResult = await activeCountQuery;
      if (activeCountResult.error) {
        if (isMissingRelationError(activeCountResult.error) || extractMissingColumnName(activeCountResult.error)) {
          return res.status(503).json({
            success: false,
            error: 'PROFESSIONAL_PORTABLE_TEMPLATES_MIGRATION_REQUIRED',
            message: 'A estrutura de fichas profissionais portáteis precisa ser aplicada.'
          });
        }
        throw activeCountResult.error;
      }

      const activeRows = Array.isArray(activeCountResult.data) ? activeCountResult.data : [];
      const isUpdatingExisting = Boolean(existingTemplate?.id);
      const consumesNewActiveSlot = !isUpdatingExisting || existingTemplate?.is_active === false;
      if (consumesNewActiveSlot && activeRows.length >= maxActiveTemplates) {
        return res.status(409).json({
          success: false,
          code: templateScope === 'personal' ? 'ANAMNESIS_PERSONAL_TEMPLATE_LIMIT' : 'ANAMNESIS_CLINIC_TEMPLATE_LIMIT',
          error: templateScope === 'personal'
            ? 'Limite de 15 fichas profissionais salvas atingido.'
            : 'Limite de 10 fichas da clínica atingido.'
        });
      }

      const nextTemplate = sanitizeAnamnesisTemplate(incomingTemplate);
      nextTemplate.version = isUpdatingExisting
        ? Math.max(1, Number(existingTemplate?.revision || existingTemplate?.questions?.version || 1)) + 1
        : 1;
      const commonPayload = cleanObject({
        organization_id: organizationId,
        scope: templateScope,
        owner_user_id: ownerUserId,
        visibility,
        name,
        description: sanitizeString(incomingTemplate?.templateDescription || incomingTemplate?.description, 500) || null,
        age_min_months: normalizeAnamnesisTemplateAgeMonth(incomingTemplate?.ageMinMonths ?? incomingTemplate?.age_min_months),
        age_max_months: normalizeAnamnesisTemplateAgeMonth(incomingTemplate?.ageMaxMonths ?? incomingTemplate?.age_max_months),
        patient_profile_type: normalizeAnamnesisPatientProfileType(incomingTemplate?.patientProfileType || incomingTemplate?.patient_profile_type),
        questions: nextTemplate,
        is_default: false,
        is_active: true,
        updated_at: new Date().toISOString()
      });

      let savedRow: any = null;
      if (isUuid(templateId)) {
        let updateQuery = supabase
          .from('anamnesis_templates')
          .update(commonPayload)
          .eq('id', templateId)
          .eq('scope', templateScope);
        updateQuery = templateScope === 'personal'
          ? updateQuery.eq('owner_user_id', actorId)
          : updateQuery.eq('organization_id', clinicId);
        const { data, error } = await updateQuery
          .select(ANAMNESIS_TEMPLATE_SELECT)
          .maybeSingle();
        if (error) throw error;
        if (!data?.id) {
          return res.status(404).json({ success: false, error: 'Ficha não encontrada para atualização.' });
        }
        savedRow = data;
      } else {
        const { data, error } = await supabase
          .from('anamnesis_templates')
          .insert([{ ...commonPayload, created_by: actorId }])
          .select(ANAMNESIS_TEMPLATE_SELECT)
          .maybeSingle();
        if (error) throw error;
        savedRow = data;
      }

      if (!savedRow?.id || savedRow?.is_active === false) {
        return res.status(500).json({ success: false, error: 'Não foi possível confirmar a persistência da ficha.' });
      }
      if (templateScope === 'personal' && sanitizeString(savedRow?.owner_user_id, 120) !== actorId) {
        return res.status(500).json({ success: false, error: 'A ficha profissional não foi associada à identidade correta.' });
      }
      if (templateScope === 'clinic' && sanitizeString(savedRow?.organization_id, 120) !== clinicId) {
        return res.status(500).json({ success: false, error: 'A ficha não foi associada à clínica correta.' });
      }

      const savedEditorTemplate = mapAnamnesisTemplateRowForEditor(savedRow);
      const previousEditorTemplate = existingTemplate ? mapAnamnesisTemplateRowForEditor(existingTemplate) : null;
      const templateChanges: string[] = [];
      if (!previousEditorTemplate) {
        const profile = savedEditorTemplate?.profiles?.[savedEditorTemplate?.profileType === 'child' ? 'child' : 'adult'];
        templateChanges.push(`Ficha criada com ${(profile?.sections || []).length} seção(ões) e ${(profile?.questions || []).length} pergunta(s).`);
      } else {
        if (previousEditorTemplate.templateName !== savedEditorTemplate.templateName) {
          templateChanges.push(`Nome: "${previousEditorTemplate.templateName}" -> "${savedEditorTemplate.templateName}"`);
        }
        if ((previousEditorTemplate.templateDescription || '') !== (savedEditorTemplate.templateDescription || '')) {
          templateChanges.push('Descrição interna alterada.');
        }
        if (previousEditorTemplate.ageMinMonths !== savedEditorTemplate.ageMinMonths || previousEditorTemplate.ageMaxMonths !== savedEditorTemplate.ageMaxMonths) {
          templateChanges.push(`Faixa etária alterada para ${savedEditorTemplate.ageMinMonths ?? 'sem mínimo'}–${savedEditorTemplate.ageMaxMonths ?? 'sem máximo'} meses.`);
        }
        if ((previousEditorTemplate.patientProfileType || '') !== (savedEditorTemplate.patientProfileType || '')) {
          templateChanges.push(`Perfil alterado para ${savedEditorTemplate.patientProfileType || 'todos'}.`);
        }
        templateChanges.push(...listAnamnesisTemplateChanges(previousEditorTemplate, savedEditorTemplate));
      }
      const uniqueChanges = Array.from(new Set(templateChanges)).slice(0, 40);
      const visibleChanges = uniqueChanges.slice(0, 6);
      const extraChanges = Math.max(0, uniqueChanges.length - visibleChanges.length);
      const auditAction = previousEditorTemplate ? 'anamnesis_template_updated' : 'anamnesis_template_created';
      await persistActivityLog({
        userId: actorId,
        clinicId,
        actorName: sanitizeString(req.session.user?.name || req.session.user?.email || 'Usuário', 180),
        title: previousEditorTemplate
          ? (templateScope === 'personal' ? 'Ficha profissional editada' : 'Ficha da clínica editada')
          : (templateScope === 'personal' ? 'Ficha profissional criada' : 'Ficha da clínica criada'),
        content: `${name}: ${visibleChanges.join(' · ')}${extraChanges > 0 ? ` · +${extraChanges} alteração(ões)` : ''}`,
        type: 'audit',
        action: auditAction,
        actionType: auditAction,
        payloadDetails: JSON.stringify({
          templateId: sanitizeString(savedRow?.id, 120),
          scope: templateScope,
          revision: Number(savedRow?.revision || savedEditorTemplate?.templateRevision || 1),
          changes: uniqueChanges
        }),
        resourceType: 'anamnesis_template',
        resourceId: sanitizeString(savedRow?.id, 120),
        timezone: currentClinicTimeZone(req.session.user),
        immutableAudit: true
      });

      return res.json({ success: true, data: mapAnamnesisTemplateRowForEditor(savedRow) });
    } catch (error: any) {
      const templateLimitError = sanitizeString(error?.message || error?.details || error?.hint, 240);
      if (templateLimitError.includes('ANAMNESIS_PERSONAL_TEMPLATE_LIMIT')) {
        return res.status(409).json({
          success: false,
          code: 'ANAMNESIS_PERSONAL_TEMPLATE_LIMIT',
          error: 'Limite de 15 fichas profissionais salvas atingido.'
        });
      }
      if (templateLimitError.includes('ANAMNESIS_CLINIC_TEMPLATE_LIMIT')) {
        return res.status(409).json({
          success: false,
          code: 'ANAMNESIS_CLINIC_TEMPLATE_LIMIT',
          error: 'Limite de 10 fichas da clínica atingido.'
        });
      }
      if (isMissingRelationError(error) || extractMissingColumnName(error)) {
        return res.status(503).json({
          success: false,
          error: 'PROFESSIONAL_PORTABLE_TEMPLATES_MIGRATION_REQUIRED',
          message: 'A estrutura de fichas profissionais portáteis precisa ser aplicada.'
        });
      }
      return sendRouteDbError(res, '/api/clinic/anamnesis-templates [POST]', error, {
        clinicId: sanitizeString(currentClinicId(req.session.user), 120),
        requestId: requestIdForLogs(req)
      });
    }
  });

  app.delete('/api/clinic/anamnesis-templates/:templateId', checkAuth, requireClinicCapability('clinical.anamnesis.edit'), async (req: any, res) => {
    try {
      const clinicId = currentClinicId(req.session.user);
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorRole = sanitizeString(req.effectiveClinicRole || req.session.user?.role, 40).toLowerCase();
      const templateId = sanitizeString(req.params?.templateId, 120);
      if (!isUuid(clinicId) || !isUuid(actorId) || !isUuid(templateId)) {
        return res.status(400).json({ success: false, error: 'Ficha inválida.' });
      }

      const { data: existing, error: existingError } = await supabase
        .from('anamnesis_templates')
        .select('id,organization_id,scope,owner_user_id,name')
        .eq('id', templateId)
        .maybeSingle();
      if (existingError) throw existingError;
      if (!existing?.id) return res.status(404).json({ success: false, error: 'Ficha não encontrada.' });

      const scope = sanitizeString(existing.scope, 20) || (existing.owner_user_id ? 'personal' : 'clinic');
      const canArchive = scope === 'personal'
        ? sanitizeString(existing.owner_user_id, 120) === actorId
        : ['director', 'coordinator'].includes(actorRole) && sanitizeString(existing.organization_id, 120) === clinicId;
      if (!canArchive) {
        return res.status(403).json({ success: false, error: 'Sem permissão para arquivar esta ficha.' });
      }

      const { data, error } = await supabase
        .from('anamnesis_templates')
        .update({ is_active: false, updated_at: new Date().toISOString() })
        .eq('id', templateId)
        .select('id')
        .maybeSingle();
      if (error) throw error;
      if (!data?.id) return res.status(404).json({ success: false, error: 'Ficha não encontrada.' });

      await persistActivityLog({
        userId: actorId,
        clinicId,
        actorName: sanitizeString(req.session.user?.name || req.session.user?.email || 'Usuário', 180),
        title: scope === 'personal' ? 'Ficha profissional arquivada' : 'Ficha de anamnese da clínica arquivada',
        content: `A ficha "${sanitizeString(existing.name, 180) || 'sem nome'}" foi removida da lista ativa.`,
        type: 'audit',
        action: 'anamnesis_template_archived',
        actionType: 'anamnesis_template_archived',
        resourceType: 'anamnesis_template',
        resourceId: templateId,
        timezone: currentClinicTimeZone(req.session.user),
        immutableAudit: true
      });

      return res.json({ success: true });
    } catch (error: any) {
      if (isMissingRelationError(error) || extractMissingColumnName(error)) {
        return res.status(503).json({
          success: false,
          error: 'PROFESSIONAL_PORTABLE_TEMPLATES_MIGRATION_REQUIRED',
          message: 'A estrutura de fichas profissionais portáteis precisa ser aplicada.'
        });
      }
      return sendRouteDbError(res, '/api/clinic/anamnesis-templates/:templateId [DELETE]', error, {
        clinicId: sanitizeString(currentClinicId(req.session.user), 120),
        requestId: requestIdForLogs(req)
      });
    }
  });

  app.post('/api/clinic/anamnesis-template', checkAuth, requireClinicCapability('clinic.settings.edit'), async (req: any, res) => {
    try {
      const clinicId = currentClinicId(req.session.user);
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorName = sanitizeString(req.session.user?.name || req.session.user?.email || 'Usuário', 180);

      const previousResult = await supabase
        .from('clinic_anamnesis_templates')
        .select('template_json')
        .eq('clinic_id', clinicId)
        .maybeSingle();
      const previousTemplate = sanitizeAnamnesisTemplate(previousResult?.data?.template_json || getDefaultAnamnesisTemplate());
      const nextTemplate = sanitizeAnamnesisTemplate(req.body?.template || {});
      nextTemplate.version = Math.max(1, Number(previousTemplate?.version || 0) + 1);
      const templateChanges = listAnamnesisTemplateChanges(previousTemplate, nextTemplate);

      const payload = {
        clinic_id: clinicId,
        template_json: nextTemplate,
        updated_by: actorId,
        updated_at: new Date().toISOString()
      };

      const { error } = await supabase
        .from('clinic_anamnesis_templates')
        .upsert([payload], { onConflict: 'clinic_id' });

      if (error) {
        if (String(error?.message || '').toLowerCase().includes('clinic_anamnesis_templates')) {
          return res.status(200).json({
            success: false,
            warning: 'Tabela clinic_anamnesis_templates não existe. Rode o SQL de foundation.'
          });
        }
        throw error;
      }

      if (actorId) {
        for (const item of templateChanges.length > 0 ? templateChanges : ['Template de anamnese publicado sem alterações detectadas.']) {
          await persistActivityLog({
            userId: actorId,
            clinicId,
            actorName,
            title: 'Template de anamnese atualizado',
            content: item,
            type: 'audit',
            action: 'anamnesis_template_updated',
            actionType: 'anamnesis_template_updated',
            resourceType: 'clinic_anamnesis_template',
            resourceId: sanitizeString(clinicId, 120),
            timezone: currentClinicTimeZone(req.session.user),
            immutableAudit: true
          });
        }
      }

      return res.json({ success: true, data: nextTemplate });
    } catch (error) {
      return res.status(500).json({ error: 'Erro interno do servidor.' });
    }
  });

  app.get('/api/clinic/state', checkAuth, requireAnyClinicCapability('clinic.view', 'calendar.own.view', 'calendar.team.view', 'calendar.clinic.view', 'aba.program.view'), async (req: any, res) => {
    try {
      const clinicId = currentClinicId(req.session.user);
      const context = req.authorizationContext as ResolvedClinicCapabilityContext;
      const canViewAppointments =
        context.capabilities.has('calendar.clinic.view') ||
        context.capabilities.has('calendar.team.view') ||
        context.capabilities.has('calendar.own.view');
      const canViewProtocols = context.capabilities.has('aba.program.view');
      const canViewRooms = canViewAppointments || context.capabilities.has('clinic.rooms.manage');
      const canViewSpecialtySettings = context.capabilities.has('clinic.settings.view');
      const scopedPatientIds = canViewAppointments
        ? await resolvePatientListScopedPatientIds(context)
        : [];
      const scopedPatientSet = scopedPatientIds === null ? null : new Set(scopedPatientIds);
      const stateResult = await fetchClinicStateWithSchemaFallback({
        supabase,
        clinicId,
        logger: console
      });
      let data = stateResult.data;
      const error = stateResult.error;

      if (error) {
        if (String(error?.message || '').toLowerCase().includes('clinic_state')) {
          return res.json({
            success: true,
            data: {
              clinicId,
              rooms: [],
              appointments: [],
              protocols: [],
              specialtySettings: {},
              updatedAt: null
            },
            warning: 'Tabela clinic_state não criada.'
          });
        }
        throw error;
      }

      if (isUuid(clinicId)) {
        try {
          const { missingApprovedProtocolKeys } = await findMissingApprovedProtocolKeysForClinicState(
            clinicId,
            normalizeProtocolArrayForRoute(data?.protocols)
          );
          if (missingApprovedProtocolKeys.length > 0) {
            await syncApprovedProtocolsToClinicState({
              clinicId,
              performedBy: sanitizeString(req.session.user?.id, 120),
              actorName: sanitizeString(req.session.user?.name || req.session.user?.email || 'Sistema Verto', 180),
              auditAction: 'restore_clinic_protocols_from_import_requests'
            });
            const refreshedState = await fetchClinicStateWithSchemaFallback({
              supabase,
              clinicId,
              logger: console
            });
            if (!refreshedState.error && refreshedState.data) data = refreshedState.data;
          }
        } catch (syncError: any) {
          console.warn('[Protocol Sync] Nao foi possivel restaurar protocolos aprovados durante GET /api/clinic/state:', {
            clinicId,
            message: syncError?.message || String(syncError)
          });
        }
      }

      const sourceAppointments = Array.isArray(data?.appointments) ? data.appointments : [];
      const scopedAppointments = !canViewAppointments
        ? []
        : scopedPatientSet === null
          ? sourceAppointments
          : sourceAppointments.filter((appointment: any) => {
              const patientId = sanitizeString(
                appointment?.patient_id || appointment?.patientId || appointment?.patient?.id,
                120
              );
              return patientId && scopedPatientSet.has(patientId);
            });

      return res.json({
        success: true,
        data: {
          clinicId,
          rooms: canViewRooms && Array.isArray(data?.rooms) ? data.rooms : [],
          appointments: scopedAppointments,
          protocols: canViewProtocols ? normalizeProtocolArrayForRoute(data?.protocols) : [],
          specialtySettings:
            canViewSpecialtySettings && data?.specialty_settings && typeof data.specialty_settings === 'object'
              ? data.specialty_settings
              : {},
          updatedAt: data?.updated_at || null,
          revision: Number(data?.revision || 0) || 0,
          sectionVersions:
            data?.section_versions && typeof data.section_versions === 'object'
              ? data.section_versions
              : {}
        }
      });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/clinic/state [GET]', error, {
        clinicId: sanitizeString(currentClinicId(req.session.user), 120),
        requestId: requestIdForLogs(req)
      });
    }
  });

  app.post('/api/clinic/protocols/reusable-adult', checkAuth, requireClinicCapability('clinical.evolution.create'), async (req: any, res) => {
    try {
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const actorId = sanitizeString(req.session.user?.id, 120);
      if (!isUuid(clinicId)) {
        return res.status(400).json({ success: false, error: 'CLINIC_SCOPE_INVALID', message: 'Clínica inválida para salvar o protocolo.' });
      }

      const operation = sanitizeString(req.body?.operation, 40).toLowerCase();
      if (!['create_protocol', 'append_skill'].includes(operation)) {
        return res.status(400).json({ success: false, error: 'REUSABLE_PROTOCOL_OPERATION_INVALID', message: 'Operação de protocolo inválida.' });
      }

      const requestedCategory = sanitizeString(req.body?.category, 40).toLowerCase();
      const category = requestedCategory === 'intervention' ? 'intervention' : requestedCategory === 'evaluation' ? 'evaluation' : '';
      if (!category) {
        return res.status(400).json({ success: false, error: 'REUSABLE_PROTOCOL_CATEGORY_INVALID', message: 'Informe se o protocolo é de avaliação ou intervenção.' });
      }

      const rawSkill = req.body?.skill && typeof req.body.skill === 'object' ? req.body.skill : {};
      const skillName = sanitizeTextField(rawSkill?.name || rawSkill?.title, 240);
      if (!skillName) {
        return res.status(400).json({ success: false, error: 'REUSABLE_PROTOCOL_SKILL_REQUIRED', message: 'Informe o nome da tarefa antes de salvar o protocolo.' });
      }
      const skillId = sanitizeString(rawSkill?.id, 120) || crypto.randomUUID();
      const rawMaxScore = Number(rawSkill?.maxScore ?? rawSkill?.max_score ?? 4);
      const maxScore = Number.isFinite(rawMaxScore) ? Math.max(1, Math.min(100, Math.round(rawMaxScore))) : 4;
      const skill = sanitizeClinicalPayload(cleanObject({
        id: skillId,
        name: skillName,
        code: sanitizeString(rawSkill?.code, 120) || undefined,
        maxScore,
        objective: sanitizeTextField(rawSkill?.objective, 4000) || undefined,
        question: sanitizeTextField(rawSkill?.question, 4000) || undefined,
        example: sanitizeTextField(rawSkill?.example, 4000) || undefined,
        criteria: sanitizeTextField(rawSkill?.criteria, 4000) || undefined,
        comment: sanitizeTextField(rawSkill?.comment, 4000) || undefined,
        createdAt: sanitizeString(rawSkill?.createdAt || rawSkill?.created_at, 80) || new Date().toISOString(),
        createdBy: actorId || undefined
      }));

      const requestedProtocolId = sanitizeString(req.body?.protocolId || req.body?.protocol_id, 120);
      const requestedDomainId = sanitizeString(req.body?.domainId || req.body?.domain_id, 120);
      const requestedProtocolTitle = sanitizeTextField(req.body?.protocolTitle || req.body?.protocol_title, 240);
      const requestedDomainName = sanitizeTextField(req.body?.domainName || req.body?.domain_name, 240);
      const requestedAgeGroup = sanitizeString(req.body?.ageGroup || req.body?.age_group, 30).toLowerCase();
      const ageGroup = requestedAgeGroup === 'senior' ? 'senior' : 'adult';
      const ageRange = ageGroup === 'senior' ? { min: 60, max: null as number | null } : { min: 19, max: 59 as number | null };
      const stableProtocolId = requestedProtocolId || crypto.randomUUID();
      const stableDomainId = requestedDomainId || crypto.randomUUID();

      if (operation === 'append_skill' && (!requestedProtocolId || !requestedDomainId)) {
        return res.status(400).json({ success: false, error: 'REUSABLE_PROTOCOL_TARGET_REQUIRED', message: 'Selecione o protocolo e o domínio onde a tarefa será salva.' });
      }
      if (operation === 'create_protocol' && (!requestedProtocolTitle || !requestedDomainName)) {
        return res.status(400).json({ success: false, error: 'REUSABLE_PROTOCOL_FIELDS_REQUIRED', message: 'Informe o nome do protocolo e do domínio.' });
      }

      const buildResponse = (params: { protocols: any[]; protocol: any; domain: any; skill: any; persisted?: any; idempotent?: boolean }) => ({
        success: true,
        data: {
          clinicId,
          protocols: params.protocols,
          protocol: params.protocol,
          domain: params.domain,
          skill: params.skill,
          revision: Number(params.persisted?.revision || 0) || 0,
          sectionVersions:
            params.persisted?.sectionVersions && typeof params.persisted.sectionVersions === 'object'
              ? params.persisted.sectionVersions
              : {},
          idempotent: Boolean(params.idempotent)
        }
      });

      for (let attempt = 0; attempt < 2; attempt += 1) {
        const current = await supabase
          .from('clinic_state')
          .select('protocols,section_versions')
          .eq('clinic_id', clinicId)
          .maybeSingle();
        if (current.error) {
          const missingColumn = extractMissingColumnName(current.error);
          if (missingColumn === 'section_versions' || isMissingRelationError(current.error)) {
            return res.status(503).json({
              success: false,
              code: 'PERSISTENCE_GUARANTEES_MIGRATION_REQUIRED',
              error: 'A migração de garantias de persistência ainda não foi aplicada no Supabase.'
            });
          }
          throw current.error;
        }

        const currentProtocols = normalizeProtocolArrayForRoute(current.data?.protocols);
        const nextProtocols = currentProtocols.map((protocol: any) => cloneJsonValue(protocol));
        let persistedProtocol: any = null;
        let persistedDomain: any = null;
        let persistedSkill: any = null;

        if (operation === 'create_protocol') {
          const existingById = nextProtocols.find((protocol: any) => sanitizeString(protocol?.id, 120) === stableProtocolId);
          if (existingById) {
            const domain = normalizeJsonArrayForRoute(existingById?.data, ['domains', 'items', 'data', 'value'])
              .find((item: any) => sanitizeString(item?.id, 120) === stableDomainId) || null;
            const existingSkill = domain
              ? normalizeJsonArrayForRoute(domain?.skills, ['skills', 'items', 'data', 'value'])
                  .find((item: any) => sanitizeString(item?.id, 120) === skillId) || null
              : null;
            if (domain && existingSkill) {
              return res.json(buildResponse({ protocols: nextProtocols, protocol: existingById, domain, skill: existingSkill, idempotent: true }));
            }
          }

          const titleKey = normalizeProtocolKey(requestedProtocolTitle);
          const duplicate = nextProtocols.find((protocol: any) => {
            const protocolCategory = sanitizeString(protocol?.category, 40).toLowerCase() || 'evaluation';
            const protocolAgeGroup = sanitizeString(protocol?.ageGroup || protocol?.age_group, 30).toLowerCase() || 'all';
            return protocolCategory === category &&
              (protocolAgeGroup === ageGroup || protocolAgeGroup === 'all') &&
              normalizeProtocolKey(sanitizeString(protocol?.title || protocol?.name, 240)) === titleKey;
          });
          if (duplicate) {
            return res.status(409).json({
              success: false,
              error: 'REUSABLE_PROTOCOL_ALREADY_EXISTS',
              message: 'Já existe um protocolo com esse nome nesta categoria. Selecione o protocolo existente para adicionar a tarefa.',
              data: { protocol: duplicate }
            });
          }

          persistedDomain = sanitizeClinicalPayload({
            id: stableDomainId,
            name: requestedDomainName,
            skills: [skill]
          });
          persistedProtocol = sanitizeClinicalPayload({
            id: stableProtocolId,
            title: requestedProtocolTitle,
            category,
            ageGroup,
            age_group: ageGroup,
            age_minima: ageRange.min,
            age_maxima: ageRange.max,
            min_age: ageRange.min,
            max_age: ageRange.max,
            data: [persistedDomain],
            origin: 'manual_adult_task_schedule',
            isManualProtocol: true,
            createdAt: new Date().toISOString(),
            createdBy: actorId || null
          });
          persistedSkill = skill;
          nextProtocols.push(persistedProtocol);
        } else {
          const protocolIndex = nextProtocols.findIndex((protocol: any) => sanitizeString(protocol?.id, 120) === requestedProtocolId);
          if (protocolIndex < 0) {
            return res.status(404).json({ success: false, error: 'REUSABLE_PROTOCOL_NOT_FOUND', message: 'O protocolo selecionado não está mais disponível nesta clínica.' });
          }
          const protocol = nextProtocols[protocolIndex];
          const domains = normalizeJsonArrayForRoute(protocol?.data, ['domains', 'items', 'data', 'value']).map((domain: any) => cloneJsonValue(domain));
          const domainIndex = domains.findIndex((domain: any) => sanitizeString(domain?.id, 120) === requestedDomainId);
          if (domainIndex < 0) {
            return res.status(404).json({ success: false, error: 'REUSABLE_PROTOCOL_DOMAIN_NOT_FOUND', message: 'O domínio selecionado não está mais disponível neste protocolo.' });
          }
          const domain = domains[domainIndex];
          const skills = normalizeJsonArrayForRoute(domain?.skills, ['skills', 'items', 'data', 'value']).map((item: any) => cloneJsonValue(item));
          const existingSkill = skills.find((item: any) =>
            sanitizeString(item?.id, 120) === skillId ||
            normalizeProtocolKey(sanitizeString(item?.name || item?.title, 240)) === normalizeProtocolKey(skillName)
          );
          if (existingSkill) {
            return res.json(buildResponse({ protocols: nextProtocols, protocol, domain, skill: existingSkill, idempotent: true }));
          }
          skills.push(skill);
          persistedDomain = sanitizeClinicalPayload({ ...domain, skills });
          domains[domainIndex] = persistedDomain;
          persistedProtocol = sanitizeClinicalPayload({ ...protocol, data: domains });
          nextProtocols[protocolIndex] = persistedProtocol;
          persistedSkill = skill;
        }

        const currentProtocolVersion = Math.max(0, Number(current.data?.section_versions?.protocols || 0) || 0);
        const operationKey = sanitizeString(req.body?.idempotencyKey || req.body?.idempotency_key, 180) ||
          `reusable-adult-protocol:${operation}:${stableProtocolId}:${stableDomainId}:${skillId}`;
        const { data: persistenceResult, error: persistenceError } = await supabase.rpc('verto_save_clinic_state_sections', {
          p_clinic_id: clinicId,
          p_updated_by: isUuid(actorId) ? actorId : null,
          p_expected_section_versions: { protocols: currentProtocolVersion },
          p_rooms: null,
          p_appointments: null,
          p_protocols: nextProtocols,
          p_specialty_settings: null,
          p_idempotency_key: `${operationKey}:v${currentProtocolVersion}`
        });
        if (persistenceError) {
          const message = String(persistenceError?.message || '').toLowerCase();
          if (sanitizeString(persistenceError?.code, 40) === '42883' || message.includes('verto_save_clinic_state_sections')) {
            return res.status(503).json({
              success: false,
              code: 'PERSISTENCE_GUARANTEES_MIGRATION_REQUIRED',
              error: 'A migração de garantias de persistência ainda não foi aplicada no Supabase.'
            });
          }
          throw persistenceError;
        }
        if (persistenceResult?.success === false && persistenceResult?.conflict === true) {
          if (attempt === 0) continue;
          return res.status(409).json({
            success: false,
            error: 'REUSABLE_PROTOCOL_CONCURRENT_EDIT',
            message: 'A biblioteca de protocolos foi alterada por outra pessoa. Atualize e tente novamente.'
          });
        }

        const persistedState = persistenceResult?.data || {};
        const persistedProtocols = normalizeProtocolArrayForRoute(persistedState?.protocols);
        const finalProtocol = persistedProtocols.find((protocol: any) => sanitizeString(protocol?.id, 120) === sanitizeString(persistedProtocol?.id, 120)) || persistedProtocol;
        const finalDomain = normalizeJsonArrayForRoute(finalProtocol?.data, ['domains', 'items', 'data', 'value'])
          .find((domain: any) => sanitizeString(domain?.id, 120) === sanitizeString(persistedDomain?.id, 120)) || persistedDomain;
        const finalSkill = normalizeJsonArrayForRoute(finalDomain?.skills, ['skills', 'items', 'data', 'value'])
          .find((item: any) => sanitizeString(item?.id, 120) === skillId) || persistedSkill;

        try {
          await persistActivityLog({
            userId: actorId,
            clinicId,
            actorName: sanitizeString(req.session.user?.name || req.session.user?.email || 'Profissional', 180),
            title: 'Protocolos atualizados',
            content: operation === 'create_protocol'
              ? `Protocolo reutilizável "${sanitizeString(finalProtocol?.title, 180)}" criado a partir do agendamento de uma tarefa adulta.`
              : `Tarefa "${skillName}" adicionada ao protocolo reutilizável "${sanitizeString(finalProtocol?.title, 180)}".`,
            type: 'clinical',
            actionType: 'update_protocols',
            payloadDetails: JSON.stringify({
              operation,
              protocolId: sanitizeString(finalProtocol?.id, 120),
              domainId: sanitizeString(finalDomain?.id, 120),
              skillId,
              category,
              reusableAdultLibrary: true
            })
          });
        } catch (auditError: any) {
          console.warn('[ReusableAdultProtocol] audit warning:', auditError?.message || String(auditError));
        }

        return res.json(buildResponse({
          protocols: persistedProtocols.length > 0 ? persistedProtocols : nextProtocols,
          protocol: finalProtocol,
          domain: finalDomain,
          skill: finalSkill,
          persisted: persistedState
        }));
      }

      return res.status(409).json({ success: false, error: 'REUSABLE_PROTOCOL_CONCURRENT_EDIT', message: 'A biblioteca de protocolos foi alterada. Atualize e tente novamente.' });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/clinic/protocols/reusable-adult [POST]', error, {
        clinicId: sanitizeString(currentClinicId(req.session.user), 120),
        requestId: requestIdForLogs(req),
        fallbackMessage: 'Não foi possível salvar o protocolo reutilizável agora.'
      });
    }
  });

  app.post('/api/clinic/state', checkAuth, async (req: any, res) => {
    try {
      const clinicId = currentClinicId(req.session.user);
      const context = await resolveClinicCapabilityContext(req.session?.user);
      if (!context) {
        return res.status(403).json({
          success: false,
          error: 'CLINIC_AUTHORIZATION_CONTEXT_UNAVAILABLE',
          message: 'Não foi possível resolver seu vínculo ativo nesta clínica.'
        });
      }
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorName = sanitizeString(req.session.user?.name || req.session.user?.email || 'Usuário', 180);
      const actorRole = context.role;
      const canManageRooms = context.capabilities.has('clinic.rooms.manage');
      const canManageAppointments = context.capabilities.has('calendar.appointment.edit');
      const canManageProtocols = context.capabilities.has('clinic.settings.edit');
      const canManageSpecialtySettings = context.capabilities.has('clinic.settings.edit');

      const requestedRooms = Array.isArray(req.body?.rooms);
      const requestedAppointments = Array.isArray(req.body?.appointments);
      const requestedProtocols = Array.isArray(req.body?.protocols);
      const requestedSpecialtySettings = Boolean(
        req.body?.specialtySettings && typeof req.body.specialtySettings === 'object'
      );
      const deniedCapability =
        requestedRooms && !canManageRooms ? 'clinic.rooms.manage'
          : requestedAppointments && !canManageAppointments ? 'calendar.appointment.edit'
            : requestedProtocols && !canManageProtocols ? 'clinic.settings.edit'
              : requestedSpecialtySettings && !canManageSpecialtySettings ? 'clinic.settings.edit'
                : null;
      if (deniedCapability) {
        return res.status(403).json({
          success: false,
          error: 'CLINIC_CAPABILITY_DENIED',
          capability: deniedCapability,
          message: 'Seu acesso atual nesta clínica não permite alterar este estado.'
        });
      }

      const nextRooms = requestedRooms ? req.body.rooms.slice(0, 400) : undefined;
      const nextAppointments = requestedAppointments ? req.body.appointments.slice(0, 5000) : undefined;
      let nextProtocols = requestedProtocols ? req.body.protocols.slice(0, 600) : undefined;
      const nextSpecialtySettings = requestedSpecialtySettings ? req.body.specialtySettings : undefined;

      if (
        nextRooms === undefined &&
        nextAppointments === undefined &&
        nextProtocols === undefined &&
        nextSpecialtySettings === undefined
      ) {
        return res.status(400).json({ success: false, error: 'Nenhum payload de estado enviado.' });
      }

      const previous = await supabase
        .from('clinic_state')
        .select('rooms, appointments, protocols, specialty_settings, revision, section_versions')
        .eq('clinic_id', clinicId)
        .maybeSingle();
      if (previous.error) {
        const missingColumn = extractMissingColumnName(previous.error);
        if (missingColumn === 'revision' || missingColumn === 'section_versions' || isMissingRelationError(previous.error)) {
          return res.status(503).json({
            success: false,
            code: 'PERSISTENCE_GUARANTEES_MIGRATION_REQUIRED',
            error: 'A migração de garantias de persistência ainda não foi aplicada no Supabase.'
          });
        }
        throw previous.error;
      }

      if (nextAppointments !== undefined) {
        const effectiveSpecialtySettings =
          nextSpecialtySettings && typeof nextSpecialtySettings === 'object'
            ? nextSpecialtySettings
            : previous.data?.specialty_settings && typeof previous.data.specialty_settings === 'object'
              ? previous.data.specialty_settings
              : {};
        const scheduleValidation = await validateClinicStateAppointmentsForScheduleConflicts({
          clinicId,
          appointments: nextAppointments,
          rooms: nextRooms !== undefined ? nextRooms : Array.isArray(previous.data?.rooms) ? previous.data.rooms : [],
          specialtySettings: effectiveSpecialtySettings
        });
        if (!scheduleValidation.ok) {
          return res.status(scheduleValidation.status).json({
            success: false,
            error: scheduleValidation.error,
          });
        }
      }

      if (
        nextProtocols !== undefined &&
        nextProtocols.length === 0 &&
        !Boolean(req.body?.forceClearProtocols)
      ) {
        const approvedProtocolCount = await getApprovedProtocolImportRequestCount(clinicId);
        if (approvedProtocolCount > 0) {
          console.warn('[Protocol Sync] Bloqueado clear acidental de clinic_state.protocols com requests aprovados.', {
            clinicId,
            approvedProtocolCount,
            actorId
          });
          return res.status(409).json({
            success: false,
            error: 'Existem protocolos aprovados para esta clinica. Para limpar a biblioteca, confirme explicitamente forceClearProtocols.',
            warning: 'protocols_clear_blocked_with_approved_imports',
            approvedProtocolCount
          });
        }
      }

      if (
        nextProtocols !== undefined &&
        nextProtocols.length > 0 &&
        !Boolean(req.body?.forceClearProtocols)
      ) {
        const approvedRowsForSave = await loadApprovedProtocolImportRequestsForClinic(clinicId);
        const approvedProtocolsForSave = approvedRowsForSave
          .map((row) => buildClinicProtocolFromApprovedRequest(row))
          .filter(Boolean);
        if (approvedProtocolsForSave.length > 0) {
          const mergedProtocolsForSave = mergeApprovedProtocolsIntoClinicState(nextProtocols, approvedProtocolsForSave);
          if (mergedProtocolsForSave.added > 0) {
            nextProtocols = mergedProtocolsForSave.protocols;
            console.info('[Protocol Sync] Preservando protocolos aprovados durante POST /api/clinic/state.', {
              clinicId,
              approvedProtocolCount: approvedProtocolsForSave.length,
              added: mergedProtocolsForSave.added,
              refreshed: mergedProtocolsForSave.refreshed
            });
          }
        }
      }

      const appointmentsForPayload =
        nextAppointments !== undefined
          ? resetRescheduledAppointmentsForNewReminderCycle(
              nextAppointments,
              Array.isArray(previous.data?.appointments) ? previous.data.appointments : []
            )
          : undefined;

      const expectedSectionVersionsRaw =
        req.body?.expectedSectionVersions && typeof req.body.expectedSectionVersions === 'object'
          ? req.body.expectedSectionVersions
          : {};
      const expectedSectionVersions = cleanObject({
        rooms: Number.isFinite(Number(expectedSectionVersionsRaw?.rooms)) ? Number(expectedSectionVersionsRaw.rooms) : undefined,
        appointments: Number.isFinite(Number(expectedSectionVersionsRaw?.appointments)) ? Number(expectedSectionVersionsRaw.appointments) : undefined,
        protocols: Number.isFinite(Number(expectedSectionVersionsRaw?.protocols)) ? Number(expectedSectionVersionsRaw.protocols) : undefined,
        specialtySettings: Number.isFinite(Number(expectedSectionVersionsRaw?.specialtySettings)) ? Number(expectedSectionVersionsRaw.specialtySettings) : undefined,
      });
      const { data: persistenceResult, error } = await supabase.rpc('verto_save_clinic_state_sections', {
        p_clinic_id: clinicId,
        p_updated_by: isUuid(actorId) ? actorId : null,
        p_expected_section_versions: expectedSectionVersions,
        p_rooms: nextRooms !== undefined ? nextRooms : null,
        p_appointments: appointmentsForPayload !== undefined ? appointmentsForPayload : null,
        p_protocols: nextProtocols !== undefined ? nextProtocols : null,
        p_specialty_settings: nextSpecialtySettings !== undefined ? nextSpecialtySettings : null,
        p_idempotency_key: sanitizeString(
          req.body?.idempotencyKey || req.body?.idempotency_key || req.headers?.['x-idempotency-key'],
          260
        ) || null,
      });

      if (error) {
        const message = String(error?.message || '').toLowerCase();
        if (sanitizeString(error?.code, 40) === '42883' || message.includes('verto_save_clinic_state_sections')) {
          return res.status(503).json({
            success: false,
            code: 'PERSISTENCE_GUARANTEES_MIGRATION_REQUIRED',
            error: 'A migração de garantias de persistência ainda não foi aplicada no Supabase.'
          });
        }
        throw error;
      }
      if (persistenceResult?.success === false && persistenceResult?.conflict === true) {
        return res.status(409).json({
          success: false,
          code: 'CLINIC_STATE_CONCURRENT_EDIT',
          conflict: true,
          section: sanitizeString(persistenceResult?.section, 80),
          revision: Number(persistenceResult?.revision || 0) || 0,
          sectionVersions:
            persistenceResult?.sectionVersions && typeof persistenceResult.sectionVersions === 'object'
              ? persistenceResult.sectionVersions
              : {},
          error: 'Outra alteração foi persistida nesta mesma seção. Sua edição local foi preservada para reconciliação.'
        });
      }
      const persistedState = persistenceResult?.data || {};
      const data = {
        clinic_id: persistedState?.clinicId || clinicId,
        rooms: Array.isArray(persistedState?.rooms) ? persistedState.rooms : [],
        appointments: Array.isArray(persistedState?.appointments) ? persistedState.appointments : [],
        protocols: Array.isArray(persistedState?.protocols) ? persistedState.protocols : [],
        specialty_settings:
          persistedState?.specialtySettings && typeof persistedState.specialtySettings === 'object'
            ? persistedState.specialtySettings
            : {},
        updated_at: persistedState?.updatedAt || new Date().toISOString(),
        revision: Number(persistedState?.revision || 0) || 0,
        section_versions:
          persistedState?.sectionVersions && typeof persistedState.sectionVersions === 'object'
            ? persistedState.sectionVersions
            : {},
      };

      if (nextAppointments !== undefined) {
        const mirroredAppointments = Array.isArray(data.appointments)
          ? data.appointments
          : appointmentsForPayload || nextAppointments || [];
        const previousAppointmentsById = new Map(
          (Array.isArray(previous.data?.appointments) ? previous.data.appointments : [])
            .map((appointment: any) => [sanitizeString(appointment?.id, 120), appointment])
            .filter(([id]: any[]) => isUuid(id))
        );
        const closureSnapshot = (appointment: any) => JSON.stringify(cleanObject({
          patientId: appointment?.patientId || appointment?.patient_id || null,
          professionalId: appointment?.professionalId || appointment?.professional_id || appointment?.therapistId || appointment?.therapist_id || null,
          type: appointment?.type || appointment?.approach || appointment?.serviceType || appointment?.service_type || null,
          date: appointment?.date || null,
          time: appointment?.time || null,
          scheduledAt: appointment?.scheduledAt || appointment?.scheduled_at || appointment?.scheduled_start_at || appointment?.scheduledStartAt || null,
          duration: appointment?.duration_minutes || appointment?.durationMinutes || appointment?.scheduled_duration_minutes || appointment?.scheduledDurationMinutes || null,
          actualStart: appointment?.actual_start_at || appointment?.actualStartAt || appointment?.actual_start || appointment?.actualStart || null,
          actualEnd: appointment?.actual_end_at || appointment?.actualEndAt || appointment?.actual_end || appointment?.actualEnd || null,
          actualDuration: appointment?.actual_duration_minutes || appointment?.actualDurationMinutes || null,
          status: appointment?.status || null,
          room: appointment?.room_id || appointment?.roomId || appointment?.room_name || appointment?.roomName || appointment?.roomDisplayName || null,
          location: appointment?.location_type || appointment?.locationType || appointment?.location || null
        }));
        const closureAppointmentIdsToRefresh = Array.from(new Set(
          mirroredAppointments
            .map((appointment: any) => {
              const id = sanitizeString(appointment?.id, 120);
              if (!isUuid(id)) return '';
              const previousAppointment = previousAppointmentsById.get(id);
              return !previousAppointment || closureSnapshot(previousAppointment) !== closureSnapshot(appointment) ? id : '';
            })
            .filter(Boolean)
        )).slice(0, 80);
        void syncAppointmentsTableFromClinicState({
          clinicId,
          appointments: mirroredAppointments,
          actorId,
          specialtySettings:
            data.specialty_settings && typeof data.specialty_settings === 'object'
              ? data.specialty_settings
              : nextSpecialtySettings || {},
          onAppointmentMirrored: (context) => flagPendingMaintenanceProbesForAppointment(context)
        })
          .then((summary) => {
            if (summary.mirrored > 0) {
              console.log('[Appointments] Agenda espelhada na tabela appointments.', summary);
            }
            void regenerateClosureForAppointments(
              closureAppointmentIdsToRefresh,
              req.session.user,
              'clinic_state_saved'
            );
            triggerAppointmentReminderScan('clinic_state_saved');
          })
          .catch((mirrorError: any) => {
            console.warn('[Appointments] Espelhamento da agenda falhou sem bloquear salvamento.', mirrorError?.message || String(mirrorError));
          });
      }

      if (nextRooms !== undefined) {
        void syncClinicRoomsTableFromClinicState({
          clinicId,
          rooms: Array.isArray(data.rooms) ? data.rooms : nextRooms,
          organizationId: req.session.user?.organizationId || req.session.user?.organization_id || clinicId
        }).catch((roomMirrorError: any) => {
          console.warn('[Rooms] Espelhamento de salas falhou sem bloquear salvamento.', roomMirrorError?.message || String(roomMirrorError));
        });
      }

      const prevData = previous.data || {};
      if (nextRooms !== undefined && JSON.stringify(prevData.rooms || []) !== JSON.stringify(nextRooms)) {
        void persistActivityLog({
          userId: actorId,
          clinicId,
          actorName,
          title: 'Salas atualizadas',
          content: `${actorName} atualizou as salas da clínica (${Array.isArray(nextRooms) ? nextRooms.length : 0} itens).`,
          type: 'management'
        });
      }
      if (nextAppointments !== undefined && JSON.stringify(prevData.appointments || []) !== JSON.stringify(nextAppointments)) {
        void persistActivityLog({
          userId: actorId,
          clinicId,
          actorName,
          title: 'Agenda clínica atualizada',
          content: `${actorName} atualizou os agendamentos da clínica (${Array.isArray(nextAppointments) ? nextAppointments.length : 0} itens).`,
          type: 'management'
        });
      }
      if (nextProtocols !== undefined && JSON.stringify(prevData.protocols || []) !== JSON.stringify(nextProtocols)) {
        void persistActivityLog({
          userId: actorId,
          clinicId,
          actorName,
          title: 'Protocolos atualizados',
          content: `${actorName} atualizou os protocolos/PEIs da clínica (${Array.isArray(nextProtocols) ? nextProtocols.length : 0} itens).`,
          type: 'clinical'
        });
      }
      if (nextSpecialtySettings !== undefined && JSON.stringify(prevData.specialty_settings || {}) !== JSON.stringify(nextSpecialtySettings)) {
        void persistActivityLog({
          userId: actorId,
          clinicId,
          actorName,
          title: 'Configurações de duração de sessão atualizadas',
          content: `${actorName} atualizou as durações por abordagem/profissional.`,
          type: 'management'
        });
      }

      return res.json({
        success: true,
        data: {
          clinicId: data.clinic_id,
          rooms: Array.isArray(data.rooms) ? data.rooms : [],
          appointments: Array.isArray(data.appointments) ? data.appointments : [],
          protocols: normalizeProtocolArrayForRoute(data.protocols),
          specialtySettings: data.specialty_settings && typeof data.specialty_settings === 'object' ? data.specialty_settings : {},
          updatedAt: data.updated_at || null,
          revision: Number(data.revision || 0) || 0,
          sectionVersions: data.section_versions || {}
        }
      });
    } catch (error) {
      return res.status(500).json({ success: false, error: 'Erro interno do servidor.' });
    }
  });

  const readClinicStateForAppointmentMutation = async (clinicId: string) => {
    const readState = (columns: string) =>
      supabase
        .from('clinic_state')
        .select(columns)
        .eq('clinic_id', clinicId)
        .maybeSingle();
    let result = await readState('clinic_id, rooms, appointments, specialty_settings');
    if (result.error && extractMissingColumnName(result.error) === 'specialty_settings') {
      result = await readState('clinic_id, rooms, appointments');
    }
    if (result.error) {
      if (isMissingRelationError(result.error)) {
        return { rooms: [], appointments: [], specialtySettings: {} };
      }
      throw result.error;
    }
    return {
      rooms: Array.isArray(result.data?.rooms) ? result.data.rooms : [],
      appointments: Array.isArray(result.data?.appointments) ? result.data.appointments : [],
      specialtySettings:
        result.data?.specialty_settings && typeof result.data.specialty_settings === 'object'
          ? result.data.specialty_settings
          : {},
    };
  };

  const appointmentSortValue = (appointment: any) => {
    const scheduledAt = buildAppointmentScheduledAt(appointment);
    if (scheduledAt) {
      const parsed = new Date(scheduledAt).getTime();
      if (Number.isFinite(parsed)) return parsed;
    }
    return Number.POSITIVE_INFINITY;
  };

  const mergeClinicStateAppointmentsById = (existingAppointments: any[], persistedAppointments: any[]) => {
    const normalizeAssignmentText = (value: any) => sanitizeString(value, 180)
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/\s+/g, ' ')
      .trim();
    const isGenericProfessionalLabel = (value: any) => {
      const normalized = normalizeAssignmentText(value);
      return !normalized || normalized === 'equipe' || normalized === 'team' || normalized === 'profissional' || normalized === 'profissional nao definido' || normalized === 'nao informado';
    };
    const isGenericRoomLabel = (value: any) => {
      const normalized = normalizeAssignmentText(value);
      return !normalized || normalized === 'outro' || normalized === 'nao informado' || normalized === 'sala nao informada' || normalized === 'sala nao identificada';
    };
    const firstMeaningfulValue = (sources: any[], keys: string[], isGeneric: (value: any) => boolean) => {
      for (const source of sources) {
        for (const key of keys) {
          const value = source?.[key];
          if (value !== null && value !== undefined && !isGeneric(value)) return value;
        }
      }
      return undefined;
    };
    const mergeAppointmentClinicalAssignment = (existing: any, incoming: any) => {
      const clearProfessional = incoming?.clearProfessional === true || incoming?.clear_professional === true;
      const clearRoom = incoming?.clearRoom === true || incoming?.clear_room === true;
      const professionalId = clearProfessional ? null : firstMeaningfulValue(
        [incoming, existing],
        ['therapist_id', 'therapistId', 'professional_id', 'professionalId', 'responsible_professional_id', 'responsibleProfessionalId'],
        (value) => !sanitizeString(value, 120)
      );
      const professionalName = clearProfessional ? null : firstMeaningfulValue(
        [incoming, existing],
        ['therapist_name', 'therapistName', 'professional_name', 'professionalName', 'professional', 'responsible_professional_name', 'responsibleProfessionalName'],
        isGenericProfessionalLabel
      );
      const roomId = clearRoom ? null : firstMeaningfulValue(
        [incoming, existing],
        ['room_id', 'roomId', 'room'],
        isGenericRoomLabel
      );
      const roomName = clearRoom ? null : firstMeaningfulValue(
        [incoming, existing],
        ['room_name', 'roomName', 'roomDisplayName'],
        isGenericRoomLabel
      );
      const merged = { ...(existing || {}), ...(incoming || {}) };
      if (professionalId !== undefined) {
        merged.therapist_id = professionalId;
        merged.therapistId = professionalId;
        merged.professional_id = professionalId;
        merged.professionalId = professionalId;
        merged.responsible_professional_id = professionalId;
        merged.responsibleProfessionalId = professionalId;
      }
      if (professionalName !== undefined) {
        merged.therapist_name = professionalName;
        merged.therapistName = professionalName;
        merged.professional = professionalName;
        merged.responsible_professional_name = professionalName;
        merged.responsibleProfessionalName = professionalName;
      }
      if (roomId !== undefined) {
        merged.room_id = roomId;
        merged.roomId = roomId;
        merged.room = roomId;
      }
      if (roomName !== undefined) {
        merged.room_name = roomName;
        merged.roomName = roomName;
        merged.roomDisplayName = roomName;
      }
      if (roomId || roomName) {
        merged.location_type = 'clinica';
        merged.locationType = 'clinica';
        merged.location = 'clinica';
      }
      const scheduledAt = buildAppointmentScheduledAt(incoming);
      if (scheduledAt) {
        const start = new Date(scheduledAt);
        const durationMinutes = getClinicStateAppointmentDurationMinutes(incoming, {});
        const explicitEnd = sanitizeString(
          incoming?.scheduled_end_at || incoming?.scheduledEndAt || incoming?.scheduledEnd || incoming?.end_time,
          80
        );
        const parsedExplicitEnd = explicitEnd ? new Date(explicitEnd) : null;
        const end = parsedExplicitEnd && !Number.isNaN(parsedExplicitEnd.getTime())
          ? parsedExplicitEnd
          : calculateAppointmentEnd(start, durationMinutes);
        merged.scheduled_at = scheduledAt;
        merged.scheduledAt = scheduledAt;
        merged.scheduled_start_at = scheduledAt;
        merged.scheduledStartAt = scheduledAt;
        merged.start_time = scheduledAt;
        merged.startTime = scheduledAt;
        merged.date = formatDateInAppointmentTimezone(start);
        merged.time = formatTimeInAppointmentTimezone(start);
        if (end) {
          const scheduledEndAt = end.toISOString();
          merged.scheduled_end_at = scheduledEndAt;
          merged.scheduledEndAt = scheduledEndAt;
          merged.scheduledEnd = scheduledEndAt;
          merged.end_time = scheduledEndAt;
          merged.endTime = formatTimeInAppointmentTimezone(end);
        }
      }
      return merged;
    };
    const byId = new Map<string, any>();
    for (const appointment of Array.isArray(existingAppointments) ? existingAppointments : []) {
      const id = sanitizeString(appointment?.id, 120);
      if (id) byId.set(id, appointment);
    }
    for (const appointment of Array.isArray(persistedAppointments) ? persistedAppointments : []) {
      const id = sanitizeString(appointment?.id, 120);
      if (id) byId.set(id, mergeAppointmentClinicalAssignment(byId.get(id) || {}, appointment));
    }
    return Array.from(byId.values()).sort((left, right) => {
      const byDate = appointmentSortValue(left) - appointmentSortValue(right);
      if (byDate !== 0) return byDate;
      return sanitizeString(left?.id, 120).localeCompare(sanitizeString(right?.id, 120));
    });
  };

  const professionalBelongsToClinic = async (professionalId: string, clinicId: string, actor: any) => {
    const safeProfessionalId = sanitizeString(professionalId, 120);
    if (!isUuid(safeProfessionalId) || !isUuid(clinicId)) return false;
    if (safeProfessionalId === sanitizeString(actor?.id, 120)) return true;

    const membership = await supabase
      .from('clinic_memberships')
      .select('user_id')
      .eq('clinic_id', clinicId)
      .eq('user_id', safeProfessionalId)
      .eq('status', 'active')
      .limit(1)
      .maybeSingle();
    if (!membership.error && membership.data?.user_id) return true;
    if (membership.error && !isMissingRelationError(membership.error)) throw membership.error;

    const userResult = await supabase
      .from('users')
      .select('id, clinic_id')
      .eq('id', safeProfessionalId)
      .limit(1)
      .maybeSingle();
    if (userResult.error) {
      if (extractMissingColumnName(userResult.error) || isMissingRelationError(userResult.error)) return false;
      throw userResult.error;
    }
    return sanitizeString(userResult.data?.clinic_id, 120) === clinicId;
  };

  const formatStructuredLocationAddress = (address: any) =>
    [
      [sanitizeString(address?.street || address?.logradouro, 180), sanitizeString(address?.number || address?.numero, 40)].filter(Boolean).join(', '),
      sanitizeString(address?.complement || address?.address_complement || address?.complemento, 120),
      sanitizeString(address?.district || address?.bairro, 120),
      [sanitizeString(address?.city || address?.cidade, 120), sanitizeString(address?.state || address?.uf, 2).toUpperCase()].filter(Boolean).join('/'),
      sanitizeString(address?.postalCode || address?.postal_code || address?.cep, 20)
    ].filter(Boolean).join(' • ');

  const resolveStructuredAppointmentLocation = async (
    raw: any,
    patient: any,
    patientId: string,
    clinicId: string,
    existingAppointment?: any | null,
  ) => {
    const requestedRoomId = sanitizeString(raw?.room_id || raw?.roomId || raw?.room, 180);
    const careSetting = normalizeCareSetting(
      raw?.care_setting || raw?.careSetting || (requestedRoomId ? 'CLINIC' : null),
      raw?.location_type || raw?.locationType || raw?.location
    );
    const locationType = careSetting === 'CLINIC' ? 'clinica' : careSetting === 'ONLINE' ? 'online' : careSetting === 'PATIENT_HOME' ? 'domicilio' : careSetting === 'SCHOOL' ? 'escola' : 'outro';
    const existingCareSetting = existingAppointment
      ? normalizeCareSetting(existingAppointment?.care_setting, existingAppointment?.location_type)
      : null;
    const existingSnapshot = parseStoredJsonObject(existingAppointment?.location_snapshot);
    const preserveHistoricalSnapshot =
      Boolean(existingAppointment?.id) &&
      ['PATIENT_HOME', 'SCHOOL'].includes(careSetting) &&
      existingCareSetting === careSetting &&
      raw?.refresh_location_snapshot !== true &&
      raw?.refreshLocationSnapshot !== true &&
      Object.keys(existingSnapshot).length > 0 &&
      (
        careSetting !== 'SCHOOL' ||
        (
          sanitizeString(existingAppointment?.school_id, 120) === sanitizeString(raw?.school_id || raw?.schoolId, 120) &&
          sanitizeString(existingAppointment?.school_unit_id, 120) === sanitizeString(raw?.school_unit_id || raw?.schoolUnitId, 120)
        )
      );
    if (preserveHistoricalSnapshot) {
      return {
        ok: true,
        data: {
          careSetting,
          locationType,
          roomId: null,
          roomName: null,
          schoolId: careSetting === 'SCHOOL' ? sanitizeString(existingAppointment?.school_id, 120) || null : null,
          schoolUnitId: careSetting === 'SCHOOL' ? sanitizeString(existingAppointment?.school_unit_id, 120) || null : null,
          locationSnapshot: existingSnapshot,
          locationNameSnapshot: sanitizeString(existingAppointment?.location_name_snapshot, 180) || (careSetting === 'PATIENT_HOME' ? 'Domicílio' : 'Escola'),
          locationAddressSnapshot: sanitizeString(existingAppointment?.location_address_snapshot, 500) || null,
          locationSource: sanitizeString(existingAppointment?.location_source, 40) || (careSetting === 'PATIENT_HOME' ? 'PATIENT_PROFILE' : 'SCHOOL_DIRECTORY'),
          locationTimezone: sanitizeString(existingAppointment?.location_timezone, 80) || 'America/Sao_Paulo',
        },
      };
    }
    if (careSetting === 'CLINIC') {
      if (!requestedRoomId) return { ok: false, status: 422, error: 'Selecione uma sala da clínica para este atendimento.' };
      const roomName = sanitizeString(raw?.room_name || raw?.roomName || raw?.roomDisplayName || requestedRoomId, 180);
      return { ok: true, data: { careSetting, locationType, roomId: requestedRoomId, roomName, schoolId: null, schoolUnitId: null, locationSnapshot: { careSetting, roomId: requestedRoomId, roomName }, locationNameSnapshot: roomName || 'Clínica', locationAddressSnapshot: null, locationSource: 'CLINIC_DIRECTORY', locationTimezone: 'America/Sao_Paulo' } };
    }
    if (careSetting === 'ONLINE') {
      return { ok: true, data: { careSetting, locationType, roomId: null, roomName: null, schoolId: null, schoolUnitId: null, locationSnapshot: { careSetting, callLinkPresent: Boolean(sanitizeString(raw?.call_link || raw?.callLink, 500)) }, locationNameSnapshot: 'Online', locationAddressSnapshot: null, locationSource: 'ONLINE', locationTimezone: 'America/Sao_Paulo' } };
    }
    if (careSetting === 'PATIENT_HOME') {
      const metadata = parseStoredJsonObject(patient?.metadata);
      const address = parseStoredJsonObject(metadata?.address);
      const snapshot = cleanObject({
        postalCode: sanitizeString(patient?.cep || address?.cep || address?.postalCode, 20) || null,
        street: sanitizeString(address?.logradouro || address?.street, 180) || null,
        number: sanitizeString(address?.numero || address?.number, 40) || null,
        complement: sanitizeString(address?.complemento || address?.complement, 120) || null,
        district: sanitizeString(address?.bairro || address?.district || address?.neighborhood, 120) || null,
        city: sanitizeString(address?.cidade || address?.city, 120) || null,
        state: sanitizeString(address?.uf || address?.state, 2).toUpperCase() || null,
        reference: sanitizeString(address?.referencia || address?.reference, 240) || null,
        operationalPhone: sanitizeString(patient?.phone, 40) || null
      });
      const missing = [...(!snapshot.street ? ['logradouro'] : []), ...(!snapshot.number ? ['número'] : []), ...(!snapshot.city ? ['cidade'] : [])];
      if (missing.length) return { ok: false, status: 422, code: 'PATIENT_HOME_ADDRESS_INCOMPLETE', error: `Complete o endereço do paciente antes de agendar no domicílio. Faltando: ${missing.join(', ')}.` };
      return { ok: true, data: { careSetting, locationType, roomId: null, roomName: null, schoolId: null, schoolUnitId: null, locationSnapshot: { careSetting, patientId, address: snapshot }, locationNameSnapshot: `Domicílio • ${sanitizeString(patient?.name, 180) || 'Paciente'}`, locationAddressSnapshot: formatStructuredLocationAddress(snapshot), locationSource: 'PATIENT_PROFILE', locationTimezone: 'America/Sao_Paulo' } };
    }
    if (careSetting === 'SCHOOL') {
      const schoolId = sanitizeString(raw?.school_id || raw?.schoolId, 120);
      const schoolUnitId = sanitizeString(raw?.school_unit_id || raw?.schoolUnitId, 120);
      if (!isUuid(schoolId)) return { ok: false, status: 422, code: 'APPOINTMENT_SCHOOL_REQUIRED', error: 'Selecione uma escola atualmente vinculada ao paciente.' };
      let query = supabase
        .from('patient_school_enrollments')
        .select('id,organization_id,school_id,school_unit_id,enrollment_type,schools(id,display_name,street,street_number,address_complement,district,city,state,postal_code),school_units(id,name,street,street_number,address_complement,district,city,state,postal_code)')
        .eq('clinic_id', clinicId)
        .eq('patient_id', patientId)
        .eq('school_id', schoolId)
        .eq('is_current', true);
      if (schoolUnitId) query = query.eq('school_unit_id', schoolUnitId);
      const result = await query.limit(1).maybeSingle();
      if (result.error) throw result.error;
      if (!result.data?.id) return { ok: false, status: 403, code: 'APPOINTMENT_PATIENT_SCHOOL_LINK_REQUIRED', error: 'A escola ou unidade não pertence aos vínculos atuais deste paciente.' };
      if (!schoolUnitId) {
        const unitsResult = await supabase
          .from('school_units')
          .select('id')
          .eq('organization_id', result.data.organization_id)
          .eq('school_id', schoolId)
          .eq('is_active', true)
          .is('archived_at', null)
          .limit(1);
        if (unitsResult.error) throw unitsResult.error;
        if ((unitsResult.data || []).length > 0) {
          return { ok: false, status: 422, code: 'APPOINTMENT_SCHOOL_UNIT_REQUIRED', error: 'Esta escola possui unidades. Atualize o vínculo escolar do paciente e selecione a unidade correta.' };
        }
      }
      const school = Array.isArray(result.data.schools) ? result.data.schools[0] : result.data.schools;
      const unit = Array.isArray(result.data.school_units) ? result.data.school_units[0] : result.data.school_units;
      const source = unit || school || {};
      const address = cleanObject({ postalCode: sanitizeString(source?.postal_code, 20) || null, street: sanitizeString(source?.street, 180) || null, number: sanitizeString(source?.street_number, 40) || null, complement: sanitizeString(source?.address_complement, 120) || null, district: sanitizeString(source?.district, 120) || null, city: sanitizeString(source?.city, 120) || null, state: sanitizeString(source?.state, 2).toUpperCase() || null });
      const addressText = formatStructuredLocationAddress(address);
      if (!address.street || !address.city || !addressText) return { ok: false, status: 422, code: 'SCHOOL_ADDRESS_INCOMPLETE', error: 'Complete o endereço da escola ou da unidade antes de agendar uma sessão escolar.' };
      const schoolName = sanitizeString(school?.display_name, 180) || 'Escola';
      const unitName = sanitizeString(unit?.name, 180) || null;
      return { ok: true, data: { careSetting, locationType, roomId: null, roomName: null, schoolId, schoolUnitId: schoolUnitId || null, locationSnapshot: { careSetting, schoolId, schoolUnitId: schoolUnitId || null, schoolName, unitName, enrollmentId: result.data.id, enrollmentType: result.data.enrollment_type, address }, locationNameSnapshot: unitName ? `${schoolName} • ${unitName}` : schoolName, locationAddressSnapshot: addressText, locationSource: 'SCHOOL_DIRECTORY', locationTimezone: 'America/Sao_Paulo' } };
    }
    const name = sanitizeString(raw?.location_name_snapshot || raw?.locationNameSnapshot || raw?.locationLabel, 180) || 'Outro local';
    const address = sanitizeString(raw?.location_address_snapshot || raw?.locationAddressSnapshot || raw?.location_notes || raw?.locationNotes, 500) || null;
    return { ok: true, data: { careSetting: 'OTHER', locationType: 'outro', roomId: null, roomName: null, schoolId: null, schoolUnitId: null, locationSnapshot: { careSetting: 'OTHER', name, address }, locationNameSnapshot: name, locationAddressSnapshot: address, locationSource: 'MANUAL', locationTimezone: 'America/Sao_Paulo' } };
  };

  const prepareAppointmentForWrite = async (
    rawAppointment: any,
    actor: any,
    clinicId: string,
    existingAppointment?: any | null,
  ) => {
    const appointmentId = sanitizeString(rawAppointment?.id, 120);
    if (!isUuid(appointmentId)) {
      return { ok: false, status: 400, error: 'Agendamento sem identificador persistente.' };
    }

    const patientId = sanitizeString(rawAppointment?.patient_id || rawAppointment?.patientId, 120);
    if (!isUuid(patientId)) {
      return { ok: false, status: 400, error: 'Selecione um paciente cadastrado para confirmar o agendamento.' };
    }

    const patientResult = await supabase
      .from('patients')
      .select('id, name, email, phone, cep, metadata, clinic_id')
      .eq('id', patientId)
      .eq('clinic_id', clinicId)
      .limit(1)
      .maybeSingle();
    if (patientResult.error) throw patientResult.error;
    if (!patientResult.data?.id) {
      return { ok: false, status: 403, error: 'Paciente não pertence à clínica atual.' };
    }

    const professionalId =
      sanitizeString(
        rawAppointment?.professional_id ||
          rawAppointment?.professionalId ||
          rawAppointment?.therapist_id ||
          rawAppointment?.therapistId,
        120
      );
    if (!isUuid(professionalId)) {
      return { ok: false, status: 400, error: 'Selecione um profissional responsável para este agendamento.' };
    }
    const professionalAllowed = await professionalBelongsToClinic(professionalId, clinicId, actor);
    if (!professionalAllowed) {
      return { ok: false, status: 403, error: 'Profissional não pertence à clínica atual.' };
    }
    const [professionalUserResult, professionalProfileResult] = await Promise.all([
      supabase
        .from('users')
        .select('id, name, email, clinic_id')
        .eq('id', professionalId)
        .limit(1)
        .maybeSingle(),
      fetchProfessionalProfileWithSchemaFallback({
        supabase,
        userId: professionalId,
        logger: console
      })
    ]);
    if (professionalUserResult.error && !extractMissingColumnName(professionalUserResult.error)) {
      throw professionalUserResult.error;
    }
    if (professionalProfileResult.error && !hasMissingFinancialSchema(professionalProfileResult.error)) {
      throw professionalProfileResult.error;
    }

    const scheduledAt = buildAppointmentScheduledAt(rawAppointment);
    if (!scheduledAt) {
      return { ok: false, status: 400, error: 'Informe data e horário válidos para este atendimento.' };
    }

    const duration = Number(
      rawAppointment?.duration_minutes ||
        rawAppointment?.durationMinutes ||
        rawAppointment?.scheduled_duration_minutes ||
        rawAppointment?.scheduledDurationMinutes ||
        50
    );
    const safeDuration = Number.isFinite(duration) && duration > 0 ? Math.min(360, Math.round(duration)) : 50;
    const start = new Date(scheduledAt);
    const end = calculateAppointmentEnd(start, safeDuration);
    const patientName = sanitizeString(patientResult.data.name || rawAppointment?.patientName || rawAppointment?.name, 180) || 'Paciente';
    const patientEmail = sanitizeEmail(patientResult.data.email || rawAppointment?.patientEmail || rawAppointment?.patient_email) || null;
    const professionalName =
      sanitizeString(
        professionalProfileResult.data?.full_name ||
          professionalProfileResult.data?.fullName ||
          professionalUserResult.data?.name ||
          rawAppointment?.therapistName ||
          rawAppointment?.therapist_name ||
          rawAppointment?.professionalName ||
          rawAppointment?.professional,
        180
      );
    if (!professionalName || ['equipe', 'team'].includes(professionalName.toLowerCase())) {
      return { ok: false, status: 400, error: 'O profissional responsável selecionado não possui um nome válido.' };
    }
    const structuredLocation = await resolveStructuredAppointmentLocation(
      rawAppointment,
      patientResult.data,
      patientId,
      clinicId,
      existingAppointment,
    );
    if (!structuredLocation.ok) return structuredLocation;
    const location = structuredLocation.data;
    const roomId = location.roomId;
    const roomName = location.roomName;
    const locationType = location.locationType;
    if (locationType === 'clinica' && !roomId) {
      return { ok: false, status: 400, error: 'Selecione uma sala da clínica para este atendimento.' };
    }

    return {
      ok: true,
      appointment: cleanObject({
        ...rawAppointment,
        id: appointmentId,
        organization_id: clinicId,
        organizationId: clinicId,
        clinic_id: clinicId,
        clinicId,
        patient_id: patientId,
        patientId,
        patient_name: patientName,
        patientName,
        name: patientName,
        patient_email: patientEmail,
        patientEmail,
        therapist_id: professionalId,
        therapistId: professionalId,
        professional_id: professionalId,
        professionalId,
        therapist_name: professionalName,
        therapistName: professionalName,
        professional: professionalName,
        responsible_professional_id: professionalId,
        responsibleProfessionalId: professionalId,
        responsible_professional_name: professionalName,
        responsibleProfessionalName: professionalName,
        room_id: roomId || null,
        roomId: roomId || null,
        room: roomId || null,
        room_name: roomName || null,
        roomName: roomName || null,
        location_type: locationType,
        locationType,
        care_setting: location.careSetting,
        careSetting: location.careSetting,
        school_id: location.schoolId,
        schoolId: location.schoolId,
        school_unit_id: location.schoolUnitId,
        schoolUnitId: location.schoolUnitId,
        location_snapshot: location.locationSnapshot,
        locationSnapshot: location.locationSnapshot,
        location_name_snapshot: location.locationNameSnapshot,
        locationNameSnapshot: location.locationNameSnapshot,
        location_address_snapshot: location.locationAddressSnapshot,
        locationAddressSnapshot: location.locationAddressSnapshot,
        location_source: location.locationSource,
        locationSource: location.locationSource,
        location_timezone: location.locationTimezone,
        locationTimezone: location.locationTimezone,
        financial_event_actor_id: isUuid(sanitizeString(actor?.id, 120)) ? sanitizeString(actor?.id, 120) : null,
        financialEventActorId: isUuid(sanitizeString(actor?.id, 120)) ? sanitizeString(actor?.id, 120) : null,
        financial_event_reason: sanitizeString(
          rawAppointment?.privatePricingReason ||
            rawAppointment?.private_pricing_reason ||
            rawAppointment?.financialEventReason ||
            rawAppointment?.financial_event_reason,
          1200
        ) || null,
        financialEventReason: sanitizeString(
          rawAppointment?.privatePricingReason ||
            rawAppointment?.private_pricing_reason ||
            rawAppointment?.financialEventReason ||
            rawAppointment?.financial_event_reason,
          1200
        ) || null,
        scheduled_at: scheduledAt,
        scheduledAt,
        scheduled_start_at: scheduledAt,
        scheduledStartAt: scheduledAt,
        scheduled_end_at: end ? end.toISOString() : rawAppointment?.scheduled_end_at || rawAppointment?.scheduledEndAt || null,
        scheduledEndAt: end ? end.toISOString() : rawAppointment?.scheduledEndAt || rawAppointment?.scheduled_end_at || null,
        duration_minutes: safeDuration,
        durationMinutes: safeDuration,
        scheduled_duration_minutes: safeDuration,
        scheduledDurationMinutes: safeDuration,
        date: sanitizeDate(rawAppointment?.date) || formatDateInAppointmentTimezone(start),
        time: normalizeAppointmentTime(rawAppointment?.time) || formatTimeInAppointmentTimezone(start),
        status: normalizeAppointmentStatusForUi(rawAppointment?.status || 'pending'),
      }),
    };
  };

  const readPersistedAppointmentRows = async (appointmentIds: string[], clinicId?: string) => {
    const ids = Array.from(new Set((appointmentIds || []).map((id) => sanitizeString(id, 120)).filter((id) => isUuid(id))));
    if (ids.length === 0) return [];
    const safeClinicId = sanitizeString(clinicId, 120);
    const criticalColumns = new Set(['id', 'clinic_id', 'patient_id', 'therapist_id', 'scheduled_at', 'status']);
    let columns = APPOINTMENT_SELECT.split(',').map((column) => column.trim()).filter(Boolean);
    while (columns.length > 0) {
      let query = supabase
        .from('appointments')
        .select(columns.join(','))
        .in('id', ids)
        .limit(ids.length);
      if (safeClinicId) query = query.eq('clinic_id', safeClinicId);
      const result = await query;
      if (!result.error) return Array.isArray(result.data) ? result.data : [];

      const missingColumn = extractMissingColumnName(result.error);
      if (missingColumn && columns.includes(missingColumn) && !criticalColumns.has(missingColumn)) {
        columns = columns.filter((column) => column !== missingColumn);
        continue;
      }
      throw result.error;
    }
    throw new Error('Não foi possível confirmar a persistência do agendamento.');
  };

  const confirmPersistedAppointmentRows = (rows: any[], expectedAppointments: any[], clinicId: string) => {
    const rowsById = new Map((rows || []).map((row: any) => [sanitizeString(row?.id, 120), row]));
    for (const appointment of expectedAppointments) {
      const appointmentId = sanitizeString(appointment?.id, 120);
      const row = rowsById.get(appointmentId);
      if (!row) return false;
      if (sanitizeString(row?.clinic_id, 120) !== clinicId) return false;
      if (sanitizeString(row?.patient_id, 120) !== sanitizeString(appointment?.patient_id || appointment?.patientId, 120)) return false;
      if (sanitizeString(row?.therapist_id, 120) !== sanitizeString(appointment?.therapist_id || appointment?.therapistId, 120)) return false;
      const expectedRoomId = sanitizeString(
        appointment?.room_id || appointment?.roomId || appointment?.room,
        180
      );
      if (expectedRoomId && sanitizeString(row?.room_id, 180) !== expectedRoomId) return false;
      const status = normalizeAppointmentStatusForUi(row?.status || 'pending');
      if (['deleted'].includes(status)) return false;
      if (!buildAppointmentScheduledAt(row)) return false;
    }
    return true;
  };

  const validateDurableAppointmentConflictsForWrite = async (params: {
    appointments: any[];
    user: any;
    clinicId: string;
    excludeIds?: string[];
  }) => {
    const clinicId = sanitizeString(params.clinicId, 120);
    const excludeIds = Array.from(new Set((params.excludeIds || []).map((id) => sanitizeString(id, 120)).filter(Boolean)));
    for (const appointment of Array.isArray(params.appointments) ? params.appointments : []) {
      const appointmentId = sanitizeString(appointment?.id, 120);
      const scheduledAt = buildAppointmentScheduledAt(appointment);
      const start = scheduledAt ? new Date(scheduledAt) : null;
      const patientId = sanitizeString(appointment?.patient_id || appointment?.patientId, 120);
      const professionalId = sanitizeString(
        appointment?.professional_id || appointment?.professionalId || appointment?.therapist_id || appointment?.therapistId,
        120
      );
      const roomId = sanitizeString(appointment?.room_id || appointment?.roomId || appointment?.room, 180);
      const locationType = normalizeScheduleLocationType(appointment?.location_type || appointment?.locationType || appointment?.location || (roomId ? 'clinica' : ''));
      if (!isUuid(clinicId) || !isUuid(patientId) || !start || Number.isNaN(start.getTime())) continue;
      const date = sanitizeDate(appointment?.date) || formatDateInAppointmentTimezone(start);
      const startTime = normalizeAppointmentTime(appointment?.time) || formatTimeInAppointmentTimezone(start);
      const durationMinutes = getClinicStateAppointmentDurationMinutes(appointment, {});
      const result = await checkScheduleConflicts({
        clinic_id: clinicId,
        organization_id: sanitizeString(appointment?.organization_id || appointment?.organizationId || clinicId, 120),
        patient_id: patientId,
        patient_name: appointment?.patient_name || appointment?.patientName || appointment?.name,
        professional_ids: professionalId ? [professionalId] : [],
        professional_names: [appointment?.professional_name || appointment?.professionalName || appointment?.therapist_name || appointment?.therapistName || appointment?.professional]
          .map((value) => sanitizeString(value, 180))
          .filter(Boolean),
        room_id: locationType === 'clinica' ? roomId : null,
        room_name: appointment?.room_name || appointment?.roomName || appointment?.roomDisplayName || roomId,
        location_type: locationType,
        date,
        start_time: startTime,
        duration_minutes: durationMinutes,
        service_type: appointment?.service_type || appointment?.serviceType || appointment?.approach || appointment?.type,
        exclude_event_id: appointmentId,
        exclude_event_ids: Array.from(new Set([appointmentId, ...excludeIds])).filter(Boolean)
      }, params.user);
      if (result?.blocking) {
        return {
          ok: false,
          status: 409,
          appointmentId,
          conflict: result,
          error: result.humanMessage || 'Já existe atendimento conflitante no mesmo horário para este paciente, profissional, especialidade ou sala.'
        };
      }
    }
    return { ok: true, status: 200 };
  };

  const readAppointmentPatientTissAuthorizationId = (appointment: any) =>
    sanitizeString(
      appointment?.patientTissAuthorizationId ||
        appointment?.patient_tiss_authorization_id ||
        appointment?.authorizationId ||
        appointment?.authorization_id,
      120
    );

  const validateAppointmentTissAuthorizationsForWrite = async (params: {
    appointments: any[];
    clinicId: string;
  }) => {
    const clinicId = sanitizeString(params.clinicId, 120);
    const selected: Array<{ appointmentId: string; authorizationId: string; available: number | null }> = [];

    for (const appointment of Array.isArray(params.appointments) ? params.appointments : []) {
      const authorizationId = readAppointmentPatientTissAuthorizationId(appointment);
      if (!authorizationId) continue;
      const appointmentId = sanitizeString(appointment?.id, 120);
      if (!isUuid(authorizationId)) {
        return {
          ok: false,
          status: 400,
          error: 'A autorização selecionada é inválida.'
        };
      }
      const patientId = sanitizeString(appointment?.patient_id || appointment?.patientId, 120);
      const options = await listAppointmentTissAuthorizationOptionsForBilling({
        organizationId: clinicId,
        patientId,
        payerId: appointment?.payerId || appointment?.payer_id,
        payerName: appointment?.payerName || appointment?.payer_name_snapshot || appointment?.payerNameSnapshot,
        serviceType: appointment?.serviceType || appointment?.service_type || appointment?.approach || appointment?.type,
        procedureCode: appointment?.procedureCode || appointment?.procedure_code,
        appointmentDate: appointment?.scheduled_start_at || appointment?.scheduled_at || appointment?.date,
        currentAppointmentId: appointmentId
      });
      const match = options.find((authorization: any) =>
        sanitizeString(authorization?.authorizationId || authorization?.patientTissAuthorizationId, 120) === authorizationId
      );
      if (!match) {
        return {
          ok: false,
          status: 409,
          error: 'Esta autorização não está disponível para a data, convênio ou procedimento da sessão.'
        };
      }
      if (!match?.canUseForAppointment && !match?.isEligibleForAppointment) {
        return {
          ok: false,
          status: 409,
          error: match?.availabilityGroup === 'no_balance'
            ? 'Esta autorização não possui saldo disponível.'
            : match?.unavailableReason || 'Esta autorização não está disponível para a data, convênio ou procedimento da sessão.'
        };
      }
      const availableValue = match?.quantityAvailable ?? match?.availableQuantity ?? match?.balance;
      selected.push({
        appointmentId,
        authorizationId,
        available: Number.isFinite(Number(availableValue)) ? Number(availableValue) : null
      });
    }

    const byAuthorization = new Map<string, { count: number; available: number | null }>();
    for (const item of selected) {
      const current = byAuthorization.get(item.authorizationId) || { count: 0, available: item.available };
      current.count += 1;
      if (item.available !== null) current.available = current.available === null ? item.available : Math.min(current.available, item.available);
      byAuthorization.set(item.authorizationId, current);
    }
    for (const entry of byAuthorization.values()) {
      if (entry.available !== null && entry.count > entry.available) {
        return {
          ok: false,
          status: 409,
          error: 'Esta autorização não possui saldo disponível para todas as sessões selecionadas.'
        };
      }
    }
    return { ok: true, status: 200 };
  };

  const writeClinicStateAppointmentsAfterPersistence = async (clinicId: string, actorId: string, previousAppointments: any[], persistedAppointments: any[]) => {
    const nextAppointments = mergeClinicStateAppointmentsById(previousAppointments, persistedAppointments);
    const basePayload = {
      clinic_id: clinicId,
      appointments: nextAppointments,
      updated_at: new Date().toISOString()
    };
    const writeState = (includeUpdatedBy: boolean) =>
      supabase
        .from('clinic_state')
        .upsert([{
          ...basePayload,
          ...(includeUpdatedBy ? { updated_by: actorId } : {})
        }], { onConflict: 'clinic_id' })
        .select('appointments')
        .single();
    let result = await writeState(true);
    if (result.error && extractMissingColumnName(result.error) === 'updated_by') {
      result = await writeState(false);
    }
    if (result.error) {
      console.warn('[Appointments] clinic_state mirror ignored after durable persistence.', {
        clinicId,
        appointmentIds: persistedAppointments.map((appointment: any) => sanitizeString(appointment?.id, 120)).filter(Boolean),
        message: extractSupabaseErrorMessage(result.error),
        code: sanitizeString(result.error?.code, 40) || null
      });
      return nextAppointments;
    }
    const confirmedStateAppointments = Array.isArray(result.data?.appointments) ? result.data.appointments : [];
    const confirmedIds = new Set(confirmedStateAppointments.map((appointment: any) => sanitizeString(appointment?.id, 120)).filter(Boolean));
    const allConfirmed = persistedAppointments.every((appointment: any) => confirmedIds.has(sanitizeString(appointment?.id, 120)));
    if (!allConfirmed) {
      console.warn('[Appointments] clinic_state mirror did not echo all durable appointments.', {
        clinicId,
        appointmentIds: persistedAppointments.map((appointment: any) => sanitizeString(appointment?.id, 120)).filter(Boolean)
      });
      return nextAppointments;
    }
    return confirmedStateAppointments;
  };

  const persistAppointmentDomainEvents = async (params: {
    eventType: string;
    appointments: any[];
    actor: any;
    clinicId: string;
    idempotencyKey: string;
    payload?: Record<string, any>;
  }) => {
    const actorId = sanitizeString(params.actor?.id, 120);
    const rows = (params.appointments || [])
      .map((appointment) => {
        const appointmentId = sanitizeString(appointment?.id, 120);
        if (!isUuid(appointmentId)) return null;
        return cleanObject({
          id: crypto.randomUUID(),
          organization_id: params.clinicId,
          clinic_id: params.clinicId,
          patient_id: isUuid(sanitizeString(appointment?.patient_id || appointment?.patientId, 120))
            ? sanitizeString(appointment?.patient_id || appointment?.patientId, 120)
            : null,
          professional_id: isUuid(sanitizeString(appointment?.therapist_id || appointment?.therapistId || appointment?.professional_id || appointment?.professionalId, 120))
            ? sanitizeString(appointment?.therapist_id || appointment?.therapistId || appointment?.professional_id || appointment?.professionalId, 120)
            : null,
          appointment_id: appointmentId,
          event_type: sanitizeString(params.eventType, 80),
          idempotency_key: `${sanitizeString(params.idempotencyKey, 220)}:${params.eventType}:${appointmentId}`,
          created_by: isUuid(actorId) ? actorId : null,
          payload: sanitizeClinicalPayload({
            source: 'appointment_action',
            status: appointment?.status || null,
            careSetting: appointment?.care_setting || appointment?.careSetting || null,
            schoolId: appointment?.school_id || appointment?.schoolId || null,
            schoolUnitId: appointment?.school_unit_id || appointment?.schoolUnitId || null,
            locationNameSnapshot: appointment?.location_name_snapshot || appointment?.locationNameSnapshot || null,
            locationSource: appointment?.location_source || appointment?.locationSource || null,
            ...params.payload,
          }),
          created_at: new Date().toISOString()
        });
      })
      .filter(Boolean) as any[];

    if (rows.length === 0) return [];
    try {
      const result = await supabase
        .from('appointment_domain_events')
        .upsert(rows, { onConflict: 'idempotency_key' })
        .select('id, event_type, clinic_id, patient_id, professional_id, appointment_id, created_by, idempotency_key, payload, created_at');
      if (!result.error) {
        return (result.data || rows).map((row: any) => ({
          eventId: sanitizeString(row?.id, 120),
          eventType: sanitizeString(row?.event_type || params.eventType, 80),
          clinicId: sanitizeString(row?.clinic_id || params.clinicId, 120) || null,
          patientId: sanitizeString(row?.patient_id, 120) || null,
          professionalId: sanitizeString(row?.professional_id, 120) || null,
          appointmentId: sanitizeString(row?.appointment_id, 120),
          createdBy: sanitizeString(row?.created_by, 120) || null,
          idempotencyKey: sanitizeString(row?.idempotency_key, 240),
          payload: row?.payload || {},
          createdAt: sanitizeString(row?.created_at, 80) || new Date().toISOString()
        }));
      }
      if (!isMissingRelationError(result.error)) throw result.error;
    } catch (error: any) {
      if (!isMissingRelationError(error)) {
        console.warn('[Appointments] Falha ao persistir eventos de dominio.', sanitizeString(error?.message || String(error), 300));
      }
    }

    for (const row of rows) {
      void persistActivityLog({
        userId: actorId || '',
        clinicId: params.clinicId,
        actorName: sanitizeString(params.actor?.name || params.actor?.email || 'Equipe', 180),
        title: 'Evento de agenda',
        content: `Evento ${row.event_type} confirmado para sessão.`,
        type: 'management',
        actionType: row.event_type,
        payloadDetails: JSON.stringify({
          eventId: row.id,
          eventType: row.event_type,
          appointmentId: row.appointment_id,
          patientId: row.patient_id,
          professionalId: row.professional_id,
          idempotencyKey: row.idempotency_key
        })
      });
    }
    return rows.map((row: any) => ({
      eventId: row.id,
      eventType: row.event_type,
      clinicId: row.clinic_id,
      patientId: row.patient_id || null,
      professionalId: row.professional_id || null,
      appointmentId: row.appointment_id,
      createdBy: row.created_by || null,
      idempotencyKey: row.idempotency_key,
      payload: row.payload || {},
      createdAt: row.created_at
    }));
  };

  const fetchPersistedAppointmentActionByIdempotencyKey = async (params: {
    clinicId: string;
    eventType: string;
    idempotencyKey: string;
  }) => {
    const clinicId = sanitizeString(params.clinicId, 120);
    const eventType = sanitizeString(params.eventType, 80);
    const idempotencyKey = sanitizeString(params.idempotencyKey, 220);
    if (!isUuid(clinicId) || !eventType || !idempotencyKey) return null;
    try {
      const { data, error } = await supabase
        .from('appointment_domain_events')
        .select('id, event_type, clinic_id, patient_id, professional_id, appointment_id, created_by, idempotency_key, payload, created_at')
        .eq('clinic_id', clinicId)
        .eq('event_type', eventType)
        .like('idempotency_key', `${idempotencyKey}:${eventType}:%`)
        .order('created_at', { ascending: true })
        .limit(80);
      if (error) {
        if (isMissingRelationError(error) || hasMissingFinancialSchema(error)) return null;
        throw error;
      }
      const events = Array.isArray(data) ? data : [];
      if (events.length === 0) return null;
      const appointmentIds = Array.from(new Set(
        events
          .map((row: any) => sanitizeString(row?.appointment_id, 120))
          .filter((id: string) => isUuid(id))
      ));
      if (appointmentIds.length === 0) return null;
      const persistedRows = await readPersistedAppointmentRows(appointmentIds, clinicId);
      if (persistedRows.length === 0) return null;
      const appointments = persistedRows.map((row: any) => serializePersistedAppointmentForAgenda(row));
      return {
        appointments,
        events: events.map((row: any) => ({
          eventId: sanitizeString(row?.id, 120),
          eventType: sanitizeString(row?.event_type || eventType, 80),
          clinicId: sanitizeString(row?.clinic_id || clinicId, 120),
          patientId: sanitizeString(row?.patient_id, 120) || null,
          professionalId: sanitizeString(row?.professional_id, 120) || null,
          appointmentId: sanitizeString(row?.appointment_id, 120),
          createdBy: sanitizeString(row?.created_by, 120) || null,
          idempotencyKey: sanitizeString(row?.idempotency_key, 240),
          payload: row?.payload || {},
          createdAt: sanitizeString(row?.created_at, 80) || null
        }))
      };
    } catch (error: any) {
      console.warn('[Appointments] Consulta idempotente de eventos ignorada.', sanitizeString(error?.message || String(error), 300));
      return null;
    }
  };

  const persistAppointmentActionBatch = async (params: {
    req: any;
    res: any;
    rawAppointments: any[];
    eventType: string;
    requireExisting?: boolean;
    pathAppointmentId?: string;
  }) => {
    const { req, res } = params;
    const actor = req.session.user;
    const actorId = sanitizeString(actor?.id, 120);
    const clinicId = sanitizeString(currentClinicId(actor), 120);
    if (!isUuid(clinicId)) {
      return res.status(400).json({ success: false, error: 'Clínica inválida para agendamento.' });
    }

    const MAX_APPOINTMENT_BATCH_SIZE = 120;
    const rawAppointmentInput = Array.isArray(params.rawAppointments) ? params.rawAppointments : [];
    if (rawAppointmentInput.length === 0) {
      return res.status(400).json({ success: false, error: 'Nenhum agendamento enviado.' });
    }
    if (rawAppointmentInput.length > MAX_APPOINTMENT_BATCH_SIZE) {
      return res.status(400).json({
        success: false,
        error: `O lote possui ${rawAppointmentInput.length} agendamentos. O limite por confirmação é ${MAX_APPOINTMENT_BATCH_SIZE}.`,
      });
    }
    const rawAppointments = rawAppointmentInput.slice();

    const existingRowsForPreparation = params.requireExisting
      ? await readPersistedAppointmentRows(
          rawAppointments.map((appointment: any) => sanitizeString(appointment?.id, 120)),
          clinicId,
        )
      : [];
    const existingById = new Map(
      existingRowsForPreparation.map((appointment: any) => [sanitizeString(appointment?.id, 120), appointment]),
    );
    const preparedAppointments: any[] = [];
    for (const rawAppointment of rawAppointments) {
      const prepared = await prepareAppointmentForWrite(
        rawAppointment,
        actor,
        clinicId,
        existingById.get(sanitizeString(rawAppointment?.id, 120)) || null,
      );
      if (!prepared.ok) {
        return res.status((prepared as any).status || 400).json({ success: false, error: (prepared as any).error });
      }
      const preparedAppointment = (prepared as any).appointment;
      const financialValidation = await validateAppointmentFinancialContextForWrite(preparedAppointment, clinicId);
      if (!financialValidation.ok) {
        return res.status((financialValidation as any).status || 400).json({
          success: false,
          error: (financialValidation as any).error || APPOINTMENT_FINANCIAL_CONTEXT_ERROR
        });
      }
      preparedAppointments.push(preparedAppointment);
    }

    const privatePricingValidation = await validatePrivateAppointmentPricingBatch(
      preparedAppointments,
      clinicId,
      actorId
    );
    if (!privatePricingValidation.ok) {
      return res.status(privatePricingValidation.status).json({
        success: false,
        error: privatePricingValidation.error
      });
    }
    const privateRescheduleValidation = await validatePrivateLateCancellationRescheduleBatch({
      appointments: preparedAppointments,
      existingById,
      clinicId,
      canManageFinance: req.authorizationContext?.capabilities?.has('finance.entries.manage') === true
    });
    if (!privateRescheduleValidation.ok) {
      return res.status(privateRescheduleValidation.status).json({
        success: false,
        error: privateRescheduleValidation.error
      });
    }
    const privateResolutionByAppointmentId = new Map(
      privatePricingValidation.resolutions.map((resolution: any) => [
        sanitizeString(resolution?.appointment_id, 120),
        resolution
      ])
    );
    for (const appointment of preparedAppointments) {
      if (readAppointmentFinancialContextType(mergeAppointmentBillingPayload(appointment)) !== 'PRIVATE') continue;
      const resolution = privateResolutionByAppointmentId.get(sanitizeString(appointment?.id, 120));
      if (!resolution) continue;
      appointment.privatePricingResolution = resolution;
      appointment.private_pricing_resolution = resolution;
    }

    const appointmentIds = preparedAppointments.map((appointment) => sanitizeString(appointment?.id, 120));
    const pathAppointmentId = sanitizeString(params.pathAppointmentId, 120);
    if (pathAppointmentId && !appointmentIds.includes(pathAppointmentId)) {
      return res.status(400).json({ success: false, error: 'A sessão editada não foi enviada para persistência.' });
    }

    const idempotencyKey = sanitizeString(
      req.body?.idempotencyKey || req.body?.idempotency_key || req.headers?.['x-idempotency-key'] || `${params.eventType}:${crypto.randomUUID()}`,
      240
    );
    const appointmentRequestHash = stableHashPayload(
      preparedAppointments.map((appointment: any) => ({
        ...appointment,
        privatePricingResolution: undefined,
        private_pricing_resolution: undefined
      }))
    );
    const previousAction = await fetchPersistedAppointmentActionByIdempotencyKey({
      clinicId,
      eventType: params.eventType,
      idempotencyKey
    });
    if (previousAction?.appointments?.length) {
      const previousRequestHash = sanitizeString(previousAction.events?.[0]?.payload?.requestHash, 128);
      if (previousRequestHash && previousRequestHash !== appointmentRequestHash) {
        return res.status(409).json({
          success: false,
          error: 'Esta chave de idempotência já foi usada com outro conteúdo. Gere uma nova tentativa sem alterar o payload anterior.'
        });
      }
      const action = params.eventType === 'appointment.created' ? 'created' : 'updated';
      return res.json({
        success: true,
        action,
        appointments: previousAction.appointments,
        items: previousAction.appointments,
        events: previousAction.events,
        idempotent: true,
        affected: {
          clinicId,
          organizationId: clinicId,
          appointmentIds: previousAction.appointments.map((appointment: any) => sanitizeString(appointment?.id, 120)).filter(Boolean),
          count: previousAction.appointments.length
        }
      });
    }

    const state = await readClinicStateForAppointmentMutation(clinicId);
    let existingRows: any[] = [];
    if (params.requireExisting) {
      const existingStateIds = new Set(state.appointments.map((appointment: any) => sanitizeString(appointment?.id, 120)));
      existingRows = await readPersistedAppointmentRows(appointmentIds, clinicId);
      const existingTableIds = new Set(existingRows.map((row: any) => sanitizeString(row?.id, 120)));
      const missingExisting = appointmentIds.some((appointmentId) => !existingStateIds.has(appointmentId) && !existingTableIds.has(appointmentId));
      if (missingExisting) {
        return res.status(404).json({ success: false, error: 'Sessão não encontrada para edição.' });
      }
    }
    const previousAppointmentsById = new Map<string, any>();
    for (const appointment of state.appointments) {
      const appointmentId = sanitizeString(appointment?.id, 120);
      if (appointmentId) previousAppointmentsById.set(appointmentId, appointment);
    }
    for (const appointment of existingRows) {
      const appointmentId = sanitizeString(appointment?.id, 120);
      if (appointmentId) previousAppointmentsById.set(appointmentId, appointment);
    }
    const scheduleChangedAppointmentIds = new Set(
      preparedAppointments
        .filter((appointment: any) => {
          const previous = previousAppointmentsById.get(sanitizeString(appointment?.id, 120));
          const previousScheduledAt = buildAppointmentScheduledAt(previous);
          const nextScheduledAt = buildAppointmentScheduledAt(appointment);
          return Boolean(previousScheduledAt && nextScheduledAt && previousScheduledAt !== nextScheduledAt);
        })
        .map((appointment: any) => sanitizeString(appointment?.id, 120))
        .filter((appointmentId: string) => isUuid(appointmentId))
    );

    const nextAppointmentsForValidation = mergeClinicStateAppointmentsById(state.appointments, preparedAppointments);
    const scheduleValidation = await validateClinicStateAppointmentsForScheduleConflicts({
      clinicId,
      appointments: nextAppointmentsForValidation,
      rooms: state.rooms,
      specialtySettings: state.specialtySettings
    });
    if (!scheduleValidation.ok) {
      return res.status(scheduleValidation.status).json({ success: false, error: scheduleValidation.error });
    }

    const authorizationValidation = await validateAppointmentTissAuthorizationsForWrite({
      appointments: preparedAppointments,
      clinicId
    });
    if (!authorizationValidation.ok) {
      return res.status(authorizationValidation.status || 409).json({
        success: false,
        error: authorizationValidation.error || 'Esta autorização não está disponível para esta sessão.',
        conflict: true,
        conflictType: 'authorization'
      });
    }

    const durableConflictValidation = await validateDurableAppointmentConflictsForWrite({
      appointments: preparedAppointments,
      user: actor,
      clinicId,
      excludeIds: appointmentIds
    });
    if (!durableConflictValidation.ok) {
      return res.status(durableConflictValidation.status || 409).json({
        success: false,
        error: durableConflictValidation.error || 'Já existe atendimento no mesmo horário.',
        conflict: durableConflictValidation.conflict || null,
        duplicateGuard: true
      });
    }

    const mirror = await syncAppointmentsTableFromClinicState({
      clinicId,
      appointments: preparedAppointments,
      actorId,
      specialtySettings: state.specialtySettings,
      onAppointmentMirrored: (context) => flagPendingMaintenanceProbesForAppointment(context)
    });
    if (mirror.mirrored < appointmentIds.length) {
      return res.status(500).json({ success: false, error: 'Não foi possível confirmar a persistência do agendamento.' });
    }

    const persistedRows = await readPersistedAppointmentRows(appointmentIds, clinicId);
    if (!confirmPersistedAppointmentRows(persistedRows, preparedAppointments, clinicId)) {
      return res.status(500).json({ success: false, error: 'Não foi possível confirmar a persistência do agendamento.' });
    }

    const persistedAppointments = persistedRows.map((row: any) => serializePersistedAppointmentForAgenda(row));
    const clinicStateAppointments = await writeClinicStateAppointmentsAfterPersistence(
      clinicId,
      actorId,
      state.appointments,
      persistedAppointments
    );
    const events = await persistAppointmentDomainEvents({
      eventType: params.eventType,
      appointments: persistedAppointments,
      actor,
      clinicId,
      idempotencyKey,
      payload: { appointmentIds, requestHash: appointmentRequestHash }
    });
    if (scheduleChangedAppointmentIds.size > 0) {
      try {
        await acknowledgeStaleAppointmentReminderNotifications(
          persistedRows.filter((appointment: any) => scheduleChangedAppointmentIds.has(sanitizeString(appointment?.id, 120)))
        );
      } catch (error: any) {
        console.warn('[Appointments] Lembretes do horario anterior nao puderam ser baixados.', {
          clinicId,
          appointmentIds: Array.from(scheduleChangedAppointmentIds),
          message: sanitizeString(error?.message || String(error), 300)
        });
      }
    }

    const preparedById = new Map(preparedAppointments.map((appointment: any) => [sanitizeString(appointment?.id, 120), appointment]));
    const revalidatedIds = new Set<string>();
    for (const appointment of persistedAppointments) {
      const appointmentId = sanitizeString(appointment?.id, 120);
      if (!isUuid(appointmentId)) continue;
      try {
        const preparedAppointment = preparedById.get(appointmentId) || {};
        const existingSourcePayload =
          appointment?.source_payload && typeof appointment.source_payload === 'object' && !Array.isArray(appointment.source_payload)
            ? appointment.source_payload
            : {};
        const revalidation = await runTissPipelineForAppointment({
          appointmentId,
          user: actor,
          scopedAppointment: {
            ...appointment,
            ...preparedAppointment,
            source_payload: {
              ...existingSourcePayload,
              ...preparedAppointment
            }
          },
          reason: params.eventType === 'appointment.created' ? 'appointment_created' : 'appointment_updated',
          mode: 'best_effort',
          revalidateAppointment: revalidateAppointmentBillingForAppointment,
          overwriteExplicitContext: true,
          forceClosure: true
        });
        if ((revalidation as any)?.ok) revalidatedIds.add(appointmentId);
      } catch (error: any) {
        console.warn('[Appointments] revalidação TUSS-ready pós-agendamento falhou:', {
          appointmentId,
          eventType: params.eventType,
          message: sanitizeString(error?.message || String(error), 300)
        });
      }
    }
    const pendingClosureIds = appointmentIds.filter((appointmentId) => !revalidatedIds.has(appointmentId));
    if (pendingClosureIds.length > 0) void regenerateClosureForAppointments(pendingClosureIds, actor, params.eventType);
    triggerAppointmentReminderScan(params.eventType);

    const action = params.eventType === 'appointment.created' ? 'created' : 'updated';
    const affected = {
      clinicId,
      organizationId: clinicId,
      patientId: persistedAppointments[0]?.patientId || persistedAppointments[0]?.patient_id || null,
      patientIds: Array.from(new Set(persistedAppointments.map((appointment: any) => sanitizeString(appointment?.patientId || appointment?.patient_id, 120)).filter(Boolean))),
      professionalId: persistedAppointments[0]?.professionalId || persistedAppointments[0]?.professional_id || persistedAppointments[0]?.therapistId || null,
      professionalIds: Array.from(new Set(persistedAppointments.map((appointment: any) => sanitizeString(appointment?.professionalId || appointment?.professional_id || appointment?.therapistId || appointment?.therapist_id, 120)).filter(Boolean))),
      date: persistedAppointments[0]?.date || null,
      appointmentIds,
      queryKeys: ['appointments']
    };

    return res.json(buildActionResultPayload({
      entity: 'appointment',
      action,
      item: persistedAppointments[0] || null,
      items: persistedAppointments,
      affected,
      events,
      legacy: {
        appointment: persistedAppointments[0] || null,
        appointments: persistedAppointments,
        clinicStateAppointments
      }
    }));
  };

  app.post('/api/appointments', checkAuth, requireClinicCapability('calendar.appointment.create'), async (req: any, res: any) => {
    try {
      return await persistAppointmentActionBatch({
        req,
        res,
        rawAppointments: Array.isArray(req.body?.appointments) ? req.body.appointments : [req.body?.appointment].filter(Boolean),
        eventType: 'appointment.created'
      });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/appointments [POST]', error, {
        requestId: requestIdForLogs(req)
      });
    }
  });

  app.patch('/api/appointments/:appointmentId', checkAuth, requireClinicCapability('calendar.appointment.edit'), async (req: any, res: any) => {
    try {
      return await persistAppointmentActionBatch({
        req,
        res,
        rawAppointments: Array.isArray(req.body?.appointments) ? req.body.appointments : [req.body?.appointment].filter(Boolean),
        eventType: 'appointment.updated',
        requireExisting: true,
        pathAppointmentId: req.params.appointmentId
      });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/appointments/:appointmentId [PATCH]', error, {
        appointmentId: sanitizeString(req.params.appointmentId, 120),
        requestId: requestIdForLogs(req)
      });
    }
  });

  const handleVapidPublicKey = (_req: any, res: any) => {
    if (!vapidPublicKey || !vapidPrivateKey) {
      return res.status(503).json({
        success: false,
        error: 'VAPID_NOT_CONFIGURED',
        message: 'Chaves VAPID ausentes no backend.'
      });
    }
    return res.json({ success: true, publicKey: vapidPublicKey });
  };

  const handlePushSubscribe = async (req: any, res: any) => {
    try {
      const subscription = req.body?.subscription || req.body;
      const endpoint = sanitizeString(subscription?.endpoint, 2000);
      if (!endpoint || !subscription?.keys?.p256dh || !subscription?.keys?.auth) {
        return res.status(400).json({ success: false, error: 'Inscrição push inválida.' });
      }

      const user = req.session.user;
      const role = sanitizeString(user?.role, 40).toLowerCase();
      const isPatientRole = role === 'patient';
      if (role !== 'patient') {
        return res.status(403).json({
          success: false,
          error: 'Notificações push de sessão são exclusivas do login do paciente.'
        });
      }

      const requestedPatientId = sanitizeString(req.body?.patientId || req.body?.patient_id, 120);
      const requestedPatientEmail = sanitizeEmail(req.body?.patientEmail || req.body?.patient_email || user?.email);
      const sessionClinicId = currentClinicId(user);
      const lookupClinicId = isPatientRole ? null : sessionClinicId;
      console.log('[Push] subscribe received.', {
        role,
        authUserId: sanitizeString(user?.id, 120) || null,
        authEmail: sanitizeEmail(user?.email) || null,
        requestedPatientId: requestedPatientId || null,
        requestedPatientEmail: requestedPatientEmail || null,
        clinicId: lookupClinicId,
        endpointPrefix: endpoint.slice(0, 80)
      });

      const patientIds = await resolvePatientIdsForPush({
        supabase,
        patientId: requestedPatientId,
        patientEmail: requestedPatientEmail,
        userId: sanitizeString(user?.id, 120),
        clinicId: lookupClinicId,
        logger: console
      });
      const patientId = patientIds[0];

      if (!patientId) {
        console.warn('[Push] subscribe patient not found.', {
          authUserId: sanitizeString(user?.id, 120) || null,
          authEmail: sanitizeEmail(user?.email) || null,
          requestedPatientId: requestedPatientId || null,
          requestedPatientEmail: requestedPatientEmail || null,
          clinicId: lookupClinicId
        });
        return res.status(409).json({
          success: false,
          error: 'Não encontrei o cadastro de paciente vinculado a este login. Verifique se o e-mail do paciente na clínica é o mesmo usado no app.'
        });
      }

      let resolvedPatientClinicId = sessionClinicId;
      if (!resolvedPatientClinicId && isUuid(patientId)) {
        const { data: patientRow, error: patientClinicError } = await supabase
          .from('patients')
          .select('id, clinic_id')
          .eq('id', patientId)
          .maybeSingle();

        if (patientClinicError) {
          console.warn('[Push] Não foi possível resolver clinic_id pelo cadastro do paciente.', {
            patientId,
            message: patientClinicError.message || String(patientClinicError)
          });
        } else {
          resolvedPatientClinicId = sanitizeString(patientRow?.clinic_id, 120) || null;
        }
      }

      console.log('[Push] subscribe resolved patient clinic.', {
        patientId,
        sessionClinicId,
        resolvedPatientClinicId
      });

      const renewalToken = crypto.randomBytes(32).toString('base64url');
      const result = await savePatientPushSubscription({
        supabase,
        deploymentEnv: vertoDeploymentEnv,
        subscription,
        patientId,
        userId: sanitizeString(user?.id, 120),
        userEmail: sanitizeEmail(user?.email),
        clinicId: sessionClinicId,
        resolvedPatientClinicId,
        role,
        renewalToken,
        logger: console
      });

      if (!result.success) {
        console.warn('[Push] Não foi possível persistir assinatura push:', result.error);
        return res.status(500).json({ success: false, error: result.error || 'Erro ao salvar inscrição push.' });
      }

      console.log('[Push] subscribe persisted.', {
        patientId,
        clinicId: resolvedPatientClinicId,
        authUserId: sanitizeString(user?.id, 120) || null,
        endpointPrefix: endpoint.slice(0, 80)
      });

      return res.json({
        success: true,
        patientId,
        ...(result.renewalTokenPersisted ? { renewalToken } : {}),
      });
    } catch (error: any) {
      console.error('[Push] subscribe error:', error?.message || String(error));
      return res.status(500).json({ success: false, error: 'Erro ao salvar inscrição push.' });
    }
  };

  const handlePushUnsubscribe = async (req: any, res: any) => {
    try {
      const user = req.session.user;
      if (sanitizeString(user?.role, 40).toLowerCase() !== 'patient') {
        return res.status(403).json({ success: false, error: 'PUSH_UNSUBSCRIBE_ROLE_DENIED' });
      }
      const actorUserId = sanitizeString(user?.id, 120);
      const subscription = req.body?.subscription || req.body;
      const endpoint = sanitizeString(subscription?.endpoint, 2000);
      if (!isUuid(actorUserId) || !endpoint) {
        return res.status(400).json({ success: false, error: 'PUSH_UNSUBSCRIBE_SCOPE_INVALID' });
      }
      // Look up only the signed-in user's endpoint, never resolve a patient from
      // user-controlled IDs or email. Idempotent when absent.
      const { data: owned, error: lookupError } = await supabase
        .from('push_subscriptions')
        .select('patient_id')
        .eq('deployment_env', vertoDeploymentEnv)
        .eq('user_id', actorUserId)
        .eq('endpoint', endpoint)
        .maybeSingle();
      if (lookupError) return res.status(503).json({ success: false, error: 'PUSH_UNSUBSCRIBE_LOOKUP_FAILED' });
      if (!owned?.patient_id) return res.json({ success: true });
      const result = await removePatientPushSubscription({
        supabase,
        deploymentEnv: vertoDeploymentEnv,
        patientId: String(owned.patient_id),
        actorUserId,
        endpoint
      });
      if (!result.success) return res.status(503).json({ success: false, error: result.error });
      return res.json({ success: true });
    } catch (_error: any) {
      return res.status(500).json({ success: false, error: 'Erro ao remover inscrição push.' });
    }
  };

  const handlePushRenew = async (req: any, res: any) => {
    try {
      const renewalToken = sanitizeString(req.body?.renewalToken || req.body?.renewal_token, 200);
      const subscription = req.body?.subscription;
      const oldEndpoint = sanitizeString(req.body?.oldEndpoint || req.body?.old_endpoint, 2000);
      const endpoint = sanitizeString(subscription?.endpoint, 2000);
      if (!renewalToken || !endpoint || !subscription?.keys?.p256dh || !subscription?.keys?.auth) {
        return res.status(400).json({ success: false, error: 'PUSH_RENEWAL_INVALID' });
      }
      const result = await renewPatientPushSubscription({
        supabase,
        deploymentEnv: vertoDeploymentEnv,
        renewalToken,
        subscription,
        oldEndpoint,
        logger: console,
      });
      if (!result.success) {
        return res.status(result.status || 500).json({ success: false, error: result.error });
      }
      res.setHeader('Cache-Control', 'no-store');
      return res.json({ success: true, renewalToken: result.renewalToken });
    } catch (error: any) {
      console.error('[Push] renewal error:', error?.message || String(error));
      return res.status(500).json({ success: false, error: 'PUSH_RENEWAL_FAILED' });
    }
  };

  app.get('/api/push/vapid-public-key', handleVapidPublicKey);
  app.get('/api/notifications/vapid-key', handleVapidPublicKey);
  app.post('/api/push/renew', pushRenewalLimiter, handlePushRenew);
  app.post('/api/push/subscribe', checkAuth, handlePushSubscribe);
  app.post('/api/notifications/subscribe', checkAuth, handlePushSubscribe);
  app.delete('/api/push/subscribe', checkAuth, handlePushUnsubscribe);
  app.delete('/api/notifications/subscribe', checkAuth, handlePushUnsubscribe);

  const processOfferItemDiscountNotifications = async (now: Date) => {
    const { data: dueRows, error: dueError } = await supabase
      .from("sales_discount_notifications")
      .select("id,offer_id,offer_item_discount_id,notification_window_days,notification_type,idempotency_key")
      .not("offer_item_discount_id", "is", null)
      .in("status", ["pending", "failed"])
      .lte("scheduled_for", now.toISOString())
      .order("scheduled_for", { ascending: true })
      .limit(250);
    if (dueError) throw dueError;
    if (!dueRows?.length) return { scanned: 0, sent: 0, failed: 0 };

    const discountIds = Array.from(new Set(dueRows.map((row: any) => row.offer_item_discount_id)));
    const { data: discounts, error: discountError } = await supabase
      .from("sales_offer_item_discounts")
      .select("id,offer_id,offer_item_id,item_key,ends_at,price_after_expiration_cents,status")
      .in("id", discountIds);
    if (discountError) throw discountError;
    const discountById = new Map((discounts || []).map((row: any) => [row.id, row]));
    const offerIds = Array.from(new Set((discounts || []).map((row: any) => row.offer_id)));
    const itemIds = Array.from(new Set((discounts || []).map((row: any) => row.offer_item_id).filter(Boolean)));
    const [offerResult, itemResult] = await Promise.all([
      supabase
        .from("sales_offers")
        .select("id,lead_id,created_by,status,accepted_at,expires_at,revoked_at")
        .in("id", offerIds),
      itemIds.length
        ? supabase
            .from("sales_offer_items")
            .select("id,public_name_snapshot")
            .in("id", itemIds)
        : Promise.resolve({ data: [], error: null }),
    ]);
    if (offerResult.error || itemResult.error) throw offerResult.error || itemResult.error;
    const offerById = new Map((offerResult.data || []).map((row: any) => [row.id, row]));
    const itemById = new Map((itemResult.data || []).map((row: any) => [row.id, row]));
    const leadIds = Array.from(new Set((offerResult.data || []).map((row: any) => row.lead_id)));
    const { data: leads, error: leadError } = await supabase
      .from("sales_leads")
      .select("id,name,email,normalized_email,assigned_owner_id")
      .in("id", leadIds)
      .is("deleted_at", null);
    if (leadError) throw leadError;
    const leadById = new Map((leads || []).map((row: any) => [row.id, row]));
    const ownerIds = Array.from(new Set([
      sanitizeString(process.env.SALES_OWNER_USER_ID, 120),
      ...(offerResult.data || []).map((row: any) => sanitizeString(row.created_by, 120)),
      ...(leads || []).map((row: any) => sanitizeString(row.assigned_owner_id, 120)),
    ].filter(isUuid)));
    const { data: owners, error: ownerError } = ownerIds.length
      ? await supabase.from("users").select("id,name,email").in("id", ownerIds)
      : { data: [], error: null };
    if (ownerError) throw ownerError;
    const ownerById = new Map((owners || []).map((row: any) => [row.id, row]));

    let sent = 0;
    let failed = 0;
    for (const due of dueRows) {
      const pendingDiscount: any = discountById.get(due.offer_item_discount_id);
      const pendingOffer: any = pendingDiscount ? offerById.get(pendingDiscount.offer_id) : null;
      if (!pendingOffer || sanitizeString(pendingOffer.status, 40) !== "paid") {
        await supabase
          .from("sales_discount_notifications")
          .update({ status: "cancelled", updated_at: new Date().toISOString() })
          .eq("id", due.id)
          .in("status", ["pending", "failed"]);
        continue;
      }
      const { data: claimed } = await supabase
        .from("sales_discount_notifications")
        .update({ status: "processing", updated_at: new Date().toISOString() })
        .eq("id", due.id)
        .in("status", ["pending", "failed"])
        .select("id")
        .maybeSingle();
      if (!claimed) continue;
      const discount: any = discountById.get(due.offer_item_discount_id);
      const offer: any = discount ? offerById.get(discount.offer_id) : null;
      const lead: any = offer ? leadById.get(offer.lead_id) : null;
      if (!discount || !offer || !lead) {
        failed += 1;
        await supabase.from("sales_discount_notifications").update({
          status: "failed",
          email_error: "DISCOUNT_NOTIFICATION_CONTEXT_MISSING",
          updated_at: new Date().toISOString(),
        }).eq("id", due.id);
        continue;
      }
      const itemName = sanitizeString(
        itemById.get(discount.offer_item_id)?.public_name_snapshot,
        180,
      ) || "módulo contratado";
      const endLabel = new Date(discount.ends_at).toLocaleDateString("pt-BR");
      const priceLabel = new Intl.NumberFormat("pt-BR", {
        style: "currency",
        currency: "BRL",
      }).format(Number(discount.price_after_expiration_cents || 0) / 100);
      const windowDays = Number(due.notification_window_days);
      const timingText = windowDays > 0
        ? `termina em ${windowDays} dias, em ${endLabel}`
        : windowDays === 0
          ? `termina hoje, ${endLabel}`
          : `terminou em ${endLabel}; o preço normal já está vigente`;
      const recipientIds = Array.from(new Set([
        sanitizeString(offer.created_by, 120),
        sanitizeString(lead.assigned_owner_id, 120),
        sanitizeString(process.env.SALES_OWNER_USER_ID, 120),
      ].filter(isUuid)));
      try {
        const internalRecipients = recipientIds
          .map((id) => ownerById.get(id))
          .filter((owner: any) => sanitizeEmail(owner?.email));
        await Promise.all(internalRecipients.map((owner: any) =>
          sendTransactionalEmailSafe({
            to: sanitizeEmail(owner.email),
            subject: `Condição comercial de ${itemName}: ${timingText}`,
            html: `<div style="font-family:Arial,sans-serif;line-height:1.6;color:#1e293b"><h2>Condição comercial programada</h2><p>O benefício de <strong>${escapeHtml(itemName)}</strong> para ${escapeHtml(sanitizeString(lead.name, 180) || "o cliente")} ${escapeHtml(timingText)}.</p><p>Preço posterior: <strong>${escapeHtml(priceLabel)} por mês</strong>.</p><p>Esta comunicação contém somente dados comerciais.</p></div>`,
            context: "offer_item_discount_internal_notification",
            from: OFFICIAL_FROM_CONTACT,
            replyTo: OFFICIAL_TRANSACTIONAL_REPLY_TO,
            metadata: { idempotencyKey: `${due.idempotency_key}:internal:${owner.id}` },
          })
        ));
        const customerEmail = sanitizeEmail(lead.normalized_email || lead.email);
        const customerSent = customerEmail
          ? await sendTransactionalEmailSafe({
              to: customerEmail,
              subject: `Condição de ${itemName}: lembrete de encerramento`,
              html: `<div style="font-family:Arial,sans-serif;line-height:1.6;color:#1e293b"><h2>Sua condição comercial Verto</h2><p>O benefício do módulo <strong>${escapeHtml(itemName)}</strong> ${escapeHtml(timingText)}.</p><p>Depois do benefício, o valor contratado será <strong>${escapeHtml(priceLabel)} por mês</strong>. Se não quiser manter o módulo antes da primeira cobrança, fale com nossa equipe comercial.</p><p>Esta mensagem contém somente informações comerciais.</p></div>`,
              context: "offer_item_discount_customer_notification",
              from: OFFICIAL_FROM_CONTACT,
              replyTo: OFFICIAL_TRANSACTIONAL_REPLY_TO,
              metadata: { idempotencyKey: `${due.idempotency_key}:customer` },
            })
          : false;
        const completedAt = new Date().toISOString();
        await Promise.all([
          supabase.from("sales_lead_events").upsert(
            [{
              lead_id: lead.id,
              event_type: "lead_updated",
              metadata: {
                action: "offer_item_discount_notification_sent",
                offer_id: offer.id,
                item_key: discount.item_key,
                notification_window_days: windowDays,
              },
              idempotency_key: `offer-item-discount-notification:${due.id}`,
            }],
            { onConflict: "idempotency_key", ignoreDuplicates: true },
          ),
          supabase.from("sales_discount_notifications").update({
            status: "sent",
            internal_notification_sent_at: completedAt,
            email_sent_at: customerSent ? completedAt : null,
            email_error: customerEmail && !customerSent ? "CUSTOMER_EMAIL_NOT_SENT" : null,
            updated_at: completedAt,
          }).eq("id", due.id),
          windowDays < 0
            ? supabase.from("sales_offer_item_discounts").update({
                status: "expired",
                updated_at: completedAt,
              }).eq("id", discount.id).neq("status", "revoked")
            : Promise.resolve({ error: null }),
        ]);
        sent += 1;
      } catch (notificationError: any) {
        failed += 1;
        await supabase.from("sales_discount_notifications").update({
          status: "failed",
          email_error: sanitizeString(notificationError?.message || String(notificationError), 500),
          updated_at: new Date().toISOString(),
        }).eq("id", due.id);
      }
    }
    return { scanned: dueRows.length, sent, failed };
  };

  app.post('/api/internal/notifications/run-appointment-reminders', appointmentReminderCronLimiter, async (req: any, res) => {
    const configuredSecret = sanitizeString(
      process.env.APPOINTMENT_REMINDER_CRON_SECRET || process.env.CRON_SECRET || '',
      240
    );
    const providedSecret = sanitizeString(
      req.headers['x-internal-cron-secret'] || req.headers['x-cron-secret'] || '',
      240
    );
    const authorized = Boolean(
      configuredSecret &&
      providedSecret &&
      Buffer.byteLength(configuredSecret) === Buffer.byteLength(providedSecret) &&
      crypto.timingSafeEqual(Buffer.from(configuredSecret), Buffer.from(providedSecret))
    );
    if (!authorized) {
      return res.status(403).json({ success: false, error: 'Acesso negado.' });
    }

    const summary = await runAppointmentReminderScan('internal_endpoint');
    return res.json({ success: true, data: summary });
  });

  app.post(
    "/api/internal/notifications/run-discount-expiry",
    appointmentReminderCronLimiter,
    async (req: any, res) => {
      const configuredSecret = sanitizeString(
        process.env.BILLING_CRON_SECRET || process.env.CRON_SECRET || "",
        240,
      );
      const providedSecret = sanitizeString(
        req.headers["x-internal-cron-secret"] ||
          req.headers["x-cron-secret"] ||
          "",
        240,
      );
      const authorized = Boolean(
        configuredSecret &&
        providedSecret &&
        Buffer.byteLength(configuredSecret) ===
          Buffer.byteLength(providedSecret) &&
        crypto.timingSafeEqual(
          Buffer.from(configuredSecret),
          Buffer.from(providedSecret),
        ),
      );
      if (!authorized)
        return res
          .status(403)
          .json({ success: false, error: "Acesso negado." });

      const now = new Date();
      const upperBound = new Date(
        now.getTime() + 31 * 24 * 60 * 60 * 1000,
      ).toISOString();
      try {
        const { data: discounts, error } = await supabase
          .from("sales_subscription_discounts")
          .select(
            "id,user_id,clinic_id,stripe_subscription_id,discount_ends_at,next_billing_at,post_discount_unit_amount_cents,estimated_next_invoice_amount_cents,discount_status",
          )
          .eq("discount_status", "active")
          .not("discount_ends_at", "is", null)
          .lte("discount_ends_at", upperBound)
          .order("discount_ends_at", { ascending: true })
          .limit(500);
        if (error) throw error;

        const userIds = Array.from(
          new Set(
            (discounts || [])
              .map((item: any) => sanitizeString(item.user_id, 120))
              .filter(isUuid),
          ),
        );
        let usersById = new Map<string, any>();
        if (userIds.length > 0) {
          const { data: users } = await supabase
            .from("users")
            .select("id,name,email")
            .in("id", userIds);
          usersById = new Map(
            (users || []).map((user: any) => [
              sanitizeString(user.id, 120),
              user,
            ]),
          );
        }

        const candidateRows: any[] = [];
        for (const discount of discounts || []) {
          const endAt = new Date(String(discount.discount_ends_at || ""));
          if (!Number.isFinite(endAt.getTime())) continue;
          const daysRemaining = Math.ceil(
            (endAt.getTime() - now.getTime()) / (24 * 60 * 60 * 1000),
          );
          if (
            !DISCOUNT_EXPIRY_NOTIFICATION_DAYS.includes(
              daysRemaining as 30 | 7 | 1,
            )
          )
            continue;
          const window = `${daysRemaining}d`;
          candidateRows.push({
            subscription_discount_id: discount.id,
            notification_window: window,
            idempotency_key: `${discount.stripe_subscription_id}:${endAt.toISOString()}:${window}`,
          });
        }

        const modularNotifications = await processOfferItemDiscountNotifications(now);
        if (candidateRows.length === 0) {
          return res.json({
            success: true,
            data: {
              scanned: (discounts || []).length,
              eligible: 0,
              sent: 0,
              skipped: 0,
              failed: 0,
              modular: modularNotifications,
            },
          });
        }

        await supabase
          .from("sales_discount_notifications")
          .upsert(candidateRows, {
            onConflict: "idempotency_key",
            ignoreDuplicates: true,
          });
        const keys = candidateRows.map((row) => row.idempotency_key);
        const { data: pendingRows } = await supabase
          .from("sales_discount_notifications")
          .select(
            "id,subscription_discount_id,notification_window,idempotency_key,internal_notification_sent_at,email_sent_at",
          )
          .in("idempotency_key", keys)
          .is("internal_notification_sent_at", null);
        const discountById = new Map(
          (discounts || []).map((item: any) => [
            sanitizeString(item.id, 120),
            item,
          ]),
        );
        let sent = 0;
        let failed = 0;
        for (const notification of pendingRows || []) {
          const discount = discountById.get(
            sanitizeString(notification.subscription_discount_id, 120),
          );
          if (!discount) continue;
          const user = usersById.get(sanitizeString(discount.user_id, 120));
          const endLabel = new Date(
            discount.discount_ends_at,
          ).toLocaleDateString("pt-BR");
          const priceLabel = new Intl.NumberFormat("pt-BR", {
            style: "currency",
            currency: "BRL",
          }).format(
            Number(
              discount.post_discount_unit_amount_cents ||
                PUBLIC_ACTIVE_PATIENT_PRICE.unitAmountCents,
            ) / 100,
          );
          try {
            if (isUuid(discount.user_id)) {
              await persistActivityLog({
                userId: discount.user_id,
                clinicId: isUuid(discount.clinic_id)
                  ? discount.clinic_id
                  : null,
                actorName: "Verto Assinatura",
                title: "Seu período promocional está chegando ao fim",
                content: `A condição promocional termina em ${endLabel}. Após essa data, o preço unitário será ${priceLabel} por paciente ativo/mês.`,
                type: "subscription_discount",
                actionType: "discount_expiry_notice",
                payloadDetails: JSON.stringify({
                  subscriptionDiscountId: discount.id,
                  discountEndsAt: discount.discount_ends_at,
                  nextBillingAt: discount.next_billing_at,
                  estimatedNextInvoiceAmountCents:
                    discount.estimated_next_invoice_amount_cents,
                  notificationWindow: notification.notification_window,
                  actionUrl: "/?tab=billing",
                }),
              });
            }
            let emailSentAt: string | null = null;
            const email = sanitizeEmail(user?.email);
            if (email) {
              const emailSent = await sendTransactionalEmailSafe({
                to: email,
                subject:
                  "Seu período promocional da Verto está chegando ao fim",
                html: `<div style="font-family:Arial,sans-serif;line-height:1.6;color:#1e293b"><h2>Seu período promocional está chegando ao fim</h2><p>Olá, ${escapeHtml(sanitizeString(user?.name, 180) || "cliente Verto")}.</p><p>A condição promocional da sua assinatura termina em <strong>${escapeHtml(endLabel)}</strong>.</p><p>A partir da próxima renovação, o preço será de <strong>${escapeHtml(priceLabel)} por paciente ativo/mês</strong>, conforme a quantidade de pacientes ativos da clínica.</p><p>Consulte a área de assinatura da Verto ou fale com nossa equipe em caso de dúvidas.</p></div>`,
                context: "discount_expiry_notification",
                from: OFFICIAL_FROM_CONTACT,
                replyTo: OFFICIAL_TRANSACTIONAL_REPLY_TO,
                metadata: {
                  idempotencyKey: notification.idempotency_key,
                  userId: discount.user_id,
                },
              });
              if (emailSent) emailSentAt = new Date().toISOString();
            }
            await supabase
              .from("sales_discount_notifications")
              .update({
                internal_notification_sent_at: new Date().toISOString(),
                email_sent_at: emailSentAt,
                email_error: email && !emailSentAt ? "EMAIL_NOT_SENT" : null,
                updated_at: new Date().toISOString(),
              })
              .eq("id", notification.id);
            sent += 1;
          } catch (itemError: any) {
            failed += 1;
            await supabase
              .from("sales_discount_notifications")
              .update({
                email_error: sanitizeString(
                  itemError?.message || String(itemError),
                  500,
                ),
                updated_at: new Date().toISOString(),
              })
              .eq("id", notification.id);
          }
        }
        return res.json({
          success: true,
          data: {
            scanned: (discounts || []).length,
            eligible: candidateRows.length,
            sent,
            skipped: candidateRows.length - (pendingRows || []).length,
            failed,
            modular: modularNotifications,
          },
        });
      } catch (error: any) {
        console.error(
          "[Discount Expiry Cron] Falha:",
          sanitizeString(error?.message || String(error), 240),
        );
        return res.status(500).json({
          success: false,
          error: "Falha ao processar avisos de término do desconto.",
        });
      }
    },
  );

  const normalizePatientCareNetworkPayload = (body: any) => {
    const clinicName = sanitizeString(body?.clinicName || body?.clinic_name, 180) || null;
    const professionalName = sanitizeString(body?.professionalName || body?.professional_name, 180);
    const specialty = sanitizeString(body?.specialty, 120) || null;
    const professionalRegistry = sanitizeString(body?.professionalRegistry || body?.professional_registry || body?.registry, 120) || null;
    const phone = sanitizeString(body?.phone || body?.telephone || body?.whatsapp, 60);
    const rawEmail = sanitizeString(body?.email, 254);
    const email = rawEmail ? sanitizeEmail(rawEmail) : '';
    const phoneDigitCount = phone.replace(/\D/g, '').length;

    if (!professionalName) return { ok: false as const, error: 'Informe o nome do profissional.' };
    if (!phone || phoneDigitCount < 6) return { ok: false as const, error: 'Informe um telefone válido para o profissional.' };
    if (rawEmail && !email) return { ok: false as const, error: 'Informe um e-mail válido ou deixe o campo em branco.' };

    return {
      ok: true as const,
      value: {
        clinic_name: clinicName,
        professional_name: professionalName,
        specialty,
        professional_registry: professionalRegistry,
        phone,
        email: email || null,
      }
    };
  };

  const patientCareNetworkColumns = 'id,clinic_id,patient_id,clinic_name,professional_name,specialty,professional_registry,phone,email,source,created_at,updated_at';

  const sendPatientCareNetworkError = (res: any, error: any, route: string) => {
    const message = sanitizeString(error?.message || String(error), 280);
    if (isMissingRelationError(error)) {
      return res.status(503).json({ success: false, code: 'PATIENT_CARE_NETWORK_SCHEMA_UNAVAILABLE', error: 'A estrutura da rede de cuidado ainda não foi aplicada.' });
    }
    if (message.includes('CARE_NETWORK_PATIENT_REVOCATION_CONFIRMATION_REQUIRED')) {
      return res.status(409).json({
        success: false,
        code: 'CARE_NETWORK_PATIENT_REVOCATION_CONFIRMATION_REQUIRED',
        error: 'Este vínculo foi desfeito pelo paciente ou responsável. Confirme explicitamente a criação de um novo vínculo antes de continuar.'
      });
    }
    if (message.includes('CARE_NETWORK_PATIENT_INELIGIBLE')) return res.status(409).json({ success: false, code: 'CARE_NETWORK_PATIENT_INELIGIBLE', error: 'Este paciente não possui vínculo ativo elegível com a clínica.' });
    if (message.includes('CARE_NETWORK_CONTACT_NOT_FOUND')) return res.status(404).json({ success: false, error: 'Profissional não encontrado nesta rede de cuidado.' });
    if (message.includes('CARE_NETWORK_EMAIL_INVALID')) return res.status(400).json({ success: false, error: 'Informe um e-mail válido ou deixe o campo em branco.' });
    return sendRouteDbError(res, route, error);
  };

  const upsertPatientCareNetworkContact = async (params: {
    clinicId: string;
    patientId: string;
    contactId?: string | null;
    actorId: string;
    source: 'PATIENT_PORTAL' | 'CLINIC';
    restoreAfterPatientRevocation?: boolean;
    value: any;
  }) => {
    const { data, error } = await supabase.rpc('upsert_patient_care_network_contact_v2', {
      p_clinic_id: params.clinicId,
      p_patient_id: params.patientId,
      p_contact_id: isUuid(params.contactId || '') ? params.contactId : null,
      p_clinic_name: params.value.clinic_name,
      p_professional_name: params.value.professional_name,
      p_specialty: params.value.specialty,
      p_professional_registry: params.value.professional_registry,
      p_phone: params.value.phone,
      p_email: params.value.email,
      p_source: params.source,
      p_actor_id: isUuid(params.actorId) ? params.actorId : null,
      p_restore_after_patient_revocation: params.restoreAfterPatientRevocation === true,
    });
    if (error) throw error;
    return data;
  };

  const listCareNetwork = async (clinicId: string, patientId: string) => {
    const { data, error } = await supabase
      .from('patient_care_network_contacts')
      .select(patientCareNetworkColumns)
      .eq('clinic_id', clinicId)
      .eq('patient_id', patientId)
      .is('archived_at', null)
      .order('created_at', { ascending: true })
      .limit(100);
    if (error) throw error;
    return data || [];
  };

  app.get('/api/patient/self/care-network', noStoreDynamicResponse, checkAuth, requireRoles('patient'), async (req: any, res) => {
    try {
      const portalScope = await resolveCanonicalPatientPortalScope(req.session.user);
      if (!portalScope) return res.status(409).json({ success: false, code: 'PATIENT_PORTAL_CONTEXT_REQUIRED', error: 'Selecione novamente o acesso do paciente para continuar.' });
      return res.json({ success: true, data: await listCareNetwork(portalScope.clinicId, portalScope.patientId) });
    } catch (error: any) {
      return sendPatientCareNetworkError(res, error, '/api/patient/self/care-network [GET]');
    }
  });

  app.post('/api/patient/self/care-network', portalActionLimiter, checkAuth, requireRoles('patient'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 16 * 1024, 'Cadastro da rede de cuidado')) return;
      const portalScope = await resolveCanonicalPatientPortalScope(req.session.user);
      if (!portalScope) return res.status(409).json({ success: false, code: 'PATIENT_PORTAL_CONTEXT_REQUIRED', error: 'Selecione novamente o acesso do paciente para continuar.' });
      const normalized = normalizePatientCareNetworkPayload(req.body);
      if (!normalized.ok) return res.status(400).json({ success: false, error: normalized.error });
      const actorId = sanitizeString(req.session.user?.id, 120);
      const data = await upsertPatientCareNetworkContact({ clinicId: portalScope.clinicId, patientId: portalScope.patientId, actorId, source: 'PATIENT_PORTAL', value: normalized.value });
      return res.status(201).json({ success: true, data });
    } catch (error: any) {
      return sendPatientCareNetworkError(res, error, '/api/patient/self/care-network [POST]');
    }
  });

  app.patch('/api/patient/self/care-network/:contactId', portalActionLimiter, checkAuth, requireRoles('patient'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 16 * 1024, 'Atualização da rede de cuidado')) return;
      const portalScope = await resolveCanonicalPatientPortalScope(req.session.user);
      if (!portalScope) return res.status(409).json({ success: false, code: 'PATIENT_PORTAL_CONTEXT_REQUIRED', error: 'Selecione novamente o acesso do paciente para continuar.' });
      const contactId = sanitizeString(req.params?.contactId, 120);
      if (!isUuid(contactId)) return res.status(400).json({ success: false, error: 'Profissional inválido.' });
      const current = await supabase.from('patient_care_network_contacts').select('id,source').eq('id', contactId).eq('clinic_id', portalScope.clinicId).eq('patient_id', portalScope.patientId).is('archived_at', null).maybeSingle();
      if (current.error) throw current.error;
      if (!current.data?.id) return res.status(404).json({ success: false, error: 'Profissional não encontrado nesta rede de cuidado.' });
      if (current.data.source === 'CLINIC') return res.status(403).json({ success: false, code: 'CARE_NETWORK_CLINIC_CONTACT_EDIT_RESTRICTED', error: 'Você pode desfazer este vínculo, mas os dados cadastrados pela clínica devem ser ajustados pela equipe.' });
      const normalized = normalizePatientCareNetworkPayload(req.body);
      if (!normalized.ok) return res.status(400).json({ success: false, error: normalized.error });
      const actorId = sanitizeString(req.session.user?.id, 120);
      const data = await upsertPatientCareNetworkContact({ clinicId: portalScope.clinicId, patientId: portalScope.patientId, contactId, actorId, source: 'PATIENT_PORTAL', value: normalized.value });
      return res.json({ success: true, data });
    } catch (error: any) {
      return sendPatientCareNetworkError(res, error, '/api/patient/self/care-network/:contactId [PATCH]');
    }
  });

  app.delete('/api/patient/self/care-network/:contactId', portalActionLimiter, checkAuth, requireRoles('patient'), async (req: any, res) => {
    try {
      const portalScope = await resolveCanonicalPatientPortalScope(req.session.user);
      if (!portalScope) return res.status(409).json({ success: false, code: 'PATIENT_PORTAL_CONTEXT_REQUIRED', error: 'Selecione novamente o acesso do paciente para continuar.' });
      const contactId = sanitizeString(req.params?.contactId, 120);
      const actorId = sanitizeString(req.session.user?.id, 120);
      if (!isUuid(contactId) || !isUuid(actorId)) return res.status(400).json({ success: false, error: 'Profissional inválido.' });
      const { data, error } = await supabase.rpc('archive_patient_care_network_contact_v2', {
        p_clinic_id: portalScope.clinicId, p_patient_id: portalScope.patientId, p_contact_id: contactId, p_actor_id: actorId, p_reason: 'PATIENT_UNLINKED'
      });
      if (error) throw error;
      return res.json({ success: true, data });
    } catch (error: any) {
      return sendPatientCareNetworkError(res, error, '/api/patient/self/care-network/:contactId [DELETE]');
    }
  });

