  app.post('/api/patients/:patientId/anamnesis/send', portalActionLimiter, checkAuth, requireClinicCapability('clinical.anamnesis.edit'), checkPatientAccess, async (req: any, res) => {
    try {
      const patientId = sanitizeString(req.resolvedPatientId || req.params.patientId, 120);
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const actorId = sanitizeString(req.session.user?.id, 120);
      if (!isUuid(patientId) || !isUuid(clinicId)) {
        return res.status(400).json({ success: false, error: 'Paciente inválido.' });
      }
      const patient = await fetchPatientForAnamnesis(patientId, clinicId);
      if (!patient?.id) return res.status(404).json({ success: false, error: 'Paciente não encontrado.' });
      const registrationPayload = await fetchPatientRegistrationPayloadForAnamnesis(patientId, clinicId);
      const patientContext = buildPatientAnamnesisContext(patient, registrationPayload);

      const nowIso = new Date().toISOString();
      const requestedTemplateId = sanitizeString(req.body?.templateId || req.body?.template_id, 120);
      const existing = await fetchPatientAnamnesisRequestWithSchemaFallback({
        patientId,
        clinicId,
        statuses: ['SENT', 'IN_PROGRESS']
      });
      if (existing.error && !isMissingRelationError(existing.error)) throw existing.error;

      const templateLookupId = sanitizeString(
        (isUuid(requestedTemplateId) ? requestedTemplateId : existing.data?.template_id) || '',
        120
      );
      const selectedTemplate = await fetchAnamnesisTemplateForPatient(
        patientContext,
        clinicId,
        templateLookupId,
        actorId,
        false
      );
      const patientEmail = sanitizeEmail(patient?.responsible_email || patient?.email);
      if (!patientEmail) {
        return res.status(400).json({
          success: false,
          error: 'Cadastre um responsável com e-mail antes de enviar a ficha.'
        });
      }
      const requestId = sanitizeString(existing.data?.id, 120) || crypto.randomUUID();
      const resolvedTemplateId = sanitizeString(
        (isUuid(requestedTemplateId) ? selectedTemplate?.selectedTemplateId : existing.data?.template_id) ||
          selectedTemplate?.selectedTemplateId,
        120
      );
      const preserveExistingSnapshot = Boolean(
        existing.data?.id &&
        !isUuid(requestedTemplateId) &&
        existing.data?.template_snapshot &&
        typeof existing.data.template_snapshot === 'object'
      );
      const templateSnapshot = preserveExistingSnapshot
        ? existing.data.template_snapshot
        : buildAnamnesisTemplateSnapshot(selectedTemplate);
      const templateRevision = preserveExistingSnapshot
        ? Math.max(1, Number(existing.data?.template_revision || (templateSnapshot as any)?.templateRevision || 1))
        : Math.max(1, Number(selectedTemplate?.templateRevision || (templateSnapshot as any)?.templateRevision || 1));
      const templateScopeSnapshot = sanitizeString(
        preserveExistingSnapshot
          ? existing.data?.template_scope_snapshot || (templateSnapshot as any)?.templateScope
          : selectedTemplate?.templateScope || (templateSnapshot as any)?.templateScope,
        20
      ) || null;
      const requestPayload = cleanObject({
        id: requestId,
        organization_id: clinicId,
        patient_id: patientId,
        template_id: isUuid(resolvedTemplateId) ? resolvedTemplateId : undefined,
        template_snapshot: templateSnapshot,
        template_revision: templateRevision,
        template_scope_snapshot: templateScopeSnapshot,
        requested_by: isUuid(actorId) ? actorId : null,
        assigned_to_user_id: isUuid(sanitizeString(patient?.responsible_user_id, 120)) ? sanitizeString(patient.responsible_user_id, 120) : null,
        status: existing.data?.id ? sanitizeString(existing.data.status, 40) || 'SENT' : 'SENT',
        sent_at: sanitizeString(existing.data?.sent_at, 80) || nowIso,
        expires_at: sanitizeString(existing.data?.expires_at, 80) || new Date(Date.now() + 45 * 24 * 60 * 60 * 1000).toISOString(),
        created_at: sanitizeString(existing.data?.created_at, 80) || nowIso,
        updated_at: nowIso
      });
      if (existing.data?.id) {
        const update = await updateRowsWithSchemaFallback({
          tableName: 'patient_anamnesis_requests',
          payload: requestPayload,
          filters: [{ column: 'id', value: requestId }],
          context: 'anamnesis-request-resend'
        });
        if (!update.success) throw update.error;
      } else {
        const insert = await insertRowWithSchemaFallback('patient_anamnesis_requests', requestPayload, 'anamnesis-request-send');
        if (!insert.success) throw insert.error;
      }

      await updatePatientOnboardingWithSchemaFallback({
        patientId,
        clinicId,
        patch: {
          status: PATIENT_STATUS_PENDING_ANAMNESIS,
          onboarding_status: ONBOARDING_ANAMNESIS_SENT,
          anamnesis_required: true,
          anamnesis_requested_at: nowIso
        },
        context: 'anamnesis-request-send'
      });

      let emailSent = false;
      const portalUrl = getAppPortalUrl({ section: 'anamnesis' });
      const emailTemplate = buildAnamnesisRequestEmail({ patientName: sanitizeString(patient?.name, 180), portalUrl });
      emailSent = await sendTransactionalEmailSafe({
        to: patientEmail,
        subject: emailTemplate.subject,
        html: emailTemplate.html,
        context: 'patient_anamnesis_request',
        from: OFFICIAL_FROM_NOREPLY,
        replyTo: OFFICIAL_TRANSACTIONAL_REPLY_TO,
        metadata: {
          patientId,
          email: maskEmail(patientEmail)
        }
      });

      void persistActivityLog({
        userId: actorId,
        clinicId,
        actorName: sanitizeString(req.session.user?.name || req.session.user?.email || 'Usuario', 180),
        title: 'Ficha de anamnese enviada',
        content: 'Solicitação de anamnese foi disponibilizada no portal da família.',
        type: 'clinical',
        actionType: 'ANAMNESIS_REQUEST_SENT',
        payload: { patientId, requestId, emailSent, templateName: sanitizeString(selectedTemplate?.templateName, 180) || null }
      });

      return res.json({
        success: true,
        message: emailSent ? 'Ficha de anamnese enviada para a família.' : 'Ficha disponibilizada no portal. E-mail não enviado agora.',
        data: {
          requestId,
          status: requestPayload.status,
          emailSent,
          selectedTemplateId: isUuid(resolvedTemplateId) ? resolvedTemplateId : null,
          templateName: sanitizeString(selectedTemplate?.templateName, 180) || null,
          availableTemplates: Array.isArray(selectedTemplate?.compatibleTemplates)
            ? selectedTemplate.compatibleTemplates.map((template: any) => ({
                id: sanitizeString(template?.id, 120),
                name: sanitizeString(template?.name, 180),
                description: sanitizeString(template?.description, 240) || null,
                templateScope: sanitizeString(template?.templateScope || template?.scope, 20) || null,
                templateRevision: Math.max(1, Number(template?.templateRevision || template?.revision || 1))
              })).filter((template: any) => template.id && template.name)
            : []
        }
      });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/patients/:patientId/anamnesis/send [POST]', error, {
        patientId: sanitizeString(req.params.patientId, 120),
        requestId: requestIdForLogs(req)
      });
    }
  });

