  app.patch('/api/notes/:noteId', checkAuth, requireClinicCapability('clinical.notes.create'), async (req: any, res) => {
    try {
      const noteId = sanitizeString(req.params.noteId, 120);
      if (!noteId) return res.status(400).json({ success: false, error: 'noteId inválido.' });
      let existing: any = null;
      let existingError: any = null;

      if (isUuid(noteId)) {
        const result = await supabase
          .from('notes')
          .select(NOTE_SELECT)
          .eq('id', noteId)
          .eq('is_active', true)
          .is('deleted_at', null)
          .maybeSingle();
        existing = result.data;
        existingError = result.error;
      } else {
        // Fallback for legacy/local IDs: resolve by patient + text/subject and update latest match.
        const fallbackPatientId = sanitizeString(req.body?.patient_id, 120);
        const fallbackText = sanitizeTextField(req.body?.text, 12000);
        const fallbackSubject = sanitizeTextField(req.body?.subject, 100);
        let fallbackQuery = supabase
          .from('notes')
          .select(NOTE_LEGACY_SELECT)
          .eq('is_active', true)
          .is('deleted_at', null)
          .order('created_at', { ascending: false })
          .limit(1);
        if (isUuid(fallbackPatientId)) fallbackQuery = fallbackQuery.eq('patient_id', fallbackPatientId);
        if (fallbackText) fallbackQuery = fallbackQuery.eq('text', fallbackText);
        if (fallbackSubject) fallbackQuery = fallbackQuery.eq('subject', fallbackSubject);
        const fallbackResult = await fallbackQuery.maybeSingle();
        existing = fallbackResult.data;
        existingError = fallbackResult.error;
      }

      if (existingError) throw existingError;
      if (!existing) return res.status(404).json({ success: false, error: 'Nota não encontrada.' });
      const notePatientId = sanitizeString(existing.patient_id, 120);
      if (!(await canAccessPatientInCurrentClinic(notePatientId, req.session.user))) {
        return res.status(403).json({ success: false, error: 'Acesso negado.' });
      }
      // The server derives the patient and family visibility from the existing
      // stored note. Frontend IDs, roles and score are not authorization sources.
      const existingFamilyNote = ['family_note', 'photo'].includes(String(existing.type || '').toLowerCase())
        || String(existing.visibility || '').toLowerCase() === 'family'
        || /fam[ií]lia/i.test(String(existing.subject || ''))
        || /registro da fam[ií]lia/i.test(String(existing.text || ''));
      const targetsFamily = ['family_note', 'photo'].includes(String(req.body?.type || '').toLowerCase())
        || String(req.body?.visibility || '').toLowerCase() === 'family'
        || /fam[ií]lia/i.test(String(req.body?.subject || ''))
        || /registro da fam[ií]lia/i.test(String(req.body?.text || ''));
      const scoreProvided = Object.prototype.hasOwnProperty.call(req.body || {}, 'score');
      if (existingFamilyNote || targetsFamily || scoreProvided) {
        if (!(await canAccessPatientInCurrentClinic(notePatientId, req.session.user, 'write'))) {
          return res.status(403).json({ success: false, error: 'Sem autorização para alterar o reconhecimento clínico deste paciente.' });
        }
      }
      if ((existingFamilyNote || targetsFamily) && scoreProvided && req.body.score !== 0 && req.body.score !== 1) {
        return res.status(400).json({ success: false, error: 'A estrelinha deve ser 0 ou 1.' });
      }
      const actorId = sanitizeString(req.session.user?.id, 120);
      if (
        resolvePatientNoteAudience(existing) === 'private' &&
        (!actorId || resolvePatientNoteAuthorId(existing) !== actorId)
      ) {
        return res.status(403).json({ success: false, error: 'Somente o autor pode editar uma anotação privada.' });
      }

      const updatedVisibility =
        req.body?.visibility !== undefined
          ? normalizeNoteVisibility(req.body?.visibility)
          : undefined;
      const updatedType =
        updatedVisibility !== undefined
          ? (updatedVisibility === 'shared_clinic'
              ? 'professional'
              : updatedVisibility === 'shared_patient'
                ? 'shared'
                : 'private')
          : undefined;
      const updates = cleanObject({
        text: req.body?.text !== undefined ? sanitizeTextField(req.body?.text, 12000) : undefined,
        content: req.body?.text !== undefined ? sanitizeTextField(req.body?.text, 12000) : undefined,
        visibility: updatedVisibility,
        type: updatedType,
        score: req.body?.score !== undefined ? asSafeNumber(req.body?.score, 0, 100) : undefined,
        image: req.body?.image !== undefined ? sanitizeUrl(req.body?.image) : undefined,
        image_url: req.body?.image_url !== undefined ? sanitizeUrl(req.body?.image_url) : undefined,
        subject: req.body?.subject !== undefined ? (sanitizeTextField(req.body?.subject, 100) || 'Geral') : undefined,
        updated_at: new Date().toISOString()
      });
      const effectiveNoteId = sanitizeString(existing?.id, 120);
      const { data, error } = await updateNoteWithSchemaFallback(effectiveNoteId, updates);
      if (error) throw error;
      return res.json({ success: true, data });
    } catch (error: any) {
      return sendClinicalMutationError(res, '/api/notes/:noteId', 'update', error, {
        noteId: sanitizeString(req.params.noteId, 120),
        actorId: sanitizeString(req.session.user?.id, 120),
        patientId: sanitizeString(req.body?.patient_id || req.body?.patientId, 120)
      });
    }
  });

