  app.post('/api/portal/appointments/:appointmentId/request-cancel', portalActionLimiter, checkAuth, requirePatientPortalModule('appointments_communication'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Payload de solicitação de cancelamento')) return;
      const context = await fetchPortalAppointmentForUser(req.params.appointmentId, req.session.user);
      if (!context.ok) return res.status((context as any).status || 404).json(portalSafeError((context as any).status || 404));
      const appointment = (context as any).appointment;
      const previousStatus = normalizeOperationalAppointmentStatus(appointment.status);
      // P1-27: the notification identifier is only an untrusted hint. The
      // service-role-only RPC validates a SENT 24h queue job and the current
      // patient/clinic/environment/scheduled instant, then cancels atomically.
      // A 12h, absent, forged, stale or unfinalized reminder continues through
      // the existing clinic-approval request flow, never direct cancellation.
      const sourceNotificationId = sanitizeString(
        req.body?.notificationId || req.body?.notification_id, 120
      );
      const portalActorId = sanitizeString(req.session.user?.id, 120);
      if (isUuid(sourceNotificationId) && isUuid(portalActorId)) {
        const { data: automaticCancel, error: automaticCancelError } = await supabase.rpc(
          'portal_cancel_from_sent_24h_reminder_v1',
          {
            p_organization_id: appointment.organization_id || appointment.clinic_id,
            p_clinic_id: appointment.clinic_id,
            p_patient_id: appointment.patient_id,
            p_appointment_id: appointment.id,
            p_actor_id: portalActorId,
            p_actor_email: sanitizeEmail(req.session.user?.email) || null,
            p_notification_id: sourceNotificationId,
            p_deployment_env: deploymentEnv,
            p_reason: sanitizeTextField(req.body?.reason, 600) || null,
            p_note: sanitizeTextField(req.body?.note || req.body?.observation, 1000) || null
          }
        );
        if (automaticCancelError) {
          if (isMissingRelationError(automaticCancelError) || hasMissingFinancialSchema(automaticCancelError)
            || String(automaticCancelError.message || '').includes('portal_cancel_from_sent_24h_reminder_v1')) {
            return res.status(503).json({ success: false, error: 'Cancelamento indisponível. Tente novamente.' });
          }
          throw automaticCancelError;
        }
        if (automaticCancel?.canceled === true) {
          const persisted = await readPersistedAppointmentRows(
            [appointment.id], sanitizeString(appointment.clinic_id, 120)
          );
          const saved = persisted.find((row: any) => String(row.id) === String(appointment.id));
          if (!saved || normalizeOperationalAppointmentStatus(saved.status) !== 'CANCELLED') {
            return res.status(503).json({ success: false, error: 'Não foi possível verificar o cancelamento.' });
          }
          let notificationIds: string[] = [];
          try {
            const result = await acknowledgePortalAppointmentNotifications({
              appointment: saved,
              user: req.session.user,
              action: 'cancelled_from_24h_reminder',
              notificationId: sourceNotificationId
            });
            if (result.ok) notificationIds = result.notificationIds;
          } catch (error: any) {
            console.warn('[PortalAppointments] 24h cancellation notification acknowledgement failed:',
              error?.message || String(error));
          }
          void regenerateClosureForAppointments(
            [appointment.id], req.session.user, 'appointment_24h_reminder_cancelled'
          );
          const serializedAppointment = await serializePortalAppointmentForFamilyView(saved);
          return res.json(buildPortalAppointmentActionResult({
            action: 'cancelled_from_24h_reminder',
            appointment: serializedAppointment,
            message: 'Sessão cancelada a partir do lembrete de 24 horas.',
            user: req.session.user,
            notificationIds,
            actionRequest: { id: automaticCancel.requestId || null, status: 'APPROVED', request_type: 'CANCEL' }
          }));
        }
      }
      if (isAppointmentTerminalForPortalAction(previousStatus)) return res.status(409).json(portalSafeError(409));
      const requestRow = await createOrUpdateAppointmentActionRequest({
        appointment,
        user: req.session.user,
        requestType: 'CANCEL',
        reason: req.body?.reason,
        note: req.body?.note || req.body?.observation
      });
      const now = new Date().toISOString();
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorRole = sanitizeString(req.session.user?.role, 40) || 'responsible';
      const update = await updateAppointmentOperationalPatch(appointment.id, {
        cancel_requested_at: now,
        cancel_requested_by: actorId || null,
        patient_response: 'cancel_requested',
        patient_responded_at: now,
        patient_confirmation_status: 'CANCEL_REQUESTED',
        patient_confirmation_at: now,
        patient_confirmation_by: actorId || null,
        patient_confirmation_source: 'portal',
        updated_at: now
      });
      if (update.error) throw update.error;
      const persistedRows = await readPersistedAppointmentRows([appointment.id], sanitizeString(appointment.clinic_id, 120));
      const persistedAppointment = persistedRows.find((row: any) => sanitizeString(row?.id, 120) === sanitizeString(appointment.id, 120));
      const persistedCancelStatus = normalizeOperationalAppointmentStatus(persistedAppointment?.status);
      const persistedCancelResponse = normalizeOperationalAppointmentStatus(persistedAppointment?.patient_confirmation_status || persistedAppointment?.patient_response);
      if (!persistedAppointment || persistedCancelStatus === 'CANCELLED' || persistedCancelResponse !== 'CANCEL_REQUESTED') {
        return res.status(500).json({ success: false, error: 'Não foi possível confirmar a persistência da resposta.' });
      }
      const notificationUpdate = await acknowledgePortalAppointmentNotifications({
        appointment: persistedAppointment,
        user: req.session.user,
        action: 'cancel_requested_by_family',
        notificationId: req.body?.notificationId || req.body?.notification_id
      });
      if (!notificationUpdate.ok) {
        return res.status((notificationUpdate as any).status || 404).json(portalSafeError((notificationUpdate as any).status || 404));
      }
      await writeAppointmentStatusAuditLog({
        organizationId: appointment.organization_id || appointment.clinic_id,
        appointmentId: appointment.id,
        patientId: appointment.patient_id,
        action: 'CANCEL_REQUESTED',
        previousStatus,
        newStatus: 'CANCEL_REQUESTED',
        performedBy: actorId,
        performedByRole: actorRole,
        metadata: { actionRequestId: requestRow?.id || null, source: 'portal' }
      });
      void regenerateClosureForAppointments([appointment.id], req.session.user, 'appointment_cancel_requested');
      const serializedAppointment = await serializePortalAppointmentForFamilyView(persistedAppointment);
      return res.json(buildPortalAppointmentActionResult({
        action: 'cancel_requested_by_family',
        appointment: serializedAppointment,
        message: 'Solicitação de cancelamento registrada.',
        user: req.session.user,
        notificationIds: notificationUpdate.notificationIds,
        actionRequest: requestRow
      }));
    } catch (error: any) {
      console.warn('[PortalAppointments] cancel request failed:', error?.message || String(error));
      return res.status(500).json(portalSafeError(500));
    }
  });

  app.post('/api/portal/sessions/:sessionId/sign', portalActionLimiter, checkAuth, async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Payload de assinatura de sessão')) return;
      const accepted = req.body?.accepted === true || req.body?.consentAccepted === true;
      if (!accepted) return res.status(400).json(portalSafeError(400));
      const sessionId = sanitizeString(req.params.sessionId, 180);
      if (!sessionId) return res.status(400).json(portalSafeError(400));
      const { data: abaSession, error: sessionError } = await supabase
        .from('aba_sessions')
        .select(CLOSURE_ABA_SESSION_SELECT)
        .eq('id', sessionId)
        .limit(1)
        .maybeSingle();
      if (sessionError) {
        if (hasMissingFinancialSchema(sessionError)) return res.status(503).json(portalSafeError(503));
        throw sessionError;
      }
      if (!abaSession?.id) return res.status(404).json(portalSafeError(404));
      const patientId = sanitizeString(abaSession.patient_id, 120);
      const appointmentId = sanitizeString(abaSession.appointment_id, 120) || null;
      let appointment: any = null;
      if (appointmentId && isUuid(appointmentId)) {
        const appointmentContext = await fetchPortalAppointmentForUser(appointmentId, req.session.user);
        if (!appointmentContext.ok) return res.status((appointmentContext as any).status || 404).json(portalSafeError((appointmentContext as any).status || 404));
        appointment = (appointmentContext as any).appointment;
      } else if (!(await canPortalUserAccessPatient(patientId, abaSession, req.session.user))) {
        return res.status(404).json(portalSafeError(404));
      }
      const sessionStatus = sanitizeString(abaSession.status, 80).toLowerCase();
      const concluded =
        ['completed', 'concluida', 'concluido'].includes(sessionStatus) ||
        Boolean(abaSession.ended_at || abaSession.actual_end_at || appointment?.actual_end_at) ||
        normalizeOperationalAppointmentStatus(appointment?.status) === 'COMPLETED';
      if (!concluded) return res.status(409).json(portalSafeError(409));

      const organizationId = sanitizeString(abaSession.organization_id || appointment?.organization_id || abaSession.clinic_id || appointment?.clinic_id, 120);
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorRole = sanitizeString(req.session.user?.role, 40) || 'responsible';
      const signerName = sanitizeString(req.body?.signedByName || req.session.user?.name || req.session.user?.email, 180) || 'Responsável';
      const existing = await supabase
        .from('session_signatures')
        .select(SESSION_SIGNATURE_SELECT)
        .eq('organization_id', organizationId)
        .eq('aba_session_id', sessionId)
        .eq('signed_by_user_id', actorId)
        .eq('status', 'SIGNED')
        .order('signed_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (existing.error && !hasMissingFinancialSchema(existing.error)) throw existing.error;
      if (existing.data?.id) {
        return res.json({ success: true, alreadySigned: true, message: 'Assinatura registrada.', data: existing.data });
      }

      const now = new Date().toISOString();
      const payload = cleanObject({
        id: crypto.randomUUID(),
        organization_id: organizationId,
        patient_id: patientId,
        appointment_id: appointmentId && isUuid(appointmentId) ? appointmentId : null,
        aba_session_id: sessionId,
        signed_by_user_id: actorId || null,
        signed_by_name: signerName,
        signed_by_role: actorRole,
        signature_type: 'DIGITAL_ACCEPTANCE',
        signature_hash: crypto.createHash('sha256').update(`${organizationId}:${patientId}:${sessionId}:${actorId}:${now}`).digest('hex'),
        ip_hash: hashOperationalValue(req.ip || req.headers['x-forwarded-for']),
        user_agent_hash: hashOperationalValue(req.headers['user-agent']),
        consent_text_version: PORTAL_SESSION_CONSENT_TEXT_VERSION,
        consent_text: PORTAL_SESSION_CONSENT_TEXT,
        signed_at: now,
        status: 'SIGNED',
        metadata: sanitizeClinicalPayload({ source: 'portal', acceptanceOnly: true }),
        created_at: now,
        updated_at: now
      });
      const { data, error } = await supabase
        .from('session_signatures')
        .insert([payload])
        .select(SESSION_SIGNATURE_SELECT)
        .maybeSingle();
      if (error) {
        if (String(error.code || '') === '23505') {
          const retry = await supabase
            .from('session_signatures')
            .select(SESSION_SIGNATURE_SELECT)
            .eq('organization_id', organizationId)
            .eq('aba_session_id', sessionId)
            .eq('signed_by_user_id', actorId)
            .eq('status', 'SIGNED')
            .order('signed_at', { ascending: false })
            .limit(1)
            .maybeSingle();
          if (!retry.error && retry.data) return res.json({ success: true, alreadySigned: true, message: 'Assinatura registrada.', data: retry.data });
        }
        throw error;
      }
      if (appointmentId) {
        await writeAppointmentStatusAuditLog({
          organizationId,
          appointmentId,
          patientId,
          action: 'SIGNATURE_CREATED',
          previousStatus: appointment?.status || null,
          newStatus: appointment?.status || null,
          performedBy: actorId,
          performedByRole: actorRole,
          metadata: { abaSessionId: sessionId, signatureType: 'DIGITAL_ACCEPTANCE' }
        });
        void regenerateClosureForAppointments([appointmentId], req.session.user, 'session_signature_created');
      }
      return res.json({ success: true, message: 'Assinatura registrada.', data });
    } catch (error: any) {
      console.warn('[PortalSignatures] sign failed:', error?.message || String(error));
      return res.status(500).json(portalSafeError(500));
    }
  });

  app.get('/api/appointments/:appointmentId/action-requests', checkAuth, requireClinicCapability('calendar.requests.manage'), async (req: any, res) => {
    try {
      const context = await fetchPortalAppointmentForUser(req.params.appointmentId, req.session.user);
      if (!context.ok) return res.status((context as any).status || 404).json(portalSafeError((context as any).status || 404));
      const appointment = (context as any).appointment;
      const organizationId = sanitizeString(appointment.organization_id || appointment.clinic_id, 120);
      const { data, error } = await supabase
        .from('appointment_action_requests')
        .select(APPOINTMENT_ACTION_REQUEST_SELECT)
        .eq('organization_id', organizationId)
        .eq('appointment_id', appointment.id)
        .order('created_at', { ascending: false })
        .limit(30);
      if (error) {
        if (hasMissingFinancialSchema(error)) return res.json({ success: true, data: [] });
        throw error;
      }
      return res.json({ success: true, data: (data || []).map(serializeAppointmentActionRequestForResponse) });
    } catch (error: any) {
      console.warn('[AppointmentActions] list failed:', error?.message || String(error));
      return res.status(500).json(portalSafeError(500));
    }
  });

  app.get('/api/appointments/action-requests/:requestId/availability', noStoreDynamicResponse, checkAuth, requireClinicCapability('calendar.requests.manage'), async (req: any, res) => {
    try {
      const schemaState = await requireAppointmentActionResolutionSchema(
        req,
        res,
        'availability',
        String(req.query?.refresh || '').toLowerCase() === '1' || String(req.query?.refresh || '').toLowerCase() === 'true',
      );
      if (!schemaState) return;
      const context = await fetchAppointmentActionRequestForAdmin(req.params.requestId, req.session.user);
      if (!context.ok) {
        return res.status((context as any).status || 404).json({
          success: false,
          error: (context as any).error || 'Solicitação não encontrada.'
        });
      }
      const requestRow = (context as any).request;
      if (requestRow.request_type !== 'RESCHEDULE') {
        return res.status(400).json({ success: false, error: 'Esta solicitação não é uma remarcação.' });
      }
      const data = await buildRescheduleApprovalPreview({
        appointment: (context as any).appointment,
        request: requestRow,
        user: req.session.user
      });
      return res.json({
        success: true,
        data: {
          ...data,
          schema: {
            availabilityReady: true,
            approvalReady: schemaState.approvalReady,
            retryable: schemaState.retryable,
          },
        },
      });
    } catch (error: any) {
      console.warn('[AppointmentActions] availability failed:', error?.message || String(error));
      return res.status(500).json({ success: false, error: 'Não foi possível verificar os horários agora.' });
    }
  });

  app.post('/api/appointments/action-requests/:requestId/approve', portalActionLimiter, checkAuth, requireClinicCapability('calendar.requests.manage'), async (req: any, res) => {
    try {
      if (!(await requireAppointmentActionResolutionSchema(req, res, 'approval'))) return;
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Payload de aprovação de solicitação')) return;
      const context = await fetchAppointmentActionRequestForAdmin(req.params.requestId, req.session.user);
      if (!context.ok) return res.status((context as any).status || 404).json(portalSafeError((context as any).status || 404));
      const requestRow = (context as any).request;
      const appointment = (context as any).appointment;
      let recoveringApprovedReschedule = false;
      if (requestRow.status !== 'PENDING') {
        if (requestRow.status === 'APPROVED' && requestRow.request_type === 'RESCHEDULE') {
          const persistedRows = await readPersistedAppointmentRows([appointment.id], sanitizeString(appointment.clinic_id, 120));
          const persistedAppointment = persistedRows.find((row: any) => sanitizeString(row?.id, 120) === sanitizeString(appointment.id, 120));
          const approvedStart = sanitizeIsoDateTime(requestRow?.metadata?.approvedStart);
          const approvedEnd = sanitizeIsoDateTime(requestRow?.metadata?.approvedEnd);
          if (persistedAppointment && approvedStart && appointmentScheduleMatches(persistedAppointment, {
            start: approvedStart,
            end: approvedEnd || calculateAppointmentEnd(new Date(approvedStart), getCalendarAppointmentDuration(persistedAppointment))?.toISOString() || '',
            status: 'SCHEDULED'
          })) {
            const snapshotOrganizationId = sanitizeString(requestRow.organization_id || appointment.organization_id || appointment.clinic_id, 120);
            const [requestsSnapshot, auditSnapshot] = await Promise.all([
              supabase
                .from('appointment_action_requests')
                .select(APPOINTMENT_ACTION_REQUEST_SELECT)
                .eq('organization_id', snapshotOrganizationId)
                .eq('appointment_id', appointment.id)
                .order('created_at', { ascending: false })
                .limit(20),
              supabase
                .from('appointment_status_audit_logs')
                .select(APPOINTMENT_STATUS_AUDIT_SELECT)
                .eq('organization_id', snapshotOrganizationId)
                .eq('appointment_id', appointment.id)
                .order('performed_at', { ascending: false })
                .limit(20)
            ]);
            return res.json({
              success: true,
              idempotent: true,
              appointment: serializePortalAppointment(persistedAppointment, {
                hasPendingReschedule: false,
                has_pending_reschedule: false,
                rescheduleStatus: 'APPROVED',
                reschedule_status: 'APPROVED'
              }),
              actionRequest: serializeAppointmentActionRequestForResponse(requestRow),
              actionRequests: !requestsSnapshot.error
                ? (requestsSnapshot.data || []).map(serializeAppointmentActionRequestForResponse)
                : undefined,
              statusHistory: !auditSnapshot.error
                ? (auditSnapshot.data || []).map(mapAuditLogToHumanHistory)
                : undefined
            });
          }
          if (approvedStart) recoveringApprovedReschedule = true;
        }
        if (!recoveringApprovedReschedule) return res.status(409).json(portalSafeError(409));
      }
      const organizationId = sanitizeString(appointment.organization_id || appointment.clinic_id, 120);
      const clinicId = sanitizeString(appointment.clinic_id || appointment.organization_id, 120);
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorRole = sanitizeString(req.session.user?.role, 40);
      const now = new Date().toISOString();
      const resolutionNote = sanitizeTextField(req.body?.resolutionNote || req.body?.resolution_note || req.body?.note, 800) || null;
      let nextAppointment: any = appointment;
      let auditAction = 'RESCHEDULE_APPROVED';
      let newStatus = 'SCHEDULED';
      let approvedRescheduleStart = '';
      let atomicActionRequest: any = null;
      let atomicAuditEntry: any = null;
      let atomicPayload: any = {};
      let rescheduleResolvedAtomically = false;
      if (requestRow.request_type === 'RESCHEDULE') {
        const parsedRequestNote = parseRescheduleRequestPayload(requestRow.note, requestRow.metadata);
        const requestedOptions = parsedRequestNote.options;
        const requestedOptionIndex = recoveringApprovedReschedule
          ? requestRow?.metadata?.approvedOptionIndex
          : req.body?.selectedOptionIndex ?? req.body?.selected_option_index;
        const parsedOptionIndex = parseSelectedRescheduleOptionIndex(requestedOptionIndex, requestedOptions.length);
        if (!parsedOptionIndex.ok) {
          return res.status(400).json({ success: false, code: 'INVALID_RESCHEDULE_OPTION', error: parsedOptionIndex.error });
        }
        const selectedOptionIndex = parsedOptionIndex.index;
        const selectedOption = requestedOptions[selectedOptionIndex] || null;
        // A clinica so pode aprovar uma opcao que o responsavel realmente enviou.
        // Nunca aceite data/hora arbitraria do corpo da requisicao.
        const requestedStart = sanitizeIsoDateTime(selectedOption?.scheduledStart);
        const requestedEnd = sanitizeIsoDateTime(selectedOption?.scheduledEnd);
        if (!requestedStart || !requestedEnd) {
          return res.status(400).json({ success: false, error: 'Escolha uma opção válida da solicitação de remarcação.' });
        }
        approvedRescheduleStart = requestedStart;
        const approvalPreview = await buildRescheduleApprovalPreview({
          appointment,
          request: requestRow,
          user: req.session.user
        });
        const optionPreview = approvalPreview.options.find((option: any) => option.index === selectedOptionIndex) || null;
        const requestedAssignmentId = sanitizeString(req.body?.assignmentId || req.body?.assignment_id, 260);
        const requestedProfessionalId = sanitizeString(req.body?.professionalId || req.body?.professional_id, 120);
        const requestedRoomId = sanitizeString(req.body?.roomId || req.body?.room_id, 180);
        if (requestedAssignmentId) {
          const parsedAssignment = parseRescheduleAssignmentId(requestedAssignmentId, selectedOptionIndex);
          if (!parsedAssignment.ok) {
            return res.status(400).json({ success: false, code: 'INVALID_RESCHEDULE_ASSIGNMENT', error: parsedAssignment.error });
          }
        }
        const allowedAssignments = [
          ...(Array.isArray(optionPreview?.assignments)
            ? optionPreview.assignments
            : [optionPreview?.assignment, ...(Array.isArray(optionPreview?.alternatives) ? optionPreview.alternatives : [])].filter(Boolean))
        ];
        const approvedAssignment = requestedAssignmentId
          ? allowedAssignments.find((candidate: any) => candidate.id === requestedAssignmentId)
          : requestedProfessionalId || requestedRoomId
            ? allowedAssignments.find((candidate: any) =>
                (!requestedProfessionalId || candidate.professionalId === requestedProfessionalId) &&
                (!requestedRoomId || candidate.roomId === requestedRoomId)
              )
            : optionPreview?.assignment || null;
        if (!optionPreview) {
          return res.status(409).json({
            success: false,
            code: 'RESCHEDULE_CONFLICT',
            error: 'A opção selecionada não pôde ser revalidada. Escolha outra opção.',
            data: approvalPreview
          });
        }
        if (!approvedAssignment || approvedAssignment.available !== true) {
          const professionalConflict = optionPreview?.issues?.find((issue: any) => issue?.type === 'professional_conflict');
          const roomConflict = optionPreview?.issues?.find((issue: any) => issue?.type === 'room_conflict');
          return res.status(409).json({
            success: false,
            code: professionalConflict ? 'PROFESSIONAL_CONFLICT' : roomConflict ? 'ROOM_CONFLICT' : 'RESCHEDULE_CONFLICT',
            error: optionPreview?.message || 'Este horário não está mais disponível. Escolha outra opção ou use uma alternativa sugerida.',
            data: approvalPreview
          });
        }
        if (approvedAssignment.approvalAllowed !== true || approvedAssignment.financialContext?.reviewRequired === true) {
          return res.status(422).json({
            success: false,
            code: 'FINANCIAL_REVIEW_REQUIRED',
            error: approvedAssignment.financialContext?.warnings?.[0] || 'O contexto financeiro precisa ser revisado antes da aprovação.',
            data: approvalPreview
          });
        }
        const durationMinutes = getCalendarAppointmentDuration(appointment);
        const startDate = new Date(requestedStart);
        const resolvedEndDate = calculateAppointmentEnd(startDate, durationMinutes);
        if (!resolvedEndDate) {
          return res.status(400).json({ success: false, error: 'Não foi possível calcular o término desta sessão.' });
        }
        const resolvedEnd = resolvedEndDate.toISOString();
        const approvalIdempotencyKey = sanitizeString(req.body?.idempotencyKey || req.body?.idempotency_key, 260);
        if (!recoveringApprovedReschedule && (!approvalIdempotencyKey || !approvalIdempotencyKey.startsWith(`reschedule:${requestRow.id}:${selectedOptionIndex}:`))) {
          return res.status(400).json({ success: false, code: 'INVALID_IDEMPOTENCY_KEY', error: 'A chave de idempotência desta aprovação é inválida.' });
        }
        const resolutionMetadata = {
          ...(requestRow.metadata && typeof requestRow.metadata === 'object' ? requestRow.metadata : {}),
          approvalIdempotencyKey: approvalIdempotencyKey || requestRow?.metadata?.approvalIdempotencyKey || null,
          approvedOptionIndex: selectedOptionIndex,
          approvedStart: requestedStart,
          approvedEnd: resolvedEnd,
          approvedProfessionalId: approvedAssignment.professionalId || null,
          approvedProfessionalName: approvedAssignment.professionalName || null,
          approvedRoomId: approvedAssignment.roomId || null,
          approvedRoomName: approvedAssignment.roomName || null,
          approvedRoomSpecialtyName: approvedAssignment.roomSpecialtyName || null,
          approvedRoomDisplayName: approvedAssignment.roomDisplayName || approvedAssignment.roomName || null,
          approvedAt: now,
          approvedBy: actorId || null
        };
        const atomicResult = await supabase.rpc('approve_appointment_reschedule_v2', {
          p_organization_id: organizationId,
          p_clinic_id: clinicId,
          p_request_id: requestRow.id,
          p_appointment_id: appointment.id,
          p_patient_id: appointment.patient_id,
          p_selected_option_index: selectedOptionIndex,
          p_scheduled_start: requestedStart,
          p_scheduled_end: resolvedEnd,
          p_duration_minutes: durationMinutes,
          p_professional_id: approvedAssignment.professionalId,
          p_professional_name: approvedAssignment.professionalName,
          p_room_id: approvedAssignment.locationType === 'clinica' ? approvedAssignment.roomId : null,
          p_room_name: approvedAssignment.locationType === 'clinica' ? approvedAssignment.roomName : null,
          p_location_type: approvedAssignment.locationType,
          p_session_buffer_minutes: approvedAssignment.sessionBufferMinutes || 0,
          p_actor_id: actorId,
          p_actor_role: actorRole,
          p_resolution_note: resolutionNote,
          p_metadata: resolutionMetadata
        });
        if (atomicResult.error) {
          const errorCode = sanitizeString(atomicResult.error?.code, 40).toUpperCase();
          const errorMessage = sanitizeString(atomicResult.error?.message, 500).toUpperCase();
          if (
            errorMessage.includes('HAS NO FIELD') ||
            errorMessage.includes('COLUMN') && errorMessage.includes('DOES NOT EXIST') ||
            errorMessage.includes('NO UNIQUE OR EXCLUSION CONSTRAINT')
          ) {
            return res.status(503).json({
              success: false,
              code: 'RESCHEDULE_APPROVAL_SCHEMA_INCOMPATIBLE',
              error: 'O banco ainda não possui o contrato atualizado da remarcação. Nenhum dado da sessão foi alterado.'
            });
          }
          if (errorCode === 'PGRST202' || errorCode === '42883' || errorMessage.includes('APPROVE_APPOINTMENT_RESCHEDULE')) {
            return res.status(503).json({
              success: false,
              code: 'RESCHEDULE_APPROVAL_SCHEMA_UNAVAILABLE',
              error: 'A atualização segura da remarcação ainda não está disponível. Nenhum dado da sessão foi alterado.'
            });
          }
          if (errorCode === '42501' || errorMessage.includes('FORBIDDEN')) {
            return res.status(403).json({ success: false, error: 'Você não tem permissão para aprovar esta remarcação.' });
          }
          if (errorCode === '22023' && errorMessage.includes('FINANCIAL_')) {
            const financialMessages: Record<string, string> = {
              FINANCIAL_AUTHORIZATION_EXPIRED: 'A guia não é válida na nova data. Revise o contexto financeiro.',
              FINANCIAL_AUTHORIZATION_NO_BALANCE: 'A autorização não possui saldo para aprovar esta remarcação.',
              FINANCIAL_PROFESSIONAL_REVIEW_REQUIRED: 'A autorização não confirma o profissional substituto selecionado.',
              FINANCIAL_PROCEDURE_MISMATCH: 'O procedimento da autorização não corresponde ao serviço desta sessão.'
            };
            return res.status(422).json({
              success: false,
              code: errorMessage.includes('EXPIRED') ? 'FINANCIAL_AUTHORIZATION_EXPIRED' : errorMessage.includes('NO_BALANCE') ? 'FINANCIAL_AUTHORIZATION_NO_BALANCE' : 'FINANCIAL_REVIEW_REQUIRED',
              error: Object.entries(financialMessages).find(([code]) => errorMessage.includes(code))?.[1] || 'O contexto financeiro precisa ser revisado antes da aprovação.',
              data: approvalPreview
            });
          }
          if (errorCode === '23P01' || errorMessage.includes('CONFLICT')) {
            const conflictCode = errorMessage.includes('PROFESSIONAL')
              ? 'PROFESSIONAL_CONFLICT'
              : errorMessage.includes('ROOM')
                ? 'ROOM_CONFLICT'
                : errorMessage.includes('PATIENT')
                  ? 'PATIENT_CONFLICT'
                  : 'RESCHEDULE_CONFLICT';
            const conflictError = conflictCode === 'PROFESSIONAL_CONFLICT'
              ? `${approvedAssignment.professionalName} não está mais disponível nesse horário.`
              : conflictCode === 'ROOM_CONFLICT'
                ? `A ${approvedAssignment.roomDisplayName || approvedAssignment.roomName || 'sala selecionada'} não está mais disponível. Escolha outra sala.`
                : conflictCode === 'PATIENT_CONFLICT'
                  ? 'O paciente já possui outra sessão nesse horário.'
                  : 'Este horário não está mais disponível. Escolha outra opção ou use uma alternativa sugerida.';
            return res.status(409).json({
              success: false,
              code: conflictCode,
              error: conflictError,
              data: approvalPreview
            });
          }
          if (errorMessage.includes('RESCHEDULE_APPOINTMENT_CHANGED') || errorMessage.includes('RESCHEDULE_APPOINTMENT_NOT_MOVABLE')) {
            return res.status(409).json({
              success: false,
              code: 'RESCHEDULE_APPOINTMENT_CHANGED',
              error: 'Esta sessão foi alterada ou cancelada enquanto a remarcação aguardava aprovação. Atualize os detalhes antes de decidir.'
            });
          }
          if (errorCode === '23503') {
            return res.status(409).json({
              success: false,
              code: 'RESCHEDULE_ASSIGNMENT_UNAVAILABLE',
              error: 'O profissional ou a sala escolhida não está mais disponível. Selecione uma alternativa livre.'
            });
          }
          if (errorCode === '40001' || errorMessage.includes('ALREADY_RESOLVED')) {
            return res.status(409).json({ success: false, error: 'Esta solicitação já foi resolvida por outro usuário.' });
          }
          throw atomicResult.error;
        }
        atomicPayload = atomicResult.data && typeof atomicResult.data === 'object' ? atomicResult.data : {};
        const confirmedRows = await readPersistedAppointmentRows([appointment.id], clinicId);
        const confirmedAppointment = confirmedRows.find((row: any) => sanitizeString(row?.id, 120) === sanitizeString(appointment.id, 120)) || atomicPayload.appointment;
        if (!confirmedAppointment || !appointmentScheduleMatches(confirmedAppointment, {
          start: requestedStart,
          end: resolvedEnd,
          status: 'SCHEDULED'
        })) {
          throw new Error('A transação de remarcação não retornou o horário confirmado.');
        }
        nextAppointment = confirmedAppointment;
        atomicActionRequest = atomicPayload.request || null;
        atomicAuditEntry = atomicPayload.audit || null;
        rescheduleResolvedAtomically = true;
        try {
          const clinicState = await readClinicStateForAppointmentMutation(clinicId);
          await writeClinicStateAppointmentsAfterPersistence(
            clinicId,
            actorId,
            clinicState.appointments,
            [confirmedAppointment]
          );
        } catch (mirrorError: any) {
          console.warn('[AppointmentActions] clinic_state reschedule mirror deferred:', {
            appointmentId: sanitizeString(appointment.id, 120),
            clinicId,
            message: mirrorError?.message || String(mirrorError)
          });
        }
      } else {
        auditAction = 'CANCEL_APPROVED';
        newStatus = 'CANCELLED';
        const update = await updateAppointmentOperationalPatch(appointment.id, {
          status: 'CANCELLED',
          patient_response: 'cancelled',
          patient_confirmation_status: 'CANCEL_REQUESTED',
          patient_confirmation_source: 'patient_request_approved_by_clinic',
          patient_responded_at: appointment.patient_responded_at || appointment.patientRespondedAt || now,
          patient_confirmation_at: appointment.patient_confirmation_at || appointment.patientConfirmationAt || now,
          updated_at: now
        });
        if (update.error) throw update.error;
        nextAppointment = {
          ...appointment,
          status: 'CANCELLED',
          patient_response: 'cancelled',
          patient_confirmation_status: 'CANCEL_REQUESTED',
          patient_confirmation_source: 'patient_request_approved_by_clinic',
          patient_responded_at: appointment.patient_responded_at || appointment.patientRespondedAt || now,
          patient_confirmation_at: appointment.patient_confirmation_at || appointment.patientConfirmationAt || now
        };
      }
      if (!rescheduleResolvedAtomically) {
        const requestResolution = await supabase
          .from('appointment_action_requests')
          .update({
            status: 'APPROVED',
            resolved_by: actorId || null,
            resolved_at: now,
            resolution_note: resolutionNote,
            metadata: requestRow.metadata,
            updated_at: now
          })
          .eq('id', requestRow.id)
          .eq('status', 'PENDING')
          .select('id')
          .maybeSingle();
        if (requestResolution.error || !requestResolution.data?.id) {
          throw requestResolution.error || new Error('A solicitação já foi resolvida por outro usuário.');
        }
        await writeAppointmentStatusAuditLog({
          organizationId,
          appointmentId: appointment.id,
          patientId: appointment.patient_id,
          action: auditAction,
          previousStatus: appointment.status,
          newStatus,
          performedBy: actorId,
          performedByRole: actorRole,
          metadata: { actionRequestId: requestRow.id, resolutionNote }
        });
      }
      if (requestRow.request_type === 'RESCHEDULE') {
        try {
          await acknowledgeStaleAppointmentReminderNotifications(nextAppointment);
        } catch (notificationError: any) {
          console.warn('[AppointmentActions] stale reminder acknowledgement deferred:', notificationError?.message || String(notificationError));
        }
        void notifyPortalRescheduleApproval({
          appointment: nextAppointment,
          originalAppointment: appointment,
          organizationId,
          scheduledStart: approvedRescheduleStart
        });
        triggerAppointmentReminderScan('appointment_reschedule_approved');
      }
      void regenerateClosureForAppointments([appointment.id], req.session.user, requestRow.request_type === 'CANCEL' ? 'appointment_cancel_approved' : 'appointment_reschedule_approved');
      return res.json(cleanObject({
        success: true,
        idempotent: requestRow.request_type === 'RESCHEDULE' ? atomicPayload?.idempotent === true : undefined,
        appointment: serializePortalAppointment(nextAppointment, {
          hasPendingReschedule: false,
          has_pending_reschedule: false,
          rescheduleStatus: atomicActionRequest?.status || (requestRow.request_type === 'RESCHEDULE' ? 'APPROVED' : null),
          reschedule_status: atomicActionRequest?.status || (requestRow.request_type === 'RESCHEDULE' ? 'APPROVED' : null),
          therapistName: requestRow.request_type === 'RESCHEDULE' ? atomicActionRequest?.metadata?.approvedProfessionalName || nextAppointment?.therapist_name : undefined,
          roomDisplayName: requestRow.request_type === 'RESCHEDULE' ? atomicActionRequest?.metadata?.approvedRoomDisplayName || nextAppointment?.source_payload?.roomDisplayName || nextAppointment?.room_name : undefined,
          roomSpecialtyName: requestRow.request_type === 'RESCHEDULE' ? atomicActionRequest?.metadata?.approvedRoomSpecialtyName || nextAppointment?.source_payload?.roomSpecialtyName || null : undefined
        }),
        actionRequest: atomicActionRequest ? serializeAppointmentActionRequestForResponse(atomicActionRequest) : undefined,
        actionRequests: Array.isArray(atomicPayload?.action_requests)
          ? atomicPayload.action_requests.map(serializeAppointmentActionRequestForResponse)
          : undefined,
        statusHistoryEntry: atomicAuditEntry ? {
          id: atomicAuditEntry.id,
          label: 'Remarcação aprovada pela clínica',
          performedAt: atomicAuditEntry.performed_at,
          metadata: atomicAuditEntry.metadata || {}
        } : undefined,
        statusHistory: Array.isArray(atomicPayload?.audit_entries)
          ? atomicPayload.audit_entries.map(mapAuditLogToHumanHistory)
          : undefined
      }));
    } catch (error: any) {
      console.warn('[AppointmentActions] approve failed:', error?.message || String(error));
      return res.status(500).json(portalSafeError(500));
    }
  });

  app.post('/api/appointments/action-requests/:requestId/reject', portalActionLimiter, checkAuth, requireClinicCapability('calendar.requests.manage'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Payload de recusa de solicitação')) return;
      const context = await fetchAppointmentActionRequestForAdmin(req.params.requestId, req.session.user);
      if (!context.ok) return res.status((context as any).status || 404).json(portalSafeError((context as any).status || 404));
      const requestRow = (context as any).request;
      const appointment = (context as any).appointment;
      if (requestRow.status !== 'PENDING') return res.status(409).json(portalSafeError(409));
      const organizationId = sanitizeString(appointment.organization_id || appointment.clinic_id, 120);
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorRole = sanitizeString(req.session.user?.role, 40);
      const now = new Date().toISOString();
      const currentStatus = normalizeOperationalAppointmentStatus(appointment.status);
      const fallbackStatus =
        currentStatus === 'CONFIRMED'
          ? 'CONFIRMED'
          : ['CANCEL_REQUESTED', 'RESCHEDULE_REQUESTED'].includes(currentStatus)
            ? 'SCHEDULED'
            : currentStatus === 'CANCELLED'
              ? 'SCHEDULED'
              : currentStatus || 'SCHEDULED';
      const restoredPatientConfirmation = fallbackStatus === 'CONFIRMED' ? 'confirmed' : null;
      const update = await updateAppointmentOperationalPatch(appointment.id, {
        status: fallbackStatus,
        patient_response: restoredPatientConfirmation,
        patient_confirmation_status: restoredPatientConfirmation,
        patient_confirmation_source: restoredPatientConfirmation ? 'appointments' : null,
        updated_at: now
      });
      if (update.error) throw update.error;
      const resolutionNote = sanitizeTextField(req.body?.resolutionNote || req.body?.resolution_note || req.body?.note, 800) || null;
      await supabase
        .from('appointment_action_requests')
        .update({
          status: 'REJECTED',
          resolved_by: actorId || null,
          resolved_at: now,
          resolution_note: resolutionNote,
          updated_at: now
        })
        .eq('id', requestRow.id);
      const auditAction = requestRow.request_type === 'CANCEL' ? 'CANCEL_REJECTED' : 'RESCHEDULE_REJECTED';
      await writeAppointmentStatusAuditLog({
        organizationId,
        appointmentId: appointment.id,
        patientId: appointment.patient_id,
        action: auditAction,
        previousStatus: appointment.status,
        newStatus: fallbackStatus,
        performedBy: actorId,
        performedByRole: actorRole,
        metadata: { actionRequestId: requestRow.id, resolutionNote }
      });
      void regenerateClosureForAppointments([appointment.id], req.session.user, 'appointment_action_request_rejected');
      return res.json({ success: true, appointment: serializePortalAppointment({
        ...appointment,
        status: fallbackStatus,
        patient_response: restoredPatientConfirmation,
        patient_confirmation_status: restoredPatientConfirmation,
        patient_confirmation_source: restoredPatientConfirmation ? 'appointments' : null
      }) });
    } catch (error: any) {
      console.warn('[AppointmentActions] reject failed:', error?.message || String(error));
      return res.status(500).json(portalSafeError(500));
    }
  });

  const fetchTimeReportAppointments = async (params: {
    clinicId: string;
    organizationId: string;
    fromIso: string;
    toIso: string;
    limit: number;
    patientId?: string;
    professionalId?: string;
    serviceType?: string;
    status?: string;
  }) => {
    let query = supabase
      .from('appointments')
      .select(TIME_REPORT_APPOINTMENT_SELECT)
      .gte('scheduled_at', params.fromIso)
      .lte('scheduled_at', params.toIso)
      .order('scheduled_at', { ascending: true })
      .limit(params.limit);
    if (params.clinicId) query = query.eq('clinic_id', params.clinicId);
    if (isUuid(params.organizationId)) query = query.eq('organization_id', params.organizationId);
    if (isUuid(params.patientId || '')) query = query.eq('patient_id', params.patientId);
    if (isUuid(params.professionalId || '')) query = query.eq('therapist_id', params.professionalId);
    if (params.serviceType) query = query.eq('service_type', params.serviceType);
    if (params.status) query = query.eq('status', params.status);
    const { data, error } = await query;
    if (!error) return Array.isArray(data) ? data.map((row: any) => normalizeConflictAppointment(row)) : [];
    if (!hasMissingFinancialSchema(error)) throw error;

    const stateResult = await fetchClinicStateWithSchemaFallback({ supabase, clinicId: params.clinicId, logger: console });
    if (stateResult.error) return [];
    const fromMs = new Date(params.fromIso).getTime();
    const toMs = new Date(params.toIso).getTime();
    return (Array.isArray(stateResult.data?.appointments) ? stateResult.data.appointments : [])
      .map((appointment: any) => normalizeConflictAppointment({ ...appointment, source_payload: appointment }))
      .filter((appointment: any) => {
        const start = new Date(appointment.start_time || appointment.scheduled_at || `${appointment.date}T${appointment.time}:00`).getTime();
        if (!Number.isFinite(start) || start < fromMs || start > toMs) return false;
        if (params.patientId && String(appointment.patient_id || appointment.patientId || '') !== params.patientId) return false;
        if (params.professionalId && !getClinicStateAppointmentProfessionals(appointment).ids.includes(params.professionalId)) return false;
        if (params.serviceType && sanitizeString(appointment.service_type || appointment.type || appointment.approach, 120) !== params.serviceType) return false;
        if (params.status && sanitizeString(appointment.status, 40) !== params.status) return false;
        return true;
      })
      .slice(0, params.limit);
  };

