  const buildBillingContextSelect = (omittedColumns: Set<string> = new Set()) => APPOINTMENT_BILLING_CONTEXT_SELECT
    .split(',')
    .map((column) => column.trim())
    .filter((column) => column && !omittedColumns.has(column))
    .join(',');

  const hasBillingContextStorageValue = (payload: any, column: string) => {
    const value = payload?.[column];
    return value !== undefined && value !== null && String(value).trim() !== '';
  };

  const buildBillingContextStoragePayload = (payload: any, omittedColumns: Set<string>) => {
    const next = { ...(payload || {}) };
    for (const column of omittedColumns) delete next[column];
    const needsMetadataFallback = !omittedColumns.has('metadata') && APPOINTMENT_BILLING_CONTEXT_METADATA_VALUE_COLUMNS.some(
      (column) => omittedColumns.has(column) && hasBillingContextStorageValue(payload, column)
    );
    if (needsMetadataFallback) next.metadata = buildBillingContextMetadata(payload);
    else if (omittedColumns.has('metadata')) delete next.metadata;
    return cleanObject(next);
  };

  const fetchAppointmentBillingContextRow = async (organizationId: string, appointmentId: string) => {
    if (!isUuid(organizationId) || !isUuid(appointmentId)) return null;
    const runQuery = (selectColumns: string) => supabase
        .from('appointment_billing_contexts')
        .select(selectColumns)
        .eq('organization_id', organizationId)
        .eq('appointment_id', appointmentId)
        .limit(1)
        .maybeSingle();
    const omittedColumns = new Set<string>();
    let lastError: any = null;
    for (let attempt = 0; attempt <= APPOINTMENT_BILLING_CONTEXT_SCHEMA_FALLBACK_COLUMNS.size; attempt += 1) {
      const result = await runQuery(buildBillingContextSelect(omittedColumns));
      if (!result.error) return mergeBillingContextMetadata(result.data || null);
      if (isMissingRelationError(result.error)) return null;
      const missingColumn = extractMissingColumnName(result.error);
      if (!missingColumn || !APPOINTMENT_BILLING_CONTEXT_SCHEMA_FALLBACK_COLUMNS.has(missingColumn) || omittedColumns.has(missingColumn)) {
        throw result.error;
      }
      omittedColumns.add(missingColumn);
      lastError = result.error;
    }
    if (lastError && hasMissingFinancialSchema(lastError)) return null;
    if (lastError) throw lastError;
    return null;
  };

  const upsertAppointmentBillingContextRow = async (payload: any, hasExistingRow = false) => {
    const isAppointmentBillingContextConflict = (error: any) => {
      const message = String(error?.message || error?.details || '').toLowerCase();
      return sanitizeString(error?.code, 40) === '23505' &&
        (
          message.includes('appointment_billing_contexts') ||
          message.includes('idx_appointment_billing_contexts_appointment') ||
          message.includes('organization_id') ||
          message.includes('appointment_id')
        );
    };

    const writeWithSelect = async (row: any, selectColumns: string) => {
      if (hasExistingRow && isUuid(sanitizeString(row?.id, 120))) {
        const updateResult = await supabase
          .from('appointment_billing_contexts')
          .update(cleanObject(row))
          .eq('organization_id', row.organization_id)
          .eq('id', row.id)
          .select(selectColumns)
          .maybeSingle();
        if (updateResult.error || updateResult.data) return updateResult;
      }
      const insertResult = await supabase
        .from('appointment_billing_contexts')
        .insert([cleanObject(row)])
        .select(selectColumns)
        .maybeSingle();
      if (!insertResult.error || !isAppointmentBillingContextConflict(insertResult.error)) return insertResult;

      const existingResult = await supabase
        .from('appointment_billing_contexts')
        .select('id, created_at, created_by')
        .eq('organization_id', row.organization_id)
        .eq('appointment_id', row.appointment_id)
        .limit(1)
        .maybeSingle();
      if (existingResult.error || !existingResult.data?.id) return insertResult;

      return supabase
        .from('appointment_billing_contexts')
        .update(cleanObject({
          ...row,
          id: existingResult.data.id,
          created_at: existingResult.data.created_at || row.created_at,
          created_by: existingResult.data.created_by || row.created_by
        }))
        .eq('organization_id', row.organization_id)
        .eq('id', existingResult.data.id)
        .select(selectColumns)
        .maybeSingle();
    };

    const omittedColumns = new Set<string>();
    let lastError: any = null;
    for (let attempt = 0; attempt <= APPOINTMENT_BILLING_CONTEXT_SCHEMA_FALLBACK_COLUMNS.size; attempt += 1) {
      const storagePayload = buildBillingContextStoragePayload(payload, omittedColumns);
      const result = await writeWithSelect(storagePayload, buildBillingContextSelect(omittedColumns));
      if (!result.error) {
        return mergeBillingContextMetadata(result.data || storagePayload);
      }
      if (isMissingRelationError(result.error)) throw result.error;
      const missingColumn = extractMissingColumnName(result.error);
      if (!missingColumn || !APPOINTMENT_BILLING_CONTEXT_SCHEMA_FALLBACK_COLUMNS.has(missingColumn) || omittedColumns.has(missingColumn)) {
        throw result.error;
      }
      omittedColumns.add(missingColumn);
      lastError = result.error;
    }
    if (lastError) throw lastError;
    return mergeBillingContextMetadata(payload);
  };

  const fetchRequiredDocumentsForAppointment = async (organizationId: string, appointmentId: string) => {
    if (!isUuid(organizationId) || !isUuid(appointmentId)) return [];
    const { data, error } = await supabase
      .from('appointment_required_documents')
      .select(APPOINTMENT_REQUIRED_DOCUMENT_SELECT)
      .eq('organization_id', organizationId)
      .eq('appointment_id', appointmentId)
      .order('created_at', { ascending: false })
      .limit(50);
    if (error) {
      if (hasMissingFinancialSchema(error)) return [];
      throw error;
    }
    return Array.isArray(data) ? data : [];
  };

  const upsertRequiredDocumentStatus = async (params: {
    organizationId: string;
    appointmentId: string;
    patientId: string;
    payerId?: string | null;
    serviceType?: string | null;
    documentType: string;
    status: string;
    performedBy?: string | null;
  }) => {
    if (!isUuid(params.organizationId) || !isUuid(params.appointmentId) || !isUuid(params.patientId)) return null;
    const documentType = normalizeDocumentType(params.documentType);
    const existingResult = await supabase
      .from('appointment_required_documents')
      .select(APPOINTMENT_REQUIRED_DOCUMENT_SELECT)
      .eq('organization_id', params.organizationId)
      .eq('appointment_id', params.appointmentId)
      .eq('document_type', documentType)
      .limit(1)
      .maybeSingle();
    if (existingResult.error && !hasMissingFinancialSchema(existingResult.error)) throw existingResult.error;
    const existing = existingResult.data || null;
    if (existing && ['WAIVED', 'PROVIDED'].includes(sanitizeString(existing.status, 40).toUpperCase())) return existing;
    const now = new Date().toISOString();
    const payload = cleanObject({
      id: existing?.id || crypto.randomUUID(),
      organization_id: params.organizationId,
      appointment_id: params.appointmentId,
      patient_id: params.patientId,
      document_type: documentType,
      status: normalizeDocumentStatus(params.status),
      required_by_payer_id: isUuid(sanitizeString(params.payerId, 120)) ? sanitizeString(params.payerId, 120) : null,
      required_for_service_type: sanitizeString(params.serviceType, 120) || null,
      uploaded_at: normalizeDocumentStatus(params.status) === 'PROVIDED' ? now : existing?.uploaded_at || null,
      uploaded_by: normalizeDocumentStatus(params.status) === 'PROVIDED' && isUuid(sanitizeString(params.performedBy, 120)) ? sanitizeString(params.performedBy, 120) : existing?.uploaded_by || null,
      created_at: existing?.created_at || now,
      updated_at: now
    });
    const { data, error } = await supabase
      .from('appointment_required_documents')
      .upsert([payload], { onConflict: 'id' })
      .select(APPOINTMENT_REQUIRED_DOCUMENT_SELECT)
      .maybeSingle();
    if (error) {
      if (hasMissingFinancialSchema(error)) return null;
      throw error;
    }
    await writePayerRequirementAuditLog({
      organizationId: params.organizationId,
      payerId: params.payerId || null,
      appointmentId: params.appointmentId,
      action: normalizeDocumentStatus(params.status) === 'PROVIDED' ? 'DOCUMENT_PROVIDED' : 'DOCUMENT_REQUIRED',
      previousValue: existing,
      newValue: data,
      performedBy: params.performedBy || null
    });
    return data;
  };

  const fetchClosureRequirements = async (organizationId: string, serviceType: string | null, appointmentId?: string | null) => {
    if (!isUuid(organizationId)) return null;
    const { data, error } = await supabase
      .from('clinic_closure_requirements')
      .select('id, organization_id, service_type, payer_type, require_signature, require_report, require_actual_duration, min_duration_minutes, max_duration_variance_minutes, is_active, updated_at')
      .eq('organization_id', organizationId)
      .eq('is_active', true)
      .order('service_type', { ascending: false })
      .limit(20);
    if (error) {
      if (hasMissingFinancialSchema(error)) return null;
      throw error;
    }
    const safeServiceType = sanitizeString(serviceType, 120);
    const row =
      (data || []).find((item: any) => sanitizeString(item?.service_type, 120) === safeServiceType) ||
      (data || []).find((item: any) => !sanitizeString(item?.service_type, 120)) ||
      null;
    const legacyFallback = row ? {
      requireSignature: row.require_signature !== false,
      requireReport: row.require_report !== false,
      requireActualDuration: row.require_actual_duration !== false,
      minDurationMinutes: row.min_duration_minutes ?? null,
      maxDurationVarianceMinutes: row.max_duration_variance_minutes ?? null
    } : {};

    const billingContext = isUuid(sanitizeString(appointmentId, 120))
      ? await fetchAppointmentBillingContextRow(organizationId, sanitizeString(appointmentId, 120))
      : null;
    let payerId = sanitizeString(billingContext?.payer_id, 120);
    let payer: any = null;
    let payerRules: PayerRequirementRule[] = [];
    if (isUuid(payerId)) {
      const [payerResult, rulesResult] = await Promise.all([
        supabase
          .from('clinic_payers')
          .select(CLINIC_PAYER_SELECT)
          .eq('organization_id', organizationId)
          .eq('id', payerId)
          .limit(1)
          .maybeSingle(),
        supabase
          .from('clinic_payer_requirements')
          .select(CLINIC_PAYER_REQUIREMENT_SELECT)
          .eq('organization_id', organizationId)
          .eq('payer_id', payerId)
          .eq('is_active', true)
          .order('service_type', { ascending: false })
          .limit(20)
      ]);
      if (payerResult.error && !hasMissingFinancialSchema(payerResult.error)) throw payerResult.error;
      if (rulesResult.error && !hasMissingFinancialSchema(rulesResult.error)) throw rulesResult.error;
      payer = payerResult.error ? null : payerResult.data || null;
      payerRules = rulesResult.error ? [] : rulesResult.data || [];
    } else if (billingContext?.payer_name_snapshot) {
      payer = await fetchPayerForClosureBillingContext(billingContext, organizationId);
      payerId = sanitizeString(payer?.id, 120);
      if (isUuid(payerId)) {
        const rulesResult = await supabase
          .from('clinic_payer_requirements')
          .select(CLINIC_PAYER_REQUIREMENT_SELECT)
          .eq('organization_id', organizationId)
          .eq('payer_id', payerId)
          .eq('is_active', true)
          .order('service_type', { ascending: false })
          .limit(20);
        if (rulesResult.error && !hasMissingFinancialSchema(rulesResult.error)) throw rulesResult.error;
        payerRules = rulesResult.error ? [] : rulesResult.data || [];
      }
    }

    const resolved = resolvePayerRequirements({
      payerId,
      serviceType: billingContext?.service_type || safeServiceType,
      rules: payerRules,
      fallback: legacyFallback
    });
    return {
      requireSignature: resolved.requireSignature,
      requireReport: resolved.requireReport,
      requireActualDuration: resolved.requireActualDuration,
      requireAuthorization: resolved.requireAuthorization,
      requireGuide: resolved.requireGuide,
      requireAuthorizationBeforeSession: resolved.requireAuthorization,
      requireGuideBeforeSession: false,
      requireProfessionalRegistry: resolved.requireProfessionalRegistry,
      requirePatientDocument: resolved.requirePatientDocument,
      allowManualOverride: resolved.allowManualOverride,
      minDurationMinutes: resolved.minDurationMinutes,
      maxDurationVarianceMinutes: resolved.maxDurationVarianceMinutes,
      payerName: sanitizeString(payer?.name || billingContext?.payer_name_snapshot, 180) || null,
      payerId: isUuid(payerId) ? payerId : null,
      appliedPayerRequirementId: resolved.appliedRuleId,
      payerRequirementSource: resolved.source,
      billingContext
    };
  };

  const fetchClosureProfessional = async (professionalId: string, clinicId: string) => {
    if (!isUuid(professionalId)) return null;
    let userResult = await supabase
      .from('users')
      .select(CLOSURE_PROFESSIONAL_SELECT)
      .eq('id', professionalId)
      .maybeSingle();
    if (userResult.error && extractMissingColumnName(userResult.error)) {
      userResult = await supabase
        .from('users')
        .select('id, name, email, role, clinic_id, updated_at')
        .eq('id', professionalId)
        .maybeSingle();
    }
    if (userResult.error) {
      if (hasMissingFinancialSchema(userResult.error)) return null;
      throw userResult.error;
    }
    const profileResult = await fetchProfessionalProfileWithSchemaFallback({
      supabase,
      userId: professionalId,
      logger: console
    });
    if (profileResult.error && !hasMissingFinancialSchema(profileResult.error)) {
      throw profileResult.error;
    }
    let billingProfile: any = null;
    if (isUuid(clinicId)) {
      const billingResult = await supabase
        .from('professional_billing_profiles')
        .select(PROFESSIONAL_BILLING_PROFILE_SELECT)
        .eq('organization_id', clinicId)
        .eq('professional_id', professionalId)
        .limit(1)
        .maybeSingle();
      if (!billingResult.error) billingProfile = billingResult.data || null;
      else if (!hasMissingFinancialSchema(billingResult.error) && !isMissingRelationError(billingResult.error)) {
        throw billingResult.error;
      }
    }
    const userData = userResult.data || {};
    const profileData = profileResult.data || {};
    const registry = sanitizeString(
      billingProfile?.council_number ||
        profileData?.council_number ||
        profileData?.councilNumber ||
        profileData?.crp ||
        userData?.professional_registry ||
        userData?.registry ||
        userData?.crp,
      80
    );
    return cleanObject({
      ...userData,
      ...profileData,
      id: professionalId,
      name: sanitizeString(
        profileData?.full_name ||
          profileData?.fullName ||
          billingProfile?.display_name ||
          userData?.name ||
          userData?.email,
        180
      ) || null,
      registry: registry || null,
      professional_registry: registry || null,
      councilNumber: registry || null,
      council_number: registry || null,
      council: sanitizeString(
        billingProfile?.council_type ||
          profileData?.council ||
          profileData?.council_type,
        40
      ) || null,
      cbo_code: sanitizeString(billingProfile?.cbo_code || profileData?.cbo_code, 40) || null
    });
  };

  const fetchAppointmentClosureContext = async (appointmentId: string, user: any, options: { scopedAppointment?: any } = {}) => {
    const safeAppointmentId = sanitizeString(appointmentId, 120);
    const clinicId = sanitizeString(currentClinicId(user), 120);
    if (!isUuid(safeAppointmentId) || !isUuid(clinicId)) {
      return { ok: false, status: 400, error: 'Sessão inválida.' };
    }

    const scopedAppointment = options?.scopedAppointment || null;
    const scopedAppointmentId = sanitizeString(scopedAppointment?.id, 120);
    const scopedClinicId = sanitizeString(scopedAppointment?.clinic_id || scopedAppointment?.clinicId, 120);
    const scopedOrganizationId = sanitizeString(scopedAppointment?.organization_id || scopedAppointment?.organizationId, 120);
    const hasScopedAppointment =
      scopedAppointmentId === safeAppointmentId &&
      (scopedClinicId === clinicId || scopedOrganizationId === clinicId);
    const isTherapistUser = sanitizeString(user?.role, 40).toLowerCase() === 'therapist';
    const appointmentOmittedColumns = new Set<string>();
    const therapistPatientIds = isTherapistUser && !hasScopedAppointment
      ? await getClosureTherapistPatientIds(user, clinicId)
      : [];
    const therapistUserId = sanitizeString(user?.id, 120);
    let appointment: any = hasScopedAppointment ? scopedAppointment : null;
    let appointmentLastError: any = null;
    if (!appointment) {
      for (let attempt = 0; attempt <= CLOSURE_APPOINTMENT_SCHEMA_FALLBACK_COLUMNS.size + 2; attempt += 1) {
        let appointmentQuery = supabase
          .from('appointments')
          .select(buildClosureAppointmentSelect(appointmentOmittedColumns))
          .eq('id', safeAppointmentId)
          .limit(1);
        if (!appointmentOmittedColumns.has('organization_id') && !appointmentOmittedColumns.has('clinic_id')) {
          appointmentQuery = appointmentQuery.or(`organization_id.eq.${clinicId},clinic_id.eq.${clinicId}`);
        } else if (!appointmentOmittedColumns.has('organization_id')) {
          appointmentQuery = appointmentQuery.eq('organization_id', clinicId);
        } else if (!appointmentOmittedColumns.has('clinic_id')) {
          appointmentQuery = appointmentQuery.eq('clinic_id', clinicId);
        }
        if (isTherapistUser) {
          const orParts = [];
          if (!appointmentOmittedColumns.has('therapist_id') && isUuid(therapistUserId)) orParts.push(`therapist_id.eq.${therapistUserId}`);
          if (therapistPatientIds.length > 0) orParts.push(`patient_id.in.(${therapistPatientIds.join(',')})`);
          if (orParts.length > 0) appointmentQuery = appointmentQuery.or(orParts.join(','));
          else return { ok: false, status: 404, error: 'Sessão não encontrada.' };
        }
        const appointmentResult = await appointmentQuery.maybeSingle();
        if (!appointmentResult.error) {
          appointment = appointmentResult.data || null;
          break;
        }
        const missingColumn = extractMissingColumnName(appointmentResult.error);
        if (missingColumn && CLOSURE_APPOINTMENT_SCHEMA_FALLBACK_COLUMNS.has(missingColumn) && !appointmentOmittedColumns.has(missingColumn)) {
          appointmentOmittedColumns.add(missingColumn);
          appointmentLastError = appointmentResult.error;
          continue;
        }
        if (hasMissingFinancialSchema(appointmentResult.error)) {
          return { ok: false, status: 503, error: 'Fechamento indisponível.' };
        }
        throw appointmentResult.error;
      }
    }
    if (!appointment && appointmentLastError && hasMissingFinancialSchema(appointmentLastError)) {
      return { ok: false, status: 503, error: 'Fechamento indisponível.' };
    }
    if (!appointment?.id) return { ok: false, status: 404, error: 'Sessão não encontrada.' };
    const patientId = sanitizeString(appointment.patient_id, 120);
    if (!hasScopedAppointment && (!isUuid(patientId) || !(await canAccessPatientInCurrentClinic(patientId, user)))) {
      return { ok: false, status: 404, error: 'Sessão não encontrada.' };
    }

    let abaSession: any = null;
    if (isUuid(patientId)) {
      const abaResult = await supabase
        .from('aba_sessions')
        .select(CLOSURE_ABA_SESSION_SELECT)
        .eq('appointment_id', safeAppointmentId)
        .eq('patient_id', patientId)
        .order('updated_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (!abaResult.error) abaSession = abaResult.data || null;
      else if (!hasMissingFinancialSchema(abaResult.error)) throw abaResult.error;
    }

    let sessionSummary: any = null;
    const abaSessionId = sanitizeString(abaSession?.id, 180);
    if (abaSessionId) {
      const summaryResult = await supabase
        .from('aba_session_summaries')
        .select(CLOSURE_SESSION_SUMMARY_SELECT)
        .eq('session_id', abaSessionId)
        .eq('patient_id', patientId)
        .order('updated_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (!summaryResult.error) sessionSummary = summaryResult.data || null;
      else if (!hasMissingFinancialSchema(summaryResult.error)) throw summaryResult.error;
    }

    let patient: any = null;
    if (isUuid(patientId)) {
      const patientResult = await supabase
        .from('patients')
        .select(CLOSURE_PATIENT_SELECT)
        .eq('id', patientId)
        .eq('clinic_id', clinicId)
        .maybeSingle();
      if (!patientResult.error) patient = patientResult.data || null;
      else if (!hasMissingFinancialSchema(patientResult.error)) throw patientResult.error;
    }

    const professionalId = sanitizeString(
      appointment.therapist_id || appointment.professional_id || abaSession?.therapist_id,
      120
    );
    const professional = await fetchClosureProfessional(professionalId, clinicId);
    const serviceType = sanitizeString(appointment.service_type || appointment.approach || appointment.type, 120) || null;
    const requirements = await fetchClosureRequirements(clinicId, serviceType, safeAppointmentId);
    const billingContext = (requirements as any)?.billingContext || null;
    const requiredDocuments = await fetchRequiredDocumentsForAppointment(clinicId, safeAppointmentId);
    const summaryPayload = parseCalendarSourcePayload(sessionSummary?.summary_payload);
    let responsibleSignature: any = null;
    const signatureQuery = supabase
      .from('session_signatures')
      .select(SESSION_SIGNATURE_SELECT)
      .eq('organization_id', clinicId)
      .eq('status', 'SIGNED')
      .order('signed_at', { ascending: false })
      .limit(1);
    const abaSessionIdForSignature = sanitizeString(abaSession?.id, 180);
    const signatureResult = abaSessionIdForSignature
      ? await signatureQuery.eq('aba_session_id', abaSessionIdForSignature).maybeSingle()
      : await signatureQuery.eq('appointment_id', safeAppointmentId).maybeSingle();
    if (!signatureResult.error) responsibleSignature = signatureResult.data || null;
    else if (!hasMissingFinancialSchema(signatureResult.error)) throw signatureResult.error;
    const signature =
      responsibleSignature ||
      professional?.signature_data_url ||
      summaryPayload?.signatureUrl ||
      summaryPayload?.signaturePresent ||
      appointment?.signature_present ||
      appointment?.has_signature ||
      null;

    return {
      ok: true,
      organizationId: clinicId,
      appointment,
      abaSession,
      sessionSummary,
      patient,
      professional,
      requirements,
      billingContext,
      requiredDocuments,
      signature
    };
  };

  const fetchAppointmentClosureCheckRow = async (params: {
    organizationId: string;
    appointmentId: string;
    user: any;
  }) => {
    const organizationId = sanitizeString(params.organizationId, 120);
    const appointmentId = sanitizeString(params.appointmentId, 120);
    const omittedColumns = new Set<string>();
    if (!isUuid(organizationId) || !isUuid(appointmentId)) {
      return { data: null, omittedColumns };
    }

    let lastError: any = null;
    for (let attempt = 0; attempt <= APPOINTMENT_CLOSURE_CHECK_SCHEMA_FALLBACK_COLUMNS.size; attempt += 1) {
      let query = supabase
        .from('appointment_closure_checks')
        .select(buildAppointmentClosureCheckSelect(omittedColumns))
        .eq('organization_id', organizationId)
        .eq('appointment_id', appointmentId)
        .limit(1);
      query = (await applyClosureTenantScope(query, params.user, organizationId)).query;
      const result = await query.maybeSingle();
      if (!result.error) return { data: result.data || null, omittedColumns };
      if (isMissingRelationError(result.error)) return { data: null, omittedColumns };

      const missingColumn = extractMissingColumnName(result.error);
      if (!missingColumn || !APPOINTMENT_CLOSURE_CHECK_SCHEMA_FALLBACK_COLUMNS.has(missingColumn) || omittedColumns.has(missingColumn)) {
        if (hasMissingFinancialSchema(result.error)) return { data: null, omittedColumns };
        throw result.error;
      }
      omittedColumns.add(missingColumn);
      lastError = result.error;
    }

    if (lastError && hasMissingFinancialSchema(lastError)) return { data: null, omittedColumns };
    if (lastError) throw lastError;
    return { data: null, omittedColumns };
  };

  const normalizeClinicPayerNameForUniqueMatch = (value: any) => sanitizeString(value, 180)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

  const isMissingPayerDisplayName = (value: any) => {
    const normalized = normalizeClinicPayerNameForUniqueMatch(value);
    return !normalized || ['sem pagador', 'sem convenio', 'sem convênio', 'nao informado', 'não informado'].includes(normalized);
  };

  const resolveClinicPayerByUniqueNameForTissPreGuide = async (organizationId: string, payerName: string) => {
    const normalizedName = normalizeClinicPayerNameForUniqueMatch(payerName);
    if (!isUuid(organizationId) || !normalizedName || isMissingPayerDisplayName(payerName)) {
      return { status: 'missing_name', reasonCode: 'WITHOUT_REAL_PAYER', payer: null as any };
    }
    const { data, error } = await supabase
      .from('clinic_payers')
      .select(CLINIC_PAYER_SELECT)
      .eq('organization_id', organizationId)
      .ilike('name', payerName)
      .limit(20);
    if (error) {
      if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) {
        return { status: 'not_found', reasonCode: 'PAYER_NAME_NOT_FOUND', payer: null as any };
      }
      throw error;
    }
    const exactMatches = (Array.isArray(data) ? data : []).filter((payer: any) =>
      normalizeClinicPayerNameForUniqueMatch(payer?.name) === normalizedName
    );
    const activeMatches = exactMatches.filter((payer: any) => {
      const status = sanitizeString(payer?.status, 40)
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toUpperCase();
      return !['INACTIVE', 'INATIVO', 'ARCHIVED', 'DELETED'].includes(status);
    });
    if (activeMatches.length === 1) {
      return { status: 'matched', reasonCode: 'OK', payer: activeMatches[0] };
    }
    if (activeMatches.length > 1) {
      return { status: 'ambiguous', reasonCode: 'AMBIGUOUS_PAYER_NAME', payer: null as any };
    }
    return { status: 'not_found', reasonCode: 'PAYER_NAME_NOT_FOUND', payer: null as any };
  };

  const resolveEffectiveClosureBillingContext = async (params: {
    organizationId: string;
    patientId: string;
    appointment: any;
    billingContext: any;
    preloadedBatchSources?: {
      enabled: true;
      financialPlans: any[];
      patient: any | null;
      payers: any[];
      tissBillingContext?: AppointmentTissBillingBatchContext;
    };
  }) => {
    const organizationId = sanitizeString(params.organizationId, 120);
    const patientId = sanitizeString(params.patientId, 120);
    const appointment = params.appointment || {};
    const base = mergeBillingContextMetadata(params.billingContext || {}) || {};
    const appointmentBillingPayload = mergeAppointmentBillingPayload(appointment);
    const appointmentPayerId = sanitizeString(appointmentBillingPayload?.payer_id || appointmentBillingPayload?.payerId, 120);
    const appointmentPayerName = sanitizeString(
      appointmentBillingPayload?.payer_name_snapshot ||
        appointmentBillingPayload?.payerName ||
        appointmentBillingPayload?.payerNameSnapshot,
      180
    );
    const serviceType = sanitizeString(
      base?.service_type ||
        appointmentBillingPayload?.service_type ||
        appointmentBillingPayload?.serviceType ||
        appointment?.service_type ||
        appointment?.approach ||
        appointment?.type,
      120
    ) || null;
    const appointmentDate = sanitizeString(appointment?.scheduled_start_at || appointment?.scheduled_at || appointment?.date || appointment?.start_time, 80) || null;
    const procedureCode = sanitizeString(base?.procedure_code || appointmentBillingPayload?.procedure_code || appointmentBillingPayload?.procedureCode || appointment?.procedure_code, 80) || null;
    let suggestion: any = null;
    try {
      suggestion = await resolveAppointmentBillingSuggestion({
        organizationId,
        patientId,
        serviceType,
        payerId: sanitizeString(base?.payer_id || appointmentPayerId, 120) || null,
        payerName: sanitizeString(base?.payer_name_snapshot || appointmentPayerName, 180) || null,
        appointmentDate,
        procedureCode,
        preloadedBatchSources: params.preloadedBatchSources
      });
    } catch (error: any) {
      console.warn('[Closure] billing suggestion skipped:', {
        appointmentId: sanitizeString(appointment?.id, 120),
        message: error?.message || String(error)
      });
    }
    const suggestionHasTissAuthorization = Boolean(
      sanitizeString(suggestion?.patientTissAuthorizationId || suggestion?.patient_tiss_authorization_id, 120) ||
        sanitizeString(suggestion?.tissAuthorization?.authorizationId || suggestion?.tissAuthorization?.authorization_id, 120) ||
        sanitizeString(suggestion?.authorizationCode || suggestion?.authorization_code, 120) ||
        sanitizeString(suggestion?.guideNumber || suggestion?.guide_number, 120)
    );
    const metadata = parseStoredJsonObject(base?.metadata);
    const effectiveMetadata = suggestionHasTissAuthorization
      ? cleanObject({
          ...metadata,
          patient_tiss_authorization_id: sanitizeString(
            suggestion?.patientTissAuthorizationId ||
              suggestion?.patient_tiss_authorization_id ||
              suggestion?.tissAuthorization?.authorizationId ||
              suggestion?.tissAuthorization?.authorization_id,
            120
          ) || undefined,
          tiss_authorization: suggestion?.tissAuthorization || metadata?.tiss_authorization || undefined
        })
      : metadata;
    const effectivePayerName = sanitizeString(
      base?.payer_name_snapshot ||
        appointmentPayerName ||
        (suggestionHasTissAuthorization ? suggestion?.payerName || suggestion?.payer_name_snapshot : null),
      180
    );
    const effectivePayerId = sanitizeString(
      base?.payer_id ||
        appointmentPayerId ||
        (suggestionHasTissAuthorization ? suggestion?.payerId || suggestion?.payer_id : null),
      120
    );
    return cleanObject({
      ...base,
      payer_id: isUuid(effectivePayerId) ? effectivePayerId : null,
      payer_name_snapshot: effectivePayerName || null,
      payer_type: normalizeAppointmentFinancialContextType(base?.payer_type) || (effectivePayerId || effectivePayerName ? 'INSURANCE' : null),
      service_type: serviceType,
      insurance_card_number: sanitizeString(
        base?.insurance_card_number ||
          appointmentBillingPayload?.insurance_card_number ||
          appointmentBillingPayload?.insuranceCardNumber ||
          suggestion?.insuranceCardNumber ||
          suggestion?.insurance_card_number,
        120
      ) || null,
      insurance_plan_name: sanitizeString(
        base?.insurance_plan_name ||
          appointmentBillingPayload?.insurance_plan_name ||
          appointmentBillingPayload?.insurancePlanName ||
          suggestion?.insurancePlanName ||
          suggestion?.insurance_plan_name,
        160
      ) || null,
      authorization_code: sanitizeString(
        base?.authorization_code ||
          appointmentBillingPayload?.authorization_code ||
          appointmentBillingPayload?.authorizationCode ||
          (suggestionHasTissAuthorization ? suggestion?.authorizationCode || suggestion?.authorization_code : null),
        120
      ) || null,
      guide_number: sanitizeString(
        base?.guide_number ||
          appointmentBillingPayload?.guide_number ||
          appointmentBillingPayload?.guideNumber ||
          (suggestionHasTissAuthorization ? suggestion?.guideNumber || suggestion?.guide_number : null),
        120
      ) || null,
      procedure_code: procedureCode,
      metadata: effectiveMetadata,
      source: sanitizeString(base?.source || (suggestionHasTissAuthorization ? 'PATIENT_TISS_AUTHORIZATION' : null), 60) || null
    });
  };

  const resolveEffectiveAppointmentBillingContext = resolveEffectiveClosureBillingContext;

  const resolveEffectiveTissPreGuideBillingContext = async (params: {
    organizationId: string;
    appointment: any;
    billingContext?: any;
    preloadedBatchSources?: {
      enabled: true;
      financialPlans: any[];
      patient: any | null;
      payers: any[];
      tissBillingContext?: AppointmentTissBillingBatchContext;
    };
  }) => {
    const organizationId = sanitizeString(params.organizationId, 120);
    const appointment = mergeAppointmentBillingPayload(params.appointment || {});
    const rawContext = mergeBillingContextMetadata(params.billingContext || {}) || {};
    const rawEligibility = evaluateTissPreGuideEligibility({ appointment, billingContext: rawContext });
    const rawHasPayerName = Boolean(sanitizeString(rawContext?.payer_name_snapshot, 180));
    const rawHasGuideAndAuthorization = Boolean(
      sanitizeString(rawContext?.guide_number || rawContext?.guideNumber, 120) &&
        sanitizeString(rawContext?.authorization_code || rawContext?.authorizationCode || rawContext?.authorization_password || rawContext?.authorizationPassword, 120)
    );
    if (rawEligibility.eligible && rawHasPayerName && rawHasGuideAndAuthorization) return rawContext;

    const patientId = sanitizeString(appointment?.patient_id || appointment?.patientId || rawContext?.patient_id, 120);
    if (!isUuid(organizationId) || !isUuid(patientId)) return rawContext;
    const resolvePayerIdByTrustedName = async (context: any) => {
      const contextPayerId = sanitizeString(context?.payer_id || context?.payerId, 120);
      if (isUuid(contextPayerId)) return context;
      const payerName = sanitizeString(context?.payer_name_snapshot || context?.payerName || context?.payer_name, 180);
      if (isMissingPayerDisplayName(payerName)) return context;
      const resolution = await resolveClinicPayerByUniqueNameForTissPreGuide(organizationId, payerName);
      if (resolution.status === 'matched' && resolution.payer?.id) {
        return cleanObject({
          ...context,
          payer_id: sanitizeString(resolution.payer.id, 120),
          payer_name_snapshot: sanitizeString(resolution.payer.name || payerName, 180) || payerName,
          payer_type: normalizeAppointmentFinancialContextType(context?.payer_type) || 'INSURANCE',
          payer_resolution_source: 'name_unique_match'
        });
      }
      return cleanObject({
        ...context,
        payer_id: null,
        payer_name_snapshot: payerName,
        payer_type: normalizeAppointmentFinancialContextType(context?.payer_type) || 'INSURANCE',
        payer_resolution_status: resolution.status,
        payer_resolution_reason_code: resolution.reasonCode
      });
    };
    try {
      const effectiveContext = await resolveEffectiveAppointmentBillingContext({
        organizationId,
        patientId,
        appointment,
        billingContext: rawContext,
        preloadedBatchSources: params.preloadedBatchSources
      });
      const mergedEffectiveContext = mergeBillingContextMetadata(effectiveContext || rawContext) || rawContext;
      return resolvePayerIdByTrustedName(mergedEffectiveContext);
    } catch (error: any) {
      console.warn('[TissPreGuide] effective billing context skipped:', {
        appointmentId: sanitizeString(appointment?.id || appointment?.appointment_id, 120),
        message: sanitizeTextField(error?.message, 300) || String(error)
      });
      return resolvePayerIdByTrustedName(rawContext);
    }
  };

  const resolveTissPreGuideEligibilityContextsInBatch = async (params: {
    organizationId: string;
    appointments: any[];
    contextsByAppointment: Map<string, any>;
  }) => {
    const organizationId = sanitizeString(params.organizationId, 120);
    const appointments = (Array.isArray(params.appointments) ? params.appointments : [])
      .map((appointment: any) => mergeAppointmentBillingPayload(appointment || {}));
    const contextsByAppointment = params.contextsByAppointment instanceof Map
      ? params.contextsByAppointment
      : new Map<string, any>();
    const unresolvedPatientIds = Array.from(new Set(
      appointments
        .filter((appointment: any) => {
          const appointmentId = sanitizeString(appointment?.id || appointment?.appointment_id, 120);
          return tissPreGuideContextNeedsBatchResolution(
            appointment,
            contextsByAppointment.get(appointmentId) || {}
          );
        })
        .map((appointment: any) => sanitizeString(appointment?.patient_id || appointment?.patientId, 120))
        .filter((patientId: string) => isUuid(patientId))
    ));
    const needsPayerBatch = unresolvedPatientIds.length > 0 || appointments.some((appointment: any) => {
      const appointmentId = sanitizeString(appointment?.id || appointment?.appointment_id, 120);
      const context = contextsByAppointment.get(appointmentId) || {};
      const eligibility = evaluateTissPreGuideEligibility({ appointment, billingContext: context });
      return eligibility.eligible && !sanitizeString(
        context?.payer_name_snapshot || appointment?.payer_name_snapshot || appointment?.payerName,
        180
      );
    });

    if (!isUuid(organizationId) || appointments.length === 0) {
      return {
        contextsByAppointment: buildTissPreGuideEligibilityContexts({
          appointments,
          contextsByAppointment,
          financialPlans: [],
          patients: [],
          payers: []
        }),
        financialPlansByPatient: new Map<string, any[]>(),
        patientsById: new Map<string, any>(),
        payers: [] as any[]
      };
    }

    const patientIdChunks = chunkTissPreGuideScopeIds(unresolvedPatientIds);
    const loadChunkedRows = async (
      loader: (patientIds: string[]) => Promise<{ data: any[] | null; error: any }>
    ) => {
      const rows: any[] = [];
      const concurrency = 4;
      for (let index = 0; index < patientIdChunks.length; index += concurrency) {
        const results = await Promise.all(patientIdChunks.slice(index, index + concurrency).map(loader));
        for (const result of results) {
          if (result.error) {
            if (sanitizeString(result.error?.message || result.error?.details, 500).includes('get_patient_financial_plans_batch_v1')) {
              throw result.error;
            }
            if (hasMissingFinancialSchema(result.error) || isMissingRelationError(result.error)) continue;
            throw result.error;
          }
          if (Array.isArray(result.data)) rows.push(...result.data);
        }
      }
      return rows;
    };

    const [financialPlans, patients, payerResult] = await Promise.all([
      loadChunkedRows((patientIds) => supabase.rpc('get_patient_financial_plans_batch_v1', {
        p_organization_id: organizationId,
        p_patient_ids: patientIds,
        p_per_patient_limit: 20,
      }) as any),
      loadChunkedRows((patientIds) => supabase
        .from('patients')
        .select('id,insurance_type,insurance_name,insurance_card_number,insurance_card_valid_until,insurance_plan_category,insurance_holder_name')
        .eq('clinic_id', organizationId)
        .in('id', patientIds)
        .limit(patientIds.length) as any),
      needsPayerBatch
        ? supabase
            .from('clinic_payers')
            .select('id,name,status')
            .eq('organization_id', organizationId)
            .limit(1000)
        : Promise.resolve({ data: [], error: null } as any)
    ]);
    if (payerResult.error && !hasMissingFinancialSchema(payerResult.error) && !isMissingRelationError(payerResult.error)) {
      throw payerResult.error;
    }

    const payers = payerResult.error ? [] : Array.isArray(payerResult.data) ? payerResult.data : [];
    const financialPlansByPatient = new Map<string, any[]>();
    for (const plan of financialPlans) {
      const patientId = sanitizeString(plan?.patient_id, 120);
      if (!isUuid(patientId)) continue;
      financialPlansByPatient.set(patientId, [...(financialPlansByPatient.get(patientId) || []), plan]);
    }
    const patientsById = new Map<string, any>(
      patients
        .map((patient: any) => [sanitizeString(patient?.id, 120), patient] as const)
        .filter(([patientId]) => isUuid(patientId))
    );
    return {
      contextsByAppointment: buildTissPreGuideEligibilityContexts({
        appointments,
        contextsByAppointment,
        financialPlans,
        patients,
        payers
      }),
      financialPlansByPatient,
      patientsById,
      payers
    };
  };

  const upsertAppointmentClosureCheckRow = async (payload: any) => {
    const isMissingUpsertConflictTargetError = (error: any) => {
      const code = sanitizeString(error?.code, 20).toUpperCase();
      const message = extractSupabaseErrorMessage(error).toLowerCase();
      return code === '42P10' || (
        message.includes('unique') &&
        message.includes('exclusion') &&
        message.includes('constraint')
      ) || message.includes('no unique or exclusion constraint matching the on conflict specification');
    };
    const withClosureCheckDiagnostics = (error: any, storagePayload: any, omittedColumns: Set<string>) => Object.assign(error || new Error('closure_check_write_failed'), {
      attemptedPayload: summarizeClosureCheckPayloadForDiagnostics({
        ...storagePayload,
        omittedColumns: Array.from(omittedColumns)
      })
    });
    const writeWithoutConflictTarget = async (storagePayload: any, selectColumns: string, omittedColumns: Set<string>) => {
      const organizationId = sanitizeString(storagePayload?.organization_id, 120);
      const appointmentId = sanitizeString(storagePayload?.appointment_id, 120);
      if (!isUuid(organizationId) || !isUuid(appointmentId)) {
        return {
          data: null,
          error: withClosureCheckDiagnostics({
            code: 'MISSING_CLOSURE_SCOPE',
            message: 'organization_id e appointment_id são obrigatórios para materializar o check.'
          }, storagePayload, omittedColumns)
        };
      }

      const existingResult = await supabase
        .from('appointment_closure_checks')
        .select('id')
        .eq('organization_id', organizationId)
        .eq('appointment_id', appointmentId)
        .limit(1)
        .maybeSingle();
      if (existingResult.error) {
        return {
          data: null,
          error: withClosureCheckDiagnostics(existingResult.error, storagePayload, omittedColumns)
        };
      }

      if (existingResult.data?.id) {
        const updatePayload = cleanObject({
          ...storagePayload,
          id: sanitizeString(existingResult.data.id, 120)
        });
        const updateResult = await supabase
          .from('appointment_closure_checks')
          .update(updatePayload)
          .eq('organization_id', organizationId)
          .eq('appointment_id', appointmentId)
          .select(selectColumns)
          .maybeSingle();
        return updateResult.error
          ? { ...updateResult, error: withClosureCheckDiagnostics(updateResult.error, updatePayload, omittedColumns) }
          : updateResult;
      }

      const insertResult = await supabase
        .from('appointment_closure_checks')
        .insert([storagePayload])
        .select(selectColumns)
        .maybeSingle();
      if (!insertResult.error) return insertResult;

      const duplicateCode = sanitizeString(insertResult.error?.code, 20).toUpperCase();
      if (duplicateCode === '23505') {
        const retryExisting = await supabase
          .from('appointment_closure_checks')
          .select('id')
          .eq('organization_id', organizationId)
          .eq('appointment_id', appointmentId)
          .limit(1)
          .maybeSingle();
        if (!retryExisting.error && retryExisting.data?.id) {
          const retryPayload = cleanObject({
            ...storagePayload,
            id: sanitizeString(retryExisting.data.id, 120)
          });
          const retryUpdate = await supabase
            .from('appointment_closure_checks')
            .update(retryPayload)
            .eq('organization_id', organizationId)
            .eq('appointment_id', appointmentId)
            .select(selectColumns)
            .maybeSingle();
          return retryUpdate.error
            ? { ...retryUpdate, error: withClosureCheckDiagnostics(retryUpdate.error, retryPayload, omittedColumns) }
            : retryUpdate;
        }
      }

      return {
        ...insertResult,
        error: withClosureCheckDiagnostics(insertResult.error, storagePayload, omittedColumns)
      };
    };

    const omittedColumns = new Set<string>();
    let lastError: any = null;
    for (let attempt = 0; attempt <= APPOINTMENT_CLOSURE_CHECK_SCHEMA_FALLBACK_COLUMNS.size; attempt += 1) {
      const storagePayload = buildAppointmentClosureCheckStoragePayload(payload, omittedColumns);
      let result = await supabase
        .from('appointment_closure_checks')
        .upsert([storagePayload], { onConflict: 'organization_id,appointment_id' })
        .select(buildAppointmentClosureCheckSelect(omittedColumns))
        .maybeSingle();
      if (result.error && isMissingUpsertConflictTargetError(result.error)) {
        console.warn('[Closure] upsert sem constraint única; usando fallback idempotente por appointment.', {
          appointmentId: sanitizeString(storagePayload?.appointment_id, 120),
          code: sanitizeString(result.error?.code, 40) || null
        });
        result = await writeWithoutConflictTarget(
          storagePayload,
          buildAppointmentClosureCheckSelect(omittedColumns),
          omittedColumns
        );
      }
      if (!result.error) {
        return {
          ok: true,
          data: cleanObject({
            ...payload,
            ...storagePayload,
            ...(result.data || {})
          })
        };
      }
      if (isMissingRelationError(result.error)) {
        return { ok: false, status: 503, error: 'Fechamento indisponível.', dbCode: sanitizeString(result.error?.code, 80) || null, dbDetail: sanitizeString(result.error?.details || result.error?.detail, 500) || null, attemptedPayload: (result.error as any)?.attemptedPayload };
      }

      const missingColumn = extractMissingColumnName(result.error);
      if (!missingColumn || !APPOINTMENT_CLOSURE_CHECK_SCHEMA_FALLBACK_COLUMNS.has(missingColumn) || omittedColumns.has(missingColumn)) {
        if (hasMissingFinancialSchema(result.error)) {
          return { ok: false, status: 503, error: 'Fechamento indisponível.', dbCode: sanitizeString(result.error?.code, 80) || null, dbDetail: sanitizeString(result.error?.details || result.error?.detail, 500) || null, attemptedPayload: (result.error as any)?.attemptedPayload };
        }
        throw withClosureCheckDiagnostics(result.error, storagePayload, omittedColumns);
      }
      omittedColumns.add(missingColumn);
      lastError = result.error;
    }

    if (lastError && hasMissingFinancialSchema(lastError)) {
      return { ok: false, status: 503, error: 'Fechamento indisponível.', dbCode: sanitizeString(lastError?.code, 80) || null, dbDetail: sanitizeString(lastError?.details || lastError?.detail, 500) || null, attemptedPayload: (lastError as any)?.attemptedPayload };
    }
    if (lastError) throw withClosureCheckDiagnostics(lastError, payload, omittedColumns);
    return { ok: false, status: 503, error: 'Fechamento indisponível.' };
  };

  const persistAppointmentClosureCheck = async (params: {
    appointmentId: string;
    user: any;
    force?: boolean;
    manualNotBillable?: boolean;
    scopedAppointment?: any;
  }) => {
    const context = await fetchAppointmentClosureContext(params.appointmentId, params.user, {
      scopedAppointment: params.scopedAppointment
    });
    if (!context.ok) return context;
    const appointment = (context as any).appointment;
    const abaSession = (context as any).abaSession;
    const sessionSummary = (context as any).sessionSummary;
    const patient = (context as any).patient;
    const professional = (context as any).professional;
    const organizationId = (context as any).organizationId;
    const appointmentId = sanitizeString(appointment?.id, 120);
    const abaSessionId = sanitizeString(abaSession?.id, 180) || null;
    const patientId = sanitizeString(appointment?.patient_id || abaSession?.patient_id, 120);
    const existingResult = await fetchAppointmentClosureCheckRow({
      organizationId,
      appointmentId,
      user: params.user
    });

    const billingContext = await resolveEffectiveClosureBillingContext({
      organizationId,
      patientId,
      appointment,
      billingContext: (context as any).billingContext || {}
    });
    const closureRequirements = {
      ...((context as any).requirements || {}),
      payerId: (context as any).requirements?.payerId || billingContext?.payer_id || null,
      payerName: (context as any).requirements?.payerName || billingContext?.payer_name_snapshot || null
    };
    const billingContextTypeForEvaluation =
      normalizeAppointmentFinancialContextType(billingContext?.payer_type) ||
      (sanitizeString(billingContext?.payer_id || billingContext?.payer_name_snapshot, 180) ? 'INSURANCE' : null);
    const requiredDocuments = Array.isArray((context as any).requiredDocuments) ? (context as any).requiredDocuments : [];
    const pendingRequiredDocuments = requiredDocuments.filter((doc: any) => ['REQUIRED', 'PENDING', 'EXPIRED'].includes(sanitizeString(doc?.status, 40).toUpperCase()));
    const appointmentForEvaluation = {
      ...appointment,
      payer_id: billingContext?.payer_id || closureRequirements?.payerId || null,
      payer_name_snapshot: billingContext?.payer_name_snapshot || null,
      payer_type: billingContextTypeForEvaluation,
      financial_context_type: billingContextTypeForEvaluation,
      insurance_card_number: billingContext?.insurance_card_number || null,
      insurance_plan_name: billingContext?.insurance_plan_name || null,
      authorization_code: billingContext?.authorization_code || null,
      guide_number: billingContext?.guide_number || null,
      procedure_code: billingContext?.procedure_code || null,
      required_documents: requiredDocuments,
      required_documents_pending_count: pendingRequiredDocuments.length
    };

    const evaluation = evaluateAppointmentClosureReadiness({
      organizationId,
      appointmentId,
      abaSessionId,
      patientId,
      triggeredBy: sanitizeString(params.user?.id, 120) || null,
      appointment: appointmentForEvaluation,
      abaSession,
      sessionSummary,
      report: sessionSummary,
      signature: (context as any).signature,
      patient,
      professional,
      requirements: closureRequirements,
      manualNotBillable: params.manualNotBillable || financialContextIsNotBillable(billingContext?.payer_type)
    });

    const existing = existingResult.data || null;
    if (!params.force && existing?.context_hash && existing.context_hash === evaluation.contextHash) {
      return {
        ok: true,
        reused: true,
        data: {
          ...existing,
          ...buildAppointmentClosureOperationalView(existing?.checklist || [], evaluation.phase)
        }
      };
    }

    const professionalId = sanitizeString(evaluation.summary.professionalId, 120);
    const payload = cleanObject({
      id: existing?.id || crypto.randomUUID(),
      organization_id: organizationId,
      appointment_id: appointmentId,
      aba_session_id: abaSessionId,
      patient_id: isUuid(patientId) ? patientId : null,
      professional_id: isUuid(professionalId) ? professionalId : null,
      service_type: evaluation.summary.serviceType,
      payer_id: isUuid(sanitizeString(billingContext?.payer_id || closureRequirements?.payerId, 120)) ? sanitizeString(billingContext?.payer_id || closureRequirements?.payerId, 120) : null,
      payer_name_snapshot: sanitizeString(billingContext?.payer_name_snapshot, 180) || null,
      authorization_code: sanitizeString(billingContext?.authorization_code, 120) || null,
      guide_number: sanitizeString(billingContext?.guide_number, 120) || null,
      applied_payer_requirement_id: isUuid(sanitizeString(closureRequirements?.appliedPayerRequirementId, 120)) ? sanitizeString(closureRequirements?.appliedPayerRequirementId, 120) : null,
      payer_requirement_source: sanitizeString(closureRequirements?.payerRequirementSource, 40) || null,
      required_document_pending_count: pendingRequiredDocuments.length,
      readiness_status: evaluation.readinessStatus,
      checklist: sanitizeClinicalPayload(evaluation.checklist),
      blocking_issues_count: evaluation.blockingIssuesCount,
      warning_issues_count: evaluation.warningIssuesCount,
      missing_required_count: evaluation.missingRequiredCount,
      scheduled_start: evaluation.summary.scheduledStart,
      scheduled_end: evaluation.summary.scheduledEnd,
      actual_start: evaluation.summary.actualStart,
      actual_end: evaluation.summary.actualEnd,
      scheduled_minutes: evaluation.summary.scheduledMinutes,
      actual_minutes: evaluation.summary.actualMinutes,
      main_issues: sanitizeClinicalPayload(evaluation.summary.mainIssues),
      generated_at: new Date().toISOString(),
      generated_by: isUuid(sanitizeString(params.user?.id, 120)) ? sanitizeString(params.user?.id, 120) : null,
      updated_at: new Date().toISOString(),
      context_hash: evaluation.contextHash
    });

    const result = await upsertAppointmentClosureCheckRow(payload);
    if (!result.ok) return result;
    await writeClosureAuditLog({
      organizationId,
      appointmentId,
      abaSessionId,
      patientId,
      action: existing ? 'CHECK_REGENERATED' : 'CHECK_GENERATED',
      previousStatus: existing?.readiness_status || null,
      newStatus: evaluation.readinessStatus,
      performedBy: sanitizeString(params.user?.id, 120),
      metadata: {
        contextHash: evaluation.contextHash,
        force: Boolean(params.force),
        manualNotBillable: Boolean(params.manualNotBillable)
        || financialContextIsNotBillable(billingContext?.payer_type)
      }
    });
    return {
      ok: true,
      reused: false,
      data: {
        ...(result.data || payload),
        phase: evaluation.phase,
        phaseSummary: evaluation.phaseSummary,
        sections: evaluation.sections
      }
    };
  };

  const regenerateClosureForAppointments = async (appointmentIds: any[], user: any, source: string) => {
    const validAppointmentIds = Array.from(
      new Set((appointmentIds || []).map((id) => sanitizeString(id, 120)).filter((id) => isUuid(id)))
    ).slice(0, 80);
    if (validAppointmentIds.length === 0) return;
    for (const appointmentId of validAppointmentIds) {
      try {
        await persistAppointmentClosureCheck({
          appointmentId,
          user,
          force: false
        });
      } catch (error: any) {
        console.warn('[Closure] revalidação por evento falhou:', {
          source,
          appointmentId,
          message: error?.message || String(error)
        });
      }
    }
  };

  const fetchClosurePeriodAppointmentRows = async (params: {
    clinicId: string;
    user: any;
    fromIso: string;
    toIso: string;
    limit?: number;
    patientId?: string | null;
    ascending?: boolean;
  }) => {
    const clinicId = sanitizeString(params.clinicId, 120);
    const patientId = sanitizeString(params.patientId, 120);
    const ascending = params.ascending !== false;
    const rowsById = new Map<string, any>();
    const limit = Math.min(Math.max(Number(params.limit || 800), 1), 1200);
    if (!isUuid(clinicId)) return [];
    const omittedColumns = new Set<string>();
    const therapistPatientIds = sanitizeString(params.user?.role, 40).toLowerCase() === 'therapist'
      ? await getClosureTherapistPatientIds(params.user, clinicId)
      : [];
    const therapistUserId = sanitizeString(params.user?.id, 120);

    for (let attempt = 0; attempt <= CLOSURE_APPOINTMENT_SCHEMA_FALLBACK_COLUMNS.size + 2; attempt += 1) {
      let retriedWithOmittedColumn = false;
      for (const dateColumn of ['scheduled_at', 'scheduled_start_at']) {
        if (omittedColumns.has(dateColumn)) continue;
        let query = supabase
          .from('appointments')
          .select(buildClosureAppointmentSelect(omittedColumns))
          .gte(dateColumn, params.fromIso)
          .lte(dateColumn, params.toIso)
          .order(dateColumn, { ascending })
          .limit(limit);
        if (!omittedColumns.has('status')) query = query.neq('status', 'deleted');
        if (isUuid(patientId)) query = query.eq('patient_id', patientId);
        if (omittedColumns.has('organization_id') && omittedColumns.has('clinic_id')) return [];
        if (!omittedColumns.has('organization_id') && !omittedColumns.has('clinic_id')) {
          query = query.or(`organization_id.eq.${clinicId},clinic_id.eq.${clinicId}`);
        } else if (!omittedColumns.has('organization_id')) {
          query = query.eq('organization_id', clinicId);
        } else if (!omittedColumns.has('clinic_id')) {
          query = query.eq('clinic_id', clinicId);
        }
        if (sanitizeString(params.user?.role, 40).toLowerCase() === 'therapist') {
          const orParts = [];
          if (!omittedColumns.has('therapist_id') && isUuid(therapistUserId)) orParts.push(`therapist_id.eq.${therapistUserId}`);
          if (therapistPatientIds.length > 0) orParts.push(`patient_id.in.(${therapistPatientIds.join(',')})`);
          if (orParts.length > 0) query = query.or(orParts.join(','));
          else if (!omittedColumns.has('therapist_id')) query = query.eq('therapist_id', '00000000-0000-0000-0000-000000000000');
          else return [];
        }
        const result = await query;
        if (result.error) {
          if (isMissingRelationError(result.error)) return [];
          const missingColumn = extractMissingColumnName(result.error);
          if (missingColumn && CLOSURE_APPOINTMENT_SCHEMA_FALLBACK_COLUMNS.has(missingColumn) && !omittedColumns.has(missingColumn)) {
            omittedColumns.add(missingColumn);
            retriedWithOmittedColumn = true;
            break;
          }
          if (hasMissingFinancialSchema(result.error)) continue;
          throw result.error;
        }
        (Array.isArray(result.data) ? result.data : []).forEach((row: any) => {
          const id = sanitizeString(row?.id, 120);
          if (isUuid(id)) rowsById.set(id, row);
        });
      }
      if (!retriedWithOmittedColumn) break;
    }
    return Array.from(rowsById.values()).sort((left: any, right: any) => {
      const leftTime = new Date(left?.scheduled_at || left?.scheduled_start_at || 0).getTime();
      const rightTime = new Date(right?.scheduled_at || right?.scheduled_start_at || 0).getTime();
      const delta = (Number.isFinite(leftTime) ? leftTime : 0) - (Number.isFinite(rightTime) ? rightTime : 0);
      return ascending ? delta : -delta;
    }).slice(0, limit);
  };

  const fetchClosureAppointmentRowsByIds = async (params: {
    clinicId: string;
    user: any;
    appointmentIds: string[];
    patientId?: string | null;
  }) => {
    const clinicId = sanitizeString(params.clinicId, 120);
    const patientId = sanitizeString(params.patientId, 120);
    const appointmentIds = Array.from(new Set(
      (params.appointmentIds || []).map((id) => sanitizeString(id, 120)).filter((id) => isUuid(id))
    )).slice(0, 500);
    if (!isUuid(clinicId) || appointmentIds.length === 0) return [];

    const omittedColumns = new Set<string>();
    const therapistPatientIds = sanitizeString(params.user?.role, 40).toLowerCase() === 'therapist'
      ? await getClosureTherapistPatientIds(params.user, clinicId)
      : [];
    const therapistUserId = sanitizeString(params.user?.id, 120);

    for (let attempt = 0; attempt <= CLOSURE_APPOINTMENT_SCHEMA_FALLBACK_COLUMNS.size + 2; attempt += 1) {
      let query = supabase
        .from('appointments')
        .select(buildClosureAppointmentSelect(omittedColumns))
        .in('id', appointmentIds)
        .limit(appointmentIds.length);
      if (!omittedColumns.has('status')) query = query.neq('status', 'deleted');
      if (isUuid(patientId)) query = query.eq('patient_id', patientId);
      if (omittedColumns.has('organization_id') && omittedColumns.has('clinic_id')) return [];
      if (!omittedColumns.has('organization_id') && !omittedColumns.has('clinic_id')) {
        query = query.or(`organization_id.eq.${clinicId},clinic_id.eq.${clinicId}`);
      } else if (!omittedColumns.has('organization_id')) {
        query = query.eq('organization_id', clinicId);
      } else if (!omittedColumns.has('clinic_id')) {
        query = query.eq('clinic_id', clinicId);
      }
      if (sanitizeString(params.user?.role, 40).toLowerCase() === 'therapist') {
        const orParts = [];
        if (!omittedColumns.has('therapist_id') && isUuid(therapistUserId)) orParts.push(`therapist_id.eq.${therapistUserId}`);
        if (therapistPatientIds.length > 0) orParts.push(`patient_id.in.(${therapistPatientIds.join(',')})`);
        if (orParts.length > 0) query = query.or(orParts.join(','));
        else if (!omittedColumns.has('therapist_id')) query = query.eq('therapist_id', '00000000-0000-0000-0000-000000000000');
        else return [];
      }
      const result = await query;
      if (!result.error) return Array.isArray(result.data) ? result.data : [];
      if (isMissingRelationError(result.error)) return [];
      const missingColumn = extractMissingColumnName(result.error);
      if (missingColumn && CLOSURE_APPOINTMENT_SCHEMA_FALLBACK_COLUMNS.has(missingColumn) && !omittedColumns.has(missingColumn)) {
        omittedColumns.add(missingColumn);
        continue;
      }
      if (hasMissingFinancialSchema(result.error)) return [];
      throw result.error;
    }
    return [];
  };

  const mirrorLegacyClosureAppointmentsForPeriod = async (params: {
    clinicId: string;
    user: any;
    fromIso: string;
    toIso: string;
    dryRun?: boolean;
  }) => {
    const clinicId = sanitizeString(params.clinicId, 120);
    const actorId = sanitizeString(params.user?.id, 120);
    if (!isUuid(clinicId)) return { legacyFound: 0, legacyMirrored: 0, legacySkipped: 0 };
    const stateResult = await fetchClinicStateWithSchemaFallback({ supabase, clinicId, logger: console });
    if (stateResult.error) {
      if (hasMissingFinancialSchema(stateResult.error) || isMissingRelationError(stateResult.error)) {
        return { legacyFound: 0, legacyMirrored: 0, legacySkipped: 0 };
      }
      throw stateResult.error;
    }
    const fromTime = new Date(params.fromIso).getTime();
    const toTime = new Date(params.toIso).getTime();
    const candidates = (Array.isArray(stateResult.data?.appointments) ? stateResult.data.appointments : [])
      .filter((appointment: any) => {
        const status = sanitizeString(appointment?.status, 80).toLowerCase();
        if (appointment?.is_active === false || appointment?.isActive === false || appointment?.deleted_at || appointment?.deletedAt || status === 'deleted') return false;
        const scheduledAt = buildAppointmentScheduledAt(appointment);
        const start = scheduledAt ? new Date(scheduledAt).getTime() : NaN;
        return Number.isFinite(start) && start >= fromTime && start <= toTime;
      })
      .slice(0, 800);
    if (candidates.length === 0 || params.dryRun) {
      return { legacyFound: candidates.length, legacyMirrored: 0, legacySkipped: 0 };
    }
    const summary = await syncAppointmentsTableFromClinicState({
      clinicId,
      appointments: candidates,
      actorId,
      specialtySettings:
        stateResult.data?.specialty_settings && typeof stateResult.data.specialty_settings === 'object'
          ? stateResult.data.specialty_settings
          : {},
      onAppointmentMirrored: (context) => flagPendingMaintenanceProbesForAppointment(context)
    });
    return {
      legacyFound: candidates.length,
      legacyMirrored: Number(summary?.mirrored || 0),
      legacySkipped: Number(summary?.skipped || 0)
    };
  };

  const buildClosureRevalidationErrorDetail = (appointment: any, appointmentId: string, failure: any) => {
    const source = parseCalendarSourcePayload(appointment?.source_payload || appointment?.sourcePayload);
    const patientId = sanitizeString(appointment?.patient_id || appointment?.patientId || source?.patient_id || source?.patientId, 120);
    const professionalId = sanitizeString(
      appointment?.therapist_id ||
        appointment?.therapistId ||
        appointment?.professional_id ||
        appointment?.professionalId ||
        source?.therapist_id ||
        source?.therapistId ||
        source?.professional_id ||
        source?.professionalId,
      120
    );
    const clinicId = sanitizeString(appointment?.clinic_id || appointment?.clinicId || source?.clinic_id || source?.clinicId, 120);
    const organizationId = sanitizeString(appointment?.organization_id || appointment?.organizationId || source?.organization_id || source?.organizationId, 120);
    const appointmentStatus = sanitizeString(appointment?.status || source?.status, 80) || null;
    const scheduledStart = buildAppointmentScheduledAt(appointment);
    const scheduledEnd = sanitizeString(
      appointment?.scheduled_end_at ||
        appointment?.scheduledEndAt ||
        appointment?.scheduled_end ||
        appointment?.scheduledEnd ||
        source?.scheduled_end_at ||
        source?.scheduledEndAt,
      80
    );
    const plannedDuration = Number(
      appointment?.scheduled_duration_minutes ||
        appointment?.duration_minutes ||
        appointment?.durationMinutes ||
        source?.scheduled_duration_minutes ||
        source?.duration_minutes ||
        source?.durationMinutes
    );
    const dbCode = sanitizeString(failure?.code || failure?.dbCode || failure?.details?.code, 80) || null;
    const message = sanitizeString(failure?.error || failure?.message || String(failure || ''), 500) || 'Falha ao materializar check de fechamento.';
    const rawDbDetail = typeof failure?.details === 'string'
      ? failure.details
      : typeof failure?.detail === 'string'
        ? failure.detail
        : failure?.dbDetail;
    const rawDbHint = typeof failure?.hint === 'string' ? failure.hint : failure?.dbHint;
    const dbDetail = sanitizeString(rawDbDetail, 500) || null;
    const dbHint = sanitizeString(rawDbHint, 500) || null;
    const missingColumn = extractMissingColumnName(failure);
    const schemaError = missingColumn || (hasMissingFinancialSchema(failure) ? message : '');
    const failureStatus = Number(failure?.status || 0);
    let reasonCode = 'MATERIALIZATION_FAILED';
    if (!isUuid(patientId)) reasonCode = 'MISSING_PATIENT_ID';
    else if (!scheduledStart) reasonCode = 'MISSING_SCHEDULED_START';
    else if (failureStatus === 404 || /n[aã]o encontrada|not found/i.test(message)) reasonCode = 'APPOINTMENT_NOT_ACCESSIBLE';
    else if (failureStatus === 503 || schemaError) reasonCode = 'CLOSURE_SCHEMA_UNAVAILABLE';
    else if (/conflict|duplicate|constraint/i.test(message)) reasonCode = 'UPSERT_CONSTRAINT_FAILED';
    else if (dbCode === '42P10') reasonCode = 'UPSERT_CONSTRAINT_MISSING';
    else if (dbCode === '23505') reasonCode = 'CONSTRAINT_DUPLICATE';
    else if (dbCode === '42501' || /row-level security|rls|permission denied/i.test(message)) reasonCode = 'RLS_OR_PERMISSION_DENIED';
    else if (dbCode) reasonCode = `DB_${dbCode}`;

    return cleanObject({
      appointmentId,
      stage: 'materialize_closure_check',
      status: 'failed',
      reasonCode,
      message,
      dbCode,
      dbDetail,
      dbHint,
      payloadTentado: failure?.attemptedPayload || null,
      appointmentSnapshot: cleanObject({
        hasClinicId: isUuid(clinicId),
        hasOrganizationId: isUuid(organizationId),
        hasPatientId: isUuid(patientId),
        hasProfessionalId: isUuid(professionalId),
        status: appointmentStatus,
        startsAt: scheduledStart || null
      }),
      details: cleanObject({
        hasPatientId: isUuid(patientId),
        hasProfessionalId: isUuid(professionalId),
        hasClinicId: isUuid(clinicId),
        hasOrganizationId: isUuid(organizationId),
        hasScheduledStart: Boolean(scheduledStart),
        hasScheduledEndOrDuration: Boolean(scheduledEnd) || (Number.isFinite(plannedDuration) && plannedDuration > 0),
        appointmentStatus,
        schemaError: schemaError || null,
        dbCode
      })
    });
  };

  const revalidateClosureChecksForPeriod = async (params: {
    clinicId: string;
    user: any;
    fromIso: string;
    toIso: string;
    dryRun?: boolean;
    source?: string;
  }) => {
    const clinicId = sanitizeString(params.clinicId, 120);
    const result = {
      found: 0,
      created: 0,
      updated: 0,
      reused: 0,
      skipped: 0,
      errors: 0,
      legacyFound: 0,
      legacyMirrored: 0,
      legacySkipped: 0,
      appointmentIds: [] as string[],
      partialFailure: false,
      errorDetails: [] as any[],
      dryRun: Boolean(params.dryRun)
    };
    if (!isUuid(clinicId)) return result;
    const legacy = await mirrorLegacyClosureAppointmentsForPeriod({
      clinicId,
      user: params.user,
      fromIso: params.fromIso,
      toIso: params.toIso,
      dryRun: params.dryRun
    });
    result.legacyFound = legacy.legacyFound;
    result.legacyMirrored = legacy.legacyMirrored;
    result.legacySkipped = legacy.legacySkipped;

    const appointmentRows = await fetchClosurePeriodAppointmentRows({
      clinicId,
      user: params.user,
      fromIso: params.fromIso,
      toIso: params.toIso
    });
    const appointmentIds = appointmentRows
      .map((row: any) => sanitizeString(row?.id, 120))
      .filter((id: string) => isUuid(id));
    result.found = appointmentIds.length;
    result.appointmentIds = appointmentIds;
    if (appointmentIds.length === 0) return result;

    let existingQuery = supabase
      .from('appointment_closure_checks')
      .select('appointment_id, readiness_status')
      .eq('organization_id', clinicId)
      .in('appointment_id', appointmentIds)
      .limit(appointmentIds.length);
    existingQuery = (await applyClosureTenantScope(existingQuery, params.user, clinicId)).query;
    const existingRowsResult = await existingQuery;
    if (existingRowsResult.error && !hasMissingFinancialSchema(existingRowsResult.error)) throw existingRowsResult.error;
    const existingIds = new Set<string>((existingRowsResult.error ? [] : existingRowsResult.data || [])
      .map((row: any) => sanitizeString(row?.appointment_id, 120))
      .filter((id: string) => isUuid(id)));

    const manualOverrideIds = new Set<string>();
    const auditResult = await supabase
      .from('appointment_closure_audit_logs')
      .select('appointment_id, action')
      .eq('organization_id', clinicId)
      .in('appointment_id', appointmentIds)
      .in('action', ['MANUAL_OVERRIDE', 'MARKED_NOT_BILLABLE'])
      .limit(Math.min(appointmentIds.length * 8, 1000));
    if (!auditResult.error) {
      (auditResult.data || []).forEach((row: any) => {
        const appointmentId = sanitizeString(row?.appointment_id, 120);
        if (isUuid(appointmentId)) manualOverrideIds.add(appointmentId);
      });
    } else if (!hasMissingFinancialSchema(auditResult.error)) {
      console.warn('[Closure] manual override audit lookup skipped:', auditResult.error?.message || String(auditResult.error));
    }

    const appointmentById = new Map<string, any>(appointmentRows.map((row: any) => [sanitizeString(row?.id, 120), row]));

    for (const appointmentId of appointmentIds) {
      if (manualOverrideIds.has(appointmentId)) {
        result.skipped += 1;
        continue;
      }
      if (params.dryRun) {
        existingIds.has(appointmentId) ? (result.reused += 1) : (result.created += 1);
        continue;
      }
      try {
        const hadExisting = existingIds.has(appointmentId);
        const generated = await persistAppointmentClosureCheck({
          appointmentId,
          user: params.user,
          force: false,
          scopedAppointment: appointmentById.get(appointmentId)
        });
        if (!(generated as any).ok) {
          result.errors += 1;
          result.errorDetails.push(buildClosureRevalidationErrorDetail(
            appointmentById.get(appointmentId),
            appointmentId,
            generated
          ));
        } else if ((generated as any).reused) {
          result.reused += 1;
        } else if (hadExisting) {
          result.updated += 1;
        } else {
          result.created += 1;
        }
      } catch (error: any) {
        result.errors += 1;
        result.errorDetails.push(buildClosureRevalidationErrorDetail(
          appointmentById.get(appointmentId),
          appointmentId,
          error
        ));
        console.warn('[Closure] period revalidation item failed:', {
          source: sanitizeString(params.source, 80) || 'period_revalidation',
          appointmentId,
          message: error?.message || String(error)
        });
      }
    }
    result.partialFailure = result.errors > 0;

    if (!params.dryRun) {
      await writeClosureAuditLog({
        organizationId: clinicId,
        action: 'PERIOD_REVALIDATED',
        performedBy: sanitizeString(params.user?.id, 120),
        metadata: {
          source: sanitizeString(params.source, 80) || 'manual',
          from: params.fromIso,
          to: params.toIso,
          ...result
        }
      });
    }
    return result;
  };

  const fetchClosureSummariesByAppointment = async (appointmentIds: string[], organizationId: string, user: any) => {
    const validAppointmentIds = Array.from(new Set(appointmentIds.filter((id) => isUuid(id)))).slice(0, 200);
    const byAppointment = new Map<string, any>();
    if (validAppointmentIds.length === 0 || !isUuid(organizationId)) return byAppointment;
    let query = supabase
      .from('appointment_closure_checks')
      .select(APPOINTMENT_CLOSURE_LIST_SELECT)
      .eq('organization_id', organizationId)
      .in('appointment_id', validAppointmentIds)
      .limit(validAppointmentIds.length);
    query = (await applyClosureTenantScope(query, user, organizationId)).query;
    const { data, error } = await query;
    if (error) {
      if (hasMissingFinancialSchema(error)) return byAppointment;
      throw error;
    }
    (data || []).forEach((row: any) => {
      const id = sanitizeString(row?.appointment_id, 120);
      if (id) byAppointment.set(id, row);
    });
    return byAppointment;
  };

