  const repairChecklistDisplayText = (value: unknown, maxLength = 800) =>
    sanitizeString(value, maxLength)
      .replace(/ÃƒÂ§/g, 'ç')
      .replace(/ÃƒÂ£/g, 'ã')
      .replace(/ÃƒÂ¡/g, 'á')
      .replace(/ÃƒÂ©/g, 'é')
      .replace(/ÃƒÂª/g, 'ê')
      .replace(/ÃƒÂ­/g, 'í')
      .replace(/ÃƒÂ³/g, 'ó')
      .replace(/ÃƒÂµ/g, 'õ')
      .replace(/ÃƒÂº/g, 'ú')
      .replace(/ÃƒÂ /g, 'à')
      .replace(/Ã§/g, 'ç')
      .replace(/Ã£/g, 'ã')
      .replace(/Ã¡/g, 'á')
      .replace(/Ã©/g, 'é')
      .replace(/Ãª/g, 'ê')
      .replace(/Ã­/g, 'í')
