  const normalizeNonNegativeCents = (value: unknown, fallback = 0) => {
    const numeric = Math.round(Number(value));
    if (!Number.isFinite(numeric)) return Math.max(0, Math.round(Number(fallback || 0)));
    return Math.max(0, numeric);
  };

