  app.post('/api/tiss/xml-drafts', portalActionLimiter, noStoreDynamicResponse, checkAuth, requireClinicModule('insurance_tiss'), requireClinicCapability('billing.xml.generate'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'XML TISS em rascunho')) return;
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      if (!isUuid(organizationId)) return res.status(400).json(payerSafeError(400));
      const payerId = sanitizeString(req.body?.payerId || req.body?.payer_id, 120);
      if (!isUuid(payerId)) {
        return res.status(400).json({
          success: false,
          code: 'TISS_XML_DRAFT_PAYER_REQUIRED',
          error: 'Selecione um pagador para gerar o XML TISS em rascunho.'
        });
      }
      const rawPreGuideIds = Array.isArray(req.body?.preGuideIds || req.body?.pre_guide_ids)
        ? (req.body?.preGuideIds || req.body?.pre_guide_ids)
        : [];
      const preGuideIds = Array.from(new Set(rawPreGuideIds.map((id: unknown) => sanitizeString(id, 120)).filter((id: string) => isUuid(id)))).slice(0, 200);
      const dateFrom = sanitizeString(req.body?.dateFrom || req.body?.date_from || req.body?.from, 80);
      const dateTo = sanitizeString(req.body?.dateTo || req.body?.date_to || req.body?.to, 80);
      const competenceMonth = normalizeTissXmlCompetenceMonth(req.body?.competenceMonth || req.body?.competence_month, dateFrom);
      if (!competenceMonth) {
        return res.status(400).json({
          success: false,
          code: 'TISS_XML_DRAFT_COMPETENCE_REQUIRED',
          error: 'Informe a competência para gerar o XML TISS em rascunho.'
        });
      }
      const monthStart = `${competenceMonth.slice(0, 7)}-01T00:00:00.000Z`;
      const monthEndDate = new Date(Date.UTC(Number(competenceMonth.slice(0, 4)), Number(competenceMonth.slice(5, 7)), 0, 23, 59, 59, 999));
      const monthEnd = monthEndDate.toISOString();
      let query = supabase
        .from('appointment_tiss_pre_guides')
        .select(APPOINTMENT_TISS_PRE_GUIDE_SELECT)
        .eq('organization_id', organizationId)
        .eq('payer_id', payerId);
      if (preGuideIds.length > 0) {
        query = query.in('id', preGuideIds);
      } else {
        query = query
          .eq('status', 'valid')
          .gte('scheduled_start', dateFrom || monthStart)
          .lte('scheduled_start', dateTo || monthEnd);
      }
      const { data: preGuideRows, error: preGuideError } = await query.limit(500);
      if (preGuideError) {
        if (hasMissingFinancialSchema(preGuideError) || isMissingRelationError(preGuideError)) {
          return res.status(503).json({
            success: false,
            code: 'TISS_XML_DRAFT_SCHEMA_MISSING',
            error: 'A estrutura de rascunho XML TISS ainda não está disponível no banco.'
          });
        }
        throw preGuideError;
      }
      const preGuides = (preGuideRows || []).map((row: any) => serializeTissPreGuide(row));
      const generated = generateTissXmlDraft({
        preGuides,
        payerId,
        competenceMonth,
        guideType: sanitizeString(req.body?.guideType || req.body?.guide_type, 40),
        tissVersion: sanitizeString(req.body?.tissVersion || req.body?.tiss_version, 80),
        generatedAt: new Date().toISOString()
      });
      if (!generated.ok) {
        const status = generated.code === 'TISS_XML_DRAFT_PRE_GUIDE_NOT_READY' ? 409 : 422;
        return res.status(status).json({
          success: false,
          code: generated.code,
          error: generated.message,
          issues: generated.issues
        });
      }
      const now = new Date().toISOString();
      const xmlHash = crypto.createHash('sha256').update(generated.xml, 'utf8').digest('hex');
      const payerName = sanitizeString(preGuides[0]?.payerName || preGuides[0]?.snapshot?.payer?.name, 180) || 'Pagador';
      const metadata = {
        draft_format: generated.draftFormat || 'tiss_sp_sadt_draft',
        payerName,
        guideCount: generated.guideCount,
        totalAmountCents: generated.totalAmountCents,
        warning: 'Rascunho interno para conferência. Não enviado à operadora.',
        fileName: buildTissXmlDraftFileName({ competence_month: competenceMonth, payerName })
      };
      await supabase
        .from('tiss_xml_drafts')
        .update({ status: 'superseded', updated_at: now })
        .eq('organization_id', organizationId)
        .eq('payer_id', payerId)
        .eq('competence_month', competenceMonth)
        .eq('status', 'draft');
      const payload = {
        organization_id: organizationId,
        clinic_id: organizationId,
        payer_id: payerId,
        competence_month: competenceMonth,
        guide_type: generated.guideType,
        tiss_version: generated.tissVersion,
        status: 'draft',
        xml_content: generated.xml,
        xml_hash: xmlHash,
        generated_from_pre_guide_ids: generated.preGuideIds,
        generated_by: sanitizeString(req.session.user?.id, 120) || null,
        generated_at: now,
        validation_summary: generated.validationSummary,
        metadata,
        created_at: now,
        updated_at: now
      };
      const { data: draft, error: draftError } = await supabase
        .from('tiss_xml_drafts')
        .insert(payload)
        .select(TISS_XML_DRAFT_SELECT)
        .single();
      if (draftError) {
        if (hasMissingFinancialSchema(draftError) || isMissingRelationError(draftError)) {
          return res.status(503).json({
            success: false,
            code: 'TISS_XML_DRAFT_SCHEMA_MISSING',
            error: 'A estrutura de rascunho XML TISS ainda não está disponível no banco.'
          });
        }
        throw draftError;
      }
      const safePreGuideIds = generated.preGuideIds
        .map((id) => sanitizeString(id, 120))
        .filter((id) => isUuid(id));
      if (safePreGuideIds.length > 0) {
        const stateUpdate = await supabase
          .from('appointment_tiss_pre_guides')
          .update({
            revenue_cycle_state: 'xml_draft_generated',
            revenue_cycle_state_reason: 'XML TISS em rascunho gerado para conferência interna; não enviado à operadora.',
            updated_at: now
          })
          .eq('organization_id', organizationId)
          .in('id', safePreGuideIds);
        if (stateUpdate.error && !hasMissingFinancialSchema(stateUpdate.error) && !isMissingRelationError(stateUpdate.error)) {
          throw stateUpdate.error;
        }
      }
      const batchDraft = await createTissBillingBatchDraftForXmlDraft({
        organizationId,
        payerId,
        competenceMonth,
        preGuideIds: safePreGuideIds,
        xmlDraftId: draft.id,
        guideCount: generated.guideCount,
        totalAmountCents: generated.totalAmountCents,
        createdBy: sanitizeString(req.session.user?.id, 120),
        validationSummary: generated.validationSummary
      });
      if (batchDraft?.id && safePreGuideIds.length > 0) {
        const batchStateUpdate = await supabase
          .from('appointment_tiss_pre_guides')
          .update({
            revenue_cycle_state: 'billing_batch_draft',
            revenue_cycle_state_reason: 'XML rascunho gerado e pré-guia agrupada em lote rascunho para conferência interna; não enviada à operadora.',
            updated_at: now
          })
          .eq('organization_id', organizationId)
          .in('id', safePreGuideIds);
        if (batchStateUpdate.error && !hasMissingFinancialSchema(batchStateUpdate.error) && !isMissingRelationError(batchStateUpdate.error)) {
          throw batchStateUpdate.error;
        }
        await Promise.all(preGuides.map((row: any) => recordTissRevenueCycleEvent({
          organizationId,
          clinicId: organizationId,
          patientId: row.patientId || null,
          appointmentId: row.appointmentId || null,
          preGuideId: row.id || null,
          xmlDraftId: draft.id,
          payerId,
          eventType: 'TISS_BILLING_BATCH_DRAFT_CREATED',
          previousState: 'xml_draft_generated',
          newState: 'billing_batch_draft',
          reason: 'Pré-guia agrupada em lote rascunho vinculado ao XML para conferência interna. Nenhum dado foi enviado à operadora.',
          performedBy: isUuid(sanitizeString(req.session.user?.id, 120)) ? sanitizeString(req.session.user?.id, 120) : null,
          metadata: {
            batchDraftId: batchDraft.id,
            xmlDraftId: draft.id,
            guideCount: generated.guideCount,
            totalAmountCents: generated.totalAmountCents,
            notSentToPayer: true
          }
        })));
      }
      await recordTissRevenueCycleEvent({
        organizationId,
        clinicId: organizationId,
        xmlDraftId: draft.id,
        payerId,
        eventType: 'XML_DRAFT_GENERATED',
        previousState: 'ready_for_billing',
        newState: batchDraft?.id ? 'billing_batch_draft' : 'xml_draft_generated',
        reason: batchDraft?.id
          ? 'XML rascunho gerado e agrupado em lote rascunho para conferência interna.'
          : 'XML rascunho gerado para conferência interna.',
        performedBy: isUuid(sanitizeString(req.session.user?.id, 120)) ? sanitizeString(req.session.user?.id, 120) : null,
        metadata: {
          guideCount: generated.guideCount,
          totalAmountCents: generated.totalAmountCents,
          preGuideIds: safePreGuideIds,
          batchDraftId: batchDraft?.id || null,
          notSentToPayer: true
        }
      });
      return sendNoStoreJson(res, {
        success: true,
        data: {
          ...serializeTissXmlDraft(draft),
          batchDraft: batchDraft || null
        },
        message: 'XML TISS em rascunho gerado para conferência interna.'
      });
    } catch (error: any) {
      console.warn('[TissXmlDraft] create failed:', {
        code: sanitizeString(error?.code, 40) || null,
        message: sanitizeTextField(error?.message, 300) || String(error)
      });
      return res.status(500).json({ success: false, error: 'Não foi possível gerar o XML TISS em rascunho agora.' });
    }
  });

  app.get('/api/tiss/xml-drafts/:draftId', noStoreDynamicResponse, checkAuth, requireClinicModule('insurance_tiss'), requireClinicCapability('billing.xml.export'), createTissXmlDraftReadHandler(() => ({ currentClinicId, sanitizeString, isUuid, supabase, payerSafeError, hasMissingFinancialSchema, isMissingRelationError, sendNoStoreJson, TISS_XML_DRAFT_DETAIL_SELECT, serializeTissXmlDraft })));

  app.post('/api/tiss/xml-drafts/:draftId/validate', portalActionLimiter, noStoreDynamicResponse, checkAuth, requireClinicModule('insurance_tiss'), requireClinicCapability('billing.xml.validate'), async (req: any, res) => {
    try {
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      const draftId = sanitizeString(req.params.draftId, 120);
      if (!isUuid(organizationId) || !isUuid(draftId)) return res.status(400).json(payerSafeError(400));
      const { data, error } = await supabase
        .from('tiss_xml_drafts')
        .select(TISS_XML_DRAFT_DETAIL_SELECT)
        .eq('organization_id', organizationId)
        .eq('id', draftId)
        .maybeSingle();
      if (error) {
        if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) return res.status(404).json(payerSafeError(404));
        throw error;
      }
      if (!data) return res.status(404).json(payerSafeError(404));

      const xmlContent = String(data.xml_content || '');
      const validationSummary = data?.validation_summary && typeof data.validation_summary === 'object' ? data.validation_summary : {};
      const metadata = data?.metadata && typeof data.metadata === 'object' ? data.metadata : {};
      const draftFormat = sanitizeString(
        metadata.draft_format ||
        metadata.draftFormat ||
        validationSummary.draftFormat ||
        (xmlContent.includes('<tissSpSadtDraft') ? 'tiss_sp_sadt_draft' : 'verto_internal'),
        80
      ) || 'verto_internal';
      const technicalValidation = validateTissXmlDraft(xmlContent);
      const nextValidationSummary = {
        ...validationSummary,
        draftFormat,
        technicalValidation
      };
      const nextMetadata = {
        ...metadata,
        draft_format: draftFormat
      };
      const { data: updated, error: updateError } = await supabase
        .from('tiss_xml_drafts')
        .update({
          validation_summary: nextValidationSummary,
          metadata: nextMetadata,
          updated_at: new Date().toISOString()
        })
        .eq('organization_id', organizationId)
        .eq('id', draftId)
        .select(TISS_XML_DRAFT_SELECT)
        .maybeSingle();
      if (updateError) {
        if (hasMissingFinancialSchema(updateError) || isMissingRelationError(updateError)) return res.status(404).json(payerSafeError(404));
        throw updateError;
      }
      if (!updated) return res.status(404).json(payerSafeError(404));
      await recordTissRevenueCycleEvent({
        organizationId,
        clinicId: organizationId,
        xmlDraftId: draftId,
        payerId: sanitizeString(data?.payer_id, 120) || null,
        eventType: 'XML_DRAFT_VALIDATED',
        previousState: 'xml_draft_generated',
        newState: 'xml_draft_generated',
        reason: 'XML rascunho validado tecnicamente para conferência interna.',
        performedBy: isUuid(sanitizeString(req.session.user?.id, 120)) ? sanitizeString(req.session.user?.id, 120) : null,
        metadata: {
          technicalValidationStatus: technicalValidation.status,
          errorCount: Array.isArray(technicalValidation.errors) ? technicalValidation.errors.length : 0,
          warningCount: Array.isArray(technicalValidation.warnings) ? technicalValidation.warnings.length : 0,
          xsdValidationStatus: technicalValidation.xsdValidation?.status || 'not_configured',
          notSentToPayer: true
        }
      });
      return sendNoStoreJson(res, {
        success: true,
        data: serializeTissXmlDraft(updated),
        validation: technicalValidation,
        message: technicalValidation.status === 'invalid'
          ? 'O XML rascunho possui erros técnicos para revisão.'
          : technicalValidation.status === 'warning'
            ? 'O XML rascunho está bem formado, mas possui avisos para revisão.'
            : 'O XML rascunho passou na validação técnica interna.'
      });
    } catch (error: any) {
      console.warn('[TissXmlDraft] validate failed:', {
        code: sanitizeString(error?.code, 40) || null,
        message: sanitizeTextField(error?.message, 300) || String(error)
      });
      return res.status(500).json({ success: false, error: 'Não foi possível validar o XML TISS em rascunho agora.' });
    }
  });

