  app.post('/api/aba/program-templates', requireAbaV2Feature, checkAuth, requireClinicCapability('clinic.settings.edit'), async (req: any, res) => {
    try {
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const organizationId = sanitizeString(req.session.user?.organizationId || req.session.user?.organization_id || clinicId, 120);
      const actorId = sanitizeString(req.session.user?.id || req.session.user?.user_id, 120);
      const role = sanitizeString(req.effectiveClinicRole, 80).toLowerCase();
      const canShareWithClinic = ['director', 'coordinator'].includes(role);
      const requestedVisibility = sanitizeString(req.body?.visibility, 20) === 'private'
        ? 'private'
        : 'clinic';
      const visibility = canShareWithClinic ? requestedVisibility : 'private';
      const sourceScope = visibility === 'private' ? 'PERSONAL' : 'CLINIC';
      const templateOrganizationId = sourceScope === 'PERSONAL' ? actorId : organizationId;
      const templateClinicId = sourceScope === 'PERSONAL' ? null : clinicId;
      const programId = sanitizeString(req.body?.programId || req.body?.program_id, 180);
      const templateSpecialtyWasProvided = Object.prototype.hasOwnProperty.call(
        req.body || {},
        'specialty',
      );
      const requestedTemplateSpecialty = sanitizeString(req.body?.specialty, 120);
      const templateSpecialty = requestedTemplateSpecialty
        ? normalizeClinicalSpecialty(requestedTemplateSpecialty)
        : null;
      if (templateSpecialtyWasProvided && requestedTemplateSpecialty && !templateSpecialty) {
        return res.status(422).json({
          success: false,
          error: 'CLINICAL_SPECIALTY_INVALID',
          message: 'Selecione uma especialidade clínica disponível para salvar o modelo.',
        });
      }
      if (!programId) {
        const name = sanitizeTextField(req.body?.name, 240);
        const objective = sanitizeTextField(req.body?.objective, 1000);
        const targets = (Array.isArray(req.body?.suggestedTargets || req.body?.suggested_targets) ? req.body?.suggestedTargets || req.body?.suggested_targets : [])
          .slice(0, 50)
          .map((target: any) => sanitizeTextField(typeof target === 'string' ? target : target?.name, 240))
          .filter(Boolean);
        if (!name || !objective || targets.length === 0) {
          return res.status(400).json({ success: false, error: 'Informe nome, objetivo e ao menos um alvo sugerido.' });
        }
        const directPrivacy = sanitizeTherapeuticTemplateContent({
          name,
          description: sanitizeTextField(req.body?.description || objective, 1000),
          objective,
          targets,
          masteryCriteria: req.body?.masteryCriteria || req.body?.mastery_criteria || {},
          advancedSettings: req.body?.advancedSettings || req.body?.advanced_settings || {},
        });
        if (directPrivacy.redacted && req.body?.privacyAcknowledged !== true) {
          return res.status(422).json({
            success: false,
            error: 'TEMPLATE_PRIVACY_REVIEW_REQUIRED',
            message: `Revise conteúdo potencialmente identificável: ${directPrivacy.warnings.join(', ')}. Os dados serão removidos do modelo.`,
            privacyWarnings: directPrivacy.warnings,
          });
        }
        const idempotencyKey = sanitizeString(req.body?.idempotencyKey || req.body?.idempotency_key, 180) || `program-template-direct:${templateOrganizationId}:${crypto.randomUUID()}`;
        const status = ['DRAFT', 'PENDING_APPROVAL', 'PUBLISHED'].includes(String(req.body?.status || '').toUpperCase())
          ? String(req.body.status).toUpperCase()
          : 'PUBLISHED';
        const now = new Date().toISOString();
        const directPayload = {
          id: `template-${crypto.createHash('sha256').update(`${templateOrganizationId}:${idempotencyKey}`).digest('hex').slice(0, 32)}`,
          organization_id: templateOrganizationId,
          clinic_id: templateClinicId,
          source_scope: sourceScope,
          owner_user_id: sourceScope === 'PERSONAL' ? actorId : null,
          name: sanitizeTextField(directPrivacy.sanitized.name, 240),
          description: sanitizeTextField(directPrivacy.sanitized.description, 1000),
          category: sanitizeString(req.body?.category || 'OUTRO', 120),
          objective: sanitizeTextField(directPrivacy.sanitized.objective, 1000),
          suggested_targets: sanitizeClinicalPayload(directPrivacy.sanitized.targets),
          measurement_type: sanitizeString(req.body?.measurementType || req.body?.measurement_type || 'independent_prompted_no_response', 80),
          mastery_criteria: sanitizeClinicalPayload(req.body?.masteryCriteria || req.body?.mastery_criteria || {}),
          advanced_settings: sanitizeClinicalPayload(req.body?.advancedSettings || req.body?.advanced_settings || {}),
          specialty: templateSpecialty,
          tags: (Array.isArray(req.body?.tags) ? req.body.tags : []).slice(0, 30).map((tag: any) => sanitizeString(tag, 60)).filter(Boolean),
          structure_snapshot: sanitizeClinicalPayload(directPrivacy.sanitized),
          template_version: 1,
          visibility,
          contains_identifiable_content: false,
          privacy_warning_acknowledged_at: directPrivacy.redacted ? now : null,
          status: canShareWithClinic ? status : 'DRAFT',
          approved_by: canShareWithClinic && status === 'PUBLISHED' ? actorId : null,
          approved_at: canShareWithClinic && status === 'PUBLISHED' ? now : null,
          idempotency_key: idempotencyKey,
          created_by: actorId,
          created_at: now,
          updated_at: now
        };
        const { data, error } = await supabase.from('aba_program_templates').upsert(directPayload, { onConflict: 'id' }).select(THERAPEUTIC_TEMPLATE_SELECT).single();
        if (error) throw error;
        return res.status(201).json({ success: true, data, message: sourceScope === 'CLINIC' && status === 'PUBLISHED' ? 'Modelo publicado na biblioteca da clínica.' : 'Modelo privado salvo.' });
      }
      const programResult = await supabase
        .from('aba_programs')
        .select(THERAPEUTIC_PROGRAM_SELECT)
        .eq('id', programId)
        .eq('organization_id', organizationId)
        .eq('clinic_id', clinicId)
        .limit(1)
        .maybeSingle();
      if (programResult.error || !programResult.data) {
        return res.status(404).json({
          success: false,
          error: 'Programa não encontrado nesta clínica.'
        });
      }
      const program: any = programResult.data;
      const canReadProgram = await canActorReadTherapeuticProgram({
        actorId,
        actorRole: role,
        organizationId,
        clinicId,
        program
      });
      if (!canReadProgram) {
        return res.status(403).json({
          success: false,
          error: 'THERAPEUTIC_PROGRAM_READ_DENIED',
          message: 'Você não possui acesso a este programa terapêutico.'
        });
      }
      const [targetsResult, patientResult] = await Promise.all([
        supabase
          .from('aba_targets')
          .select('name,description,sort_order')
          .eq('program_id', programId)
          .eq('organization_id', organizationId)
          .eq('clinic_id', clinicId)
          .eq('patient_id', program.patient_id)
          .order('sort_order', { ascending: true })
          .limit(100),
        supabase
          .from('patients')
          .select('name')
          .eq('id', program.patient_id)
          .eq('clinic_id', clinicId)
          .limit(1)
          .maybeSingle()
      ]);
      if (targetsResult.error || patientResult.error) {
        throw targetsResult.error || patientResult.error;
      }
      const templatePatient = patientResult.data;
      const patientName = templatePatient?.name || null;
      const templatePrivacy = sanitizeTherapeuticTemplateContent({
        name: req.body?.name || program.name,
        description: program.description || program.objective,
        objective: program.objective || program.description,
        suggestedTargets: (targetsResult.data || []).map((target: any) => ({
          name: target.name,
          description: target.description,
        })),
        masteryCriteria: program.mastery_criteria || {},
        advancedSettings: program.advanced_settings || {},
      }, patientName);
      if (templatePrivacy.redacted && req.body?.privacyAcknowledged !== true) {
        return res.status(422).json({
          success: false,
          error: 'TEMPLATE_PRIVACY_REVIEW_REQUIRED',
          message: `Revise conteúdo potencialmente identificável: ${templatePrivacy.warnings.join(', ')}. Os dados serão removidos do modelo.`,
          privacyWarnings: templatePrivacy.warnings,
        });
      }
      const idempotencyKey = sanitizeString(req.body?.idempotencyKey || req.body?.idempotency_key, 180) || `program-template:${programId}:${sourceScope}:${actorId}`;
      const templatePayload = {
        id: `template-${crypto.createHash('sha256').update(`${templateOrganizationId}:${idempotencyKey}`).digest('hex').slice(0, 32)}`,
        organization_id: templateOrganizationId,
        clinic_id: templateClinicId,
        source_scope: sourceScope,
        owner_user_id: sourceScope === 'PERSONAL' ? actorId : null,
        name: sanitizeTextField(templatePrivacy.sanitized.name, 240),
        description: sanitizeTextField(templatePrivacy.sanitized.description, 1000),
        category: sanitizeString(program.category || 'OUTRO', 120),
        objective: sanitizeTextField(templatePrivacy.sanitized.objective, 1000),
        suggested_targets: sanitizeClinicalPayload(
          (templatePrivacy.sanitized.suggestedTargets as any[] || []).map((target: any) => target.name)
        ),
        measurement_type: sanitizeString(program.measurement_type || 'independent_prompted_no_response', 80),
        mastery_criteria: sanitizeClinicalPayload(program.mastery_criteria || {}),
        advanced_settings: sanitizeClinicalPayload(program.advanced_settings || {}),
        specialty: templateSpecialty,
        tags: (Array.isArray(req.body?.tags) ? req.body.tags : []).slice(0, 30).map((tag: any) => sanitizeString(tag, 60)).filter(Boolean),
        structure_snapshot: sanitizeClinicalPayload(templatePrivacy.sanitized),
        template_version: 1,
        visibility,
        contains_identifiable_content: false,
        privacy_warning_acknowledged_at: templatePrivacy.redacted ? new Date().toISOString() : null,
        status: sourceScope === 'CLINIC' ? 'PUBLISHED' : 'DRAFT',
        approved_by: sourceScope === 'CLINIC' ? actorId : null,
        approved_at: sourceScope === 'CLINIC' ? new Date().toISOString() : null,
        idempotency_key: idempotencyKey,
        created_by: actorId,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      };
      const { data, error } = await supabase.from('aba_program_templates').upsert(templatePayload, { onConflict: 'id' }).select(THERAPEUTIC_TEMPLATE_SELECT).single();
      if (error) throw error;
      return res.status(201).json({ success: true, data, message: sourceScope === 'CLINIC' ? 'Modelo publicado na biblioteca da clínica.' : 'Modelo pessoal salvo.' });
    } catch (error) {
      return sendRouteDbError(res, '/api/aba/program-templates [POST]', error, {
        fallbackMessage: 'Não foi possível salvar o modelo.'
      });
    }
  });

  app.patch('/api/aba/program-templates/:templateId', requireAbaV2Feature, checkAuth, requireClinicCapability('clinic.settings.edit'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 48 * 1024, 'Modelo de programa')) return;
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const organizationId = sanitizeString(req.session.user?.organizationId || req.session.user?.organization_id || clinicId, 120);
      const actorId = sanitizeString(req.session.user?.id || req.session.user?.user_id, 120);
      const actorRole = sanitizeString(req.effectiveClinicRole, 40).toLowerCase();
      const templateId = sanitizeString(req.params.templateId, 180);
      const existingResult = await supabase
        .from('aba_program_templates')
        .select(THERAPEUTIC_TEMPLATE_SELECT)
        .eq('id', templateId)
        .neq('source_scope', 'VERTO')
        .limit(1)
        .maybeSingle();
      if (existingResult.error || !existingResult.data) return res.status(404).json({ success: false, error: 'Modelo não encontrado.' });
      const existing: any = existingResult.data;
      const existingScope = sanitizeString(existing.source_scope, 40).toUpperCase();
      const canManageExisting = existingScope === 'PERSONAL'
        ? sanitizeString(existing.owner_user_id, 120) === actorId
        : sanitizeString(existing.organization_id, 120) === organizationId && ['director', 'coordinator'].includes(actorRole);
      if (!canManageExisting) {
        return res.status(403).json({ success: false, error: 'TEMPLATE_ACCESS_DENIED' });
      }
      const saveNewVersion = sanitizeString(req.body?.action, 40) === 'new_version';
      const expectedVersion = Number(req.body?.expectedVersion ?? existing.template_version ?? 1);
      if (
        saveNewVersion
        && (!Number.isInteger(expectedVersion) || expectedVersion !== Number(existing.template_version || 1))
      ) {
        return res.status(409).json({
          success: false,
          error: 'TEMPLATE_VERSION_CONFLICT',
          message: 'O modelo foi atualizado por outra pessoa. Recarregue antes de salvar uma nova versão.'
        });
      }
      const requestedStatus = String(req.body?.status || existing.status || 'DRAFT').toUpperCase();
      if (!['DRAFT', 'PENDING_APPROVAL', 'PUBLISHED', 'ARCHIVED'].includes(requestedStatus)) {
        return res.status(400).json({ success: false, error: 'Status de modelo inválido.' });
      }
      const targetsInput = req.body?.suggestedTargets ?? req.body?.suggested_targets;
      const targets = Array.isArray(targetsInput)
        ? targetsInput.slice(0, 50).map((target: any) => sanitizeTextField(typeof target === 'string' ? target : target?.name, 240)).filter(Boolean)
        : existing.suggested_targets;
      const privacyReview = sanitizeTherapeuticTemplateContent({
        name: req.body?.name ?? existing.name,
        description: req.body?.description ?? existing.description,
        objective: req.body?.objective ?? existing.objective,
        suggestedTargets: targets,
        masteryCriteria: req.body?.masteryCriteria ?? req.body?.mastery_criteria ?? existing.mastery_criteria ?? {},
        advancedSettings: req.body?.advancedSettings ?? req.body?.advanced_settings ?? existing.advanced_settings ?? {},
      });
      if (privacyReview.redacted && req.body?.privacyAcknowledged !== true) {
        return res.status(422).json({
          success: false,
          error: 'TEMPLATE_PRIVACY_REVIEW_REQUIRED',
          message: `Revise conteúdo potencialmente identificável: ${privacyReview.warnings.join(', ')}. Os dados serão removidos do modelo.`,
          privacyWarnings: privacyReview.warnings,
        });
      }
      const visibility = existingScope === 'PERSONAL' ? 'private' : 'clinic';
      const templateSpecialtyWasProvided = Object.prototype.hasOwnProperty.call(
        req.body || {},
        'specialty',
      );
      const requestedTemplateSpecialty = sanitizeString(req.body?.specialty, 120);
      const normalizedTemplateSpecialty = requestedTemplateSpecialty
        ? normalizeClinicalSpecialty(requestedTemplateSpecialty)
        : null;
      if (
        templateSpecialtyWasProvided &&
        requestedTemplateSpecialty &&
        !normalizedTemplateSpecialty
      ) {
        return res.status(422).json({
          success: false,
          error: 'CLINICAL_SPECIALTY_INVALID',
          message: 'Selecione uma especialidade clínica disponível para salvar o modelo.',
        });
      }
      const patch = {
        name: sanitizeTextField(privacyReview.sanitized.name, 240),
        description: sanitizeTextField(privacyReview.sanitized.description, 1000),
        category: sanitizeString(req.body?.category ?? existing.category, 120),
        objective: sanitizeTextField(privacyReview.sanitized.objective, 1000),
        suggested_targets: sanitizeClinicalPayload(privacyReview.sanitized.suggestedTargets),
        measurement_type: sanitizeString(req.body?.measurementType ?? req.body?.measurement_type ?? existing.measurement_type, 80),
        mastery_criteria: sanitizeClinicalPayload(privacyReview.sanitized.masteryCriteria),
        advanced_settings: sanitizeClinicalPayload(privacyReview.sanitized.advancedSettings),
        specialty: templateSpecialtyWasProvided
          ? normalizedTemplateSpecialty
          : sanitizeString(existing.specialty, 120) || null,
        tags: (Array.isArray(req.body?.tags) ? req.body.tags : existing.tags || []).slice(0, 30).map((tag: any) => sanitizeString(tag, 60)).filter(Boolean),
        organization_id: existingScope === 'PERSONAL' ? actorId : organizationId,
        clinic_id: existingScope === 'PERSONAL' ? null : clinicId,
        visibility,
        source_scope: existingScope,
        owner_user_id: existingScope === 'PERSONAL' ? actorId : null,
        contains_identifiable_content: false,
        privacy_warning_acknowledged_at: privacyReview.redacted ? new Date().toISOString() : existing.privacy_warning_acknowledged_at,
        status: requestedStatus,
        approved_by: requestedStatus === 'PUBLISHED' ? actorId : existing.approved_by,
        approved_at: requestedStatus === 'PUBLISHED' ? new Date().toISOString() : existing.approved_at,
        template_version: saveNewVersion
          ? Number(existing.template_version || 1) + 1
          : Number(existing.template_version || 1),
        archived_at: requestedStatus === 'ARCHIVED' ? new Date().toISOString() : null,
        updated_at: new Date().toISOString()
      };
      if (!patch.name || !patch.objective || !Array.isArray(targets) || targets.length === 0) {
        return res.status(400).json({ success: false, error: 'Informe nome, objetivo e ao menos um alvo sugerido.' });
      }
      if (saveNewVersion) {
        const { error: versionError } = await supabase
          .from('aba_program_template_versions')
          .upsert([{
            template_id: templateId,
            organization_id: existingScope === 'PERSONAL' ? actorId : (sanitizeString(existing.organization_id, 120) || organizationId),
            clinic_id: existingScope === 'PERSONAL' ? null : (sanitizeString(existing.clinic_id, 120) || clinicId),
            version: Number(existing.template_version || 1),
            snapshot: existing,
            change_reason: sanitizeTextField(req.body?.changeReason, 500) || 'Nova versão do modelo',
            created_by: actorId
          }], { onConflict: 'template_id,version', ignoreDuplicates: true });
        if (versionError) throw versionError;
      }
      let updateQuery = supabase
        .from('aba_program_templates')
        .update(patch)
        .eq('id', templateId);
      updateQuery = existingScope === 'PERSONAL'
        ? updateQuery.eq('owner_user_id', actorId)
        : updateQuery.eq('organization_id', organizationId);
      if (saveNewVersion) updateQuery = updateQuery.eq('template_version', expectedVersion);
      const { data, error } = await updateQuery
        .select(THERAPEUTIC_TEMPLATE_SELECT)
        .single();
      if (error) throw error;
      return res.json({ success: true, data, message: requestedStatus === 'ARCHIVED' ? 'Modelo arquivado.' : requestedStatus === 'PUBLISHED' ? 'Modelo publicado.' : 'Modelo atualizado.' });
    } catch (error) {
      return sendRouteDbError(res, '/api/aba/program-templates/:templateId [PATCH]', error, {
        fallbackMessage: 'Não foi possível atualizar o modelo.'
      });
    }
  });

  app.patch('/api/aba/patients/:patientId/targets/:targetId/mastery-criteria', checkAuth, checkPatientAccess, requireClinicCapability('aba.program.edit'), async (req: any, res) => {
    try {
      const patientId = sanitizeString(req.params.patientId || req.body?.patient_id || req.body?.patientId, 120);
      const targetId = sanitizeString(req.params.targetId || req.body?.target_id || req.body?.targetId, 180);
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const organizationId = sanitizeString(req.session.user?.organizationId || req.session.user?.organization_id || clinicId, 120);
      const actorId = sanitizeString(req.session.user?.id || req.session.user?.user_id, 120);
      if (!isUuid(patientId) || !isUuid(targetId) || !clinicId) {
        return res.status(400).json({ success: false, error: 'Dados invalidos para editar o criterio.' });
      }

      let targetQuery = supabase
        .from('aba_targets')
        .select(ABA_TARGET_RECOMMENDATION_SELECT)
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('id', targetId)
        .limit(1);
      targetQuery = applyAbaTenantScope(targetQuery, req.session.user, clinicId, organizationId);
      const targetResult = await targetQuery.maybeSingle();
      if (targetResult.error) {
        if (hasMissingFinancialSchema(targetResult.error) || isMissingRelationError(targetResult.error)) {
          return res.status(503).json({ success: false, error: 'Schema ABA ainda nao aplicado.' });
        }
        throw targetResult.error;
      }
      const target = targetResult.data;
      if (!target?.id) return res.status(404).json({ success: false, error: 'Habilidade nao encontrada para este paciente.' });

      const previousCriteria = target?.mastery_criteria && typeof target.mastery_criteria === 'object' ? target.mastery_criteria : null;
      const built = buildAbaMasteryCriteriaUpdatePayload(req.body, actorId);
      if (built.error || !built.criteria || !built.normalized) {
        return res.status(400).json({ success: false, error: built.error || 'Criterio invalido.' });
      }

      const update = await updateAbaTargetWithSchemaFallback(
        targetId,
        {
          mastery_criteria: built.criteria,
          updated_at: new Date().toISOString()
        },
        clinicId,
        organizationId,
        patientId
      );
      if (update.error) {
        if (hasMissingFinancialSchema(update.error) || isMissingRelationError(update.error)) {
          return res.status(503).json({ success: false, error: 'Schema ABA ainda nao aplicado.' });
        }
        throw update.error;
      }

      void persistActivityLog({
        userId: actorId || '',
        clinicId,
        actorName: sanitizeString(req.session.user?.name || req.session.user?.email, 180) || 'Equipe',
        title: 'Criterio de maestria atualizado',
        content: `Criterio da habilidade "${sanitizeString(target?.name, 180) || 'habilidade'}" atualizado.`,
        type: 'clinical',
        actionType: 'MASTERY_CRITERIA_UPDATED',
        payload: {
          targetName: sanitizeString(target?.name, 180) || null,
          previousCriterion: previousCriteria ? formatAbaMasteryCriterion(normalizeAbaMasteryCriterion(previousCriteria)) : 'Criterio nao configurado',
          newCriterion: formatAbaMasteryCriterion(built.normalized),
          source: 'skill'
        }
      });

      return res.json({
        success: true,
        message: 'Criterio de maestria atualizado.',
        data: {
          criteria: built.criteria,
          criterionLabel: formatAbaMasteryCriterion(built.normalized),
          criterionSourceLabel: abaMasteryCriterionSourceLabel(built.normalized)
        }
      });
    } catch (error) {
      return sendRouteDbError(res, '/api/aba/patients/:patientId/targets/:targetId/mastery-criteria [PATCH]', error, {
        fallbackMessage: 'Nao foi possivel editar o criterio agora.'
      });
    }
  });

  const fetchAbaMasteryCriterion = async (params: {
    organizationId: string;
    clinicId: string;
    patientId: string;
    targetId: string;
    programId?: string | null;
  }) => {
    const organizationId = sanitizeString(params.organizationId || params.clinicId, 120);
    const targetId = sanitizeString(params.targetId, 180);
    const programId = sanitizeString(params.programId, 180);
    let targetRow: any = null;

    if (targetId) {
      const targetRes = await supabase
        .from('aba_targets')
        .select('id,organization_id,clinic_id,patient_id,program_id,name,mastery_criteria,phase,clinical_status')
        .eq('patient_id', params.patientId)
        .eq('id', targetId)
        .limit(1)
        .maybeSingle();
      if (!targetRes.error) targetRow = targetRes.data || null;
    }

    const resolvedProgramId = sanitizeString(programId || targetRow?.program_id, 180);

    if (targetId) {
      let targetCriteriaQuery = supabase
        .from('aba_mastery_criteria')
        .select(ABA_MASTERY_CRITERIA_SELECT)
        .eq('organization_id', organizationId)
        .eq('target_id', targetId)
        .eq('is_active', true)
        .order('updated_at', { ascending: false })
        .limit(1);
      if (params.clinicId) targetCriteriaQuery = targetCriteriaQuery.eq('clinic_id', params.clinicId);
      const targetCriteria = await targetCriteriaQuery.maybeSingle();
      if (!targetCriteria.error && targetCriteria.data && normalizeAbaMasteryCriterion(targetCriteria.data)) {
        return {
          criterion: {
            ...targetCriteria.data,
            source: 'skill',
            sourceLabel: abaMasteryCriterionSourceLabel({ ...targetCriteria.data, source: 'skill' })
          },
          target: targetRow
        };
      }
      if (targetCriteria.error && !hasMissingFinancialSchema(targetCriteria.error)) throw targetCriteria.error;
    }

    const embeddedCriteria = targetRow?.mastery_criteria && typeof targetRow.mastery_criteria === 'object'
      ? targetRow.mastery_criteria
      : null;
    if (embeddedCriteria && Object.keys(embeddedCriteria).length > 0) {
      const embeddedRequiredIndependentCorrectTrials =
        embeddedCriteria.required_independent_correct_trials ??
        embeddedCriteria.requiredIndependentCorrectTrials ??
        embeddedCriteria.min_independent_correct_trials ??
        embeddedCriteria.minIndependentCorrectTrials ??
        null;
      const embeddedRequiredConsecutiveIndependentCorrectTrials =
        embeddedCriteria.required_consecutive_independent_correct_trials ??
        embeddedCriteria.requiredConsecutiveIndependentCorrectTrials ??
        embeddedCriteria.min_consecutive_independent_correct_trials ??
        embeddedCriteria.minConsecutiveIndependentCorrectTrials ??
        embeddedCriteria.consecutive_independent_correct_trials_required ??
        embeddedCriteria.consecutiveIndependentCorrectTrialsRequired ??
        embeddedCriteria.min_consecutive_successes ??
        embeddedCriteria.minConsecutiveSuccesses ??
        embeddedCriteria.meta_sucessos ??
        embeddedCriteria.metaSucessos ??
        embeddedCriteria.mastery_target ??
        embeddedCriteria.masteryTarget ??
        null;
      const embeddedRequiredCorrectTrials =
        embeddedCriteria.required_correct_trials ??
        embeddedCriteria.requiredCorrectTrials ??
        embeddedCriteria.required_successes ??
        embeddedCriteria.requiredSuccesses ??
        embeddedCriteria.success_threshold ??
        embeddedCriteria.successThreshold ??
        null;
      const embeddedSource = sanitizeString(embeddedCriteria.source || embeddedCriteria.criterionSource || embeddedCriteria.criterion_source, 80) || 'skill';
      const embeddedCriterion = {
        ...embeddedCriteria,
        id: null,
        organization_id: organizationId,
        clinic_id: params.clinicId,
        program_id: resolvedProgramId || null,
        target_id: targetId || null,
        name: sanitizeString(embeddedCriteria.name, 180) || 'Critério do target',
        required_independent_correct_trials: embeddedRequiredIndependentCorrectTrials,
        required_consecutive_independent_correct_trials: embeddedRequiredConsecutiveIndependentCorrectTrials,
        mastery_criterion_mode: embeddedRequiredConsecutiveIndependentCorrectTrials ? 'consecutive_independent' : (embeddedCriteria.mastery_criterion_mode ?? embeddedCriteria.masteryCriterionMode ?? embeddedCriteria.criterion_mode ?? embeddedCriteria.criterionMode ?? null),
        requires_consecutive_successes: Boolean(embeddedRequiredConsecutiveIndependentCorrectTrials || embeddedCriteria.requires_consecutive_successes || embeddedCriteria.requiresConsecutiveSuccesses || embeddedCriteria.consecutive_required || embeddedCriteria.consecutiveRequired),
        required_correct_trials: embeddedRequiredCorrectTrials,
        min_accuracy_percent: embeddedCriteria.min_accuracy_percent ?? embeddedCriteria.minAccuracyPercent ?? embeddedCriteria.required_accuracy ?? embeddedCriteria.requiredAccuracy ?? null,
        min_independence_percent: embeddedCriteria.min_independence_percent ?? embeddedCriteria.minIndependencePercent ?? embeddedCriteria.required_independence ?? embeddedCriteria.requiredIndependence ?? null,
        min_trials_per_session: embeddedCriteria.min_trials_per_session ?? embeddedCriteria.minTrialsPerSession ?? embeddedCriteria.minimum_trials ?? embeddedCriteria.minimumTrials ?? embeddedCriteria.required_trials ?? embeddedCriteria.requiredTrials ?? null,
        min_consecutive_days: embeddedCriteria.min_consecutive_days ?? embeddedCriteria.minConsecutiveDays ?? null,
        require_first_trial_independent: Boolean(embeddedCriteria.require_first_trial_independent ?? embeddedCriteria.requireFirstTrialIndependent),
        cold_probe_only: Boolean(embeddedCriteria.cold_probe_only ?? embeddedCriteria.coldProbeOnly),
        min_distinct_therapists: embeddedCriteria.min_distinct_therapists ?? embeddedCriteria.minDistinctTherapists ?? null,
        maintenance_required: Boolean(embeddedCriteria.maintenance_required ?? embeddedCriteria.maintenanceRequired),
        maintenance_days: embeddedCriteria.maintenance_days ?? embeddedCriteria.maintenanceDays ?? null,
        is_active: true,
        source: embeddedSource,
        sourceLabel: embeddedCriteria.sourceLabel || embeddedCriteria.source_label || abaMasteryCriterionSourceLabel({ ...embeddedCriteria, source: embeddedSource })
      };
      if (normalizeAbaMasteryCriterion(embeddedCriterion)) {
        return { criterion: embeddedCriterion, target: targetRow };
      }
    }

    if (resolvedProgramId) {
      let programCriteriaQuery = supabase
        .from('aba_mastery_criteria')
        .select(ABA_MASTERY_CRITERIA_SELECT)
        .eq('organization_id', organizationId)
        .eq('program_id', resolvedProgramId)
        .is('target_id', null)
        .eq('is_active', true)
        .order('updated_at', { ascending: false })
        .limit(1);
      if (params.clinicId) programCriteriaQuery = programCriteriaQuery.eq('clinic_id', params.clinicId);
      const programCriteria = await programCriteriaQuery.maybeSingle();
      if (!programCriteria.error && programCriteria.data && normalizeAbaMasteryCriterion(programCriteria.data)) {
        return {
          criterion: {
            ...programCriteria.data,
            source: 'protocol',
            sourceLabel: abaMasteryCriterionSourceLabel({ ...programCriteria.data, source: 'protocol' })
          },
          target: targetRow
        };
      }
      if (programCriteria.error && !hasMissingFinancialSchema(programCriteria.error)) throw programCriteria.error;
    }

    let clinicCriteriaQuery = supabase
      .from('aba_mastery_criteria')
      .select(ABA_MASTERY_CRITERIA_SELECT)
      .eq('organization_id', organizationId)
      .is('program_id', null)
      .is('target_id', null)
      .eq('is_active', true)
      .order('updated_at', { ascending: false })
      .limit(1);
    if (params.clinicId) clinicCriteriaQuery = clinicCriteriaQuery.eq('clinic_id', params.clinicId);
    const clinicCriteria = await clinicCriteriaQuery.maybeSingle();
    if (!clinicCriteria.error && clinicCriteria.data && normalizeAbaMasteryCriterion(clinicCriteria.data)) {
      return {
        criterion: {
          ...clinicCriteria.data,
          source: 'clinic_default',
          sourceLabel: abaMasteryCriterionSourceLabel({ ...clinicCriteria.data, source: 'clinic_default' })
        },
        target: targetRow
      };
    }
    if (clinicCriteria.error && !hasMissingFinancialSchema(clinicCriteria.error)) throw clinicCriteria.error;

    return { criterion: null, target: targetRow };
  };

  const evaluateAndPersistSessionMastery = async (params: {
    sessionId: string;
    patientId: string;
    clinicId: string;
    therapistId: string;
    evaluatedAt: string;
  }) => {
    const sessionId = sanitizeString(params.sessionId, 180);
    const patientId = sanitizeString(params.patientId, 120);
    const clinicId = sanitizeString(params.clinicId, 120);
    if (!sessionId || !isUuid(patientId) || !clinicId) return [];

    const trialSelect = [
      'id',
      'organization_id',
      'clinic_id',
      'patient_id',
      'session_id',
      'target_id',
      'target_name',
      'program_id',
      'collection_type',
      'maintenance_schedule_id',
      'response_score',
      'max_score',
      'correct',
      'independent',
      'prompt_level_key',
      'latency_ms',
      'raw_payload',
      'occurred_at',
      'therapist_id',
      'created_at'
    ].join(',');
    const { data: trials, error: trialsError } = await supabase
      .from('aba_trials')
      .select(trialSelect)
      .eq('session_id', sessionId)
      .eq('patient_id', patientId)
      .eq('clinic_id', clinicId)
      .order('occurred_at', { ascending: true })
      .limit(1000);
    if (trialsError) {
      if (hasMissingFinancialSchema(trialsError)) return [];
      throw trialsError;
    }

    const grouped = new Map<string, any[]>();
    for (const trial of Array.isArray(trials) ? trials : []) {
      if (sanitizeString(trial?.collection_type, 80).toLowerCase() === 'maintenance_probe') continue;
      const key = sanitizeString(trial?.target_id, 180) || sanitizeString(trial?.target_name, 240);
      if (!key) continue;
      grouped.set(key, [...(grouped.get(key) || []), trial]);
    }

    const masterySummary: any[] = [];
    for (const [targetKey, targetTrials] of grouped.entries()) {
      const firstTrial = targetTrials[0] || {};
      const organizationId = sanitizeString(firstTrial.organization_id || clinicId, 120);
      const targetId = sanitizeString(firstTrial.target_id || targetKey, 180);
      const targetName = sanitizeTextField(firstTrial.target_name || targetKey, 240);
      const programId = sanitizeString(firstTrial.program_id, 180);
      const { criterion, target } = await fetchAbaMasteryCriterion({
        organizationId,
        clinicId,
        patientId,
        targetId,
        programId
      });

      let previousQuery = supabase
        .from('aba_mastery_evaluations')
        .select('id,session_id,status,evaluation_status,evaluated_at,therapist_id,consecutive_successful_days')
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('target_id', targetId)
        .neq('session_id', sessionId)
        .order('evaluated_at', { ascending: false })
        .limit(30);
      if (clinicId) previousQuery = previousQuery.eq('clinic_id', clinicId);
      const previousRes = await previousQuery;
      if (previousRes.error && !hasMissingFinancialSchema(previousRes.error)) throw previousRes.error;

      const evaluation = evaluateTargetMastery({
        organizationId,
        patientId,
        targetId,
        targetName,
        sessionId,
        criteria: criterion,
        trials: targetTrials,
        previousEvaluations: previousRes.data || [],
        evaluatedAt: params.evaluatedAt
      });
      const evaluationId = `mastery-${sessionId}-${targetId}`;
      const lastTrial = targetTrials[targetTrials.length - 1] || {};
      const payload = cleanObject({
        id: evaluationId,
        organization_id: organizationId,
        clinic_id: clinicId,
        patient_id: patientId,
        session_id: sessionId,
        target_id: targetId,
        target_name: targetName,
        criteria_id: evaluation.criteriaId,
        status: evaluation.status,
        evaluation_status: normalizeAbaMasteryStatusForLegacy(evaluation.status),
        suggested_phase: evaluation.suggestedPhase,
        total_trials: evaluation.totalTrials,
        independent_trials: evaluation.independentTrials,
        prompted_trials: evaluation.promptedTrials,
        error_trials: evaluation.errorTrials,
        accuracy_percent: evaluation.accuracyPercent,
        independence_percent: evaluation.independencePercent,
        consecutive_successes: evaluation.criterionProgressCount,
        consecutive_successful_days: evaluation.consecutiveSuccessfulDays,
        min_consecutive_successes: evaluation.criterionRequiredCount || criterion?.min_consecutive_days || criterion?.minConsecutiveDays || 1,
        trials_considered: evaluation.totalTrials,
        cold_probe_trials_count: evaluation.coldProbeTrialsCount,
        distinct_therapists_count: evaluation.distinctTherapistsCount,
        first_trial_independent: evaluation.firstTrialIndependent,
        criteria: sanitizeClinicalPayload(criterion || {}),
        reasons: sanitizeClinicalPayload(evaluation.reasons),
        evaluated_at: evaluation.evaluatedAt,
        therapist_id: sanitizeString(lastTrial.therapist_id || params.therapistId, 120),
        source_trial_id: sanitizeString(lastTrial.id, 180) || null,
        raw_payload: sanitizeClinicalPayload({
          status: evaluation.status,
          criterionLabel: evaluation.criterionLabel,
          criterionProgressLabel: evaluation.criterionProgressLabel,
          successfulSessions: evaluation.successfulSessions,
          targetPhaseAtEvaluation: target?.phase || null,
          noAutomaticTargetMutation: true
        }),
        created_at: new Date().toISOString()
      });
      const writeResult = await writeAbaRowWithSchemaFallback('aba_mastery_evaluations', payload, 'upsert');
      if (writeResult.error && !hasMissingFinancialSchema(writeResult.error)) throw writeResult.error;
      masterySummary.push({
        id: evaluationId,
        targetId,
        name: targetName,
        criterion: evaluation.criterionLabel || formatAbaMasteryCriterion(criterion),
        performanceText: evaluation.performanceText,
        contributes: evaluation.status === 'MET_TODAY' || evaluation.status === 'READY_FOR_REVIEW',
        status: abaMasteryStatusLabel(evaluation.status),
        statusCode: evaluation.status,
        totalTrials: evaluation.totalTrials,
        independentTrials: evaluation.independentTrials,
        promptedTrials: evaluation.promptedTrials,
        errorTrials: evaluation.errorTrials,
        accuracyPercent: evaluation.accuracyPercent,
        independencePercent: evaluation.independencePercent,
        consecutiveSuccessfulDays: evaluation.consecutiveSuccessfulDays,
        successfulSessions: evaluation.successfulSessions,
        criterionProgressCount: evaluation.criterionProgressCount,
        criterionRequiredCount: evaluation.criterionRequiredCount,
        criterionProgressLabel: evaluation.criterionProgressLabel,
        reasons: evaluation.reasons
      });
    }
    return masterySummary;
  };

  const evaluateAndPersistSessionMaintenance = async (params: {
    sessionId: string;
    patientId: string;
    clinicId: string;
    therapistId: string;
    evaluatedAt: string;
    appointmentId?: string | null;
  }) => {
    const sessionId = sanitizeString(params.sessionId, 180);
    const patientId = sanitizeString(params.patientId, 120);
    const clinicId = sanitizeString(params.clinicId, 120);
    if (!sessionId || !isUuid(patientId) || !clinicId) return [];
    let appointmentId = isUuid(sanitizeString(params.appointmentId, 180)) ? sanitizeString(params.appointmentId, 180) : '';
    if (!appointmentId) {
      const sessionScope = await supabase
        .from('aba_sessions')
        .select('id,appointment_id')
        .eq('id', sessionId)
        .eq('patient_id', patientId)
        .eq('clinic_id', clinicId)
        .limit(1)
        .maybeSingle();
      if (!sessionScope.error && sessionScope.data?.appointment_id) {
        appointmentId = sanitizeString(sessionScope.data.appointment_id, 180);
      } else if (sessionScope.error && !hasMissingFinancialSchema(sessionScope.error)) {
        throw sessionScope.error;
      }
    }

    const trialSelect = [
      'id',
      'organization_id',
      'clinic_id',
      'patient_id',
      'session_id',
      'target_id',
      'target_name',
      'program_id',
      'collection_type',
      'maintenance_schedule_id',
      'response_score',
      'max_score',
      'correct',
      'independent',
      'prompt_level_key',
      'occurred_at',
      'therapist_id',
      'created_at'
    ].join(',');
    const { data: trials, error: trialsError } = await supabase
      .from('aba_trials')
      .select(trialSelect)
      .eq('session_id', sessionId)
      .eq('patient_id', patientId)
      .eq('clinic_id', clinicId)
      .eq('collection_type', 'maintenance_probe')
      .order('occurred_at', { ascending: true })
      .limit(1000);
    if (trialsError) {
      if (hasMissingFinancialSchema(trialsError)) return [];
      throw trialsError;
    }

    const grouped = new Map<string, any[]>();
    for (const trial of Array.isArray(trials) ? trials : []) {
      const key = sanitizeString(trial?.target_id, 180) || sanitizeString(trial?.target_name, 240);
      if (!key) continue;
      grouped.set(key, [...(grouped.get(key) || []), trial]);
    }

    const maintenanceSummary: any[] = [];
    for (const [targetKey, targetTrials] of grouped.entries()) {
      const firstTrial = targetTrials[0] || {};
      const organizationId = sanitizeString(firstTrial.organization_id || clinicId, 120);
      const targetId = sanitizeString(firstTrial.target_id || targetKey, 180);
      const targetName = sanitizeTextField(firstTrial.target_name || targetKey, 240);
      const programId = sanitizeString(firstTrial.program_id, 180);
      const trialScheduleId = sanitizeString(firstTrial.maintenance_schedule_id, 180);
      if (!hasPersistedMaintenanceScheduleId(trialScheduleId)) continue;
      const { criterion } = await fetchAbaMasteryCriterion({
        organizationId,
        clinicId,
        patientId,
        targetId,
        programId
      });

      let schedule: any = null;
      const scheduleRes = await supabase
        .from('aba_maintenance_schedules')
        .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
        .eq('id', trialScheduleId)
        .eq('organization_id', organizationId)
        .eq('clinic_id', clinicId)
        .eq('patient_id', patientId)
        .eq('target_id', targetId)
        .maybeSingle();
      if (!scheduleRes.error) schedule = scheduleRes.data || null;
      if (scheduleRes.error && !hasMissingFinancialSchema(scheduleRes.error)) throw scheduleRes.error;
      if (!schedule?.id) continue;

      let previousProbeResults: any[] = [];
      const previousRes = await supabase
        .from('aba_maintenance_probe_results')
        .select(ABA_MAINTENANCE_PROBE_RESULT_SELECT)
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('target_id', targetId)
        .order('occurred_at', { ascending: false })
        .limit(10);
      if (!previousRes.error) previousProbeResults = previousRes.data || [];
      if (previousRes.error && !hasMissingFinancialSchema(previousRes.error)) throw previousRes.error;

      const evaluation = evaluateMaintenanceStatus({
        organizationId,
        patientId,
        targetId,
        targetName,
        sessionId,
        maintenanceScheduleId: schedule?.id || null,
        criteria: criterion,
        trials: targetTrials,
        previousProbeResults,
        occurredAt: params.evaluatedAt
      });
      const lastMaintenanceTrial = targetTrials[targetTrials.length - 1] || firstTrial;
      const resultId = `maintenance-${trialScheduleId}-${sessionId}-${sanitizeString(lastMaintenanceTrial.id, 180) || targetId}`;
      const payload = cleanObject({
        id: resultId,
        organization_id: organizationId,
        clinic_id: clinicId,
        patient_id: patientId,
        target_id: targetId,
        maintenance_schedule_id: trialScheduleId,
        appointment_id: appointmentId || null,
        session_id: sessionId,
        trial_id: sanitizeString(lastMaintenanceTrial.id, 180) || null,
        probe_date: sanitizeDate(evaluation.occurredAt) || evaluation.occurredAt.slice(0, 10),
        clinical_date: sanitizeDate(evaluation.occurredAt) || evaluation.occurredAt.slice(0, 10),
        occurred_at: evaluation.occurredAt,
        result: evaluation.errorTrials > 0 ? 'error' : evaluation.independentTrials > 0 ? 'independent' : 'prompted',
        prompt_type: sanitizeString(lastMaintenanceTrial.prompt_level_key, 80) || null,
        passed: evaluation.status === 'MAINTAINED',
        total_trials: evaluation.totalTrials,
        independent_trials: evaluation.independentTrials,
        prompted_trials: evaluation.promptedTrials,
        error_trials: evaluation.errorTrials,
        accuracy_percent: evaluation.accuracyPercent,
        independence_percent: evaluation.independencePercent,
        status: evaluation.status,
        raw_payload: sanitizeClinicalPayload({
          targetName,
          criterion,
          minAccuracyPercent: evaluation.minAccuracyPercent,
          minIndependencePercent: evaluation.minIndependencePercent,
          reasons: evaluation.reasons,
          consecutiveFailureCount: evaluation.consecutiveFailureCount,
          shouldCreateRegressionAlert: evaluation.shouldCreateRegressionAlert,
          suggestedClinicalStatus: evaluation.suggestedClinicalStatus,
          noAutomaticTargetMutation: true,
          humanReviewRequiredForRegressionConfirmed: true
        }),
        created_by: sanitizeString(params.therapistId, 120) || null,
        updated_by: sanitizeString(params.therapistId, 120) || null,
        updated_at: new Date().toISOString(),
        created_at: new Date().toISOString()
      });
      const writeResult = await writeAbaRowWithSchemaFallback('aba_maintenance_probe_results', payload, 'upsert');
      if (writeResult.error && !hasMissingFinancialSchema(writeResult.error)) throw writeResult.error;
      if (evaluation.status === 'MAINTAINED') {
        await completeMaintenanceScheduleAfterProbe({
          scheduleId: trialScheduleId,
          clinicId,
          organizationId,
          patientId,
          completedAt: evaluation.occurredAt,
          completedBy: params.therapistId
        });
      } else {
        const update = await updateAbaScheduleWithSchemaFallback(trialScheduleId, cleanObject({
          status: evaluation.status,
          updated_at: new Date().toISOString(),
          raw_payload: sanitizeClinicalPayload({
            ...readMaintenanceStoredPayload(schedule?.raw_payload || schedule?.rawPayload),
            lastMaintenanceProbeResultId: resultId,
            lastMaintenanceProbeStatus: evaluation.status,
            humanReviewRequired: true,
            noAutomaticTargetMutation: true
          })
        }), clinicId, organizationId, patientId);
        if (update.error && !hasMissingFinancialSchema(update.error)) throw update.error;
      }

      maintenanceSummary.push({
        id: resultId,
        targetId,
        name: targetName,
        maintenanceScheduleId: trialScheduleId,
        scheduledFor: schedule?.scheduled_for || null,
        targetDueDate: schedule?.target_due_date || null,
        appointmentId: schedule?.appointment_id || null,
        status: evaluation.status,
        totalTrials: evaluation.totalTrials,
        independentTrials: evaluation.independentTrials,
        promptedTrials: evaluation.promptedTrials,
        errorTrials: evaluation.errorTrials,
        accuracyPercent: evaluation.accuracyPercent,
        independencePercent: evaluation.independencePercent,
        consecutiveFailureCount: evaluation.consecutiveFailureCount,
        shouldCreateRegressionAlert: evaluation.shouldCreateRegressionAlert,
        reasons: evaluation.reasons,
        performanceText: evaluation.performanceText
      });
    }
    return maintenanceSummary;
  };

  const resolveAbaSessionReadScope = async (sessionId: string, user: any) => {
    const safeSessionId = sanitizeString(sessionId, 180);
    if (!safeSessionId) return { ok: false, status: 400, error: 'Sessão inválida.' };
    const clinicId = sanitizeString(currentClinicId(user), 120);
    let query = supabase
      .from('aba_sessions')
      .select('id,clinic_id,patient_id,therapist_id,therapeutic_plan_id,appointment_id,status,reference_date,scheduled_start_at,actual_start_at,started_at,created_at')
      .eq('id', safeSessionId);
    if (!hasGlobalClinicAccess(user) && clinicId) query = query.eq('clinic_id', clinicId);
    if (sanitizeString(user?.role, 40).toLowerCase() === 'therapist') {
      query = query.eq('therapist_id', sanitizeString(user?.id, 120));
    }
    const { data, error } = await query.maybeSingle();
    if (error) {
      if (hasMissingFinancialSchema(error)) return { ok: false, status: 503, error: 'Schema ABA ainda não aplicado.' };
      throw error;
    }
    if (!data?.id) return { ok: false, status: 404, error: 'Sessão ABA não encontrada.' };
    const patientId = sanitizeString(data.patient_id, 120);
    if (!(await canAccessPatientInCurrentClinic(patientId, user))) {
      return { ok: false, status: 403, error: 'Paciente fora do escopo da clínica.' };
    }
    return { ok: true, session: data, patientId, clinicId: sanitizeString(data.clinic_id || clinicId, 120) };
  };


  const validateAbaSessionTargetPlanScope = async (params: {
    organizationId: string;
    patientId: string;
    therapeuticPlanId: string;
    targetIds: string[];
  }) => {
    const targetIds = Array.from(new Set((params.targetIds || []).map((value) => sanitizeString(value, 180)).filter(Boolean))).slice(0, 200);
    if (!params.therapeuticPlanId || targetIds.length === 0) return { ok: true };
    const { data: targetRows, error: targetError } = await supabase
      .from('aba_targets')
      .select('id,program_id')
      .eq('clinic_id', params.organizationId)
      .eq('patient_id', params.patientId)
      .in('id', targetIds)
      .limit(200);
    if (targetError) throw targetError;
    const programIds = Array.from(new Set((targetRows || []).map((row: any) => sanitizeString(row?.program_id, 180)).filter(Boolean)));
    if (programIds.length === 0) return { ok: true, conflictingTargetIds: [] as string[] };
    const { data: programRows, error: programError } = await supabase
      .from('aba_programs')
      .select('id,therapeutic_plan_id')
      .eq('clinic_id', params.organizationId)
      .eq('patient_id', params.patientId)
      .in('id', programIds)
      .limit(200);
    if (programError) throw programError;
    const planIdByProgramId = new Map(
      (programRows || []).map((program: any) => [
        sanitizeString(program?.id, 180),
        sanitizeString(program?.therapeutic_plan_id, 120),
      ]),
    );
    const conflictingTargetIds = (targetRows || []).flatMap((target: any) => {
      const targetId = sanitizeString(target?.id, 180);
      const programId = sanitizeString(target?.program_id, 180);
      const planId = planIdByProgramId.get(programId) || '';
      return targetId && planId && planId !== params.therapeuticPlanId ? [targetId] : [];
    });
    return conflictingTargetIds.length > 0
      ? { ok: false, code: 'ABA_SESSION_TARGET_PLAN_MISMATCH', conflictingTargetIds }
      : { ok: true, conflictingTargetIds: [] as string[] };
  };

  const serializeAbaV3BindingForClient = (binding: any) => ({
    bindingId: sanitizeString(binding?.id, 120),
    measurementModelVersion: sanitizeString(binding?.measurement_model_version, 60),
    collectionDefinitionVersionId: sanitizeString(binding?.collection_definition_version_id, 120) || null,
    targetPhaseAssignmentId: sanitizeString(binding?.target_phase_assignment_id, 120) || null,
    bindingReason: sanitizeString(binding?.binding_reason, 180) || null,
    boundAt: sanitizeString(binding?.bound_at, 80) || null
  });

  const ABA_V3_PR9A_TRIAL_TARGET_TYPES = new Set(['dtt', 'net', 'probe']);
  const ABA_V3_PR9B_BINDABLE_TARGET_TYPES = new Set([...ABA_V3_PR9A_TRIAL_TARGET_TYPES, 'task_analysis']);

  const assertAbaV3TargetReadyForTypes = async (organizationId: string, patientId: string, targetId: string, allowedTypes: Set<string>) => {
    const { data, error } = await supabase
      .from('aba_targets')
      .select('id,target_type')
      .eq('id', targetId)
      .eq('patient_id', patientId)
      .eq('clinic_id', organizationId)
      .maybeSingle();
    if (error) {
      if (hasMissingFinancialSchema(error)) return { ok: false, status: 503, code: 'ABA_V3_SCHEMA_NOT_READY', error: 'Schema ABA ainda não aplicado.' };
      throw error;
    }
    if (!data?.id) return { ok: false, status: 404, code: 'ABA_V3_TARGET_NOT_FOUND', error: 'Alvo ABA não encontrado.' };
    const targetType = sanitizeString(data.target_type, 40).toLowerCase();
    if (!allowedTypes.has(targetType)) {
      return {
        ok: false,
        status: 409,
        code: 'ABA_V3_UI_MEASUREMENT_NOT_READY',
        error: 'Esta família de medida V3 ainda não está liberada nesta etapa da interface.'
      };
    }
    return { ok: true, targetType };
  };

  const assertAbaV3Pr9aTrialTargetReady = async (organizationId: string, patientId: string, targetId: string) => (
    await assertAbaV3TargetReadyForTypes(organizationId, patientId, targetId, ABA_V3_PR9A_TRIAL_TARGET_TYPES)
  );

  const assertAbaV3Pr9bTargetReady = async (organizationId: string, patientId: string, targetId: string) => (
    await assertAbaV3TargetReadyForTypes(organizationId, patientId, targetId, ABA_V3_PR9B_BINDABLE_TARGET_TYPES)
  );

  const handleAbaV3CollectionRpcError = (res: any, error: any) => {
    const message = sanitizeString(error?.message || '', 700);
    if (hasMissingFinancialSchema(error) || /record_aba_trial_action_v3|record_aba_trial_revision_v3|record_aba_trial_correction_v3|resolve_aba_session_target_measurement_binding_v1|set_aba_session_target_exposure_v3|resolve_aba_behavior_collection_v3|record_aba_behavior_action_v3|start_aba_interval_run_action_v3|record_aba_interval_observation_action_v3|finalize_aba_interval_run_action_v3|get_aba_task_analysis_definition_for_session_v3|record_aba_task_analysis_action_v3|PGRST202|42883|42P01/i.test(message)) {
      return res.status(503).json({ success: false, code: 'ABA_V3_SCHEMA_NOT_READY', error: 'Schema de coleta ABA V3 ainda não aplicado.' });
    }
    if (/CROSS_TENANT|SCOPE_MISMATCH|_SCOPE_INVALID|ACCESS_DENIED/i.test(message)) {
      return res.status(403).json({ success: false, code: 'ABA_V3_COLLECTION_SCOPE_DENIED', error: 'Acesso negado ao escopo ABA V3.' });
    }
    if (/ABA_V3_UI_MEASUREMENT_NOT_READY/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_UI_MEASUREMENT_NOT_READY', error: 'Esta família de medida V3 ainda não está liberada nesta etapa da interface.' });
    }
    if (/ABA_V3_TARGET_NOT_V3/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_TARGET_NOT_V3', error: 'Este alvo está vinculado ao modelo Legacy V2 nesta sessão.' });
    }
    if (/ABA_V3_BEHAVIOR_NOT_V3/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_BEHAVIOR_NOT_V3', error: 'Este comportamento permanece no modelo Legacy V2 nesta sessão.' });
    }
    if (/BEHAVIOR_PRIMARY_COLLECTOR_ALREADY_ASSIGNED|INTERVAL_COLLECTOR_SCOPE_INVALID/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_COLLECTOR_CONFLICT', error: 'A coleta V3 deste item já possui outro coletor primário ativo.' });
    }
    if (/ABA_V3_ABC_LEGACY_ONLY/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_ABC_LEGACY_ONLY', error: 'ABC permanece no modelo Legacy V2 durante o primeiro piloto V3.' });
    }
    if (/BEHAVIOR_METHOD_MISMATCH|TASK_ANALYSIS_TARGET_INVALID|TASK_ANALYSIS_PROMPT_NOT_CONFIGURED/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_CONFIGURATION_INCOMPLETE', error: 'A configuração clínica V3 deste item não é compatível com a coleta solicitada.' });
    }
    if (/DURATION_ALREADY_CLOSED|OBSERVATION_ALREADY_CLOSED|INTERVAL_RUN_CLOSED/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_COLLECTION_ALREADY_CLOSED', error: 'Esta coleta V3 já foi encerrada.' });
    }
    if (/SYNC_NOT_READY|SYNC_CURRENTLY_DISABLED/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_SYNC_NOT_READY', error: 'A coleta V3 está temporariamente indisponível para este alvo.' });
    }
    if (/COLLECTION_DEFINITION_MISSING|COLLECTION_DEFINITION_MISSING_AT_SESSION_START|TARGET_PROGRAM_REQUIRED|TARGET_PHASE_MISSING|TARGET_PHASE_MISSING_AT_SESSION_START|TARGET_PHASE_WINDOW_MISMATCH|BINDING_COLLECTION_VERSION_NOT_VALID_AT_SESSION_START|BINDING_PHASE_NOT_VALID_AT_SESSION_START|PROBE_CLINICAL_STATE_INVALID|PROBE_MAINTENANCE_CRITERION_INCOMPLETE|PROBE_REQUIRES_MAINTENANCE_PHASE/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_CONFIGURATION_INCOMPLETE', error: 'A configuração clínica V3 deste alvo ainda está incompleta.' });
    }
    if (/ABA_V3_REVISION_(VOID_TRANSITION_INVALID|RESTORE_REQUIRES_VOID|SUPERSEDE_TRANSITION_INVALID|REPLACEMENT_SELF_REFERENCE|REPLACEMENT_SCOPE_INVALID|REPLACEMENT_NOT_ALLOWED)|ABA_V3_ATOMIC_CORRECTION_/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_REVISION_CONFLICT', error: 'Este registro clínico já possui uma revisão incompatível com a operação solicitada.' });
    }
    if (/ABA_V3_EXPOSURE_CONFLICTS_WITH_COLLECTED_TRIALS|ABA_V3_EXPOSURE_REQUIRES_V3_BINDING/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_EXPOSURE_CONFLICT', conflict: true, error: 'Já existem tentativas para este alvo ou a sessão não usa coleta V3.' });
    }
    if (/IDEMPOTENCY.*CONFLICT|ABA_V3_REVISION_IDEMPOTENCY_CONFLICT/i.test(message)) {
      return res.status(409).json({ success: false, code: 'ABA_V3_IDEMPOTENCY_CONFLICT', conflict: true, error: 'A mesma operação foi reenviada com conteúdo diferente.' });
    }
    throw error;
  };

  app.post(
    '/api/aba/v3/sessions/:sessionId/targets/:targetId/resolve-binding',
    requireAbaV3CollectionFeature,
    checkAuth,
    requireClinicCapability('aba.trial.record'),
    checkPatientAccess,
    async (req: any, res) => {
      try {
        if (!enforcePayloadLimit(req, res, 16 * 1024, 'Resolução de binding ABA V3')) return;
        const patientId = sanitizeString(req.resolvedPatientId || req.body?.patient_id || req.body?.patientId, 120);
        const organizationId = sanitizeString(req.resolvedPatientClinicId || currentClinicId(req.session.user), 120);
        const actorId = sanitizeString(req.session.user?.id, 120);
        const sessionId = sanitizeString(req.params.sessionId, 180);
        const targetId = sanitizeString(req.params.targetId, 180);
        if (!isUuid(patientId) || !isUuid(organizationId) || !isUuid(actorId) || !sessionId || !targetId) {
          return res.status(400).json({ success: false, code: 'ABA_V3_COLLECTION_SCOPE_INVALID', error: 'Escopo ABA V3 inválido.' });
        }
        const sessionScope = await resolveAbaSessionReadScope(sessionId, req.session.user);
        if (!sessionScope.ok) return res.status((sessionScope as any).status || 400).json({ success: false, error: (sessionScope as any).error });
        if (sanitizeString((sessionScope as any).patientId, 120) !== patientId || sanitizeString((sessionScope as any).clinicId, 120) !== organizationId) {
          return res.status(403).json({ success: false, code: 'ABA_V3_COLLECTION_SCOPE_DENIED', error: 'Sessão fora do escopo do paciente.' });
        }
        const writeScope = await assertAbaSessionCanAcceptClinicalWrite(sessionId, organizationId, req.session.user);
        if (!writeScope.ok) return res.status(writeScope.status || 409).json({ success: false, error: writeScope.error });
        const targetReadiness = await assertAbaV3Pr9bTargetReady(organizationId, patientId, targetId);
        if (!targetReadiness.ok) {
          return res.status(targetReadiness.status || 409).json({ success: false, code: targetReadiness.code, error: targetReadiness.error });
        }

        const { data, error } = await supabase.rpc('resolve_aba_session_target_measurement_binding_v1', {
          p_organization_id: organizationId,
          p_patient_id: patientId,
          p_session_id: sessionId,
          p_target_id: targetId,
          p_actor_id: actorId
        });
        if (error) return handleAbaV3CollectionRpcError(res, error);
        res.setHeader('Cache-Control', 'private, no-store');
        return res.json({ success: true, data: serializeAbaV3BindingForClient(data) });
      } catch (error: any) {
        return res.status(500).json({ success: false, error: 'Erro interno do servidor.' });
      }
    }
  );

  // Persist exposure state without fabricating an ABA V3 trial.
  app.post(
    '/api/aba/v3/target-exposures',
    requireAbaV3CollectionFeature,
    checkAuth,
    requireClinicCapability('aba.trial.record'),
    checkPatientAccess,
    async (req: any, res) => {
      try {
        if (!enforcePayloadLimit(req, res, 16 * 1024, 'Exposição de target ABA V3')) return;
        const patientId = sanitizeString(req.resolvedPatientId || req.body?.patient_id || req.body?.patientId, 120);
        const organizationId = sanitizeString(req.resolvedPatientClinicId || currentClinicId(req.session.user), 120);
        const actorId = sanitizeString(req.session.user?.id, 120);
        const sessionId = sanitizeString(req.body?.session_id || req.body?.sessionId, 180);
        const targetId = sanitizeString(req.body?.target_id || req.body?.targetId, 180);
        const clientEventId = sanitizeString(req.body?.client_event_id || req.body?.clientEventId, 240);
        const status = sanitizeString(req.body?.status, 40).toUpperCase();
        if (!isUuid(patientId) || !isUuid(organizationId) || !isUuid(actorId)
          || !sessionId || !targetId || !clientEventId || status !== 'NO_OPPORTUNITY') {
          return res.status(400).json({ success: false, code: 'ABA_V3_EXPOSURE_INVALID', error: 'Estado de exposição ABA V3 inválido.' });
        }
        const sessionScope = await resolveAbaSessionReadScope(sessionId, req.session.user);
        if (!sessionScope.ok) return res.status((sessionScope as any).status || 404).json({ success: false, error: (sessionScope as any).error });
        if (sanitizeString((sessionScope as any).patientId, 120) !== patientId
          || sanitizeString((sessionScope as any).clinicId, 120) !== organizationId) {
          return res.status(403).json({ success: false, code: 'ABA_V3_COLLECTION_SCOPE_DENIED', error: 'Sessão fora do escopo do paciente.' });
        }
        const writeScope = await assertAbaSessionCanAcceptClinicalWrite(sessionId, organizationId, req.session.user);
        if (!writeScope.ok) return res.status(writeScope.status || 409).json({ success: false, error: writeScope.error });
        const targetReadiness = await assertAbaV3Pr9bTargetReady(organizationId, patientId, targetId);
        if (!targetReadiness.ok) return res.status(targetReadiness.status || 409).json({ success: false, code: targetReadiness.code, error: targetReadiness.error });
        const { data, error } = await supabase.rpc('set_aba_session_target_exposure_v3', {
          p_organization_id: organizationId,
          p_patient_id: patientId,
          p_session_id: sessionId,
          p_target_id: targetId,
          p_status: 'NO_OPPORTUNITY',
          p_reason_code: 'NO_OPPORTUNITY_REPORTED',
          p_reason_text: null,
          p_actor_id: actorId
        });
        if (error) return handleAbaV3CollectionRpcError(res, error);
        if (!data?.id || data.exposure_status !== 'NO_OPPORTUNITY') {
          return res.status(503).json({ success: false, code: 'ABA_V3_EXPOSURE_UNCONFIRMED', error: 'Estado de exposição não confirmado no servidor.' });
        }
        res.setHeader('Cache-Control', 'private, no-store');
        return res.json({ success: true, data: { id: data.id, status: data.exposure_status, stateVersion: data.state_version } });
      } catch (_error: any) {
        return res.status(500).json({ success: false, error: 'Erro interno do servidor.' });
      }
    }
  );

  app.post(
    '/api/aba/v3/trials',
    requireAbaV3CollectionFeature,
    checkAuth,
    requireClinicCapability('aba.trial.record'),
    checkPatientAccess,
    async (req: any, res) => {
      try {
        if (!enforcePayloadLimit(req, res, 64 * 1024, 'Tentativa ABA V3')) return;
        const patientId = sanitizeString(req.resolvedPatientId || req.body?.patient_id || req.body?.patientId, 120);
        const organizationId = sanitizeString(req.resolvedPatientClinicId || currentClinicId(req.session.user), 120);
        const actorId = sanitizeString(req.session.user?.id, 120);
        const sessionId = sanitizeString(req.body?.session_id || req.body?.sessionId, 180);
        const targetId = sanitizeString(req.body?.target_id || req.body?.targetId, 180);
        const clientEventId = sanitizeString(req.body?.client_event_id || req.body?.clientEventId, 240);
        const actionKey = normalizeAbaV3TrialActionKey(req.body?.action_key || req.body?.actionKey);
        const trialType = mapAbaV3TrialType(req.body?.trial_type || req.body?.trialType || req.body?.collection_type || req.body?.collectionType);
        if (!isUuid(patientId) || !isUuid(organizationId) || !isUuid(actorId) || !sessionId || !targetId || !clientEventId || !actionKey || !trialType) {
          return res.status(400).json({ success: false, code: 'ABA_V3_TRIAL_INVALID', error: 'Tentativa ABA V3 inválida.' });
        }
        const rawOccurredAt = sanitizeString(req.body?.occurred_at || req.body?.occurredAt, 80);
        const occurredDate = new Date(rawOccurredAt);
        if (!rawOccurredAt || Number.isNaN(occurredDate.getTime())) {
          return res.status(400).json({ success: false, code: 'ABA_V3_OCCURRED_AT_INVALID', error: 'Horário da tentativa inválido.' });
        }
        const occurredAt = occurredDate.toISOString();
        const sessionScope = await resolveAbaSessionReadScope(sessionId, req.session.user);
        if (!sessionScope.ok) return res.status((sessionScope as any).status || 400).json({ success: false, error: (sessionScope as any).error });
        if (sanitizeString((sessionScope as any).patientId, 120) !== patientId || sanitizeString((sessionScope as any).clinicId, 120) !== organizationId) {
          return res.status(403).json({ success: false, code: 'ABA_V3_COLLECTION_SCOPE_DENIED', error: 'Sessão fora do escopo do paciente.' });
        }
        const writeScope = await assertAbaSessionCanAcceptClinicalWrite(sessionId, organizationId, req.session.user);
        if (!writeScope.ok) return res.status(writeScope.status || 409).json({ success: false, error: writeScope.error });

        let promptRow: any = null;
        let promptKey = '';
        if (actionKey === 'PROMPTED_CORRECT') {
          const promptTypeId = sanitizeString(req.body?.prompt_type_id || req.body?.promptTypeId, 120);
          const requestedPromptKey = normalizePromptTypeKey(req.body?.prompt_key || req.body?.promptKey);
          let promptQuery = supabase
            .from('aba_prompt_types')
            .select('id,key,name,category,intrusiveness_order,active,show_in_session')
            .eq('organization_id', organizationId)
            .eq('active', true)
            .eq('show_in_session', true)
            .limit(1);
          if (isUuid(promptTypeId)) promptQuery = promptQuery.eq('id', promptTypeId);
          else if (requestedPromptKey) promptQuery = promptQuery.eq('key', requestedPromptKey);
          else return res.status(400).json({ success: false, code: 'ABA_V3_PROMPT_REQUIRED', error: 'Tipo de ajuda é obrigatório.' });
          const promptResult = await promptQuery.maybeSingle();
          if (promptResult.error) {
            if (hasMissingFinancialSchema(promptResult.error)) return res.status(503).json({ success: false, code: 'ABA_V3_PROMPT_SCHEMA_NOT_READY', error: 'Tipos de ajuda ABA ainda não estão disponíveis.' });
            throw promptResult.error;
          }
          promptRow = promptResult.data;
          promptKey = sanitizeString(promptRow?.key, 160);
          if (!promptRow?.id || !promptKey || ['independent', 'error'].includes(promptKey)) {
            return res.status(409).json({ success: false, code: 'ABA_V3_PROMPT_NOT_CONFIGURED', error: 'Este tipo de ajuda não está configurado para coleta V3.' });
          }
        }

        let steps;
        try {
          steps = buildAbaV3TrialSteps(actionKey, promptKey || null);
        } catch {
          return res.status(400).json({ success: false, code: 'ABA_V3_PROMPT_REQUIRED', error: 'Tipo de ajuda é obrigatório.' });
        }

        const maintenanceScheduleId = sanitizeString(req.body?.maintenance_schedule_id || req.body?.maintenanceScheduleId, 120);
        if (trialType === 'MAINTENANCE_PROBE' && !maintenanceScheduleId) {
          return res.status(409).json({ success: false, code: 'ABA_V3_MAINTENANCE_SCHEDULE_REQUIRED', error: 'Sondagem de manutenção V3 exige uma agenda vinculada.' });
        }
        const probeKey = trialType === 'MAINTENANCE_PROBE'
          ? sanitizeString(`schedule:${maintenanceScheduleId}:session:${sessionId}:target:${targetId}`, 180)
          : null;
        const sourceDeviceId = sanitizeString(req.body?.source_device_id || req.body?.sourceDeviceId, 120) || null;
        const trialPayload = cleanObject({
          client_event_id: clientEventId,
          session_id: sessionId,
          target_id: targetId,
          trial_type: trialType,
          occurred_at: occurredAt,
          source_device_id: sourceDeviceId,
          client_metadata: {
            source: 'session_mode_v3',
            ui_action: actionKey,
            prompt_type_id: promptRow?.id || null,
            prompt_name: promptRow?.name || null,
            prompt_category: promptRow?.category || null,
            prompt_intrusiveness_order: promptRow?.intrusiveness_order ?? null,
            maintenance_schedule_id: maintenanceScheduleId || null
          },
          steps
        });

        const { data, error } = await supabase.rpc('record_aba_trial_action_v3', {
          p_organization_id: organizationId,
          p_patient_id: patientId,
          p_trial: trialPayload,
          p_probe_key: probeKey,
          p_actor_id: actorId
        });
        if (error) return handleAbaV3CollectionRpcError(res, error);
        const quarantine = Array.isArray((data as any)?.quarantine) ? (data as any).quarantine : [];
        if (Number((data as any)?.quarantined || 0) > 0 || quarantine.length > 0) {
          return res.status(422).json({
            success: false,
            code: 'ABA_V3_TRIAL_QUARANTINED',
            error: 'A tentativa foi preservada em quarentena e não entrou nos resultados clínicos.',
            details: { reasons: quarantine.map((item: any) => sanitizeString(item?.reason_code, 120)).filter(Boolean) }
          });
        }
        const accepted = Array.isArray((data as any)?.accepted) ? (data as any).accepted : [];
        const acceptedTrial = accepted[0] || null;
        if (!acceptedTrial?.trial_id) {
          return res.status(500).json({ success: false, code: 'ABA_V3_TRIAL_ACCEPTANCE_INVALID', error: 'Persistência V3 não confirmou a tentativa.' });
        }
        res.setHeader('Cache-Control', 'private, no-store');
        return res.json({
          success: true,
          data: {
            trialId: sanitizeString(acceptedTrial.trial_id, 120),
            clientEventId,
            inserted: Boolean(acceptedTrial.inserted),
            measurementModelVersion: 'V3',
            maintenanceProbeId: sanitizeString((data as any)?.maintenance_probe_id, 120) || null,
            maintenanceProbeLinked: Boolean((data as any)?.maintenance_probe_linked)
          }
        });
      } catch (error: any) {
        return res.status(500).json({ success: false, error: 'Erro interno do servidor.' });
      }
    }
  );


  app.post(
    '/api/aba/v3/trial-revisions',
    requireAbaV3CollectionFeature,
    checkAuth,
    requireClinicCapability('aba.trial.record'),
    checkPatientAccess,
    async (req: any, res) => {
      try {
        if (!enforcePayloadLimit(req, res, 48 * 1024, 'Revisão de tentativa ABA V3')) return;
        const patientId = sanitizeString(req.resolvedPatientId || req.body?.patient_id || req.body?.patientId, 120);
        const organizationId = sanitizeString(req.resolvedPatientClinicId || currentClinicId(req.session.user), 120);
        const actorId = sanitizeString(req.session.user?.id, 120);
        const requestedSessionId = sanitizeString(req.body?.session_id || req.body?.sessionId, 180);
        const originalTrialId = sanitizeString(req.body?.original_trial_id || req.body?.originalTrialId, 120);
        const originalClientEventId = sanitizeString(req.body?.original_client_event_id || req.body?.originalClientEventId, 240);
        const eventType = sanitizeString(req.body?.event_type || req.body?.eventType, 40).toUpperCase();
        const clientRevisionEventId = sanitizeString(req.body?.client_revision_event_id || req.body?.clientRevisionEventId, 240);
        const reason = sanitizeTextField(req.body?.reason, 1000);

        if (!isUuid(patientId) || !isUuid(organizationId) || !isUuid(actorId)) {
          return res.status(400).json({ success: false, code: 'ABA_V3_REVISION_SCOPE_INVALID', error: 'Escopo da revisão ABA V3 inválido.' });
        }
        if (!['VOID', 'CORRECT'].includes(eventType)) {
          return res.status(400).json({ success: false, code: 'ABA_V3_REVISION_EVENT_INVALID', error: 'Operação de revisão inválida.' });
        }
        if (!clientRevisionEventId || reason.trim().length < 3) {
          return res.status(400).json({ success: false, code: 'ABA_V3_REVISION_REASON_REQUIRED', error: 'Informe o motivo da alteração com pelo menos 3 caracteres.' });
        }
        if (!isUuid(originalTrialId) && !originalClientEventId) {
          return res.status(400).json({ success: false, code: 'ABA_V3_REVISION_TRIAL_REQUIRED', error: 'Tentativa V3 original não identificada.' });
        }

        let originalQuery = supabase
          .from('aba_trials_v3')
          .select('id,organization_id,patient_id,session_id,target_id,collection_definition_version_id,target_phase_assignment_id,trial_type,occurred_at,source_device_id,client_metadata')
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .limit(1);
        originalQuery = isUuid(originalTrialId)
          ? originalQuery.eq('id', originalTrialId)
          : originalQuery.eq('client_event_id', originalClientEventId);
        const originalResult = await originalQuery.maybeSingle();
        if (originalResult.error) {
          if (hasMissingFinancialSchema(originalResult.error)) return res.status(503).json({ success: false, code: 'ABA_V3_SCHEMA_NOT_READY', error: 'Schema ABA V3 ainda não aplicado.' });
          throw originalResult.error;
        }
        const original = originalResult.data as any;
        if (!original?.id) {
          return res.status(404).json({ success: false, code: 'ABA_V3_REVISION_TRIAL_NOT_FOUND', error: 'Tentativa V3 original não encontrada.' });
        }
        const sessionId = sanitizeString(original.session_id, 180);
        if (requestedSessionId && requestedSessionId !== sessionId) {
          return res.status(403).json({ success: false, code: 'ABA_V3_REVISION_SCOPE_DENIED', error: 'Tentativa fora da sessão informada.' });
        }
        const sessionScope = await resolveAbaSessionReadScope(sessionId, req.session.user);
        if (!sessionScope.ok) return res.status((sessionScope as any).status || 400).json({ success: false, error: (sessionScope as any).error });
        if (sanitizeString((sessionScope as any).patientId, 120) !== patientId || sanitizeString((sessionScope as any).clinicId, 120) !== organizationId) {
          return res.status(403).json({ success: false, code: 'ABA_V3_REVISION_SCOPE_DENIED', error: 'Tentativa fora do escopo autorizado.' });
        }
        const writeScope = await assertAbaSessionCanAcceptClinicalWrite(sessionId, organizationId, req.session.user, { allowCompletedComplement: true });
        if (!writeScope.ok) return res.status(writeScope.status || 409).json({ success: false, error: writeScope.error });

        if (eventType === 'VOID') {
          const { data, error } = await supabase.rpc('record_aba_trial_revision_v3', {
            p_organization_id: organizationId,
            p_trial_id: original.id,
            p_event_type: 'VOID',
            p_replacement_trial_id: null,
            p_reason: reason,
            p_client_revision_event_id: clientRevisionEventId,
            p_actor_id: actorId,
            p_metadata: { source: 'session_mode_v3_revision', requested_action: 'DELETE' }
          });
          if (error) return handleAbaV3CollectionRpcError(res, error);
          const revisionId = sanitizeString((data as any)?.id, 120);
          const auditPersisted = await persistActivityLog({
            userId: actorId,
            clinicId: organizationId,
            actorName: sanitizeString(req.session.user?.name || req.session.user?.email || 'Profissional', 180),
            title: 'Tentativa ABA V3 anulada',
            content: 'Uma tentativa da sessão foi anulada por revisão auditável; o evento clínico original foi preservado.',
            type: 'clinical',
            action: 'aba_trial_voided',
            actionType: 'aba_trial_voided',
            payloadDetails: JSON.stringify({ originalTrialId: original.id, revisionId, reason }),
            resourceType: 'aba_trial_v3',
            resourceId: sanitizeString(original.id, 120),
            patientId,
            sessionId,
            timezone: currentClinicTimeZone(req.session.user),
            immutableAudit: true,
            idempotencyKey: `aba-trial-void:${organizationId}:${clientRevisionEventId}`
          });
          res.setHeader('Cache-Control', 'private, no-store');
          return res.json({
            success: true,
            auditPersisted,
            ...(auditPersisted ? {} : { warning: 'Revisão salva; auditoria pendente de reconciliação.' }),
            data: { revisionId, originalTrialId: sanitizeString(original.id, 120), eventType: 'VOID', measurementModelVersion: 'V3' }
          });
        }

        const actionKey = normalizeAbaV3TrialActionKey(req.body?.action_key || req.body?.actionKey);
        const replacementClientEventId = sanitizeString(req.body?.replacement_client_event_id || req.body?.replacementClientEventId, 240);
        if (!actionKey || !replacementClientEventId) {
          return res.status(400).json({ success: false, code: 'ABA_V3_REVISION_REPLACEMENT_INVALID', error: 'Novo resultado da tentativa não foi informado corretamente.' });
        }

        let promptRow: any = null;
        let promptKey = '';
        if (actionKey === 'PROMPTED_CORRECT') {
          const promptTypeId = sanitizeString(req.body?.prompt_type_id || req.body?.promptTypeId, 120);
          const requestedPromptKey = normalizePromptTypeKey(req.body?.prompt_key || req.body?.promptKey);
          let promptQuery = supabase
            .from('aba_prompt_types')
            .select('id,key,name,category,intrusiveness_order,active,show_in_session')
            .eq('organization_id', organizationId)
            .eq('active', true)
            .eq('show_in_session', true)
            .limit(1);
          if (isUuid(promptTypeId)) promptQuery = promptQuery.eq('id', promptTypeId);
          else if (requestedPromptKey) promptQuery = promptQuery.eq('key', requestedPromptKey);
          else return res.status(400).json({ success: false, code: 'ABA_V3_PROMPT_REQUIRED', error: 'Tipo de ajuda é obrigatório.' });
          const promptResult = await promptQuery.maybeSingle();
          if (promptResult.error) {
            if (hasMissingFinancialSchema(promptResult.error)) return res.status(503).json({ success: false, code: 'ABA_V3_PROMPT_SCHEMA_NOT_READY', error: 'Tipos de ajuda ABA ainda não estão disponíveis.' });
            throw promptResult.error;
          }
          promptRow = promptResult.data;
          promptKey = sanitizeString(promptRow?.key, 160);
          if (!promptRow?.id || !promptKey || ['independent', 'error'].includes(promptKey)) {
            return res.status(409).json({ success: false, code: 'ABA_V3_PROMPT_NOT_CONFIGURED', error: 'Este tipo de ajuda não está configurado para coleta V3.' });
          }
        }

        let steps;
        try {
          steps = buildAbaV3TrialSteps(actionKey, promptKey || null);
        } catch {
          return res.status(400).json({ success: false, code: 'ABA_V3_PROMPT_REQUIRED', error: 'Tipo de ajuda é obrigatório.' });
        }

        const originalMetadata = original?.client_metadata && typeof original.client_metadata === 'object' && !Array.isArray(original.client_metadata)
          ? original.client_metadata
          : {};
        const replacementTrial = cleanObject({
          client_event_id: replacementClientEventId,
          session_id: sessionId,
          target_id: sanitizeString(original.target_id, 180),
          collection_definition_version_id: sanitizeString(original.collection_definition_version_id, 120),
          target_phase_assignment_id: sanitizeString(original.target_phase_assignment_id, 120),
          trial_type: sanitizeString(original.trial_type, 60).toUpperCase(),
          occurred_at: sanitizeIsoDateTime(original.occurred_at),
          source_device_id: sanitizeString(original.source_device_id, 120) || null,
          client_metadata: {
            ...originalMetadata,
            source: 'session_mode_v3_revision',
            corrected_from_trial_id: sanitizeString(original.id, 120),
            ui_action: actionKey,
            prompt_type_id: promptRow?.id || null,
            prompt_name: promptRow?.name || null,
            prompt_category: promptRow?.category || null,
            prompt_intrusiveness_order: promptRow?.intrusiveness_order ?? null
          },
          steps
        });

        const { data, error } = await supabase.rpc('record_aba_trial_correction_v3', {
          p_organization_id: organizationId,
          p_patient_id: patientId,
          p_original_trial_id: original.id,
          p_event_type: 'CORRECT',
          p_replacement_trial: replacementTrial,
          p_reason: reason,
          p_client_revision_event_id: clientRevisionEventId,
          p_actor_id: actorId,
          p_metadata: { source: 'session_mode_v3_revision', requested_action: 'EDIT' }
        });
        if (error) return handleAbaV3CollectionRpcError(res, error);
        const revisionId = sanitizeString((data as any)?.revision_id, 120);
        const replacementTrialId = sanitizeString((data as any)?.replacement_trial_id, 120);
        const auditPersisted = await persistActivityLog({
          userId: actorId,
          clinicId: organizationId,
          actorName: sanitizeString(req.session.user?.name || req.session.user?.email || 'Profissional', 180),
          title: 'Tentativa ABA V3 corrigida',
          content: 'Uma tentativa da sessão foi corrigida por revisão auditável; a tentativa original permanece preservada.',
          type: 'clinical',
          action: 'aba_trial_corrected',
          actionType: 'aba_trial_corrected',
          payloadDetails: JSON.stringify({
            originalTrialId: original.id,
            replacementTrialId,
            revisionId,
            actionKey,
            promptKey: promptKey || null,
            reason
          }),
          resourceType: 'aba_trial_v3',
          resourceId: sanitizeString(original.id, 120),
          patientId,
          sessionId,
          timezone: currentClinicTimeZone(req.session.user),
          immutableAudit: true,
          idempotencyKey: `aba-trial-correct:${organizationId}:${clientRevisionEventId}`
        });
        res.setHeader('Cache-Control', 'private, no-store');
        return res.json({
          success: true,
          auditPersisted,
          ...(auditPersisted ? {} : { warning: 'Correção salva; auditoria pendente de reconciliação.' }),
          data: {
            revisionId,
            replacementTrialId,
            originalTrialId: sanitizeString(original.id, 120),
            replacementClientEventId,
            eventType: 'CORRECT',
            measurementModelVersion: 'V3'
          }
        });
      } catch (error: any) {
        return res.status(500).json({ success: false, error: 'Erro interno do servidor.' });
      }
    }
  );


  app.get(
    '/api/aba/v3/patients/:patientId/behavior-catalog',
    requireAbaV3CollectionFeature,
    checkAuth,
    requireClinicCapability('aba.behavior.record'),
    checkPatientAccess,
    async (req: any, res) => {
      try {
        const patientId = sanitizeString(req.resolvedPatientId || req.params.patientId, 120);
        const organizationId = sanitizeString(req.resolvedPatientClinicId || currentClinicId(req.session.user), 120);
        if (!isUuid(patientId) || !isUuid(organizationId)) {
          return res.status(400).json({ success: false, code: 'ABA_V3_COLLECTION_SCOPE_INVALID', error: 'Escopo do catálogo comportamental inválido.' });
        }
        const { data, error } = await supabase
          .from('aba_behavior_definitions')
          .select('id,name,measurement_type,interval_seconds,status')
          .eq('patient_id', patientId)
          .eq('clinic_id', organizationId)
          .eq('status', 'active')
          .order('name', { ascending: true })
          .limit(200);
        if (error) {
          if (hasMissingFinancialSchema(error)) return res.status(503).json({ success: false, code: 'ABA_V3_SCHEMA_NOT_READY', error: 'Schema ABA ainda não aplicado.' });
          throw error;
        }
        res.setHeader('Cache-Control', 'private, max-age=60');
        return res.json({ success: true, data: (data || []).map((row: any) => ({
          id: sanitizeString(row?.id, 180),
          name: sanitizeString(row?.name, 240),
          measurementType: sanitizeString(row?.measurement_type, 60).toLowerCase(),
          intervalSeconds: Number(row?.interval_seconds || 0) || null,
          status: sanitizeString(row?.status, 40).toLowerCase()
        })).filter((row: any) => row.id && row.name && row.measurementType) });
      } catch (error: any) {
        return res.status(500).json({ success: false, error: 'Erro interno do servidor.' });
      }
    }
  );

