  app.get('/api/aba/patients/:patientId/next-session/plan-items', requireAbaV2Feature, checkAuth, requireClinicCapability('aba.next_session.view'), checkPatientAccess, createMaintenancePlanItemsHandler(() => ({ sanitizeString, currentClinicId, parseAbaRecordListLimit, supabase, ABA_NEXT_SESSION_PLAN_ITEM_SELECT, normalizeAbaPlanItemStatus, applyAbaTenantScope, hasMissingFinancialSchema })));

  app.patch('/api/aba/next-session-plan-items/:planItemId', requireAbaV2Feature, checkAuth, requireClinicCapability('aba.suggestions.apply'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 48 * 1024, 'Payload de item do plano ABA')) return;
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const planItemId = sanitizeString(req.params.planItemId, 180);
      if (!isUuid(planItemId)) {
        return res.status(400).json({ success: false, error: 'INVALID_PLAN_ITEM_ID' });
      }
      const { data: existingPlanItem, error: existingPlanItemError } = await supabase
        .from('aba_next_session_plan_items')
        .select('id,patient_id,clinic_id,organization_id')
        .eq('id', planItemId)
        .eq('clinic_id', clinicId)
        .limit(1)
        .maybeSingle();
      if (existingPlanItemError) {
        if (hasMissingFinancialSchema(existingPlanItemError)) {
          return res.status(503).json({ success: false, error: 'Schema de planejamento ABA ainda não aplicado.' });
        }
        throw existingPlanItemError;
      }
      const scopedPatientId = sanitizeString(existingPlanItem?.patient_id, 120);
      if (!existingPlanItem?.id || !isUuid(scopedPatientId)) {
        return res.status(404).json({ success: false, error: 'Item de plano não encontrado.' });
      }
      if (!(await canAccessPatientInCurrentClinic(scopedPatientId, req.session.user))) {
        return res.status(403).json({ success: false, error: 'Paciente fora do seu escopo clínico.' });
      }
      const patch = cleanObject({
        status: req.body?.status !== undefined ? normalizeAbaPlanItemStatus(req.body.status) : undefined,
        instructions: req.body?.instructions !== undefined ? sanitizeTextField(req.body.instructions, 1000) : undefined,
        planned_trial_type: req.body?.planned_trial_type !== undefined || req.body?.plannedTrialType !== undefined
          ? normalizeAbaPlanTrialType(req.body?.planned_trial_type || req.body?.plannedTrialType)
          : undefined,
        updated_at: new Date().toISOString()
      });
      let query = supabase
        .from('aba_next_session_plan_items')
        .update(patch)
        .eq('id', planItemId);
      if (!hasGlobalClinicAccess(req.session.user) && clinicId) query = query.eq('clinic_id', clinicId);
      const { data, error } = await query.select(ABA_NEXT_SESSION_PLAN_ITEM_SELECT).maybeSingle();
      if (error) {
        if (hasMissingFinancialSchema(error)) return res.status(503).json({ success: false, error: 'Schema de planejamento ABA ainda não aplicado.' });
        throw error;
      }
      return res.json({ success: true, data });
    } catch (error: any) {
      return res.status(500).json({ success: false, error: error?.message || 'Não foi possível atualizar o plano sugerido agora.' });
    }
  });

  app.get('/api/aba/patients/:patientId/clinical-line-chart', requireAbaV2Feature, checkAuth, requireClinicCapability('aba.analytics.view'), checkPatientAccess, async (req: any, res) => {
    try {
      const { patientId, clinicId, organizationId } = resolveAbaChartPatientScope(req);
      if (!isUuid(patientId)) {
        return res.json({
          success: true,
          data: { points: [], phases: [], annotations: [], summary: buildAbaClinicalLineSummary([]), availableMetrics: [], availableItems: [] }
        });
      }
      const params = parseAbaClinicalLineParams(req.query);
      const categoryChartType: Record<AbaClinicalLineCategory, string> = {
        target: 'targets',
        behavior: 'behaviors',
        mastery: 'mastery',
        maintenance: 'maintenance',
        general: 'overview'
      };
      const metricOptions = getAbaClinicalLineMetricOptions(params.category);
      const metricOptionIds = metricOptions.map((option) => option.id);
      const itemTargetId = params.category === 'target' || params.category === 'mastery' || params.category === 'maintenance' ? params.itemId : '';
      const itemBehaviorId = params.category === 'behavior' ? params.itemId : '';
      let points: AbaClinicalLinePoint[] = [];
      let availableItems: Array<{ id: string; label: string; category: AbaClinicalLineCategory }> = [];
      let source = 'aba_session_metric_snapshots';

      if (params.category === 'target') {
        const targetRows = await fetchAbaTargetSummaryRows({
          patientId,
          clinicId,
          organizationId,
          user: req.session.user,
          targetId: params.itemId || undefined,
          dateFromIso: params.dateFromIso,
          dateToIso: params.dateToIso,
          limit: params.limit
        });
        availableItems = uniqueLineItems(targetRows, 'target');
        if (params.itemId) {
          points = params.specialty || params.professionalId ? [] : buildAbaClinicalLinePointsFromTargetSummaries(targetRows, { metric: params.metric, groupBy: params.groupBy });
          source = 'aba_target_live_summaries';
          if (points.length === 0 || ['TARGET_ACCURACY', 'TARGET_INDEPENDENCE', 'TARGET_TRIAL_COUNT', 'TARGET_COMPARE_RESPONSES'].includes(params.metric)) {
            const snapshotRows = await fetchAbaSnapshotRows({
              patientId,
              clinicId,
              organizationId,
              user: req.session.user,
              metricTypes: ['TARGET_ACCURACY', 'TARGET_INDEPENDENCE', 'TARGET_TRIAL_COUNT'],
              targetId: params.itemId,
              metricType: ['TARGET_ACCURACY', 'TARGET_INDEPENDENCE', 'TARGET_TRIAL_COUNT'].includes(params.metric) ? params.metric : undefined,
              dateFromIso: params.dateFromIso,
              dateToIso: params.dateToIso,
              limit: params.limit,
              significantOnly: false,
              specialty: params.specialty,
              professionalId: params.professionalId
            });
            if (snapshotRows.length > 0 || params.specialty || params.professionalId) {
              points = buildAbaClinicalLinePointsFromSnapshots(snapshotRows, { category: 'target', metric: params.metric, groupBy: params.groupBy });
              source = 'aba_session_metric_snapshots';
            }
          }
        }
      } else if (params.category === 'behavior') {
        const behaviorMetrics = ['BEHAVIOR_FREQUENCY', 'BEHAVIOR_DURATION_EPISODES', 'BEHAVIOR_DURATION_TOTAL', 'BEHAVIOR_DURATION_AVG', 'BEHAVIOR_INTERVAL_OCCURRENCE'];
        let dailyQuery = supabase
          .from('aba_behavior_daily_summaries')
          .select(ABA_BEHAVIOR_DAILY_CHART_SELECT)
          .eq('patient_id', patientId)
          .gte('date', params.dateFrom)
          .lte('date', params.dateTo)
          .order('date', { ascending: true })
          .limit(params.limit);
        dailyQuery = applyAbaChartTenantScope(dailyQuery, req.session.user, clinicId, organizationId);
        if (params.itemId) dailyQuery = dailyQuery.eq('behavior_id', params.itemId);
        const dailyResult = await dailyQuery;
        if (dailyResult.error && !hasMissingFinancialSchema(dailyResult.error)) throw dailyResult.error;
        const dailyRows = dailyResult.error ? [] : dailyResult.data || [];
        availableItems = uniqueLineItems(dailyRows, 'behavior');
        if (params.itemId) {
          const snapshotRows = await fetchAbaSnapshotRows({
            patientId,
            clinicId,
            organizationId,
            user: req.session.user,
            metricTypes: behaviorMetrics,
            behaviorId: params.itemId,
            metricType: behaviorMetrics.includes(params.metric) ? params.metric : undefined,
            dateFromIso: params.dateFromIso,
            dateToIso: params.dateToIso,
            limit: params.limit,
            significantOnly: false,
            specialty: params.specialty,
            professionalId: params.professionalId
          });
          points = snapshotRows.length > 0
            ? buildAbaClinicalLinePointsFromSnapshots(snapshotRows, { category: 'behavior', metric: params.metric, groupBy: params.groupBy })
            : params.specialty || params.professionalId ? [] : buildBehaviorDailyLinePoints(dailyRows, params.metric, params.groupBy);
          source = snapshotRows.length > 0 ? 'aba_session_metric_snapshots' : 'aba_behavior_daily_summaries';
        }
      } else if (params.category === 'mastery') {
        let evaluationQuery = supabase
          .from('aba_mastery_evaluations')
          .select(ABA_MASTERY_LIST_SELECT)
          .eq('patient_id', patientId)
          .gte('evaluated_at', params.dateFromIso)
          .lte('evaluated_at', params.dateToIso)
          .order('evaluated_at', { ascending: true })
          .limit(params.limit);
        evaluationQuery = applyAbaChartTenantScope(evaluationQuery, req.session.user, clinicId, organizationId);
        if (params.itemId) evaluationQuery = evaluationQuery.eq('target_id', params.itemId);
        const evaluationResult = await evaluationQuery;
        if (evaluationResult.error && !hasMissingFinancialSchema(evaluationResult.error)) throw evaluationResult.error;
        const evaluationRows = evaluationResult.error ? [] : evaluationResult.data || [];
        availableItems = uniqueLineItems(evaluationRows, 'target');
        if (params.itemId && (params.specialty || params.professionalId)) {
          const scopedRows = await fetchAbaSnapshotRows({ patientId, clinicId, organizationId, user: req.session.user, metricTypes: ['MASTERY_STATUS'], targetId: params.itemId, dateFromIso: params.dateFromIso, dateToIso: params.dateToIso, limit: params.limit, specialty: params.specialty, professionalId: params.professionalId });
          points = buildAbaClinicalLinePointsFromSnapshots(scopedRows, { category: 'mastery', metric: params.metric, groupBy: params.groupBy });
          source = 'aba_session_metric_snapshots';
        } else if (params.itemId) points = buildMasteryLinePoints(evaluationRows, params.metric, params.groupBy);
        if (!(params.specialty || params.professionalId)) source = 'aba_mastery_evaluations';
      } else if (params.category === 'maintenance') {
        let probeQuery = supabase
          .from('aba_maintenance_probe_results')
          .select(ABA_MAINTENANCE_PROBE_RESULT_SELECT)
          .eq('patient_id', patientId)
          .gte('occurred_at', params.dateFromIso)
          .lte('occurred_at', params.dateToIso)
          .order('occurred_at', { ascending: true })
          .limit(params.limit);
        probeQuery = applyAbaChartTenantScope(probeQuery, req.session.user, clinicId, organizationId);
        if (params.itemId) probeQuery = probeQuery.eq('target_id', params.itemId);
        const probeResult = await probeQuery;
        if (probeResult.error && !hasMissingFinancialSchema(probeResult.error)) throw probeResult.error;
        const probeRows = await enrichMaintenanceRowsWithTargetDisplay(probeResult.error ? [] : probeResult.data || [], clinicId, organizationId, req.session.user);
        availableItems = uniqueLineItems(probeRows, 'target');
        if (params.itemId && (params.specialty || params.professionalId)) {
          const scopedRows = await fetchAbaSnapshotRows({ patientId, clinicId, organizationId, user: req.session.user, metricTypes: ['MAINTENANCE_STATUS', 'REGRESSION_RISK'], targetId: params.itemId, dateFromIso: params.dateFromIso, dateToIso: params.dateToIso, limit: params.limit, specialty: params.specialty, professionalId: params.professionalId });
          points = buildAbaClinicalLinePointsFromSnapshots(scopedRows, { category: 'maintenance', metric: params.metric, groupBy: params.groupBy });
          source = 'aba_session_metric_snapshots';
        } else if (params.itemId) points = buildMaintenanceLinePoints(probeRows, params.metric, params.groupBy);
        if (!(params.specialty || params.professionalId)) source = 'aba_maintenance_probe_results';
      } else {
        const rows = await fetchAbaSnapshotRows({
          patientId,
          clinicId,
          organizationId,
          user: req.session.user,
          metricType: metricOptionIds.includes(params.metric) ? params.metric : undefined,
          dateFromIso: params.dateFromIso,
          dateToIso: params.dateToIso,
          limit: params.limit,
          significantOnly: false,
          specialty: params.specialty,
          professionalId: params.professionalId
        });
        points = buildAbaClinicalLinePointsFromSnapshots(rows, { category: 'general', metric: params.metric, groupBy: params.groupBy });
        availableItems = uniqueLineItems(rows, 'target');
      }

      const [lineAnnotations, categoryAnnotations] = await Promise.all([
        fetchAbaGraphAnnotations({
          patientId,
          clinicId,
          organizationId,
          user: req.session.user,
          chartType: 'clinical-line-chart',
          dateFromIso: params.dateFromIso,
          dateToIso: params.dateToIso,
          targetId: itemTargetId,
          behaviorId: itemBehaviorId
        }),
        fetchAbaGraphAnnotations({
          patientId,
          clinicId,
          organizationId,
          user: req.session.user,
          chartType: categoryChartType[params.category],
          dateFromIso: params.dateFromIso,
          dateToIso: params.dateToIso,
          targetId: itemTargetId,
          behaviorId: itemBehaviorId
        })
      ]);
      const annotations = dedupeAnnotations([...lineAnnotations, ...categoryAnnotations]);
      return res.json({
        success: true,
        data: {
          points,
          phases: buildClinicalLinePhases(annotations),
          annotations,
          summary: buildAbaClinicalLineSummary(points),
          availableMetrics: metricOptions,
          availableItems,
          category: params.category,
          metric: params.metric,
          groupBy: params.groupBy
        },
        source
      });
    } catch (error: any) {
      return res.status(500).json({ success: false, error: error?.message || 'Erro interno do servidor.' });
    }
  });



  app.post('/api/patients/:patientId/clinical-observations', checkAuth, requireClinicCapability('clinical.notes.create'), checkPatientAccess, async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Observação clínica')) return;
      const patientId = sanitizeString(req.resolvedPatientId || req.params.patientId, 120);
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const organizationId = sanitizeString(req.session.user?.organizationId || req.session.user?.organization_id || clinicId, 120);
      const actorId = sanitizeString(req.session.user?.id || req.session.user?.user_id, 120);
      const actorRole = sanitizeString(req.effectiveClinicRole, 40).toLowerCase();
      const planId = sanitizeString(req.body?.planId || req.body?.plan_id, 120);
      const idempotencyKey = sanitizeString(req.body?.idempotencyKey || req.body?.idempotency_key, 180);
      const metricKey = sanitizeString(req.body?.metricKey || req.body?.metric_key, 120);
      const metricLabel = sanitizeTextField(req.body?.metricLabel || req.body?.metric_label, 180);
      const direction = sanitizeString(req.body?.direction, 40).toLowerCase() || 'higher_is_better';
      const missingReason = sanitizeString(req.body?.missingReason || req.body?.missing_reason, 60).toLowerCase() || null;
      const allowedDirections = new Set(['higher_is_better', 'lower_is_better', 'target_value', 'target_range', 'event']);
      const allowedMissingReasons = new Set(['not_collected', 'session_cancelled', 'not_applicable', 'incomplete', 'patient_absent', 'instrument_unavailable', 'invalid']);
      if (!isUuid(patientId) || !isUuid(planId) || idempotencyKey.length < 16 || !metricKey || !metricLabel || !allowedDirections.has(direction)) {
        return res.status(422).json({ success: false, error: 'CLINICAL_OBSERVATION_PAYLOAD_INVALID', message: 'Revise os dados da observação clínica.' });
      }
      if (missingReason && !allowedMissingReasons.has(missingReason)) {
        return res.status(422).json({ success: false, error: 'CLINICAL_OBSERVATION_MISSING_REASON_INVALID', message: 'Motivo de ausência de dado inválido.' });
      }
      const value = req.body?.value === null || req.body?.value === undefined || req.body?.value === '' ? null : Number(req.body.value);
      const numerator = req.body?.numerator === null || req.body?.numerator === undefined || req.body?.numerator === '' ? null : Number(req.body.numerator);
      const denominator = req.body?.denominator === null || req.body?.denominator === undefined || req.body?.denominator === '' ? null : Number(req.body.denominator);
      if ((!missingReason && !Number.isFinite(value)) || (numerator !== null && !Number.isFinite(numerator)) || (denominator !== null && (!Number.isFinite(denominator) || denominator <= 0))) {
        return res.status(422).json({ success: false, error: 'CLINICAL_OBSERVATION_VALUE_INVALID', message: 'Informe um valor válido ou registre o motivo da ausência de dado.' });
      }

      const [planResult, linkResult] = await Promise.all([
        supabase
          .from('patient_therapeutic_plans')
          .select('id,patient_id,organization_id,clinic_id,mode,specialty,participant_specialties,responsible_professional_id,participant_professional_ids,edit_version')
          .eq('id', planId)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .limit(1)
          .maybeSingle(),
        supabase
          .from('patient_professional_links')
          .select('patient_id,professional_id,status,permissions')
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .eq('professional_id', actorId)
          .eq('status', 'active')
          .limit(1)
          .maybeSingle()
      ]);
      if (planResult.error) throw planResult.error;
      if (linkResult.error) throw linkResult.error;
      if (!planResult.data || !canEditTherapeuticPlanScope(planResult.data, { actorId, actorRole, professionalLinks: linkResult.data ? [linkResult.data] : [] })) {
        return res.status(403).json({ success: false, error: 'CLINICAL_OBSERVATION_ACCESS_DENIED', message: 'Você não possui permissão para registrar evidências neste plano.' });
      }

      const observedAtRaw = sanitizeString(req.body?.observedAt || req.body?.observed_at, 50);
      const observedAtDate = observedAtRaw && !Number.isNaN(new Date(observedAtRaw).getTime()) ? new Date(observedAtRaw) : new Date();
      if (observedAtDate.getTime() > Date.now() + 5 * 60_000 || observedAtDate.getTime() < Date.now() - 20 * 365 * 86_400_000) {
        return res.status(422).json({ success: false, error: 'CLINICAL_OBSERVATION_DATE_INVALID', message: 'A data da observação clínica está fora do intervalo permitido.' });
      }
      const observedAt = observedAtDate.toISOString();
      const requestedSpecialty = normalizeClinicalSpecialty(req.body?.specialty);
      const planSpecialty = normalizeClinicalSpecialty(planResult.data.specialty);
      const allowedPlanSpecialties = new Set((Array.isArray(planResult.data.participant_specialties) ? planResult.data.participant_specialties : []).map((item: unknown) => normalizeClinicalSpecialty(item)).filter(Boolean));
      const authoritativeSpecialty = planResult.data.mode === 'specialty'
        ? planSpecialty
        : requestedSpecialty && allowedPlanSpecialties.has(requestedSpecialty)
          ? requestedSpecialty
          : null;
      const context = sanitizeString(req.body?.context, 80).toLowerCase() || 'clinic';
      const source = sanitizeString(req.body?.source, 80).toLowerCase() || 'professional_observation';
      const metricType = sanitizeString(req.body?.metricType || req.body?.metric_type, 60).toLowerCase() || 'numeric';
      const allowedContexts = new Set(['clinic', 'home', 'school', 'community', 'telehealth', 'other']);
      const allowedSources = new Set(['professional_observation', 'patient_report', 'family_report', 'school_report', 'standardized_instrument', 'imported']);
      const allowedMetricTypes = new Set(['numeric', 'percentage', 'frequency', 'rate', 'duration', 'latency', 'ordinal', 'scale', 'binary']);
      if (!allowedContexts.has(context) || !allowedSources.has(source) || !allowedMetricTypes.has(metricType)) {
        return res.status(422).json({ success: false, error: 'CLINICAL_OBSERVATION_CLASSIFICATION_INVALID', message: 'Contexto, fonte ou tipo de métrica inválido.' });
      }
      const sourceSessionId = sanitizeString(req.body?.sessionId || req.body?.session_id, 120) || null;
      let authoritativePlanVersion = Math.max(1, Number(planResult.data.edit_version || 1));
      if (String(planResult.data.mode || '').toLowerCase() === 'interdisciplinary') {
        if (!isUuid(organizationId)) {
          return res.status(422).json({ success: false, error: 'PTS_COLLECTION_ORGANIZATION_INVALID' });
        }
        const versionResult = await supabase.rpc('resolve_patient_pts_plan_version_v1', {
          p_organization_id: organizationId,
          p_patient_id: patientId,
          p_plan_id: planId,
          p_source_session_id: sourceSessionId,
          p_actor_id: actorId,
          p_now: new Date().toISOString(),
        });
        if (versionResult.error) {
          const code = sanitizeString(versionResult.error?.message || versionResult.error?.code, 500);
          if (code.includes('PGRST202') || code.includes('resolve_patient_pts_plan_version_v1')) {
            return res.status(503).json({ success: false, error: 'PTS_CONTEXT_SCHEMA_REQUIRED', message: 'O vínculo entre evidência e versão do PTS ainda não está disponível.' });
          }
          if (code.includes('PTS_COLLECTION_SESSION_SCOPE_INVALID') || code.includes('PTS_COLLECTION_VERSION_NOT_FOUND')) {
            return res.status(409).json({ success: false, error: 'PTS_COLLECTION_CONTEXT_INVALID', message: 'A sessão não possui uma versão válida do PTS para esta coleta.' });
          }
          throw versionResult.error;
        }
        authoritativePlanVersion = Math.max(1, Number(versionResult.data || 1));
      }
      const payload = {
        organization_id: organizationId,
        clinic_id: clinicId,
        patient_id: patientId,
        plan_id: planId,
        plan_version: authoritativePlanVersion,
        goal_id: sanitizeString(req.body?.goalId || req.body?.goal_id, 100) || null,
        program_id: sanitizeString(req.body?.programId || req.body?.program_id, 120) || null,
        session_id: sourceSessionId,
        professional_id: actorId,
        specialty: authoritativeSpecialty || null,
        measure_definition_id: isUuid(req.body?.measureDefinitionId || req.body?.measure_definition_id) ? sanitizeString(req.body?.measureDefinitionId || req.body?.measure_definition_id, 120) : null,
        metric_key: metricKey,
        metric_label: metricLabel,
        metric_type: metricType,
        unit: sanitizeTextField(req.body?.unit, 40) || null,
        direction,
        value: Number.isFinite(value) ? value : null,
        numerator: Number.isFinite(numerator) ? numerator : null,
        denominator: Number.isFinite(denominator) ? denominator : null,
        observed_at: observedAt,
        context,
        source,
        instrument_id: sanitizeString(req.body?.instrumentId || req.body?.instrument_id, 120) || null,
        instrument_version: sanitizeString(req.body?.instrumentVersion || req.body?.instrument_version, 80) || null,
        definition_version: Math.max(1, Math.min(1000, Number(req.body?.definitionVersion || req.body?.definition_version || 1))),
        missing_reason: missingReason,
        metadata: sanitizeClinicalPayload(req.body?.metadata && typeof req.body.metadata === 'object' && !Array.isArray(req.body.metadata) ? req.body.metadata : {}),
        idempotency_key: idempotencyKey,
        created_by: actorId
      };
      const { data, error } = await supabase
        .from('clinical_observations')
        .upsert(payload, { onConflict: 'organization_id,idempotency_key', ignoreDuplicates: true })
        .select('id,plan_id,plan_version,goal_id,program_id,session_id,professional_id,specialty,metric_key,metric_label,metric_type,unit,direction,value,numerator,denominator,observed_at,context,source,instrument_id,instrument_version,definition_version,missing_reason,metadata,created_at')
        .maybeSingle();
      if (error) {
        if (isMissingRelationError(error) || hasMissingFinancialSchema(error)) {
          return res.status(503).json({ success: false, error: 'CLINICAL_OUTCOMES_SCHEMA_REQUIRED', message: 'A estrutura de resultados clínicos ainda não foi aplicada no banco.' });
        }
        throw error;
      }
      return res.status(201).json({ success: true, data, idempotent: !data });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/patients/:patientId/clinical-observations [POST]', error, {
        fallbackMessage: 'Não foi possível registrar a evidência clínica agora.'
      });
    }
  });

  const finiteClinicalOutcomeNumber = (value: any) => {
    if (value === null || value === undefined || value === '') return null;
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : null;
  };

  const normalizeClinicalOutcomeDirectionFromV3 = (value: any) => {
    const normalized = sanitizeString(value, 80).toUpperCase();
    if (normalized === 'DECREASE_IS_BETTER') return 'lower_is_better';
    if (normalized === 'TARGET_RANGE_IS_BETTER') return 'target_range';
    if (normalized === 'NO_DIRECTIONAL_JUDGMENT') return 'no_directional_judgment';
    return 'higher_is_better';
  };

  const normalizeClinicalOutcomeValueFromV3 = (row: any) => {
    const canonicalUnit = sanitizeString(row?.canonical_value_unit, 80).toUpperCase();
    const preferredUnitCode = sanitizeString(row?.unit_code, 80);
    const preferredUnitLabel = sanitizeString(row?.unit_label, 120);
    const finiteValue = finiteClinicalOutcomeNumber(row?.value_number);

    if (canonicalUnit === 'CATEGORY') {
      return { value: null, valueText: sanitizeString(row?.value_text, 180) || null, unit: '' };
    }
    if (canonicalUnit === 'EVENTS_PER_HOUR') {
      return { value: finiteValue, valueText: null, unit: 'eventos/h' };
    }
    if (canonicalUnit === 'MILLISECOND') {
      if (finiteValue === null) return { value: null, valueText: null, unit: 'ms' };
      const requested = `${preferredUnitCode} ${preferredUnitLabel}`.trim().toLowerCase();
      if (/\b(hour|hours|hora|horas|h)\b/.test(requested)) return { value: finiteValue / 3_600_000, valueText: null, unit: preferredUnitLabel || 'h' };
      if (/\b(minute|minutes|minuto|minutos|min)\b/.test(requested)) return { value: finiteValue / 60_000, valueText: null, unit: preferredUnitLabel || 'min' };
      if (/\b(second|seconds|segundo|segundos|sec|s)\b/.test(requested) && !/milli|mili/.test(requested)) return { value: finiteValue / 1_000, valueText: null, unit: preferredUnitLabel || 's' };
      return { value: finiteValue, valueText: null, unit: preferredUnitLabel || preferredUnitCode || 'ms' };
    }
    if (canonicalUnit === 'COUNT') {
      return { value: finiteValue, valueText: null, unit: preferredUnitLabel || preferredUnitCode || 'contagem' };
    }
    return {
      value: finiteValue,
      valueText: sanitizeString(row?.value_text, 180) || null,
      unit: preferredUnitLabel || preferredUnitCode || sanitizeString(row?.canonical_value_unit, 80),
    };
  };

  const normalizeClinicalPlanOutcomesV3ForDashboard = (
    rows: any[],
    visiblePlanMap: Map<string, any>,
    objectivePlanMap: Map<string, Set<string>>,
    targetById: Map<string, any>,
    programById: Map<string, any>,
    ptsVersionBySessionPlan: Map<string, number>,
    historyBindingBySessionTarget: Map<string, any>,
  ) => {
    const normalized: any[] = [];
    for (const row of Array.isArray(rows) ? rows : []) {
      const sourceKind = sanitizeString(row?.source_kind, 40).toUpperCase();
      const objectiveId = sanitizeString(row?.therapeutic_objective_id, 120);
      const directPlanId = sanitizeString(row?.plan_id, 120);
      const planIds = sourceKind === 'PLAN_GOAL' || sourceKind === 'ABA_TARGET'
        ? (visiblePlanMap.has(directPlanId) ? [directPlanId] : [])
        : Array.from(objectivePlanMap.get(objectiveId) || []);
      if (!planIds.length) continue;

      const normalizedValue = normalizeClinicalOutcomeValueFromV3(row);
      const observedAt = sanitizeString(row?.observed_at, 80) || `${sanitizeString(row?.clinical_date, 20)}T00:00:00.000Z`;
      const coverageStatus = sanitizeString(row?.coverage_status, 80).toUpperCase();
      const missingReason = coverageStatus && coverageStatus !== 'OBSERVED' ? coverageStatus.toLowerCase() : null;
      const metricKey = sanitizeString(row?.metric_key, 120);
      const programTargetMatch = metricKey.match(/^program_target:([^:]+):/i);
      const semanticTargetId = sourceKind === 'ABA_TARGET'
        ? sanitizeString(row?.value_details?.aba_target_id || row?.target_id, 180)
        : sanitizeString(programTargetMatch?.[1], 180);
      const semanticTarget = semanticTargetId ? targetById.get(semanticTargetId) || null : null;
      const semanticProgram = semanticTarget?.program_id ? programById.get(String(semanticTarget.program_id)) || null : null;
      const historyBinding = sourceKind === 'ABA_TARGET' ? historyBindingBySessionTarget.get(`${sanitizeString(row?.session_id, 180)}::${semanticTargetId}`) || null : null;
      const historyVersionStatus = sourceKind === 'ABA_TARGET' ? (historyBinding?.program_version_id ? 'VERSION_BOUND' : 'LEGACY_UNVERSIONED') : 'VERSION_BOUND';
      const targetMasteryCriteria = semanticTarget?.mastery_criteria && typeof semanticTarget.mastery_criteria === 'object' && !Array.isArray(semanticTarget.mastery_criteria) && Object.keys(semanticTarget.mastery_criteria).length > 0
        ? semanticTarget.mastery_criteria
        : null;
      const programMasteryCriteria = semanticProgram?.mastery_criteria && typeof semanticProgram.mastery_criteria === 'object' && !Array.isArray(semanticProgram.mastery_criteria) && Object.keys(semanticProgram.mastery_criteria).length > 0
        ? semanticProgram.mastery_criteria
        : null;
      for (const planId of planIds) {
        const plan = visiblePlanMap.get(planId) || {};
        const sourceSessionId = sanitizeString(row?.session_id, 180);
        const boundPlanVersion = sourceSessionId ? ptsVersionBySessionPlan.get(`${sourceSessionId}::${planId}`) : undefined;
        normalized.push({
          id: `cmv3:${sanitizeString(row?.expectation_id, 120)}:${planId}`,
          planId,
          planVersion: Number(boundPlanVersion || plan?.edit_version || 1),
          goalId: sanitizeString(row?.goal_id, 120) || objectiveId || null,
          programId: sanitizeString(row?.program_id || semanticProgram?.id, 180) || null,
          sessionId: sanitizeString(row?.session_id, 180) || null,
          professionalId: null,
          specialty: sanitizeTextField(row?.specialty || plan?.specialty, 120) || null,
          itemId: sourceKind === 'ABA_TARGET'
            ? sanitizeString(row?.value_details?.series_key || row?.item_id || row?.target_id, 260) || null
            : sanitizeString(row?.item_id || row?.target_id, 260) || null,
          itemLabel: sanitizeTextField(row?.item_label || row?.metric_label, 220) || null,
          metricKey: metricKey || sanitizeString(row?.definition_id, 120),
          metricLabel: sanitizeTextField(row?.metric_label, 180) || sanitizeString(row?.metric_key, 120) || 'Métrica clínica',
          metricType: sanitizeString(row?.semantic_family, 40).toLowerCase(),
          unit: normalizedValue.unit,
          direction: normalizeClinicalOutcomeDirectionFromV3(row?.directionality),
          value: normalizedValue.value,
          valueText: normalizedValue.valueText,
          numerator: finiteClinicalOutcomeNumber(row?.numerator),
          denominator: finiteClinicalOutcomeNumber(row?.denominator),
          observedAt,
          context: 'clinic',
          source: sanitizeString(row?.read_model_source, 120) === 'ABA_V3_TARGET_CHART_READ_MODEL' ? 'ABA V3 canônico' : 'V3 canônico',
          instrumentId: sanitizeString(row?.read_model_source, 120) === 'ABA_V3_TARGET_CHART_READ_MODEL' ? 'ABA_V3_PHASE' : null,
          instrumentVersion: sanitizeString(row?.value_details?.phase_assignment_id, 180) || null,
          definitionVersion: Math.max(1, Number(row?.definition_version || 1)),
          missingReason,
          projectionStale: row?.projection_stale === true,
          sourceAuthority: 'canonical',
          metadata: {
            cmv3: true,
            sourceKind,
            targetId: row?.target_id || null,
            definitionId: row?.definition_id || null,
            definitionVersionId: row?.definition_version_id || null,
            expectationId: row?.expectation_id || null,
            coverageStatus: row?.coverage_status || null,
            canonicalValueUnit: row?.canonical_value_unit || null,
            valueDetails: row?.value_details || {},
            projectionQueueStatus: row?.projection_queue_status || null,
            sourceLatestRecordedAt: row?.source_latest_recorded_at || null,
            computedAt: row?.computed_at || null,
            readModelSource: row?.read_model_source || null,
            abaTargetId: sourceKind === 'ABA_TARGET' ? semanticTargetId || null : null,
            programTargetId: sourceKind === 'THERAPEUTIC_OBJECTIVE' ? semanticTargetId || null : null,
            targetDescription: semanticTarget?.description || null,
            masteryCriteria: targetMasteryCriteria || programMasteryCriteria || null,
            programMasteryCriteria: programMasteryCriteria || null,
            criterionSource: targetMasteryCriteria ? 'TARGET' : programMasteryCriteria ? 'PROGRAM_INHERITED' : null,
            targetType: semanticTarget?.target_type || null,
            targetPhase: sourceKind === 'ABA_TARGET' ? (historyBinding?.target_status_snapshot || null) : (semanticTarget?.phase || null),
            programMeasurementType: sourceKind === 'ABA_TARGET' ? (historyBinding?.measurement_type_snapshot || null) : (semanticProgram?.measurement_type || null),
            historyVersionStatus,
            programVersionId: historyBinding?.program_version_id || null,
            programVersion: historyBinding?.program_version_snapshot || null,
            sourceFamily: row?.value_details?.source_family || null,
            requiresReview: row?.value_details?.requires_review === true,
            phaseAssignmentId: row?.value_details?.phase_assignment_id || null,
            phaseType: row?.value_details?.phase_type || null,
            phaseLabel: row?.value_details?.phase_label || null,
          },
          minimumDataPoints: 4,
          recencyWindowDays: 30,
          sourceRecordType: 'cmv3_projection',
        });
      }
    }
    return normalized;
  };

  const clinicalOutcomeCrossSourceFingerprint = (row: any) => {
    const observed = new Date(String(row?.observedAt || ''));
    const observedSecond = Number.isFinite(observed.getTime()) ? Math.floor(observed.getTime() / 1000) : String(row?.observedAt || '');
    const numeric = finiteClinicalOutcomeNumber(row?.value);
    const numerator = finiteClinicalOutcomeNumber(row?.numerator);
    const denominator = finiteClinicalOutcomeNumber(row?.denominator);
    return [
      sanitizeString(row?.planId, 120),
      sanitizeString(row?.goalId, 120),
      sanitizeString(row?.metricKey, 120).toLowerCase(),
      sanitizeString(row?.unit, 80).toLowerCase(),
      sanitizeString(row?.direction, 80).toLowerCase(),
      sanitizeTextField(row?.specialty, 120).toLowerCase(),
      observedSecond,
      numeric !== null ? String(Math.round(numeric * 1_000_000) / 1_000_000) : sanitizeString(row?.valueText, 180),
      numerator !== null ? String(numerator) : '',
      denominator !== null ? String(denominator) : '',
    ].join('::');
  };

  const mergeClinicalOutcomeRowsV3First = (canonicalRows: any[], legacyRows: any[]) => {
    const canonical = Array.isArray(canonicalRows) ? canonicalRows : [];
    const legacy = Array.isArray(legacyRows) ? legacyRows : [];
    const canonicalFingerprints = new Set(canonical.map(clinicalOutcomeCrossSourceFingerprint));
    const canonicalAbaSessionTargets = new Set(
      canonical
        .filter((row) => sanitizeString(row?.metadata?.readModelSource, 120) === 'ABA_V3_TARGET_CHART_READ_MODEL')
        .map((row) => {
          const sessionId = sanitizeString(row?.sessionId, 180);
          const targetId = sanitizeString(row?.metadata?.abaTargetId, 180);
          return sessionId && targetId ? `${sessionId}::${targetId}` : '';
        })
        .filter(Boolean)
    );
    let deduplicatedLegacyCount = 0;
    const preservedLegacy = legacy.filter((row) => {
      const legacySessionId = sanitizeString(row?.sessionId, 180);
      const legacyTargetId = sanitizeString(row?.itemId, 180);
      const canonicalOwnsSessionTarget = row?.sourceRecordType === 'aba_snapshot'
        && legacySessionId
        && legacyTargetId
        && canonicalAbaSessionTargets.has(`${legacySessionId}::${legacyTargetId}`);
      if (!canonicalOwnsSessionTarget && !canonicalFingerprints.has(clinicalOutcomeCrossSourceFingerprint(row))) return true;
      deduplicatedLegacyCount += 1;
      return false;
    });
    const rows = [...canonical, ...preservedLegacy];
    rows.sort((left, right) => new Date(String(left?.observedAt || 0)).getTime() - new Date(String(right?.observedAt || 0)).getTime());
    return { rows, deduplicatedLegacyCount };
  };

  const isClinicalPlanV3ReaderUnavailable = (error: any) => {
    const code = sanitizeString(error?.code, 80).toUpperCase();
    const message = sanitizeString(error?.message || error?.details || error, 400).toLowerCase();
    return code === 'PGRST202'
      || ((message.includes('read_clinical_outcomes_converged_v3') || message.includes('read_clinical_plan_outcomes_v3'))
        && (message.includes('does not exist') || message.includes('schema cache') || message.includes('could not find')));
  };

  app.get('/api/patients/:patientId/clinical-outcomes-dashboard', noStoreDynamicResponse, checkAuth, requireClinicCapability('reports.clinical.indicators'), checkPatientAccess, createClinicalOutcomesDashboardHandler(() => ({ sanitizeString, currentClinicId, isUuid, supabase, applyAbaChartTenantScope, ABA_SESSION_METRIC_SNAPSHOT_SELECT, isMissingRelationError, hasMissingFinancialSchema, normalizeClinicalSpecialty, filterTherapeuticPlanScopesForActor, filterClinicalGraphPlanScopesForActor, canEditTherapeuticPlanScope, filterTherapeuticPlanProgramsForActor, isClinicalPlanV3ReaderUnavailable, normalizeClinicalPlanOutcomesV3ForDashboard, finiteClinicalOutcomeNumber, normalizeAbaSnapshotPoint, clinicalGraphLegacySnapshotVisibleToActor, abaMetricUnit, mergeClinicalOutcomeRowsV3First, sanitizeTextField, sendRouteDbError })));

  const abaChartReadHandlers = createAbaChartReadHandlers(() => ({ supabase, resolveAbaChartPatientScope, isUuid, parseAbaChartParams, fetchAbaSnapshotRows, fetchAbaGraphAnnotations, normalizeAbaSnapshotPoint, applyAbaChartTenantScope, hasMissingFinancialSchema, analyzeBehaviorContextPatterns, enrichMaintenanceRowsWithTargetDisplay, isAbaSignificantChange, buildAbaChartInsight, ABA_BEHAVIOR_DAILY_CHART_SELECT, ABA_MASTERY_LIST_SELECT, ABA_MAINTENANCE_SCHEDULE_SELECT, ABA_MAINTENANCE_PROBE_RESULT_SELECT, ABA_REGRESSION_ALERT_SELECT, ABA_PATIENT_SUMMARY_SELECT }));
  app.get('/api/aba/patients/:patientId/charts/targets', requireAbaV2Feature, checkAuth, requireClinicCapability('aba.analytics.view'), checkPatientAccess, abaChartReadHandlers.targets);

  app.get('/api/aba/patients/:patientId/charts/behaviors', requireAbaV2Feature, checkAuth, requireClinicCapability('aba.analytics.view'), checkPatientAccess, abaChartReadHandlers.behaviors);

