      const collectionStatus = ['COMPLETED', 'PARTIALLY_COMPLETED', 'CANCELLED'].includes(rawCollectionStatus)
        ? rawCollectionStatus
        : (answeredIntervals < plannedIntervals ? 'PARTIALLY_COMPLETED' : 'COMPLETED');
