  app.get(
    "/api/billing/discount-summary",
    checkAuth,
    requireRoles("coordinator", "admin", "owner"),
    async (req: any, res) => {
      const sessionUser = req.session?.user || {};
      const userId = sanitizeString(sessionUser.id, 120);
      const clinicId = sanitizeString(
        sessionUser.activeWorkspaceId || sessionUser.clinicId || sessionUser.id,
        120,
      );
      if (!isUuid(userId) || !isUuid(clinicId)) {
        return res.status(400).json({
          success: false,
          error: "Clínica inválida para consultar a assinatura.",
        });
      }

      try {
        const { data: discount, error } = await supabase
          .from("sales_subscription_discounts")
          .select(
            "id,discount_type,discount_percentage,discount_duration_months,discount_started_at,discount_ends_at,next_billing_at,post_discount_unit_amount_cents,estimated_next_invoice_amount_cents,discount_status,last_discount_sync_at,offer:sales_offers(initial_active_patient_quantity)",
          )
          .eq("clinic_id", clinicId)
          .order("updated_at", { ascending: false })
          .limit(1)
          .maybeSingle();
        if (error) throw error;

        let notifications: any[] = [];
        if (discount?.id) {
          const { data: rows, error: notificationsError } = await supabase
            .from("sales_discount_notifications")
            .select(
              "notification_window,internal_notification_sent_at,email_sent_at",
            )
            .eq("subscription_discount_id", discount.id)
            .order("created_at", { ascending: false })
            .limit(12);
          if (notificationsError) throw notificationsError;
          notifications = rows || [];
        }

        const relatedOffer = Array.isArray((discount as any)?.offer)
          ? (discount as any).offer[0]
          : (discount as any)?.offer;
        return res.json({
          success: true,
          data: {
            officialPrice: PUBLIC_ACTIVE_PATIENT_PRICE,
            source: "persisted_stripe_snapshot",
            discount: discount
              ? {
                  discountType:
                    sanitizeString(discount.discount_type, 20) === "coupon"
                      ? "coupon"
                      : "none",
                  discountPercentage:
                    discount.discount_percentage == null
                      ? null
                      : Number(discount.discount_percentage),
                  discountDurationMonths: isCustomCouponDurationMonths(
                    Number(discount.discount_duration_months),
                  )
                    ? Number(discount.discount_duration_months)
                    : null,
                  discountStartedAt: discount.discount_started_at || null,
                  discountEndsAt: discount.discount_ends_at || null,
                  nextBillingAt: discount.next_billing_at || null,
                  postDiscountUnitAmountCents: Number(
                    discount.post_discount_unit_amount_cents ||
                      PUBLIC_ACTIVE_PATIENT_PRICE.unitAmountCents,
                  ),
                  estimatedNextInvoiceAmountCents:
                    discount.estimated_next_invoice_amount_cents == null
                      ? null
                      : Number(discount.estimated_next_invoice_amount_cents),
                  initialActivePatientQuantity:
                    relatedOffer?.initial_active_patient_quantity == null
                      ? null
                      : Number(relatedOffer.initial_active_patient_quantity),
                  status:
                    sanitizeString(discount.discount_status, 40) ||
                    "pending_sync",
                  lastSyncedAt: discount.last_discount_sync_at || null,
                  notifications: notifications.map((notification: any) => ({
                    window: sanitizeString(
                      notification.notification_window,
                      40,
                    ),
                    internalSentAt:
                      notification.internal_notification_sent_at || null,
                    emailSentAt: notification.email_sent_at || null,
                  })),
                }
              : null,
          },
        });
      } catch (error: any) {
        if (isMissingRelationError(error)) {
          return res.json({
            success: true,
            data: {
              officialPrice: PUBLIC_ACTIVE_PATIENT_PRICE,
              source: "commercial_schema_pending",
              discount: null,
              warning: "Sincronização de descontos ainda não habilitada.",
            },
          });
        }
        console.error("[Billing Discount] Falha ao carregar snapshot:", {
          clinicId,
          message: sanitizeString(error?.message || String(error), 240),
        });
        return res.status(500).json({
          success: false,
          error: "Não foi possível carregar a condição da assinatura.",
        });
      }
    },
  );

  app.get('/api/billing/plans', checkAuth, async (req: any, res) => {
    try {
      const sessionUser = req.session?.user || {};
      const role = sanitizeString(sessionUser?.role, 40).toLowerCase();
      if (role === 'patient') {
        return res.json({
          success: true,
          data: {
            billingModel: 'patient_subscription',
            plans: [],
            salesContactUrl: resolveSalesContactUrl()
          }
        });
      }

      const clinicId = sanitizeString(sessionUser.activeWorkspaceId || sessionUser.clinicId || sessionUser.id, 120);
      const demoState = await fetchClinicDemoState(clinicId);
      if (demoState.isDemo || isDemoSessionUser(sessionUser)) {
        return res.json({
          success: true,
          data: {
            billingModel: DEMO_SANDBOX_BILLING_MODEL,
            plans: [],
            stripeEnabled: false,
            demo: true,
            salesContactUrl: resolveSalesContactUrl()
          }
        });
      }

      const enterpriseThreshold = resolveActivePatientEnterpriseThreshold();
      const { plans, source, sync } = await loadBillingPlansFromSnapshots({ allowSync: true });
      const activePatientPriceId = resolveActivePatientPriceId() || plans.find((plan) => plan.selfService && !plan.isCustom)?.priceId || '';
      const patientBasedBillingEnabled = resolvePatientBasedBillingEnabled();
      const patientPricingTiers = resolveVertoPatientPricingTiers();
      console.info('[Billing Plans] diagnostics:', {
        stripeConfigured: hasStripeSecretConfigured(),
        source,
        cacheSyncTriggered: Boolean(sync),
        pricesFound: plans.length,
        activeRecurringPrices: plans.filter((plan) => Boolean(plan.interval)).length,
        tieredPricesFound: plans.filter((plan) => plan.billingScheme === 'tiered').length,
        returnedPlans: plans.length,
        firstPlanHasPriceId: Boolean(plans[0]?.priceId),
        firstPlanTierCount: plans[0]?.tiers?.length || 0
      });

      return res.json({
        success: true,
        data: {
          billingModel: ACTIVE_PATIENT_BILLING_MODEL,
          defaultPriceId: activePatientPriceId || plans.find((plan) => !plan.isCustom)?.priceId || null,
          enterpriseThreshold,
          patientBasedBillingEnabled,
          patientPricingTiers,
          pricingModel: plans.some((plan) => plan.pricingModel === 'tiered_active_patients')
            ? 'tiered_active_patients'
            : 'plans_by_limit',
          plans,
          salesContactUrl: resolveSalesContactUrl(),
          stripeEnabled: true
        }
      });
    } catch (error: any) {
      console.error('[Billing Plans] Falha ao carregar planos Stripe:', {
        message: error?.message || String(error),
        code: sanitizeString(error?.code, 80) || (isMissingStripeConfigError(error) ? 'MISSING_STRIPE_CONFIG' : null)
      });
      return res.status(503).json({
        success: false,
        code: isMissingStripeConfigError(error) ? 'MISSING_STRIPE_CONFIG' : 'BILLING_PLANS_UNAVAILABLE',
        error: 'Não foi possível carregar os planos agora. Tente novamente em alguns instantes.'
      });
    }
  });

  app.post('/api/billing/estimate', checkAuth, async (req: any, res) => {
    let estimateDiagnostics: Record<string, unknown> = {
      priceIdPresent: Boolean(req.body?.selectedPriceId || req.body?.priceId),
      priceFound: false,
      activePatients: normalizeActivePatientQuantity(req.body?.activePatients || req.body?.expectedActivePatients),
      tierCount: 0,
      estimatedAmountCents: null,
      errorCode: null
    };
    const rejectEstimate = (status: number, code: string, error: string) => {
      console.warn('[Billing Estimate] diagnostics:', {
        ...estimateDiagnostics,
        errorCode: code
      });
      return res.status(status).json({ success: false, code, error });
    };

    try {
      const sessionUser = req.session?.user || {};
      if (sanitizeString(sessionUser.role, 40).toLowerCase() === 'patient') {
        return rejectEstimate(400, 'UNSUPPORTED_BILLING_MODEL', 'Este simulador é exclusivo para planos de clínica.');
      }

      const activePatients = normalizeActivePatientQuantity(req.body?.activePatients || req.body?.expectedActivePatients);
      if (!activePatients) {
        return rejectEstimate(400, 'INVALID_ACTIVE_PATIENTS', 'Informe uma quantidade válida de pacientes ativos.');
      }
      estimateDiagnostics = { ...estimateDiagnostics, activePatients };

      const activePatientPriceId = resolveActivePatientPriceId();
      const { plans: billingPlans, source } = await loadBillingPlansFromSnapshots({ allowSync: true });
      const requestedPriceId = sanitizeString(req.body?.selectedPriceId || req.body?.priceId, 120);
      const requestedPlan = requestedPriceId ? billingPlans.find((plan) => plan.priceId === requestedPriceId) || null : null;
      if (requestedPriceId && !requestedPlan) {
        return rejectEstimate(400, 'PRICE_NOT_AVAILABLE', 'Plano selecionado não está disponível para contratação.');
      }

      const selectedPlan =
        requestedPlan ||
        billingPlans.find((plan) => plan.priceId === activePatientPriceId && !plan.isCustom) ||
        billingPlans.find((plan) => !plan.isCustom) ||
        null;
      estimateDiagnostics = {
        ...estimateDiagnostics,
        priceFound: Boolean(selectedPlan),
        tierCount: selectedPlan?.tiers?.length || 0
      };

      if (!selectedPlan) {
        return rejectEstimate(503, 'PLANS_NOT_CONFIGURED', 'Planos de assinatura ainda não estão configurados.');
      }
      const estimate = estimateStripeActivePatientPlan({
        plan: selectedPlan,
        activePatients,
        enterpriseThreshold: selectedPlan.enterpriseThreshold
      });
      const patientBasedBillingEnabled = resolvePatientBasedBillingEnabled();
      const patientBasedBillingPreview = patientBasedBillingEnabled
        ? calculateVertoPatientBasedMonthlyPrice(activePatients, resolveVertoPatientPricingTiers())
        : null;
      const estimatedAmountCents =
        patientBasedBillingPreview && !patientBasedBillingPreview.requiresCustomPricing
          ? patientBasedBillingPreview.totalAmountCents
          : estimate.estimatedAmountCents;
      console.info('[Billing Estimate] diagnostics:', {
        ...estimateDiagnostics,
        source,
        tierCount: selectedPlan.tiers?.length || 0,
        estimatedAmountCents,
        stripeEstimatedAmountCents: estimate.estimatedAmountCents,
        patientBasedBillingEnabled,
        errorCode: null
      });

      return res.json({
        success: true,
        data: {
          ...estimate,
          estimatedAmountCents,
          stripeEstimatedAmountCents: estimate.estimatedAmountCents,
          patientBasedBillingEnabled,
          patientBasedBillingPreview
        }
      });
    } catch (error: any) {
      console.error('[Billing Estimate] Falha ao estimar plano Stripe:', {
        ...estimateDiagnostics,
        message: error?.message || String(error),
        code: sanitizeString(error?.code, 80) || (isMissingStripeConfigError(error) ? 'MISSING_STRIPE_CONFIG' : null)
      });
      return res.status(503).json({
        success: false,
        code: isMissingStripeConfigError(error) ? 'MISSING_STRIPE_CONFIG' : 'BILLING_ESTIMATE_UNAVAILABLE',
        error: 'Não foi possível calcular a estimativa agora. Tente novamente em alguns instantes.'
      });
    }
  });

  async function persistBillingPlanChangeAudit(params: {
    clinicId?: string | null;
    userId?: string | null;
    stripeSubscriptionId?: string | null;
    stripeSubscriptionItemId?: string | null;
    stripePriceId?: string | null;
    previousLimit?: number | null;
    requestedLimit?: number | null;
    activePatientCount?: number | null;
    effectiveDate?: string | null;
    status: string;
    trigger: string;
    metadata?: Record<string, any>;
  }) {
    try {
      const payload = cleanObject({
        clinic_id: isUuid(sanitizeString(params.clinicId, 120)) ? sanitizeString(params.clinicId, 120) : null,
        user_id: isUuid(sanitizeString(params.userId, 120)) ? sanitizeString(params.userId, 120) : null,
        stripe_subscription_id: sanitizeString(params.stripeSubscriptionId, 200) || null,
        stripe_subscription_item_id: sanitizeString(params.stripeSubscriptionItemId, 200) || null,
        stripe_price_id: sanitizeString(params.stripePriceId, 200) || null,
        previous_limit: typeof params.previousLimit === 'number' ? Math.max(0, Math.floor(params.previousLimit)) : null,
        requested_limit: typeof params.requestedLimit === 'number' ? Math.max(0, Math.floor(params.requestedLimit)) : null,
        active_patient_count: typeof params.activePatientCount === 'number' ? Math.max(0, Math.floor(params.activePatientCount)) : null,
        effective_date: sanitizeString(params.effectiveDate, 80) || null,
        status: sanitizeString(params.status, 80),
        trigger: sanitizeString(params.trigger, 100),
        metadata: params.metadata || {}
      });
      const { error } = await supabase
        .from('billing_plan_change_audit_logs')
        .insert([payload]);
      if (error && !isMissingRelationError(error) && !extractMissingColumnName(error)) {
        console.warn('[Billing Limits] Falha ao registrar auditoria de mudança de faixa.', {
          clinicId: sanitizeString(params.clinicId, 120),
          status: sanitizeString(params.status, 80),
          message: sanitizeString(error.message, 240)
        });
      }
    } catch (error: any) {
      console.warn('[Billing Limits] Auditoria de mudança de faixa indisponível.', {
        clinicId: sanitizeString(params.clinicId, 120),
        status: sanitizeString(params.status, 80),
        message: sanitizeString(error?.message || String(error), 240)
      });
    }
  }

  async function resolveStoredSubscriptionItemForClinic(params: {
    stripe: Stripe;
    clinicId: string;
    billingState: Awaited<ReturnType<typeof readClinicActivePatientBillingState>>;
    priceId?: string | null;
  }): Promise<{ subscription: Stripe.Subscription; subscriptionItemId: string; priceId: string }> {
    const subscriptionId = sanitizeString(params.billingState.stripeSubscriptionId, 200);
    if (!subscriptionId) {
      throw Object.assign(new Error('Assinatura Stripe não encontrada para esta clínica.'), {
        code: 'SUBSCRIPTION_NOT_READY'
      });
    }
    const subscription = await params.stripe.subscriptions.retrieve(subscriptionId, { expand: ['items.data.price'] });
    const requestedPriceId =
      sanitizeString(params.priceId, 200) ||
      sanitizeString(params.billingState.stripePriceId, 200) ||
      resolveActivePatientPriceId();
    const storedItemId = sanitizeString(params.billingState.stripeSubscriptionItemId, 200);
    const subscriptionItem =
      (storedItemId ? subscription.items.data.find((item) => item.id === storedItemId) : null) ||
      (requestedPriceId
        ? subscription.items.data.find((item) => sanitizeString((item.price as any)?.id, 200) === requestedPriceId)
        : null) ||
      subscription.items.data[0] ||
      null;
    const subscriptionItemId = sanitizeString(subscriptionItem?.id, 200);
    if (!subscriptionItemId) {
      throw Object.assign(new Error('Item de assinatura Stripe não encontrado para esta clínica.'), {
        code: 'SUBSCRIPTION_ITEM_NOT_READY'
      });
    }
    return {
      subscription,
      subscriptionItemId,
      priceId: sanitizeString((subscriptionItem?.price as any)?.id, 200) || requestedPriceId
    };
  }

